    if (isset($_POST['admin_song_action']) && isset($_POST['song_ids']) && is_array($_POST['song_ids'])) {
      $db = get_db();
      $action = $_POST['admin_song_action'];
      
      foreach ($_POST['song_ids'] as $sid) {
        $sid = (int)$sid;
        
        if ($action === 'ban') {
          $db->prepare("UPDATE music SET banned = 1 WHERE id = ?")->execute([$sid]);
        } elseif ($action === 'unban') {
          $db->prepare("UPDATE music SET banned = 0 WHERE id = ?")->execute([$sid]);
        } elseif ($action === 'soft_delete') {
          $db->prepare("DELETE FROM music WHERE id = ?")->execute([$sid]);
        } elseif ($action === 'perm_delete') {
          $stmt = $db->prepare("SELECT file FROM music WHERE id = ?");
          $stmt->execute([$sid]);
          $song = $stmt->fetch();
          if ($song) {
            $db->prepare("DELETE FROM music WHERE id = ?")->execute([$sid]);
            $file_path = $song['file'] ?? '';
            if ($file_path && file_exists(MUSIC_DIR . '/' . $file_path)) {
              @unlink(MUSIC_DIR . '/' . $file_path);
            } else {
              $dynamic_path = MUSIC_DIR . '/uploads/' . basename(dirname(dirname($file_path))) . '/' . basename(dirname($file_path)) . '/' . basename($file_path);
              if (file_exists($dynamic_path)) @unlink($dynamic_path);
            }
          }
        }
      }
      
      log_admin_activity($db, $_SESSION['admin_email'], "Bulk Action ({$action}) on Songs: " . implode(',', $_POST['song_ids']), 0);
      $_SESSION['admin_flash_msg'] = "Bulk action executed successfully.";
      header('Location: ' . $_SERVER['REQUEST_URI']);
      exit;
    }

    if (isset($_POST['edit_admin_artwork']) && isset($_POST['artwork_id'])) {
      $db = get_db();
      $aid = (int)$_POST['artwork_id'];
      $title = trim(htmlspecialchars($_POST['title'] ?? '', ENT_QUOTES, 'UTF-8'));
      $description = trim(htmlspecialchars($_POST['description'] ?? '', ENT_QUOTES, 'UTF-8'));
      $tags = trim(htmlspecialchars($_POST['tags'] ?? '', ENT_QUOTES, 'UTF-8'));
      $parodies = trim(htmlspecialchars($_POST['parodies'] ?? '', ENT_QUOTES, 'UTF-8'));
      $characters = trim(htmlspecialchars($_POST['characters'] ?? '', ENT_QUOTES, 'UTF-8'));
      $groups_name = trim(htmlspecialchars($_POST['groups_name'] ?? '', ENT_QUOTES, 'UTF-8'));
      $type = in_array($_POST['type'] ?? '', ['image', 'manga']) ? ($_POST['type'] ?? 'image') : 'image';
      $nsfw = !empty($_POST['nsfw']) ? 1 : 0;

      $seriesId = null;
      $seriesNew = trim(htmlspecialchars($_POST['series_new'] ?? '', ENT_QUOTES, 'UTF-8'));
      $seriesSelected = $_POST['series_id'] ?? '';
      if ($seriesNew !== '') {
        $check = $db->prepare("SELECT id FROM art_series WHERE title = ? COLLATE NOCASE");
        $check->execute([$seriesNew]);
        $existing = $check->fetchColumn();
        if ($existing) {
          $seriesId = (int)$existing;
        } else {
          $uid = (int)$_SESSION['admin_id'];
          $ins = $db->prepare("INSERT INTO art_series (public_id, user_id, title) VALUES (?, ?, ?)");
          $ins->execute([uniqid('ser_'), $uid, $seriesNew]);
          $seriesId = (int)$db->lastInsertId();
        }
      } elseif ($seriesSelected !== '') {
        $seriesId = (int)$seriesSelected;
      }
      $db->prepare("UPDATE arts SET title = ?, description = ?, tags = ?, series_id = ?, parodies = ?, characters = ?, groups_name = ?, type = ?, nsfw = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?")->execute([$title, $description, $tags, $seriesId, $parodies, $characters, $groups_name, $type, $nsfw, $aid]);
      log_admin_activity($db, $_SESSION['admin_email'], 'Edited Artwork ID: ' . $aid, 0);

      $_SESSION['admin_flash_msg'] = "Artwork metadata updated successfully.";
      header('Location: ' . $_SERVER['REQUEST_URI']);
      exit;
    }

    if (isset($_POST['bulk_edit_admin_artworks']) && isset($_POST['artwork_ids']) && is_array($_POST['artwork_ids'])) {
      $db = get_db();
      $title = trim(htmlspecialchars($_POST['title'] ?? '', ENT_QUOTES, 'UTF-8'));
      $description = trim(htmlspecialchars($_POST['description'] ?? '', ENT_QUOTES, 'UTF-8'));
      $tags = trim(htmlspecialchars($_POST['tags'] ?? '', ENT_QUOTES, 'UTF-8'));
      $parodies = trim(htmlspecialchars($_POST['parodies'] ?? '', ENT_QUOTES, 'UTF-8'));
      $characters = trim(htmlspecialchars($_POST['characters'] ?? '', ENT_QUOTES, 'UTF-8'));
      $groups_name = trim(htmlspecialchars($_POST['groups_name'] ?? '', ENT_QUOTES, 'UTF-8'));
      $type = in_array($_POST['type'] ?? '', ['image', 'manga']) ? ($_POST['type'] ?? '') : '';
      $nsfw = isset($_POST['nsfw']) ? (int)$_POST['nsfw'] : -1;
      $transfer_to = trim($_POST['transfer_to'] ?? '');

      $updates = [];
      $params = [];

      if ($title !== '') { $updates[] = "title = ?"; $params[] = $title; }
      if ($description !== '') { $updates[] = "description = ?"; $params[] = $description; }
      if ($tags !== '') { $updates[] = "tags = ?"; $params[] = $tags; }
      if ($parodies !== '') { $updates[] = "parodies = ?"; $params[] = $parodies; }
      if ($characters !== '') { $updates[] = "characters = ?"; $params[] = $characters; }
      if ($groups_name !== '') { $updates[] = "groups_name = ?"; $params[] = $groups_name; }
      if ($type !== '') { $updates[] = "type = ?"; $params[] = $type; }
      if ($nsfw !== -1) { $updates[] = "nsfw = ?"; $params[] = $nsfw; }

      if ($transfer_to !== '') {
        $stmt_u = $db->prepare("SELECT id FROM users WHERE id = ? OR email = ?");
        $stmt_u->execute([$transfer_to, $transfer_to]);
        $transfer_user_id = $stmt_u->fetchColumn();
        if ($transfer_user_id) {
          $updates[] = "user_id = ?";
          $params[] = $transfer_user_id;
        } else {
          $_SESSION['admin_flash_msg'] = "Transfer failed: User ID or Email not found.";
          header('Location: ' . $_SERVER['REQUEST_URI']);
          exit;
        }
      }

      if (!empty($updates)) {
        $sql = "UPDATE arts SET " . implode(", ", $updates) . " WHERE id IN (" . implode(',', array_map('intval', $_POST['artwork_ids'])) . ")";
        $db->prepare($sql)->execute($params);
        log_admin_activity($db, $_SESSION['admin_email'], 'Bulk Edited/Transferred Artworks: ' . implode(',', $_POST['artwork_ids']), 0);
        $_SESSION['admin_flash_msg'] = "Selected artworks updated and/or transferred successfully.";
      }
      header('Location: ' . $_SERVER['REQUEST_URI']);
      exit;
    }

    if (isset($_POST['multi_edit_admin_artworks']) && isset($_POST['multi_edit_ids']) && is_array($_POST['multi_edit_ids'])) {
      $db = get_db();
      $stmt = $db->prepare("UPDATE arts SET title = ?, description = ?, tags = ?, series_id = ?, parodies = ?, characters = ?, groups_name = ?, type = ?, nsfw = ?, user_id = ? WHERE id = ?");
      foreach ($_POST['multi_edit_ids'] as $aid) {
        $aid = (int)$aid;
        $title = trim(htmlspecialchars($_POST['multi_title'][$aid] ?? '', ENT_QUOTES, 'UTF-8'));
        $description = trim(htmlspecialchars($_POST['multi_description'][$aid] ?? '', ENT_QUOTES, 'UTF-8'));
        $tags = trim(htmlspecialchars($_POST['multi_tags'][$aid] ?? '', ENT_QUOTES, 'UTF-8'));
        $parodies = trim(htmlspecialchars($_POST['multi_parodies'][$aid] ?? '', ENT_QUOTES, 'UTF-8'));
        $characters = trim(htmlspecialchars($_POST['multi_characters'][$aid] ?? '', ENT_QUOTES, 'UTF-8'));
        $groups_name = trim(htmlspecialchars($_POST['multi_groups_name'][$aid] ?? '', ENT_QUOTES, 'UTF-8'));
        $type = in_array($_POST['multi_type'][$aid] ?? '', ['image', 'manga']) ? $_POST['multi_type'][$aid] : 'image';
        $nsfw = !empty($_POST['multi_nsfw'][$aid]) ? 1 : 0;
        $uid = (int)($_POST['multi_userid'][$aid] ?? 0);

        $seriesId = null;
        $seriesNew = trim(htmlspecialchars($_POST['multi_series_new'][$aid] ?? '', ENT_QUOTES, 'UTF-8'));
        $seriesSelected = $_POST['multi_series_id'][$aid] ?? '';
        if ($seriesNew !== '') {
          $check = $db->prepare("SELECT id FROM art_series WHERE title = ? COLLATE NOCASE");
          $check->execute([$seriesNew]);
          $existing = $check->fetchColumn();
          if ($existing) {
            $seriesId = (int)$existing;
          } else {
            $ins = $db->prepare("INSERT INTO art_series (public_id, user_id, title) VALUES (?, ?, ?)");
            $ins->execute([uniqid('ser_'), $uid ?: 0, $seriesNew]);
            $seriesId = (int)$db->lastInsertId();
          }
        } elseif ($seriesSelected !== '') {
          $seriesId = (int)$seriesSelected;
        }

        $stmt->execute([$title, $description, $tags, $seriesId, $parodies, $characters, $groups_name, $type, $nsfw, $uid, $aid]);
      }
      log_admin_activity($db, $_SESSION['admin_email'], 'Multi-Edited Artworks: ' . implode(',', $_POST['multi_edit_ids']), 0);
      $_SESSION['admin_flash_msg'] = "Selected artworks updated successfully.";
      header('Location: ' . $_SERVER['REQUEST_URI']);
      exit;
    }

    if (isset($_POST['admin_artwork_action']) && isset($_POST['artwork_ids']) && is_array($_POST['artwork_ids'])) {
      $db = get_db();
      $action = $_POST['admin_artwork_action'];

      foreach ($_POST['artwork_ids'] as $aid) {
        $aid = (int)$aid;

        if ($action === 'soft_delete') {
          $db->prepare("DELETE FROM arts WHERE id = ?")->execute([$aid]);
        } elseif ($action === 'perm_delete') {
          $stmt = $db->prepare("SELECT id FROM arts WHERE id = ?");
          $stmt->execute([$aid]);
          $artwork = $stmt->fetch();
          if ($artwork) {
            $db->prepare("DELETE FROM arts WHERE id = ?")->execute([$aid]);
            $file_stmt = $db->prepare("SELECT file_path FROM art_files WHERE art_id = ?");
            $file_stmt->execute([$aid]);
            while ($file = $file_stmt->fetch()) {
              $file_path = $file['file_path'] ?? '';
              if ($file_path && file_exists(MUSIC_DIR . '/' . $file_path)) {
                @unlink(MUSIC_DIR . '/' . $file_path);
              }
              $thumb_path = $file['thumb_path'] ?? '';
              if ($thumb_path && file_exists(MUSIC_DIR . '/' . $thumb_path)) {
                @unlink(MUSIC_DIR . '/' . $thumb_path);
              }
            }
            $db->prepare("DELETE FROM art_files WHERE art_id = ?")->execute([$aid]);
          }
        }
      }

      log_admin_activity($db, $_SESSION['admin_email'], "Bulk Action ({$action}) on Artworks: " . implode(',', $_POST['artwork_ids']), 0);
      $_SESSION['admin_flash_msg'] = "Bulk action executed successfully.";
      header('Location: ' . $_SERVER['REQUEST_URI']);
      exit;
    }

    if (isset($_POST['permanent_delete_user']) && isset($_POST['user_id'])) {
      $db = get_db();
      $del_uid = (int)$_POST['user_id'];
      $stmt = $db->prepare("SELECT file FROM music WHERE user_id = ?");
      $stmt->execute([$del_uid]);
      while ($row = $stmt->fetch()) {
        if ($row['file'] && file_exists($row['file'])) @unlink($row['file']);
      }
      $db->prepare("DELETE FROM starred_messages WHERE user_id = ?")->execute([$del_uid]);
      $db->prepare("DELETE FROM user_statuses WHERE user_id = ?")->execute([$del_uid]);
      $db->prepare("DELETE FROM rhythm_scores WHERE user_id = ?")->execute([$del_uid]);
      $db->prepare("DELETE FROM rhythm_favorites WHERE user_id = ?")->execute([$del_uid]);
      $db->prepare("DELETE FROM users WHERE id = ?")->execute([$del_uid]);
      log_admin_activity($db, $_SESSION['admin_email'], 'Permanently Deleted User', $del_uid);
      header('Location: ' . $_SERVER['REQUEST_URI']);
      exit;
    }

    if (isset($_POST['generate_api_key'])) {
       $name = htmlspecialchars(trim($_POST['key_name'] ?? 'Unnamed App'));
       $token = 'pk_' . bin2hex(random_bytes(16));
       $expires_at = date('Y-m-d H:i:s', strtotime('+1 month'));
       get_db()->prepare("INSERT INTO api_keys (name, token, reset_month, user_id, status, expires_at) VALUES (?, ?, ?, ?, 'active', ?)")->execute([$name, $token, date('Y-m'), $_SESSION['admin_id'] ?? 0, $expires_at]);
       log_admin_activity(get_db(), $_SESSION['admin_email'], "Generated API Key: $name", 0);
       $_SESSION['admin_flash_msg'] = "Custom API Key generated successfully! Expires in 1 month.";
       header("Location: ?access=admin&page=api"); exit;
    }
    if (isset($_POST['verify_api_key'])) {
      $expires_at = date('Y-m-d H:i:s', strtotime('+1 month'));
      $token = 'pk_' . bin2hex(random_bytes(16));
      get_db()->prepare("UPDATE api_keys SET status = 'active', token = ?, expires_at = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?")->execute([$token, $expires_at, (int)$_POST['key_id']]);
      log_admin_activity(get_db(), $_SESSION['admin_email'], "Verified User API Key", 0);
      $_SESSION['admin_flash_msg'] = "API Key verified! Valid for 1 month.";
      header("Location: ?access=admin&page=api"); exit;
    }
    if (isset($_POST['ban_api_key'])) {
      get_db()->prepare("UPDATE api_keys SET status = 'banned', updated_at = CURRENT_TIMESTAMP WHERE id = ?")->execute([(int)$_POST['key_id']]);
      log_admin_activity(get_db(), $_SESSION['admin_email'], "Banned API Key", 0);
      $_SESSION['admin_flash_msg'] = "API Key banned!";
      header("Location: ?access=admin&page=api"); exit;
    }
    if (isset($_POST['unban_api_key'])) {
      get_db()->prepare("UPDATE api_keys SET status = 'active', updated_at = CURRENT_TIMESTAMP WHERE id = ?")->execute([(int)$_POST['key_id']]);
      log_admin_activity(get_db(), $_SESSION['admin_email'], "Unbanned API Key", 0);
      $_SESSION['admin_flash_msg'] = "API Key unbanned!";
      header("Location: ?access=admin&page=api"); exit;
    }
    if (isset($_POST['delete_api_key'])) {
      get_db()->prepare("DELETE FROM api_keys WHERE id = ?")->execute([(int)$_POST['key_id']]);
      log_admin_activity(get_db(), $_SESSION['admin_email'], "Revoked an API Key", 0);
      $_SESSION['admin_flash_msg'] = "API Key removed permanently!";
      header("Location: ?access=admin&page=api"); exit;
    }
        
    if (isset($_POST['reset_opcache'])) {
      if (function_exists('opcache_reset')) {
        opcache_reset();
      }
      header('Location: ?access=admin');
      exit;
    }
  }

  $admin_login_error = '';
  if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['admin_email']) && isset($_POST['admin_password'])) {
    $db = get_db();
    $stmt = $db->prepare("SELECT id, artist, password_hash, is_admin, status FROM users WHERE email = ?");
    $stmt->execute([$_POST['admin_email']]);
    $user = $stmt->fetch();
    
    if ($user && password_verify($_POST['admin_password'], $user['password_hash'])) {
      if ($user['is_admin'] == 1 || $user['status'] === 'admin' || $user['status'] === 'super_admin') {
        $_SESSION['admin_logged_in'] = true;
        $_SESSION['admin_email'] = $_POST['admin_email'];
        $_SESSION['admin_id'] = $user['id'];
        
        // Auto-login to Main Site simultaneously
        $_SESSION['user_id'] = $user['id'];
        $_SESSION['user_artist'] = $user['artist'];
        
        setcookie('admin_session_token', hash('sha256', $user['password_hash'] . ($_SERVER['HTTP_USER_AGENT'] ?? '')), time() + 31536000, '/');
        setcookie('admin_email', $_POST['admin_email'], time() + 31536000, '/');
        header('Location: ?access=admin');
        exit;
      } else {
        $admin_login_error = "Access denied: Account is not an administrator.";
      }
    } else {
      $admin_login_error = "Invalid email or password.";
    }
  }

  if (isset($_GET['logout'])) {
    // Hard destroy the entire session to safely logout everywhere
    session_destroy();
    setcookie('admin_session_token', '', time() - 3600, '/');
    setcookie('admin_email', '', time() - 3600, '/');
    header('Location: ?access=admin');
    exit;
  }
  
  $is_admin_logged_in = isset($_SESSION['admin_logged_in']) && $_SESSION['admin_logged_in'] === true;

  // FETCH ADMIN PERMISSIONS & ENFORCE ACCESS
  $current_admin_permissions = ['users', 'songs', 'artworks', 'logs', 'reports', 'appeals', 'drive', 'dbmanager', 'ide', 'api', 'playground', 'storage']; // Default to all if missing
  $is_super_admin_check = false;
  
  if ($is_admin_logged_in && isset($_SESSION['admin_id'])) {
    $db_fw = get_db();
    $stmt_fw = $db_fw->prepare("SELECT status, settings FROM users WHERE id = ?");
    $stmt_fw->execute([$_SESSION['admin_id']]);
    $adm_row = $stmt_fw->fetch();
    if ($adm_row) {
      if ($adm_row['status'] === 'super_admin') {
        $is_super_admin_check = true;
      } else {
        $adm_settings = json_decode($adm_row['settings'] ?: '{}', true) ?? [];
        if (isset($adm_settings['admin_permissions'])) {
          $current_admin_permissions = $adm_settings['admin_permissions'];
        }
      }
    }
  }

  $req_page = $_GET['page'] ?? 'users';
  if (empty($req_page)) $req_page = 'users';

  // Strict page enforcement and redirection engine
  if ($is_admin_logged_in && !$is_super_admin_check && !isset($_POST['admin_email'])) {
    if (!in_array($req_page, $current_admin_permissions)) {
      $first_allowed = !empty($current_admin_permissions) ? $current_admin_permissions[0] : '';
      if ($first_allowed) {
        $redirect_url = "?access=admin" . ($first_allowed === 'users' ? '' : "&page=" . $first_allowed);
        $_SESSION['admin_flash_msg'] = "Access Denied. Redirected to your first allowed page.";
        header("Location: $redirect_url");
        exit;
      } else {
        die("Access Denied: You have no administrative permissions assigned to view any pages.");
      }
    }
  }
?>
