      ::-webkit-scrollbar-track {
        background: var(--ytm-surface);
      }
      ::-webkit-scrollbar-thumb {
        background: var(--ytm-surface-2);
        border-radius: 4px;
      }
      ::-webkit-scrollbar-thumb:hover {
        background: #555;
      }

      /* Disable text selection during drag operations */
      .ide-file-tree {
        user-select: none;
        -webkit-user-select: none;
      }

      .app-container {
        display: flex;
        height: 100dvh;
        flex-direction: column;
        overflow: hidden;
      }

      .sidebar {
        width: 260px;
        background-color: var(--ytm-surface);
        border-right: 1px solid var(--ytm-surface-2);
        display: flex;
        flex-direction: column;
        flex-shrink: 0;
        z-index: 1045;
        transition: width 0.3s ease, transform 0.3s ease;
        overflow-y: auto;
        box-shadow: inset -1px 0 0 rgba(255, 255, 255, 0.02);
      }

      .main-content {
        flex-grow: 1;
        display: flex;
        flex-direction: column;
        overflow-y: auto;
        overflow-x: hidden;
        background-color: var(--ytm-bg);
      }

      .content-area-wrapper {
        padding: 1.5rem 2rem;
      }

      .sidebar .logo {
        font-size: 1.25rem;
        font-weight: 700;
        display: flex;
        align-items: center;
        gap: 8px;
      }

      .sidebar .logo span {
        color: var(--ytm-accent);
      }

      .nav-link {
        color: var(--ytm-secondary-text);
        display: flex;
        align-items: center;
        font-weight: 500;
        gap: 1rem;
        text-decoration: none;
        padding: 0.75rem 1.25rem;
        margin: 0.2rem 0.75rem;
        border-radius: 12px;
        transition: all 0.2s ease-in-out;
        border: none;
        border-left: 4px solid transparent;
        /* Left red indicator base */
        border-radius: 0 12px 12px 0;
        /* Flat left side, rounded right */
      }

      .nav-link:hover {
        color: var(--ytm-primary-text);
        background-color: rgba(255, 255, 255, 0.05);
        border-left-color: var(--ytm-accent);
      }

      .nav-link.active {
        background-color: rgba(255, 0, 0, 0.1);
        color: var(--ytm-accent);
        font-weight: 700;
        border-left-color: var(--ytm-accent);
      }

      .nav-link .bi {
        font-size: 1.25rem;
        width: 24px;
        text-align: center;
        transition: color 0.2s;
      }

      .nav-link:hover .bi {
        color: var(--ytm-primary-text);
      }

      .nav-link.active .bi {
        color: var(--ytm-accent);
      }

      /* Desktop Minimized Sidebar Mode */
      @media (min-width: 992px) {
        .sidebar.minimized {
          width: 80px;
        }
        .sidebar.minimized .nav-link {
          justify-content: center;
          padding-left: 0 !important;
          padding-right: 0 !important;
          margin-left: 0.5rem;
          margin-right: 0.5rem;
          border-radius: 12px !important;
        }
        .sidebar.minimized .nav-link span {
          display: none;
        }
        .sidebar.minimized .nav-link .bi {
          margin: 0;
          font-size: 1.5rem;
        }
        .sidebar.minimized .admin-profile-info,
        .sidebar.minimized .admin-profile-badge,
        .sidebar.minimized .sidebar-logo-text {
          display: none !important;
        }
        .sidebar.minimized #desktop-sidebar-toggle {
          margin-left: auto !important;
          margin-right: auto !important;
        }
        .sidebar.minimized .admin-profile-img {
          width: 44px !important;
          height: 44px !important;
          margin-bottom: 0 !important;
        }
        .sidebar.minimized .p-4.border-bottom {
          padding: 1rem 0 !important;
        }
      }

      /* Fullscreen IDE Mode */
      .app-container.ide-fullscreen .sidebar {
        display: none !important;
      }
      .app-container.ide-fullscreen .d-lg-none.p-3.border-bottom {
        display: none !important;
      }

      .offcanvas-lg {
        background-color: var(--ytm-surface) !important;
        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.8) !important;
      }

      .page-header {
        padding: 1.5rem 2rem 1.5rem 2rem;
      }

      .content-title {
        font-size: 2rem;
        font-weight: 700;
        margin-bottom: 0;
      }

      /* Unified Drive UI Design System */
      :root {
