                        JOIN users u ON a.user_id = u.id
                        $where_sql
                      ");
                      $stmt_count->execute($params);
                      $total_apps = $stmt_count->fetchColumn();
                      $total_app_pages = ceil($total_apps / $app_limit);

                      $stmt_apps = $db->prepare("
                        SELECT a.*, u.artist, u.email, u.banned 
                        FROM ban_appeals a
