                  foreach ($cols as $col) {
                    $cn = $col['name']; if (!array_key_exists($cn, $data)) continue;
                    if ($col['pk'] && strtolower($col['type']) === 'integer' && $data[$cn] === '') continue;
                    $insertCols[] = dbm_quote_ident($cn); $insertVals[] = $data[$cn] === '' && !isset($_POST['row_set'][$cn]) ? null : $data[$cn];
