                  $pkCol = dbm_get_pk_column($dbm_pdo, $curTable) ?: 'rowid'; $pkVal = $_POST['pk_val'] ?? ''; $data = $_POST['row'] ?? []; $setClauses = []; $params = [];
                  foreach ($data as $k => $v) { 
                    if ($v === '[BLOB_DATA]') continue; // Safety: Never overwrite existing un-editable BLOB arrays
