              const doIdePaste = async (targetPath) => {
                if (window.ideClipboard && window.ideClipboard.items.length > 0) {
                  const action = window.ideClipboard.action;
                  termLog(`Pasting ${window.ideClipboard.items.length} item(s) into ${targetPath || 'root'}...`);
  
                  let res = await driveFetch(action, { action: action, items: window.ideClipboard.items, target: targetPath }, targetPath);
  
                  if (res.success) {
                    window.ideClipboard = null; 
                    window.updateIdeClipboardUI();
                    loadTree(targetPath);
                    termLog('Paste successful.');
                  } else if (res.error) {
                    alert(res.error);
                  }
                }
              };
  
              const clipboardPasteBtn = document.getElementById('ide-btn-clipboard-paste');
              if (clipboardPasteBtn) {
                clipboardPasteBtn.onclick = () => { doIdePaste(window.currentIdeTreePath || ''); };
              }
  
              const clipboardCancelBtn = document.getElementById('ide-btn-cancel-clipboard');
              if (clipboardCancelBtn) {
                clipboardCancelBtn.onclick = () => {
                   window.ideClipboard = null;
                   window.updateIdeClipboardUI();
                };
              }
  
              const clipboardNewFolderBtn = document.getElementById('ide-btn-clipboard-new-folder');
              if (clipboardNewFolderBtn) {
                clipboardNewFolderBtn.onclick = () => {
                  const parentPath = window.currentIdeTreePath || '';
                  openIdeNewItemModal('folder', parentPath);
                };
              }
  
              document.getElementById('ide-btn-copy').onclick = () => {
                const pathStr = document.getElementById('ide-ctx-path').value;
                const paths = pathStr.split('|').filter(p => p);
                window.ideClipboard = { action: 'copy_items', items: paths };
                document.getElementById('ide-ctx-modal').style.display = 'none';
                termLog(`Copied ${paths.length} item(s) to clipboard.`);
                window.updateIdeClipboardUI();
                window.ideSelectedItems.clear();
                window.updateIdeSelectionUI();
              };
  
              document.getElementById('ide-btn-cut').onclick = () => {
                const pathStr = document.getElementById('ide-ctx-path').value;
                const paths = pathStr.split('|').filter(p => p);
                window.ideClipboard = { action: 'move_items', items: paths };
                document.getElementById('ide-ctx-modal').style.display = 'none';
                termLog(`Cut ${paths.length} item(s) to clipboard.`);
                window.updateIdeClipboardUI();
                window.ideSelectedItems.clear();
                window.updateIdeSelectionUI();
              };
  
              document.getElementById('ide-btn-paste').onclick = () => {
                const targetPath = document.getElementById('ide-ctx-path').value;
                document.getElementById('ide-ctx-modal').style.display = 'none';
                doIdePaste(targetPath);
              };
  
              document.getElementById('ide-btn-rename').onclick = () => {
                const path = document.getElementById('ide-ctx-path').value;
                document.getElementById('ide-ctx-modal').style.display = 'none';
                if (!path) return;
  
                const oldName = path.includes('/') ? path.substring(path.lastIndexOf('/') + 1) : path;
                const parentPath = path.includes('/') ? path.substring(0, path.lastIndexOf('/')) : '';
                currentRenameTarget = { path, parentPath, oldName };
  
                const renameInput = document.getElementById('ide-rename-input');
                renameInput.value = oldName;
  
                const modal = bootstrap.Modal.getOrCreateInstance(document.getElementById('ide-rename-modal'));
                modal.show();
                setTimeout(() => {
                  renameInput.focus();
                  renameInput.select();
                }, 150);
              };
  
              const handleRenameSubmit = async () => {
                const name = document.getElementById('ide-rename-input').value.trim();
                const { path, parentPath, oldName } = currentRenameTarget;
  
                if (name && name !== oldName && path) {
                  const submitBtn = document.getElementById('ide-rename-submit');
                  submitBtn.disabled = true;
                  submitBtn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';
  
                  const res = await driveFetch('rename', { action: 'rename', old: path, new: name }, parentPath);
                  submitBtn.disabled = false;
                  submitBtn.innerText = 'Rename';
  
                  if (res.success) {
                    const openFile = openFiles.find(f => f.path === path);
                    if (openFile) {
                      const newPath = parentPath ? parentPath + '/' + name : name;
                      openFile.path = newPath;
                      openFile.name = name;
                      openFile.ext = name.split('.').pop().toLowerCase();
                      if (currentPath === path) currentPath = newPath;
                      if (activeTabPath === path) activeTabPath = newPath;
                      localStorage.setItem('ide_open_files', JSON.stringify(openFiles));
                      localStorage.setItem('ide_active_tab', activeTabPath);
                      renderTabs();
                    }
                    loadTree(parentPath);
                    bootstrap.Modal.getInstance(document.getElementById('ide-rename-modal')).hide();
                  } else {
                    alert(res.error || 'Rename failed.');
                  }
                } else if (name === oldName) {
                  bootstrap.Modal.getInstance(document.getElementById('ide-rename-modal')).hide();
                }
              };
  
              document.getElementById('ide-rename-submit').onclick = handleRenameSubmit;
  
              document.getElementById('ide-rename-input').addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                  e.preventDefault();
                  handleRenameSubmit();
                }
              });
  
              window.toggleIdeTerminal = () => {
                const bp = document.getElementById('ide-bottom-panel');
                if(bp.classList.contains('active')) {
                  bp.classList.remove('active');
                } else {
                  bp.classList.add('active');
                  document.querySelectorAll('.panel-tab').forEach(t => t.classList.remove('active'));
                  document.querySelector('.panel-tab[data-target="terminal"]').classList.add('active');
                  document.querySelectorAll('.panel-pane').forEach(p => p.classList.remove('active'));
                  document.getElementById('pane-terminal').classList.add('active');
                }
                setTimeout(() => aceEditor.resize(true), 50);
              };
  
              window.switchIdeSidebar = (view) => {
                if (view === 'ai') {
                  if (typeof window.toggleAiWidget === 'function') window.toggleAiWidget();
                  return;
                }

                const sidebar = document.getElementById('ide-main-sidebar');
                const actionEl = document.getElementById('act-' + view);
                if (!sidebar || !actionEl) return;

                if (actionEl.classList.contains('active')) {
                  sidebar.classList.toggle('d-none');
                  actionEl.classList.toggle('active');
                  setTimeout(() => aceEditor.resize(true), 50);
                  return;
                }

                sidebar.classList.remove('d-none');
                document.querySelectorAll('.ide-activity-action').forEach(el => el.classList.remove('active'));
                actionEl.classList.add('active');

                document.getElementById('ide-file-tree').classList.add('d-none');
                document.getElementById('ide-git-tree').classList.add('d-none');
                document.getElementById('ide-history-tree').classList.add('d-none');
                document.getElementById('ide-trash-tree').classList.add('d-none');
  
                if (view === 'explorer') {
                  document.getElementById('ide-sidebar-title').innerHTML = '<span>EXPLORER</span><div class="d-flex gap-2 align-items-center"><i class="bi bi-search" style="cursor:pointer;" id="ide-tree-search" title="Search Files"></i><i class="bi bi-file-earmark-plus" style="cursor:pointer;" id="ide-tree-new-file" title="New File"></i><i class="bi bi-folder-plus" style="cursor:pointer;" id="ide-tree-new-folder" title="New Folder"></i><div class="dropdown d-flex align-items-center"><i class="bi bi-upload" style="cursor:pointer;" data-bs-toggle="dropdown" aria-expanded="false" title="Upload"></i><ul class="dropdown-menu dropdown-menu-dark shadow-lg border-secondary" style="font-size: 0.85rem; min-width: 150px; z-index: 1060;"><li><div class="dropdown-item py-2 d-flex align-items-center gap-2" style="cursor:pointer;" id="ide-tree-upload"><i class="bi bi-file-earmark-arrow-up"></i> Upload Files</div></li><li><div class="dropdown-item py-2 d-flex align-items-center gap-2" style="cursor:pointer;" id="ide-tree-upload-folder"><i class="bi bi-folder-symlink"></i> Upload Folder</div></li><li><div class="dropdown-item py-2 d-flex align-items-center gap-2" style="cursor:pointer;" id="ide-tree-upload-url"><i class="bi bi-link"></i> Upload via URL</div></li></ul></div><i class="bi bi-arrow-clockwise" style="cursor:pointer;" id="ide-refresh-tree" title="Refresh"></i></div>';
                  document.getElementById('ide-file-tree').classList.remove('d-none');
  
                  const btnSearch = document.getElementById('ide-tree-search');
                  if (btnSearch) btnSearch.onclick = () => {
                    const ideSearchContainer = document.getElementById('ide-sidebar-search-container');
                    const ideSearchInput = document.getElementById('ide-sidebar-search-input');
                    ideSearchContainer.classList.toggle('d-none');
                    if (!ideSearchContainer.classList.contains('d-none')) {
                      ideSearchInput.focus();
                    } else {
                      ideSearchInput.value = '';
                      ideSearchInput.dispatchEvent(new Event('input'));
                    }
                  };
  
                  const btnNewFile = document.getElementById('ide-tree-new-file');
                  if (btnNewFile) btnNewFile.onclick = () => {
                    const cp = window.currentIdeTreePath || '';
                    openIdeNewItemModal('file', cp);
                  };
                  const btnNewFolder = document.getElementById('ide-tree-new-folder');
                  if (btnNewFolder) btnNewFolder.onclick = () => {
                    const cp = window.currentIdeTreePath || '';
                    openIdeNewItemModal('folder', cp);
                  };
                  const btnUpload = document.getElementById('ide-tree-upload');
                  if (btnUpload) btnUpload.onclick = () => handleUploadClick(window.currentIdeTreePath || '', false);
                  const btnUploadFolder = document.getElementById('ide-tree-upload-folder');
                  if (btnUploadFolder) btnUploadFolder.onclick = () => handleUploadClick(window.currentIdeTreePath || '', true);
                  const btnUploadUrl = document.getElementById('ide-tree-upload-url');
                  if (btnUploadUrl) btnUploadUrl.onclick = () => handleUploadUrlClick(window.currentIdeTreePath || '');
                  const btnRefresh = document.getElementById('ide-refresh-tree');
                  if (btnRefresh) btnRefresh.onclick = () => loadTree(window.currentIdeTreePath || '');
                } else if(view === 'git') {
                  document.getElementById('ide-sidebar-title').innerHTML = '<span>GIT / ACTIVITY</span><div class="d-flex gap-2"><i class="bi bi-cloud-arrow-down" style="cursor:pointer;" onclick="window.gitAction(\'pull\')" title="Git Pull"></i><i class="bi bi-cloud-arrow-up" style="cursor:pointer;" onclick="window.gitAction(\'push\')" title="Git Push"></i><i class="bi bi-check2-circle" style="cursor:pointer;" onclick="window.gitAction(\'commit\')" title="Git Commit"></i></div>';
                  document.getElementById('ide-git-tree').classList.remove('d-none');
                  window.fetchGitLog();
                } else if(view === 'history') {
                  document.getElementById('ide-sidebar-title').innerHTML = '<span>FILE HISTORY</span>';
                  document.getElementById('ide-history-tree').classList.remove('d-none');
                } else if(view === 'trash') {
                  document.getElementById('ide-sidebar-title').innerHTML = '<span>TRASH</span><div class="d-flex gap-2"><i class="bi bi-trash2-fill text-danger" style="cursor:pointer;" onclick="window.emptyIdeTrash()" title="Empty Trash"></i><i class="bi bi-arrow-clockwise" style="cursor:pointer;" onclick="window.fetchIdeTrash()" title="Refresh"></i></div>';
                  document.getElementById('ide-trash-tree').classList.remove('d-none');
                  window.fetchIdeTrash();
                }
                setTimeout(() => aceEditor.resize(true), 50);
              };
  
              window.gitAction = async (action) => {
                let cmd = '';
                if (action === 'pull') cmd = 'git pull origin main';
                if (action === 'push') cmd = 'git push origin main';
                if (action === 'commit') {
                  const msg = prompt("Enter commit message:");
                  if (!msg) return;
                  cmd = `git add . && git commit -m "${msg.replace(/"/g, '\\"')}"`;
                }
  
                termLog(`Executing: ${cmd}`);
                try {
                  const res = await driveFetch('terminal_cmd', { action: 'terminal_cmd', cmd });
                  if (res && res.success) {
                    termLog(res.output);
                    window.fetchGitLog();
                  } else {
                    termLog(`<span class="text-danger">${res.output || 'Command failed'}</span>`);
                  }
                } catch (e) {
                  termLog(`<span class="text-danger">Error executing git command.</span>`);
                }
              };
  
              window.fetchGitLog = async () => {
                const gitPane = document.getElementById('ide-git-tree');
                if(!gitPane) return;
                gitPane.innerHTML = '<div class="text-center mt-4 text-secondary"><i class="spinner-border spinner-border-sm"></i> Loading Activity...</div>';
                try {
                  const resActivity = await fetch(`?access=admin&page=drive&api=true&action=activity`).then(r => r.json());
                  const resGit = await fetch(`?access=admin&page=drive&api=true&action=git_history`).then(r => r.json());
  
                  let html = '';
  
                  if (resGit && resGit.success && resGit.history) {
                    html += `<div class="mb-2 text-warning fw-bold border-bottom border-secondary pb-1">Git Repository History</div>`;
                    html += `<div class="mb-3 p-2 bg-dark rounded border border-secondary" style="font-family: monospace; white-space: pre-wrap; font-size: 0.75rem; color: #ccc;">${resGit.history}</div>`;
                  }
  
                  if(resActivity && resActivity.success) {
                    if (Object.keys(resActivity.activity).length === 0) {
                      html += '<div class="text-secondary p-2">No drive activity found.</div>';
                    } else {
                      for (const [group, items] of Object.entries(resActivity.activity)) {
                        html += `<div class="mb-2 text-white fw-bold border-bottom border-secondary pb-1">${group}</div>`;
                        items.forEach(item => {
                          const date = new Date(item.mtime * 1000);
                          const timeStr = date.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
                          html += `
                            <div class="d-flex flex-column bg-dark p-2 rounded mb-2 border border-secondary" style="cursor: pointer;" onclick="window.ideOpenTab('${item.path}')">
                              <div class="d-flex justify-content-between">
                                <span class="text-info">${timeStr}</span>
                                <span class="text-secondary" style="font-size: 0.7rem;">${item.action.toUpperCase()}</span>
                              </div>
                              <div class="text-white text-truncate mt-1">${item.name}</div>
                            </div>
                          `;
                        });
                      }
                    }
                  } else {
                    html += '<div class="text-danger p-2">Failed to fetch drive activity.</div>';
                  }
                  gitPane.innerHTML = html;
                } catch (e) {
                  gitPane.innerHTML = '<div class="text-danger p-2">Error communicating with server.</div>';
                }
              };
  
              window.fetchIdeTrash = async () => {
                const trashPane = document.getElementById('ide-trash-tree');
                if(!trashPane) return;
                trashPane.innerHTML = '<div class="text-center mt-4 text-secondary"><i class="spinner-border spinner-border-sm"></i> Loading Trash...</div>';
                try {
                  const res = await fetch(`?access=admin&page=drive&api=true&action=list_trash`).then(r => r.json());
                  if(res && res.success) {
                    if (!res.trash || res.trash.length === 0) {
                      trashPane.innerHTML = '<div class="text-secondary p-2 text-center mt-4"><i class="bi bi-trash2 fs-1 d-block mb-2 opacity-50"></i>Trash is empty.</div>';
                    } else {
                      let html = '';
                      res.trash.forEach(item => {
                        html += `
                          <div class="d-flex flex-column bg-dark p-2 rounded mb-2 border border-secondary" style="font-size: 0.8rem;">
                            <div class="fw-bold text-white text-truncate mb-1" title="${item.name}">${item.name}</div>
                            <div class="text-secondary small mb-1">From: ${item.original_parent || 'root'}</div>
                            <div class="text-secondary small mb-2">${item.deleted_at}</div>
                            <div class="d-flex justify-content-between gap-1">
                              <button class="btn btn-sm btn-outline-info py-0 px-2 fw-bold" style="font-size: 0.75rem;" onclick="window.restoreIdeTrash('${item.uniq}')"><i class="bi bi-arrow-counterclockwise"></i> Restore</button>
                              <button class="btn btn-sm btn-outline-danger py-0 px-2 fw-bold" style="font-size: 0.75rem;" onclick="window.deletePermIdeTrash('${item.uniq}')"><i class="bi bi-trash2"></i> Delete</button>
                            </div>
                          </div>
                        `;
                      });
                      trashPane.innerHTML = html;
                    }
                  } else {
                    trashPane.innerHTML = '<div class="text-danger p-2">Failed to load trash.</div>';
                  }
                } catch(e) {
                  trashPane.innerHTML = '<div class="text-danger p-2">Error connecting to server.</div>';
                }
              };
  
              window.restoreIdeTrash = async (uniq) => {
                termLog(`Restoring item from trash...`);
                const res = await driveFetch('restore_trash', { action: 'restore_trash', items: [uniq] });
                if (res && res.success) {
                  termLog(`Item restored successfully.`);
                  window.fetchIdeTrash();
                  loadTree();
                } else {
                  termLog(`Restore failed: ${res ? res.error : 'Unknown error'}`, true);
                }
              };
  
              window.deletePermIdeTrash = async (uniq) => {
                if (!confirm('Permanently delete this item? This action is irreversible.')) return;
                termLog(`Permanently deleting item...`);
                const res = await driveFetch('delete_perm', { action: 'delete_perm', items: [uniq] });
                if (res && res.success) {
                  termLog(`Item permanently deleted.`);
                  window.fetchIdeTrash();
                } else {
                  termLog(`Delete failed: ${res ? res.error : 'Unknown error'}`, true);
                }
              };
  
              window.emptyIdeTrash = async () => {
                if (!confirm('Empty entire Trash permanently? All items in Trash will be lost forever.')) return;
                termLog(`Emptying entire Trash...`);
                const res = await driveFetch('empty_trash', { action: 'empty_trash' });
                if (res && res.success) {
                  termLog(`Trash emptied successfully.`);
                  window.fetchIdeTrash();
                } else {
                  termLog(`Empty trash failed: ${res ? res.error : 'Unknown error'}`, true);
                }
              };
  
              const sidebarResizer = document.getElementById('ide-sidebar-resizer');
              const mainSidebar = document.getElementById('ide-main-sidebar');
              let isResizingSidebar = false;
              let sidebarRaf = null;
              
              if (sidebarResizer) {
                const startSidebarResize = (e) => {
                  isResizingSidebar = true;
                  sidebarResizer.classList.add('resizing');
                  document.body.style.cursor = 'col-resize';
                  const iframe = document.getElementById('ide-preview-iframe');
                  if (iframe) iframe.style.pointerEvents = 'none';
                  if (e.cancelable) e.preventDefault();
                };
                
                const moveSidebarResize = (e) => {
                  if (!isResizingSidebar) return;
                  const clientX = e.touches ? e.touches[0].clientX : e.clientX;
                  
                  if (sidebarRaf) cancelAnimationFrame(sidebarRaf);
                  sidebarRaf = requestAnimationFrame(() => {
                    const newW = clientX - mainSidebar.getBoundingClientRect().left;
                    if (newW > 150 && newW < 600) {
                      mainSidebar.style.width = newW + 'px';
                      aceEditor.resize(); // Fast resize without deep recalculation
                    }
                  });
                };

                const stopSidebarResize = () => {
                  if (isResizingSidebar) {
                    isResizingSidebar = false;
                    sidebarResizer.classList.remove('resizing');
                    document.body.style.cursor = 'default';
                    const iframe = document.getElementById('ide-preview-iframe');
                    if (iframe) iframe.style.pointerEvents = 'auto';
                    aceEditor.resize(true);
                  }
                };

                sidebarResizer.addEventListener('mousedown', startSidebarResize);
                sidebarResizer.addEventListener('touchstart', startSidebarResize, { passive: false });
                document.addEventListener('mousemove', moveSidebarResize);
                document.addEventListener('touchmove', moveSidebarResize, { passive: false });
                document.addEventListener('mouseup', stopSidebarResize);
                document.addEventListener('touchend', stopSidebarResize);
              }
  
              window.exportWorkspace = async () => {
                if(confirm("Download entire workspace as ZIP? This may take a while.")) {
                   window.location.href = "?access=admin&page=drive&batch=context&path=";
                }
              };
  
              const resizer = document.getElementById('ide-panel-resizer');
              let isResizing = false;
              let panelRaf = null;
              window.isColumnsLayout = localStorage.getItem('ide_panel_layout') === 'columns';
  
              if(resizer) {
                const startPanelResize = (e) => {
                  isResizing = true;
                  resizer.classList.add('resizing');
                  document.body.style.cursor = window.isColumnsLayout ? 'ew-resize' : 'ns-resize';
                  const iframe = document.getElementById('ide-preview-iframe');
                  if (iframe) iframe.style.pointerEvents = 'none';
                  if (e.cancelable) e.preventDefault();
                };

                const movePanelResize = (e) => {
                  if (!isResizing) return;
                  const bottomPanel = document.getElementById('ide-bottom-panel');
                  const splitContainer = document.getElementById('ide-split-container');
                  if (!bottomPanel || !splitContainer) return;
                  
                  const clientX = e.touches ? e.touches[0].clientX : e.clientX;
                  const clientY = e.touches ? e.touches[0].clientY : e.clientY;
                  
                  if (panelRaf) cancelAnimationFrame(panelRaf);
                  panelRaf = requestAnimationFrame(() => {
                    const rect = splitContainer.getBoundingClientRect();
                    
                    if (window.isColumnsLayout) {
                      const newW = rect.right - clientX;
                      if (newW > 150 && newW < rect.width - 150) {
                        bottomPanel.style.width = newW + 'px';
                        aceEditor.resize(); // Fast resize without deep recalculation
                      }
                    } else {
                      const newH = rect.bottom - clientY;
                      if (newH > 35 && newH < rect.height - 50) {
                        bottomPanel.style.height = newH + 'px';
                        aceEditor.resize(); // Fast resize without deep recalculation
                      }
                    }
                  });
                };

                const stopPanelResize = () => {
                  if (isResizing) {
                    isResizing = false;
                    resizer.classList.remove('resizing');
                    document.body.style.cursor = 'default';
                    const iframe = document.getElementById('ide-preview-iframe');
                    if (iframe) iframe.style.pointerEvents = 'auto';
                    aceEditor.resize(true);
                  }
                };

                resizer.addEventListener('mousedown', startPanelResize);
                resizer.addEventListener('touchstart', startPanelResize, { passive: false });
                document.addEventListener('mousemove', movePanelResize);
                document.addEventListener('touchmove', movePanelResize, { passive: false });
                document.addEventListener('mouseup', stopPanelResize);
                document.addEventListener('touchend', stopPanelResize);
              }

              const applyPanelLayout = (isColumns) => {
                const splitContainer = document.getElementById('ide-split-container');
                const bp = document.getElementById('ide-bottom-panel');
                const res = document.getElementById('ide-panel-resizer');
                const toggleBtn = document.getElementById('panel-layout-toggle');
                
                if (isColumns) {
                  splitContainer.style.flexDirection = 'row';
                  bp.style.height = '100%';
                  bp.style.width = '50%'; 
                  bp.style.borderLeft = '1px solid #2d2d2d';
                  bp.style.borderTop = 'none';
                  res.style.width = '4px';
                  res.style.height = '100%';
                  res.style.position = 'absolute';
                  res.style.left = '0';
                  res.style.top = '0';
                  res.style.cursor = 'ew-resize';
                  if (toggleBtn) toggleBtn.className = 'bi bi-layout-split text-info';
                } else {
                  splitContainer.style.flexDirection = 'column';
                  bp.style.width = '100%';
                  bp.style.height = '50%';
                  bp.style.borderLeft = 'none';
                  bp.style.borderTop = '1px solid #2d2d2d';
                  res.style.height = '4px';
                  res.style.width = '100%';
                  res.style.position = 'static';
                  res.style.cursor = 'ns-resize';
                  if (toggleBtn) toggleBtn.className = 'bi bi-layout-split';
                }
                setTimeout(() => aceEditor.resize(true), 50);
              };

              document.getElementById('panel-layout-toggle')?.addEventListener('click', () => {
                window.isColumnsLayout = !window.isColumnsLayout;
                localStorage.setItem('ide_panel_layout', window.isColumnsLayout ? 'columns' : 'rows');
                applyPanelLayout(window.isColumnsLayout);
              });
              
              if (window.isColumnsLayout) applyPanelLayout(true);

              document.querySelectorAll('#panel-live-toggle, #panel-live-toggle-m').forEach(btn => {
                btn.addEventListener('click', (e) => {
                  window.isLivePreview = !window.isLivePreview;
                  const icon = e.currentTarget.querySelector('i') || e.currentTarget;
                  if (window.isLivePreview) {
                    icon.className = 'bi bi-lightning-charge-fill text-warning';
                    window.updateIdeOutputPreview();
                  } else {
                    icon.className = 'bi bi-lightning-charge';
                  }
                });
              });
  
              if (window.ideKeydownHandler) {
                document.removeEventListener('keydown', window.ideKeydownHandler);
              }
              window.ideKeydownHandler = (e) => {
                if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') {
                  const ideCont = document.querySelector('.ide-container:not(.d-none)');
                  if (ideCont && window.getComputedStyle(ideCont).display !== 'none') {
                    e.preventDefault();
                    if (typeof window.saveCurrentFile === 'function') window.saveCurrentFile();
                  }
                }
              };
              document.addEventListener('keydown', window.ideKeydownHandler);
  
              document.getElementById('ide-find-btn').addEventListener('click', () => {
                if (aceEditor) aceEditor.execCommand('find');
              });
  
              (function() {
                const dispatchMouseClick = (target, touch) => {
                  if (!target) return;
                  const rect = target.getBoundingClientRect();
                  const clientX = touch ? touch.clientX : (rect.left + rect.width / 2);
                  const clientY = touch ? touch.clientY : (rect.top + rect.height / 2);
  
                  const eventInit = {
                    bubbles: true,
                    cancelable: true,
                    view: window,
                    detail: 1,
                    clientX: clientX,
                    clientY: clientY,
                    screenX: clientX,
                    screenY: clientY,
                    button: 0,
                    buttons: 1
                  };
  
                  target.dispatchEvent(new MouseEvent('mousedown', eventInit));
                  target.dispatchEvent(new MouseEvent('mouseup', eventInit));
                  target.dispatchEvent(new MouseEvent('click', eventInit));
                };
  
                let activeTouchTarget = null;
  
                document.addEventListener('touchstart', function(e) {
                  const target = e.target.closest('.ace_searchbtn, .ace_button, .ace_searchbtn_close, [action]');
                  if (target) {
                    activeTouchTarget = target;
                    e.preventDefault();
                    e.stopPropagation();
                  }
                }, { passive: false, capture: true });
  
                document.addEventListener('touchend', function(e) {
                  const target = e.target.closest('.ace_searchbtn, .ace_button, .ace_searchbtn_close, [action]') || activeTouchTarget;
                  if (target && target.closest('.ace_search')) {
                    e.preventDefault();
                    e.stopPropagation();
                    const touch = e.changedTouches ? e.changedTouches[0] : null;
                    dispatchMouseClick(target, touch);
                  }
                  activeTouchTarget = null;
                }, { passive: false, capture: true });
  
                document.addEventListener('keydown', function(e) {
                  if (e.target && e.target.classList && e.target.classList.contains('ace_search_field')) {
                    if (e.key === 'Enter' || e.keyCode === 13) {
                      e.preventDefault();
                      e.stopPropagation();
                      const searchBox = e.target.closest('.ace_search');
                      if (!searchBox) return;
  
                      const isReplaceInput = e.target.closest('.ace_replace_form');
                      if (isReplaceInput) {
                        const replaceBtn = searchBox.querySelector('[action="replaceAndFindNext"], [action="replace"], .ace_searchbtn[action="replace"]');
                        if (replaceBtn) dispatchMouseClick(replaceBtn);
                      } else {
                        if (e.shiftKey) {
                          const prevBtn = searchBox.querySelector('[action="findPrev"], .ace_searchbtn.prev, .prev');
                          if (prevBtn) dispatchMouseClick(prevBtn);
                        } else {
                          const nextBtn = searchBox.querySelector('[action="findNext"], .ace_searchbtn.next, .next');
                          if (nextBtn) dispatchMouseClick(nextBtn);
                        }
                      }
                    }
                  }
                }, true);
              })();
  
              window.updateIdeOutputPreview = () => {
                if (!previewIframe) return;
                if (!currentPath) {
                  previewIframe.removeAttribute('src');
                  previewIframe.srcdoc = '<!DOCTYPE html><html data-bs-theme="dark"><body style="background:#0a0a0a;color:#888;font-family:sans-serif;padding:20px;text-align:center;">No file selected for preview.</body></html>';
                  return;
                }
  
                const file = openFiles.find(f => f.path === currentPath);
                const ext = file ? file.ext.toLowerCase() : currentPath.split('.').pop().toLowerCase();
  
                if (ext === 'md' || ext === 'markdown') {
                  const content = aceEditor.getValue();
                  let parsed = content;
                  if (typeof marked !== 'undefined') {
                    try {
                      marked.use({ gfm: true, breaks: true });
                      parsed = marked.parse(content);
                    } catch(e) {}
                  }
                  previewIframe.removeAttribute('src');
                  previewIframe.srcdoc = `<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/github-markdown-css@5/github-markdown-dark.min.css"><style>body{background-color:#0d1117;color:#c9d1d9;margin:0;padding:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans",Helvetica,Arial,sans-serif;}.markdown-body{box-sizing:border-box;min-width:200px;max-width:980px;margin:0 auto;padding:32px;background-color:#0d1117 !important;}@media(max-width:767px){.markdown-body{padding:15px;}}</style></head><body><article class="markdown-body">${parsed}</article></body></html>`;
                  } else if (['html', 'htm', 'php'].includes(ext)) {
                  previewIframe.removeAttribute('srcdoc');
                  previewIframe.setAttribute('sandbox', 'allow-scripts allow-forms allow-same-origin allow-popups');
                  const xdebugKey = encodeURIComponent(localStorage.getItem('ide_xdebug_key') || 'IDE');
                  previewIframe.src = './' + currentPath + '?XDEBUG_SESSION=' + xdebugKey + '&XDEBUG_SESSION_START=' + xdebugKey + '&t=' + Date.now();
                } else if (['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg'].includes(ext)) {
                  const streamUrl = `?access=admin&page=drive&api=true&action=stream&file=${encodeURIComponent(currentPath)}`;
                  previewIframe.removeAttribute('src');
                  previewIframe.srcdoc = `<!DOCTYPE html><html><body style="background:#0a0a0a;margin:0;display:flex;align-items:center;justify-content:center;height:100vh;"><img src="${streamUrl}" style="max-width:90%;max-height:90%;object-fit:contain;"></body></html>`;
                } else {
                  const content = aceEditor.getValue();
                  const escapeHtml = (str) => (str || '').replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
                  previewIframe.removeAttribute('src');
                  previewIframe.srcdoc = `<!DOCTYPE html><html data-bs-theme="dark"><head><meta charset="utf-8"><style>body{background:#0a0a0a;color:#f8f8f2;font-family:monospace;padding:16px;margin:0;}pre{white-space:pre-wrap;word-break:break-all;margin:0;font-size:13px;line-height:1.5;}</style></head><body><pre>${escapeHtml(content)}</pre></body></html>`;
                }
              };
  
              document.getElementById('ide-preview-btn').addEventListener('click', () => {
                bottomPanel.classList.add('active');
                document.querySelectorAll('.panel-tab').forEach(t => t.classList.remove('active'));
                document.querySelector('.panel-tab[data-target="output"]').classList.add('active');
                document.querySelectorAll('.panel-pane').forEach(p => p.classList.remove('active'));
                document.getElementById('pane-output').classList.add('active');
  
                termLog(`Executing preview for ${currentPath || 'index'}...`);
                window.updateIdeOutputPreview();
              });
  
              document.querySelectorAll('.panel-tab').forEach(tab => {
                tab.addEventListener('click', () => {
                  document.querySelectorAll('.panel-tab').forEach(t => t.classList.remove('active'));
                  tab.classList.add('active');
                  document.querySelectorAll('.panel-pane').forEach(p => p.classList.remove('active'));
                  document.getElementById(`pane-${tab.dataset.target}`).classList.add('active');
                });
              });
  
              document.getElementById('panel-close').addEventListener('click', () => {
                bottomPanel.classList.remove('active');
              });
  
              document.getElementById('panel-fullscreen').addEventListener('click', (e) => {
                bottomPanel.classList.toggle('fullscreen');
                e.target.className = bottomPanel.classList.contains('fullscreen') ? 'bi bi-chevron-down' : 'bi bi-chevron-up';
                setTimeout(() => aceEditor.resize(true), 50);
              });
  
              const ideFullscreenBtn = document.getElementById('ide-fullscreen-btn');
              const appContainer = document.querySelector('.app-container');
              if (ideFullscreenBtn && appContainer) {
                const isSavedFullscreen = localStorage.getItem('admin_ide_fullscreen') === 'true';
                if (isSavedFullscreen) {
                  appContainer.classList.add('ide-fullscreen');
                  ideFullscreenBtn.innerHTML = '<i class="bi bi-fullscreen-exit"></i> Exit Fullscreen';
                }
                ideFullscreenBtn.addEventListener('click', () => {
                  const isFullscreen = appContainer.classList.toggle('ide-fullscreen');
                  localStorage.setItem('admin_ide_fullscreen', isFullscreen);
                  if (isFullscreen) {
                    ideFullscreenBtn.innerHTML = '<i class="bi bi-fullscreen-exit"></i> Exit Fullscreen';
                  } else {
                    ideFullscreenBtn.innerHTML = '<i class="bi bi-arrows-fullscreen"></i> Fullscreen';
                  }
                  setTimeout(() => aceEditor.resize(true), 300);
                });
              }
  
              document.getElementById('act-settings').addEventListener('click', () => {
                const modal = bootstrap.Modal.getOrCreateInstance(document.getElementById('ide-settings-modal'));
                document.getElementById('ide-setting-theme').value = localStorage.getItem('ide_theme') || "ace/theme/tomorrow_night_eighties";
                document.getElementById('ide-setting-indent').value = localStorage.getItem('ide_indent') || "2";
                document.getElementById('ide-setting-wrap').checked = localStorage.getItem('ide_wrap') === 'true';
                document.getElementById('ide-setting-autosave').checked = localStorage.getItem('ide_autosave') !== 'false';
                document.getElementById('ide-setting-show_wordcount').checked = localStorage.getItem('ide_show_wordcount') === 'true';
                document.getElementById('ide-setting-show_charcount').checked = localStorage.getItem('ide_show_charcount') === 'true';
              document.getElementById('ide-setting-xdebug').value = localStorage.getItem('ide_xdebug_key') || 'IDE';
  
              const cliToggle = document.getElementById('ide-setting-disable-cli');
                if (cliToggle) {
                   cliToggle.checked = localStorage.getItem('ide_disable_cli') === 'true';
                }
  
                const currentFontSize = localStorage.getItem('ide_fontsize') || '14';
                const fontInput = document.getElementById('ide-setting-fontsize');
                const fontVal = document.getElementById('ide-setting-fontsize-val');
                if (fontInput) fontInput.value = currentFontSize;
                if (fontVal) fontVal.innerText = currentFontSize + 'px';
  
                modal.show();
              });
  
              const fontInput = document.getElementById('ide-setting-fontsize');
              const fontVal = document.getElementById('ide-setting-fontsize-val');
              const fontMinus = document.getElementById('ide-fontsize-minus');
              const fontPlus = document.getElementById('ide-fontsize-plus');
  
              const updateFontSize = (newSize) => {
                const size = Math.max(10, Math.min(36, parseInt(newSize, 10)));
                localStorage.setItem('ide_fontsize', size.toString());
                if (fontInput) fontInput.value = size;
                if (fontVal) fontVal.innerText = size + 'px';
                aceEditor.setOption('fontSize', size + 'px');
              };
  
              if (fontInput) {
                fontInput.addEventListener('input', (e) => updateFontSize(e.target.value));
              }
              if (fontMinus) {
                fontMinus.addEventListener('click', () => {
                  const current = parseInt(localStorage.getItem('ide_fontsize') || '14', 10);
                  updateFontSize(current - 1);
                });
              }
              if (fontPlus) {
                fontPlus.addEventListener('click', () => {
                  const current = parseInt(localStorage.getItem('ide_fontsize') || '14', 10);
                  updateFontSize(current + 1);
                });
              }
  
              const cliToggle = document.getElementById('ide-setting-disable-cli');
              if (cliToggle) {
                 cliToggle.addEventListener('change', async (e) => {
                    localStorage.setItem('ide_disable_cli', e.target.checked.toString());
                    await driveFetch('toggle_cli', { disable: e.target.checked });
                 });
              }
  
              document.getElementById('ide-setting-xdebug').addEventListener('change', (e) => {
                localStorage.setItem('ide_xdebug_key', e.target.value);
              });

              ['theme', 'indent', 'wrap', 'autosave', 'show_wordcount', 'show_charcount'].forEach(key => {
                document.getElementById('ide-setting-' + key).addEventListener('change', (e) => {
                  const val = e.target.type === 'checkbox' ? e.target.checked.toString() : e.target.value;
                  localStorage.setItem('ide_' + key, val);
                  if (key === 'theme') aceEditor.setTheme(val);
                  if (key === 'wrap') aceEditor.setOption('wrap', val === 'true');
                  if (key === 'indent') {
                    aceEditor.session.setTabSize(val === 'tab' ? 4 : parseInt(val));
                    aceEditor.session.setUseSoftTabs(val !== 'tab');
                    updateIDEStatusBar();
                  }
                  if (key === 'show_wordcount' || key === 'show_charcount') updateIDEStatusBar();
                });
              });
  
              document.querySelectorAll('#panel-newtab, #panel-newtab-m').forEach(btn => {
                btn.addEventListener('click', () => {
                  const win = window.open('about:blank', '_blank');
                  if (win) {
                    if (previewIframe.srcdoc) {
                      win.document.open();
                      win.document.write(previewIframe.srcdoc);
                      win.document.close();
                    } else if (currentPath) {
                      win.location.href = './' + currentPath;
                    } else {
                      win.location.href = './';
                    }
                  }
                });
              });
  
              document.querySelectorAll('#panel-eruda, #panel-eruda-m').forEach(btn => {
                btn.addEventListener('click', () => {
                  if (!bottomPanel.classList.contains('active')) {
                    bottomPanel.classList.add('active');
                  }
                  document.querySelectorAll('.panel-tab').forEach(t => t.classList.remove('active'));
                  const outputTab = document.querySelector('.panel-tab[data-target="output"]');
                  if (outputTab) outputTab.classList.add('active');
                  document.querySelectorAll('.panel-pane').forEach(p => p.classList.remove('active'));
                  const paneOutput = document.getElementById('pane-output');
                  if (paneOutput) paneOutput.classList.add('active');
                  if (!previewIframe.contentWindow) return;
                  const doc = previewIframe.contentWindow.document;
                  if (doc.getElementById('eruda')) {
                    previewIframe.contentWindow.eruda.show();
                    return;
                  }
                  const script = doc.createElement('script');
                  script.src = 'https://cdn.jsdelivr.net/npm/eruda';
                  script.onload = () => {
                    const initScript = doc.createElement('script');
                    initScript.innerHTML = 'eruda.init(); eruda.show();';
                    doc.body.appendChild(initScript);
                  };
                  doc.head.appendChild(script);
                });
              });
  
              document.querySelectorAll('#panel-reload, #panel-reload-m').forEach(btn => {
                btn.addEventListener('click', () => {
                  if (previewIframe) {
                    window.updateIdeOutputPreview();
                    termLog('Hard reloading preview...');
                  }
                });
              });
  
              document.querySelectorAll('#panel-popup, #panel-popup-m').forEach(btn => {
                btn.addEventListener('click', () => {
                  const win = window.open('about:blank', 'PreviewWindow', 'width=800,height=600,resizable=yes,scrollbars=yes');
                  if (win) {
                    if (previewIframe.srcdoc) {
                      win.document.open();
                      win.document.write(previewIframe.srcdoc);
                      win.document.close();
                    } else if (previewIframe.src && previewIframe.src !== 'about:blank') {
                      win.location.href = previewIframe.src;
                    } else if (currentPath) {
                      win.location.href = './' + currentPath;
                    }
                  }
                });
              });
  
              document.querySelectorAll('#panel-clear, #panel-clear-m').forEach(btn => {
                btn.addEventListener('click', () => {
                  document.getElementById('terminal-logs').innerHTML = '';
                });
              });
  
              const termInput = document.getElementById('ide-terminal-input');
              if (termInput) {
                termInput.addEventListener('keydown', async (e) => {
                  if (e.key === 'Enter' && termInput.value.trim() !== '') {
                    const cmd = termInput.value.trim();
                    const termPrompt = '<?php echo htmlspecialchars($_SESSION['admin_email'] ?? 'admin@server'); ?>:~$';
                    termLog(`<span class="text-success">${termPrompt}</span> ${cmd}`);
                    termInput.value = '';
  
                    if (cmd === 'clear') {
                      document.getElementById('terminal-logs').innerHTML = '';
                    } else {
                      try {
                        const res = await driveFetch('terminal_cmd', { action: 'terminal_cmd', cmd });
                        if (res && res.success) {
                          termLog(res.output !== undefined && res.output !== null ? res.output : '');
                        } else {
                          termLog(`<span class="text-danger">${res?.error || res?.output || 'Command failed'}</span>`);
                        }
                      } catch (err) {
                        termLog(`<span class="text-danger">Failed to execute command.</span>`);
                      }
                    }
                  }
                });
              }
  
              document.getElementById('ide-refresh-tree').addEventListener('click', () => loadTree());
  
              const ideSearchInput = document.getElementById('ide-sidebar-search-input');
              const ideSearchContainer = document.getElementById('ide-sidebar-search-container');
  
              document.getElementById('ide-tree-search').addEventListener('click', () => {
                ideSearchContainer.classList.toggle('d-none');
                if (!ideSearchContainer.classList.contains('d-none')) {
                  ideSearchInput.focus();
                } else {
                  ideSearchInput.value = '';
                  ideSearchInput.dispatchEvent(new Event('input'));
                }
              });
  
              let ideSearchTimeout = null;
              ideSearchInput.addEventListener('input', (e) => {
                const q = e.target.value.trim();
                clearTimeout(ideSearchTimeout);
                if (q === '') {
                  loadTree();
                  return;
                }
  
                ideSearchTimeout = setTimeout(async () => {
                  const treeEl = document.getElementById('ide-file-tree');
                  if (!treeEl) return;
                  treeEl.innerHTML = '<div class="text-center mt-4 text-secondary"><i class="spinner-border spinner-border-sm"></i> Searching entire workspace...</div>';
  
                  try {
                    const res = await fetch(`?access=admin&page=drive&api=true&action=search_drive&q=${encodeURIComponent(q)}`);
                    if (!res.ok) throw new Error('Network error');
                    const data = await res.json();
  
                    if (data && data.success) {
                      if (data.folders.length === 0 && data.files.length === 0) {
                        treeEl.innerHTML = '<div class="text-secondary p-2 text-center mt-3">No files found matching your search.</div>';
                        return;
                      }
  
                      data.folders.forEach(f => f.name = f.path);
                      data.files.forEach(f => f.name = f.path);
                      renderTree(data, ''); 
                    } else {
                      treeEl.innerHTML = `<div class="text-danger p-2 text-center">Search failed: ${data.error || 'Unknown error'}</div>`;
                    }
                  } catch (err) {
                    treeEl.innerHTML = '<div class="text-danger p-2 text-center">Search connection error.</div>';
                  }
                }, 400);
              });
  
              const ideSidebar = document.getElementById('ide-main-sidebar');
              if (ideSidebar) {
                const scanIdeDroppedItems = async (items) => {
                  const files = [];
                  const paths = [];
  
                  const readAllEntries = async (dirReader) => {
                    let allEntries = [];
                    const read = async () => {
                      const entries = await new Promise((resolve) => dirReader.readEntries(resolve));
                      if (entries && entries.length > 0) {
                        allEntries = allEntries.concat(entries);
                        await read();
                      }
                    };
                    await read();
                    return allEntries;
                  };
  
                  const traverseEntry = async (entry, path = '') => {
                    if (entry.isFile) {
                      const file = await new Promise((resolve) => entry.file(resolve));
                      files.push(file);
                      paths.push(path + file.name);
                    } else if (entry.isDirectory) {
                      const dirReader = entry.createReader();
                      const entries = await readAllEntries(dirReader);
                      for (const childEntry of entries) {
                        await traverseEntry(childEntry, path + entry.name + '/');
                      }
                    }
                  };
  
                  for (let i = 0; i < items.length; i++) {
                    const entry = items[i].webkitGetAsEntry();
                    if (entry) await traverseEntry(entry);
                  }
  
                  return { files, paths };
                };
  
                ideSidebar.addEventListener('dragover', (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  ideSidebar.style.outline = '2px dashed #ff0000';
                  ideSidebar.style.outlineOffset = '-4px';
                  ideSidebar.style.backgroundColor = 'rgba(255, 0, 0, 0.08)';
                });
  
                ['dragleave', 'dragend'].forEach(evt => {
                  ideSidebar.addEventListener(evt, (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    ideSidebar.style.outline = 'none';
                    ideSidebar.style.backgroundColor = '#0a0a0a';
                  });
                });
  
                ideSidebar.addEventListener('drop', async (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  ideSidebar.style.outline = 'none';
                  ideSidebar.style.backgroundColor = '#0a0a0a';
  
                  if (e.dataTransfer.items && e.dataTransfer.items.length) {
                    termLog('Scanning dropped items...');
                    const { files, paths } = await scanIdeDroppedItems(e.dataTransfer.items);
                    if (files.length > 0) {
                      await window.ideChunkedUpload(files, paths, window.currentIdeTreePath || '');
                    }
                  }
                });
              }
  
              // ==========================================
              // AGENTIC AI CODING ASSISTANT (BRANCHING & PERMANENT HISTORY)
              // ==========================================
              let aiCurrentChatId = localStorage.getItem('ide_ai_current_chat_id') || null;
              let aiAllMessages = [];
              let aiActiveLeafId = null;
              let aiAttachedFiles = [];
              let isAiGenerating = false;
              let aiAbortController = null;
              let isAiSearchActive = localStorage.getItem('ide_ai_search') === 'true';
              let isAiThinkActive = localStorage.getItem('ide_ai_think') === 'true';

              // Render Uploaded File Pills
              window.renderAiAttachments = () => {
                const container = document.getElementById('ide-ai-attachments');
                if (!container) return;
                if (aiAttachedFiles.length === 0) {
                  container.innerHTML = '';
                  return;
                }
                container.innerHTML = aiAttachedFiles.map((f, idx) => `
                  <div class="badge bg-dark border border-secondary border-opacity-75 text-white d-flex align-items-center gap-1 py-1 px-2 shadow-sm" style="font-size: 0.72rem; border-radius: 6px;">
                    <i class="bi bi-file-earmark-code text-danger"></i>
                    <span class="text-truncate" style="max-width: 130px;" title="${f.name}">${f.name}</span>
                    <i class="bi bi-x ms-1 text-secondary" style="cursor: pointer;" onclick="removeAiAttachment(${idx})" title="Remove"></i>
                  </div>
                `).join('');
              };

              window.removeAiAttachment = (idx) => {
                aiAttachedFiles.splice(idx, 1);
                renderAiAttachments();
              };

              // Open Attached File Preview Modal
              window.openAiFileModal = (b64Name, b64Content) => {
                const name = decodeURIComponent(escape(window.atob(b64Name)));
                const content = decodeURIComponent(escape(window.atob(b64Content)));

                const titleEl = document.getElementById('ide-ai-file-modal-title');
                const contentEl = document.getElementById('ide-ai-file-modal-content');
                const copyBtn = document.getElementById('ide-ai-file-modal-copy');

                if (titleEl) titleEl.textContent = name;
                if (contentEl) contentEl.textContent = content;

                if (copyBtn) {
                  copyBtn.onclick = () => {
                    navigator.clipboard.writeText(content);
                    copyBtn.innerHTML = '<i class="bi bi-check-lg text-success me-1"></i> Copied!';
                    setTimeout(() => {
                      copyBtn.innerHTML = '<i class="bi bi-copy me-1"></i> Copy Code';
                    }, 2000);
                  };
                }

                const modal = bootstrap.Modal.getOrCreateInstance(document.getElementById('ide-ai-file-modal'));
                modal.show();
              };

              // File Attachment Listener (Supports Any Programming Language)
              document.getElementById('ide-ai-attach-btn')?.addEventListener('click', () => {
                document.getElementById('ide-ai-file-input')?.click();
              });

              document.getElementById('ide-ai-file-input')?.addEventListener('change', (e) => {
                const files = Array.from(e.target.files || []);
                if (files.length === 0) return;

                files.forEach(file => {
                  const reader = new FileReader();
                  reader.onload = (evt) => {
                    aiAttachedFiles.push({
                      name: file.name,
                      content: evt.target.result || ''
                    });
                    renderAiAttachments();
                  };
                  reader.readAsText(file);
                });
                e.target.value = '';
              });

              // Context Menu "Send to AI (Analyze / Fix)" for File Explorer
              document.getElementById('ide-btn-ai-analyze')?.addEventListener('click', async () => {
                const path = document.getElementById('ide-ctx-path').value;
                document.getElementById('ide-ctx-modal').style.display = 'none';
                if (!path) return;

                const fileName = path.split('/').pop();
                const res = await driveFetch('read', { action: 'read', file: path }, path);
                const content = res?.content || '';

                window.toggleAiWidget(true);
                aiAttachedFiles.push({ name: fileName, content: content });
                renderAiAttachments();

                const inputEl = document.getElementById('ide-ai-input');
                if (inputEl) {
                  inputEl.value = `Analyze and review ${fileName} for potential bugs, security issues, and performance optimizations. Provide detailed fixes.`;
                  inputEl.focus();
                }
              });

              // Context Menu "Ask AI to Fix / Explain" for Ace Editor Selection
              document.getElementById('ide-editor-ai-analyze')?.addEventListener('click', () => {
                document.getElementById('ide-editor-ctx-modal').style.display = 'none';
                if (!aceEditor) return;

                const selectedText = aceEditor.getSelectedText();
                const fileName = currentPath ? currentPath.split('/').pop() : 'Snippet';
                const codeToAnalyze = selectedText || aceEditor.getValue();

                window.toggleAiWidget(true);
                aiAttachedFiles.push({ name: fileName, content: codeToAnalyze });
                renderAiAttachments();

                const inputEl = document.getElementById('ide-ai-input');
                if (inputEl) {
                  inputEl.value = selectedText 
                    ? `Review, debug, and optimize this selected code snippet from ${fileName}:` 
                    : `Analyze and fix any bugs in ${fileName}:`;
                  inputEl.focus();
                }
              });

              const aiWidget = document.getElementById('ideAiHelperWidget');
              const aiHeader = document.getElementById('ideAiHeader');
              const aiBtn = document.getElementById('ide-ai-btn');
              const actAiBtn = document.getElementById('act-ai');

              window.toggleAiWidget = () => {
                if (!aiWidget) return;
                const isHidden = aiWidget.style.display === 'none' || !aiWidget.style.display;
                aiWidget.style.display = isHidden ? 'flex' : 'none';
                if (isHidden) {
                  document.getElementById('ide-ai-input')?.focus();
                  if (!aiCurrentChatId) initAiChatSession();
                }
              };

              // Tree Walking: Reconstruct active conversation thread from root to current leaf
              const getAiThreadPath = (leafId) => {
                let path = [];
                let currId = leafId;
                const msgMap = new Map();
                for (let m of aiAllMessages) msgMap.set(m.id, m);

                while (currId) {
                  let msg = msgMap.get(currId);
                  if (!msg) break;
                  path.unshift(msg);
                  currId = msg.parent_id;
                }
                return path;
              };

              // Tree Traversal: Find deepest leaf node along a branch
              const findAiDeepestLeaf = (startId) => {
                const childrenMap = new Map();
                for (let m of aiAllMessages) {
                  const pid = m.parent_id || '__root__';
                  if (!childrenMap.has(pid)) childrenMap.set(pid, []);
                  childrenMap.get(pid).push(m);
                }

                function traverse(id) {
                  const children = childrenMap.get(id) || [];
                  if (children.length === 0) return id;
                  return traverse(children[children.length - 1].id);
                }
                return traverse(startId);
              };

              // Branch Switching: Navigate between siblings (< 1/2 >)
              window.switchAiBranch = (msgId, direction) => {
                const msg = aiAllMessages.find(m => m.id === msgId);
                if (!msg) return;

                const siblings = aiAllMessages.filter(m => m.parent_id === msg.parent_id);
                const idx = siblings.findIndex(m => m.id === msgId);
                const targetIdx = idx + direction;

                if (targetIdx >= 0 && targetIdx < siblings.length) {
                  aiActiveLeafId = findAiDeepestLeaf(siblings[targetIdx].id);
                  renderAiMessages();
                }
              };

              const saveAiMessageToDB = async (msg) => {
                await driveFetch('ai_save_message', {
                  action: 'ai_save_message',
                  id: msg.id,
                  chat_id: msg.chat_id,
                  parent_id: msg.parent_id,
                  role: msg.role,
                  content: msg.content
                });
              };

              let aiHistoryPage = 1;
              let aiHistorySearchQuery = '';
              let aiHistoryChats = [];

              const loadAiChatsList = async (page = 1, append = false) => {
                aiHistoryPage = page;
                const listEl = document.getElementById('ide-ai-history-list');
                const totalEl = document.getElementById('ide-ai-history-total');
                if (!listEl) return;

                if (!append) {
                  listEl.innerHTML = '<div class="text-secondary small text-center my-4"><span class="spinner-border spinner-border-sm me-1"></span> Loading sessions...</div>';
                }

                const res = await driveFetch('ai_get_chats', {
                  action: 'ai_get_chats',
                  page: aiHistoryPage,
                  q: aiHistorySearchQuery
                });

                if (res && res.success) {
                  if (totalEl) totalEl.textContent = res.total || 0;
                  const fetched = res.chats || [];

                  if (append) {
                    aiHistoryChats = aiHistoryChats.concat(fetched);
                  } else {
                    aiHistoryChats = fetched;
                  }

                  if (aiHistoryChats.length === 0) {
                    listEl.innerHTML = '<div class="text-secondary small text-center my-4">' + (aiHistorySearchQuery ? 'No matching sessions found.' : 'No saved conversations yet.') + '</div>';
                    return;
                  }

                  listEl.innerHTML = aiHistoryChats.map(c => {
                    const isActive = c.id === aiCurrentChatId;
                    const isPinned = parseInt(c.pinned) === 1;
                    const dateStr = c.created_at ? new Date(c.created_at.replace(' ', 'T') + 'Z').toLocaleDateString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '';
                    const safeTitle = (c.title || 'Untitled Session').replace(/"/g, '&quot;');
                    const escapedTitle = (c.title || 'Untitled Session').replace(/'/g, "\\'");

                    return `
                      <div class="d-flex align-items-center justify-content-between p-2 rounded-3 mb-1 ${isActive ? 'bg-danger bg-opacity-25 border border-danger' : 'bg-dark border border-secondary border-opacity-50'}" style="cursor: pointer; transition: all 0.2s;" onclick="selectAiChatSession('${c.id}', '${escapedTitle}')">
                        <div class="d-flex align-items-center gap-2 min-width-0 flex-grow-1 me-2">
                          <i class="bi ${isPinned ? 'bi-pin-angle-fill text-warning' : 'bi-chat-left-text text-danger'} fs-6 flex-shrink-0"></i>
                          <div class="d-flex flex-column min-width-0 flex-grow-1">
                            <span class="text-white text-truncate fw-medium" style="font-size: 0.8rem;" title="${safeTitle}">${safeTitle}</span>
                            <span class="text-secondary text-truncate" style="font-size: 0.68rem;">${dateStr}</span>
                          </div>
                        </div>
                        <div class="d-flex align-items-center gap-1 flex-shrink-0" onclick="event.stopPropagation()">
                          <button class="btn btn-sm btn-link text-secondary p-0 text-decoration-none" onclick="toggleAiPinChat('${c.id}', ${isPinned ? 1 : 0})" title="${isPinned ? 'Unpin' : 'Pin to top'}">
                            <i class="bi ${isPinned ? 'bi-pin-angle-fill text-warning' : 'bi-pin-angle'}" style="font-size: 0.78rem;"></i>
                          </button>
                          <button class="btn btn-sm btn-link text-secondary p-0 text-decoration-none" onclick="renameAiChatSession('${c.id}', '${escapedTitle}')" title="Rename">
                            <i class="bi bi-pencil" style="font-size: 0.78rem;"></i>
                          </button>
                          <button class="btn btn-sm btn-link text-secondary p-0 text-decoration-none" onclick="deleteAiChatSession('${c.id}')" title="Delete">
                            <i class="bi bi-trash" style="font-size: 0.78rem;"></i>
                          </button>
                        </div>
                      </div>
                    `;
                  }).join('');

                  // Load More Pagination Trigger
                  if (res.has_more) {
                    const moreBtn = document.createElement('button');
                    moreBtn.className = 'btn btn-sm btn-outline-secondary w-100 py-1 mt-1 small text-white-50 border-dashed';
                    moreBtn.style.fontSize = '0.74rem';
                    moreBtn.innerHTML = '<i class="bi bi-chevron-down me-1"></i> Load Older Sessions (25)';
                    moreBtn.onclick = () => loadAiChatsList(aiHistoryPage + 1, true);
                    listEl.appendChild(moreBtn);
                  }
                } else {
                  listEl.innerHTML = '<div class="text-danger small text-center my-4">Failed to load chat history.</div>';
                }
              };

              window.toggleAiPinChat = async (chatId, currentPinned) => {
                await driveFetch('ai_pin_chat', {
                  action: 'ai_pin_chat',
                  chat_id: chatId,
                  pinned: currentPinned ? 0 : 1
                });
                loadAiChatsList(1, false);
              };

              window.renameAiChatSession = async (chatId, currentTitle) => {
                const newTitle = prompt('Enter session name:', currentTitle);
                if (newTitle && newTitle.trim() && newTitle.trim() !== currentTitle) {
                  await driveFetch('ai_rename_chat', {
                    action: 'ai_rename_chat',
                    chat_id: chatId,
                    title: newTitle.trim()
                  });
                  if (aiCurrentChatId === chatId) {
                    document.getElementById('ide-ai-chat-title').textContent = newTitle.trim();
                  }
                  loadAiChatsList(1, false);
                }
              };

              window.selectAiChatSession = async (chatId, title) => {
                aiCurrentChatId = chatId;
                localStorage.setItem('ide_ai_current_chat_id', chatId);
                document.getElementById('ide-ai-chat-title').textContent = title || 'Coding Session';
                document.getElementById('ide-ai-history-drawer')?.classList.add('d-none');

                const res = await driveFetch('ai_get_messages', { action: 'ai_get_messages', chat_id: chatId });
                if (res && res.success) {
                  aiAllMessages = res.messages || [];
                  aiActiveLeafId = aiAllMessages.length > 0 ? aiAllMessages[aiAllMessages.length - 1].id : null;
                }
                renderAiMessages();
              };

              window.deleteAiChatSession = async (chatId) => {
                if (!confirm('Delete this AI chat session?')) return;
                await driveFetch('ai_delete_chat', { action: 'ai_delete_chat', chat_id: chatId });
                if (aiCurrentChatId === chatId) {
                  initAiChatSession();
                } else {
                  loadAiChatsList(1, false);
                }
              };

              const initAiChatSession = async () => {
                const res = await driveFetch('ai_create_chat', { action: 'ai_create_chat', title: 'Session ' + new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) });
                if (res && res.success) {
                  aiCurrentChatId = res.chat_id;
                  localStorage.setItem('ide_ai_current_chat_id', aiCurrentChatId);
                  aiAllMessages = [];
                  aiActiveLeafId = null;
                  document.getElementById('ide-ai-chat-title').textContent = 'New Session';
                  document.getElementById('ide-ai-history-drawer')?.classList.add('d-none');
                  renderAiMessages();
                }
              };

              // Real-Time Search Debounce
              let aiHistorySearchTimeout = null;
              document.getElementById('ide-ai-history-search-input')?.addEventListener('input', (e) => {
                clearTimeout(aiHistorySearchTimeout);
                aiHistorySearchQuery = e.target.value.trim();
                aiHistorySearchTimeout = setTimeout(() => {
                  loadAiChatsList(1, false);
                }, 250);
              });

              document.getElementById('ide-ai-new-chat-btn')?.addEventListener('click', initAiChatSession);
              document.getElementById('ide-ai-history-new-btn')?.addEventListener('click', initAiChatSession);
              document.getElementById('ide-ai-history-toggle-btn')?.addEventListener('click', () => {
                const drawer = document.getElementById('ide-ai-history-drawer');
                drawer?.classList.toggle('d-none');
                if (!drawer?.classList.contains('d-none')) {
                  const searchInp = document.getElementById('ide-ai-history-search-input');
                  if (searchInp) searchInp.value = '';
                  aiHistorySearchQuery = '';
                  loadAiChatsList(1, false);
                }
              });
              document.getElementById('ide-ai-close-history-btn')?.addEventListener('click', () => {
                document.getElementById('ide-ai-history-drawer')?.classList.add('d-none');
              });

              if (aiBtn) aiBtn.onclick = window.toggleAiWidget;
              if (actAiBtn) actAiBtn.onclick = window.toggleAiWidget;
              document.getElementById('ide-ai-close-btn')?.addEventListener('click', () => {
                if (aiWidget) aiWidget.style.display = 'none';
              });

              // Draggable Popup Window Logic
              let isAiDragging = false, aiStartX = 0, aiStartY = 0, aiInitLeft = 0, aiInitTop = 0;
              if (aiHeader) {
                aiHeader.onmousedown = (e) => {
                  if (e.target.closest('button')) return;
                  isAiDragging = true;
                  aiStartX = e.clientX;
                  aiStartY = e.clientY;
                  const rect = aiWidget.getBoundingClientRect();
                  aiInitLeft = rect.left;
                  aiInitTop = rect.top;
                  aiWidget.style.bottom = 'auto';
                  aiWidget.style.right = 'auto';
                  aiWidget.style.left = aiInitLeft + 'px';
                  aiWidget.style.top = aiInitTop + 'px';
                  e.preventDefault();
                };
              }

              document.addEventListener('mousemove', (e) => {
                if (!isAiDragging || !aiWidget) return;
                const dx = e.clientX - aiStartX;
                const dy = e.clientY - aiStartY;
                aiWidget.style.left = Math.max(10, Math.min(window.innerWidth - aiWidget.offsetWidth - 10, aiInitLeft + dx)) + 'px';
                aiWidget.style.top = Math.max(10, Math.min(window.innerHeight - aiWidget.offsetHeight - 10, aiInitTop + dy)) + 'px';
              });

              document.addEventListener('mouseup', () => { isAiDragging = false; });

              // Toggles for Search and Think
              const btnSearch = document.getElementById('ide-ai-btn-search');
              const btnThink = document.getElementById('ide-ai-btn-think');

              const updateToggleButtons = () => {
                if (btnSearch) {
                  btnSearch.className = isAiSearchActive 
                    ? 'btn btn-sm btn-info text-dark fw-bold p-1 px-2 d-flex align-items-center gap-1 rounded-pill' 
                    : 'btn btn-sm btn-outline-secondary border-0 p-1 px-2 d-flex align-items-center gap-1 rounded-pill';
                }
                if (btnThink) {
                  btnThink.className = isAiThinkActive 
                    ? 'btn btn-sm btn-warning text-dark fw-bold p-1 px-2 d-flex align-items-center gap-1 rounded-pill' 
                    : 'btn btn-sm btn-outline-secondary border-0 p-1 px-2 d-flex align-items-center gap-1 rounded-pill';
                }
              };

              btnSearch?.addEventListener('click', () => {
                isAiSearchActive = !isAiSearchActive;
                localStorage.setItem('ide_ai_search', isAiSearchActive.toString());
                updateToggleButtons();
              });

              btnThink?.addEventListener('click', () => {
                isAiThinkActive = !isAiThinkActive;
                localStorage.setItem('ide_ai_think', isAiThinkActive.toString());
                updateToggleButtons();
              });

              updateToggleButtons();

              // Load AI Settings and enforce Super Admin permission UI
              const loadAiSettings = async () => {
                const res = await driveFetch('ai_get_settings', { action: 'ai_get_settings' });
                if (res && res.success) {
                  const provSelect = document.getElementById('ide-ai-setting-provider');
                  if (provSelect) {
                    provSelect.value = res.provider;
                    document.getElementById('ide-ai-gemini-fields')?.classList.toggle('d-none', res.provider !== 'gemini');
                    document.getElementById('ide-ai-hf-fields')?.classList.toggle('d-none', res.provider === 'gemini');
                  }

                  const geminiInp = document.getElementById('ide-ai-setting-gemini-token');
                  if (geminiInp) {
                    geminiInp.value = res.gemini_token;
                    geminiInp.disabled = !res.is_super_admin;
                    if (!res.is_super_admin) geminiInp.placeholder = res.has_gemini_token ? 'Configured by Super Admin' : 'Not configured';
                  }

                  const hfInp = document.getElementById('ide-ai-setting-hf-token');
                  if (hfInp) {
                    hfInp.value = res.hf_token;
                    hfInp.disabled = !res.is_super_admin;
                    if (!res.is_super_admin) hfInp.placeholder = res.has_hf_token ? 'Configured by Super Admin' : 'Not configured';
                  }

                  const gModel = document.getElementById('ide-ai-setting-gemini-model');
                  if (gModel) gModel.value = res.gemini_model;
                  const hfModel = document.getElementById('ide-ai-setting-hf-model');
                  if (hfModel) hfModel.value = res.hf_model;

                  const tag = document.getElementById('ide-ai-model-tag');
                  if (tag) tag.textContent = res.provider === 'gemini' ? res.gemini_model : res.hf_model.split('/').pop();
                }
              };

              const saveAiSettings = async () => {
                const payload = {
                  action: 'ai_save_settings',
                  provider: document.getElementById('ide-ai-setting-provider')?.value || 'gemini',
                  gemini_token: document.getElementById('ide-ai-setting-gemini-token')?.value || '',
                  hf_token: document.getElementById('ide-ai-setting-hf-token')?.value || '',
                  gemini_model: document.getElementById('ide-ai-setting-gemini-model')?.value || 'gemini-3.1-flash-lite',
                  hf_model: document.getElementById('ide-ai-setting-hf-model')?.value || 'Qwen/Qwen2.5-Coder-32B-Instruct'
                };
                await driveFetch('ai_save_settings', payload);
              };

              const ideSettingsModal = document.getElementById('ide-settings-modal');
              if (ideSettingsModal) {
                ideSettingsModal.addEventListener('hide.bs.modal', saveAiSettings);
                ideSettingsModal.addEventListener('show.bs.modal', loadAiSettings);
              }

              window.applyAiCodeSnippet = (b64Code, actionType) => {
                const code = decodeURIComponent(escape(window.atob(b64Code)));
                if (!aceEditor) return;

                if (actionType === 'replace_file') {
                  if (confirm('Replace the ENTIRE current file with this AI solution?')) {
                    aceEditor.setValue(code, -1);
                    termLog('AI code replaced entire file buffer.');
                  }
                } else if (actionType === 'replace_selection') {
                  const range = aceEditor.getSelectionRange();
                  aceEditor.session.replace(range, code);
                  termLog('AI code replaced editor selection.');
                } else {
                  aceEditor.insert(code);
                  termLog('AI code inserted at cursor position.');
                }
              };

              // Parser for Live Thinking and Output Rendering
              const parseAiContent = (rawText) => {
                let text = rawText || '';
                let searchHtml = '';
                let thinkHtml = '';

                text = text.replace(/<search>([\s\S]*?)<\/search>/gi, (_, p1) => {
                  searchHtml += `<div class="p-1 px-2 mb-2 rounded bg-info bg-opacity-10 border border-info border-opacity-25 text-info small"><i class="bi bi-globe me-1"></i> ${p1.trim()}</div>`;
                  return '';
                });

                // When Thinking mode is OFF: completely strip out any <think> blocks
                if (!isAiThinkActive) {
                  text = text
                    .replace(/<\s*(?:think|thinking|thought)\s*[^>]*>[\s\S]*?<\s*\/\s*(?:think|thinking|thought)\s*[^>]*>/gi, '')
                    .replace(/<\s*(?:think|thinking|thought)\s*[^>]*>[\s\S]*$/gi, '')
                    .trim();
                } else {
                  // When Thinking mode is ON: extract and render collapsible reasoning
                  let cleanText = text
                    .replace(/<\s*(?:think|thinking|thought)\s*[^>]*>/gi, '<think>')
                    .replace(/<\s*\/\s*(?:think|thinking|thought)\s*[^>]*>/gi, '</think>');

                  let firstClose = cleanText.indexOf('</think>');
                  let firstOpen = cleanText.indexOf('<think>');
                  if (firstClose !== -1 && (firstOpen === -1 || firstOpen > firstClose)) {
                    cleanText = '<think>' + cleanText;
                  }

                  let parts = cleanText.split('<think>');
                  let mainContent = parts[0];

                  for (let i = 1; i < parts.length; i++) {
                    let splitClose = parts[i].split('</think>');
                    let thoughtBlock = splitClose[0].trim();
                    if (thoughtBlock) {
                      thinkHtml += `<details class="p-2 mb-2 rounded bg-black bg-opacity-50 border border-secondary border-opacity-25 small text-secondary" open><summary class="fw-bold text-warning" style="cursor:pointer;"><i class="bi bi-lightbulb me-1"></i> Reasoning Process</summary><div class="mt-1 font-monospace" style="font-size:0.75rem; white-space:pre-wrap; color:#aaa;">${thoughtBlock}</div></details>`;
                    }
                    if (splitClose.length > 1) {
                      mainContent += splitClose.slice(1).join('</think>');
                    }
                  }
                  text = mainContent;
                }

                let parsedMarkdown = typeof marked !== 'undefined' ? marked.parse(text.trim()) : text;

                // Agentic Quick Action Buttons for codeblocks
                parsedMarkdown = parsedMarkdown.replace(/<pre><code class="language-([a-zA-Z0-9_\-]+)">([\s\S]*?)<\/code><\/pre>/gi, (match, lang, codeRaw) => {
                  const decodedCode = codeRaw.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#039;/g, "'");
                  const b64Code = window.btoa(unescape(encodeURIComponent(decodedCode)));
                  return `
                    <div class="position-relative my-2 rounded border border-secondary border-opacity-50 overflow-hidden">
                      <div class="d-flex align-items-center justify-content-between px-2 py-1 bg-dark border-bottom border-secondary border-opacity-25 small text-secondary">
                        <span class="fw-bold font-monospace text-uppercase" style="font-size: 0.7rem;">${lang}</span>
                        <div class="d-flex gap-1">
                          <button class="btn btn-sm btn-outline-light border-0 py-0 px-1" style="font-size: 0.72rem;" onclick="navigator.clipboard.writeText(decodeURIComponent(escape(window.atob('${b64Code}')))); this.innerText='Copied!';" title="Copy Code"><i class="bi bi-copy"></i></button>
                          <button class="btn btn-sm btn-outline-info border-0 py-0 px-1" style="font-size: 0.72rem;" onclick="window.applyAiCodeSnippet('${b64Code}', 'insert')" title="Insert at Cursor"><i class="bi bi-cursor-text"></i> Insert</button>
                          <button class="btn btn-sm btn-outline-warning border-0 py-0 px-1" style="font-size: 0.72rem;" onclick="window.applyAiCodeSnippet('${b64Code}', 'replace_file')" title="Replace Active File"><i class="bi bi-file-earmark-code"></i> Replace All</button>
                        </div>
                      </div>
                      ${match}
                    </div>`;
                });

                return searchHtml + thinkHtml + parsedMarkdown;
              };

              const renderAiMessages = () => {
                const container = document.getElementById('ide-ai-messages');
                if (!container) return;

                const thread = getAiThreadPath(aiActiveLeafId);

                if (thread.length === 0) {
                  container.innerHTML = `
                    <div class="text-secondary small text-center my-auto">
                      <i class="bi bi-stars text-danger fs-2 d-block mb-2"></i>
                      Ask AI to explain code, fix bugs, write features, or refactor.
                    </div>`;
                  return;
                }

                container.innerHTML = thread.map((m) => {
                  const isUser = m.role === 'user';
                  const siblings = aiAllMessages.filter(s => s.parent_id === m.parent_id);
                  const bIndex = siblings.findIndex(s => s.id === m.id);

                  let branchNavHtml = '';
                  if (siblings.length > 1) {
                    branchNavHtml = `
                      <div class="d-inline-flex align-items-center gap-1 bg-black bg-opacity-50 px-2 py-0 rounded border border-secondary border-opacity-50" style="font-size: 0.68rem;">
                        <button class="btn btn-sm btn-link text-white-50 p-0 text-decoration-none" ${bIndex === 0 ? 'disabled' : ''} onclick="switchAiBranch('${m.id}', -1)">‹</button>
                        <span class="text-white-50">${bIndex + 1}/${siblings.length}</span>
                        <button class="btn btn-sm btn-link text-white-50 p-0 text-decoration-none" ${bIndex === siblings.length - 1 ? 'disabled' : ''} onclick="switchAiBranch('${m.id}', 1)">›</button>
                      </div>`;
                  }

                  let parsedContent = '';
                  if (isUser) {
                    let safeText = m.content
                      .replace(/&/g, '&amp;')
                      .replace(/</g, '&lt;')
                      .replace(/>/g, '&gt;')
                      .replace(/"/g, '&quot;')
                      .replace(/'/g, '&#039;');

                    // Render interactive file badges exactly like phpchatai.txt
                    safeText = safeText.replace(/\[File:\s*(.*?)\]\n([\s\S]*?)\n\[End of File\]/g, (match, fName, fContent) => {
                      const rawContent = fContent.replace(/&#039;/g, "'").replace(/&quot;/g, '"').replace(/&gt;/g, '>').replace(/&lt;/g, '<').replace(/&amp;/g, '&');
                      const rawFName = fName.replace(/&#039;/g, "'").replace(/&quot;/g, '"').replace(/&gt;/g, '>').replace(/&lt;/g, '<').replace(/&amp;/g, '&');

                      const base64Content = window.btoa(unescape(encodeURIComponent(rawContent)));
                      const base64Name = window.btoa(unescape(encodeURIComponent(rawFName)));

                      return `
                        <div class="d-inline-flex align-items-center gap-2 bg-dark border border-secondary border-opacity-75 rounded-3 px-2 py-1 my-1 shadow-sm" style="cursor: pointer;" onclick="openAiFileModal('${base64Name}', '${base64Content}')" title="Click to view file">
                          <i class="bi bi-file-earmark-code text-danger"></i>
                          <span class="fw-medium text-white text-truncate" style="font-size: 0.76rem; max-width: 160px;">${rawFName}</span>
                        </div>
                      `;
                    });

                    parsedContent = safeText.replace(/\n/g, '<br>');
                  } else {
                    parsedContent = parseAiContent(m.content);
                    if (!parsedContent && isAiGenerating && m.id === aiActiveLeafId) {
                      parsedContent = '<span class="text-secondary fst-italic"><span class="spinner-border spinner-border-sm me-1" style="width: 12px; height: 12px;"></span> Generating solution...</span>';
                    }
                  }

                  return `
                    <div class="p-3 rounded-3 ${isUser ? 'bg-danger bg-opacity-10 border border-danger border-opacity-50 text-white ms-3' : 'bg-dark border border-secondary border-opacity-50 text-light me-3'}" style="font-size: 0.82rem; word-break: break-word;" id="aimsg-${m.id}">
                      <div class="d-flex align-items-center justify-content-between mb-2">
                        <div class="fw-bold small ${isUser ? 'text-danger' : 'text-info'}">
                          ${isUser ? '<i class="bi bi-person me-1"></i> You' : '<i class="bi bi-robot me-1"></i> AI Assistant'}
                        </div>
                        <div class="d-flex align-items-center gap-2">
                          ${branchNavHtml}
                          ${isUser ? `<button class="btn btn-sm btn-link text-secondary p-0 text-decoration-none" onclick="editAiPrompt('${m.id}')" title="Edit Prompt"><i class="bi bi-pencil" style="font-size:0.75rem;"></i></button>` : ''}
                        </div>
                      </div>
                      <div class="ai-msg-body">${parsedContent}</div>
                    </div>`;
                }).join('');

                container.scrollTop = container.scrollHeight;
              };

              const aiInputTextarea = document.getElementById('ide-ai-input');
              const adjustAiInputHeight = () => {
                if (!aiInputTextarea) return;
                aiInputTextarea.style.height = '36px';
                const scrollH = aiInputTextarea.scrollHeight;
                const newHeight = Math.max(36, Math.min(180, scrollH));
                aiInputTextarea.style.height = newHeight + 'px';
                aiInputTextarea.style.overflowY = scrollH > 180 ? 'auto' : 'hidden';
              };

              aiInputTextarea?.addEventListener('input', adjustAiInputHeight);

              window.editAiPrompt = (msgId) => {
                const msg = aiAllMessages.find(m => m.id === msgId);
                if (!msg) return;
                const inputEl = document.getElementById('ide-ai-input');
                if (inputEl) {
                  inputEl.value = msg.content;
                  adjustAiInputHeight();
                  inputEl.focus();
                  window.aiEditParentId = msg.parent_id;
                }
              };

              const stopAiGeneration = () => {
                if (aiAbortController) {
                  aiAbortController.abort();
                  aiAbortController = null;
                }
                isAiGenerating = false;
                document.getElementById('ide-ai-send-btn')?.classList.remove('d-none');
                document.getElementById('ide-ai-stop-btn')?.classList.add('d-none');
              };

              document.getElementById('ide-ai-stop-btn')?.addEventListener('click', stopAiGeneration);

              const sendAiMessage = async () => {
                if (isAiGenerating) return;

                const inputEl = document.getElementById('ide-ai-input');
                let prompt = inputEl.value.trim();
                if (!prompt && aiAttachedFiles.length === 0) return;
                if (!prompt && aiAttachedFiles.length > 0) {
                  prompt = 'Please inspect and analyze the attached code files.';
                }

                if (!aiCurrentChatId) {
                  await initAiChatSession();
                }

                // Standardized File Format Serialization according to phpchatai.txt reference
                let fullContent = prompt;
                if (aiAttachedFiles.length > 0) {
                  const filesBlock = aiAttachedFiles.map(f => `[File: ${f.name}]\n${f.content}\n[End of File]`).join('\n\n');
                  fullContent = fullContent ? (fullContent + '\n\n' + filesBlock) : filesBlock;
                  aiAttachedFiles = [];
                  renderAiAttachments();
                }

                // Automatic Chat Title Generation with Truncation on First User Turn
                const isFirstTurn = aiAllMessages.filter(m => m.role === 'user').length === 0;
                const currentTitle = document.getElementById('ide-ai-chat-title')?.textContent || '';
                if (isFirstTurn || currentTitle === 'New Session' || currentTitle.startsWith('Session ')) {
                  let cleanTitle = prompt
                    .replace(/\[File:\s*.*?\]\n[\s\S]*?\n\[End of File\]/g, '')
                    .replace(/```[\s\S]*?```/g, '')
                    .replace(/[#*`_~>\-\[\]\(\)\{\}\\\/]/g, '')
                    .replace(/\s+/g, ' ')
                    .trim();
                  if (!cleanTitle && fullContent.includes('[File:')) {
                    const match = fullContent.match(/\[File:\s*(.*?)\]/);
                    if (match) cleanTitle = match[1];
                  }
                  if (cleanTitle.length > 28) {
                    cleanTitle = cleanTitle.substring(0, 28).trim() + '...';
                  }
                  if (!cleanTitle) cleanTitle = 'Code Session';

                  driveFetch('ai_rename_chat', { action: 'ai_rename_chat', chat_id: aiCurrentChatId, title: cleanTitle });
                  const titleEl = document.getElementById('ide-ai-chat-title');
                  if (titleEl) titleEl.textContent = cleanTitle;
                }

                const attachActiveCode = document.getElementById('ide-ai-include-file')?.checked;
                let fileContext = '';
                if (attachActiveCode && currentPath && aceEditor) {
                  const code = aceEditor.getValue();
                  fileContext = `[File: ${currentPath}]\n${code}\n[End of File]`;
                }

                const parentId = window.aiEditParentId !== undefined ? window.aiEditParentId : aiActiveLeafId;
                window.aiEditParentId = undefined;

                const userMsgId = 'aim_' + Math.random().toString(36).substring(2, 9);
                const userMsg = {
                  id: userMsgId,
                  chat_id: aiCurrentChatId,
                  parent_id: parentId,
                  role: 'user',
                  content: fullContent
                };

                aiAllMessages.push(userMsg);
                aiActiveLeafId = userMsgId;
                await saveAiMessageToDB(userMsg);

                inputEl.value = '';
                adjustAiInputHeight();

                const aiMsgId = 'aim_' + Math.random().toString(36).substring(2, 9);
                const aiAssistantMsg = {
                  id: aiMsgId,
                  chat_id: aiCurrentChatId,
                  parent_id: userMsgId,
                  role: 'assistant',
                  content: isAiSearchActive ? '<search>Searching web sources...</search>' : ''
                };

                aiAllMessages.push(aiAssistantMsg);
                aiActiveLeafId = aiMsgId;
                renderAiMessages();

                isAiGenerating = true;
                document.getElementById('ide-ai-send-btn')?.classList.add('d-none');
                document.getElementById('ide-ai-stop-btn')?.classList.remove('d-none');

                aiAbortController = new AbortController();

                let searchContext = '';
                if (isAiSearchActive) {
                  try {
                    const cleanSearchPrompt = prompt.replace(/\[File:\s*.*?\]\n[\s\S]*?\n\[End of File\]/g, '').trim() || 'programming solution';
                    const searchRes = await driveFetch('ai_search', { action: 'ai_search', q: cleanSearchPrompt });
                    if (searchRes && searchRes.success && searchRes.context) {
                      searchContext = searchRes.context;
                      aiAssistantMsg.content = `<search>Analyzed ${searchRes.urls.length} web reference(s).</search>\n\n`;
                    }
                  } catch (e) {}
                  renderAiMessages();
                }

                try {
                  const csrfToken = '<?php echo $_SESSION['admin_csrf_token'] ?? ''; ?>';
                  const activeThread = getAiThreadPath(userMsgId);
                  const sanitizedMessages = activeThread.map(m => ({ role: m.role, content: m.content }));

                  const res = await fetch('?access=admin&page=drive&api=true', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrfToken },
                    body: JSON.stringify({
                      action: 'ai_chat',
                      csrf_token: csrfToken,
                      messages: sanitizedMessages,
                      file_context: fileContext,
                      search_context: searchContext,
                      think: isAiThinkActive
                    }),
                    signal: aiAbortController.signal
                  });

                  if (!res.ok) throw new Error(`HTTP ${res.status}`);

                  const reader = res.body.getReader();
                  const decoder = new TextDecoder('utf-8');
                  let sseBuffer = '';
                  let textBuffer = '';
                  let reasoningBuffer = '';

                  while (true) {
                    const { done, value } = await reader.read();
                    if (done) break;

                    sseBuffer += decoder.decode(value, { stream: true });
                    const lines = sseBuffer.split('\n');
                    sseBuffer = lines.pop();

                    for (let line of lines) {
                      line = line.trim();
                      if (!line) continue;

                      let dataStr = line;
                      if (line.startsWith('data: ')) dataStr = line.substring(6).trim();
                      else if (line.startsWith('{') && line.endsWith('}')) dataStr = line;
                      else continue;

                      if (dataStr === '[DONE]') continue;

                      try {
                        const parsed = JSON.parse(dataStr);

                        if (parsed.error || parsed.success === false) {
                          const errText = parsed.error ? (typeof parsed.error === 'object' ? (parsed.error.message || JSON.stringify(parsed.error)) : parsed.error) : (parsed.message || 'Unknown error');
                          aiAssistantMsg.content = `⚠️ **API Error**: ${errText}`;
                          renderAiMessages();
                          stopAiGeneration();
                          await saveAiMessageToDB(aiAssistantMsg);
                          return;
                        }

                        if (parsed.choices && parsed.choices[0].delta) {
                          const delta = parsed.choices[0].delta;
                          if (isAiThinkActive && (delta.reasoning_content || delta.reasoning || delta.thinking)) {
                            reasoningBuffer += delta.reasoning_content || delta.reasoning || delta.thinking;
                          }
                          if (delta.content) textBuffer += delta.content;
                        } else if (parsed.candidates && parsed.candidates[0].content && parsed.candidates[0].content.parts) {
                          const parts = parsed.candidates[0].content.parts;
                          for (let part of parts) {
                            if (part.thought) {
                              if (isAiThinkActive) reasoningBuffer += part.text;
                            } else if (part.text) {
                              textBuffer += part.text;
                            }
                          }
                        }

                        let combined = '';
                        if (searchContext) combined += `<search>Used web references.</search>\n\n`;
                        if (isAiThinkActive && reasoningBuffer) combined += '<think>\n' + reasoningBuffer + '\n</think>\n';
                        combined += textBuffer;
                        aiAssistantMsg.content = combined;
                        renderAiMessages();
                      } catch (e) {}
                    }
                  }
                } catch (err) {
                  if (err.name !== 'AbortError') {
                    aiAssistantMsg.content += `\n\n⚠️ **AI Error**: ${err.message}`;
                    renderAiMessages();
                  }
                } finally {
                  stopAiGeneration();
                  await saveAiMessageToDB(aiAssistantMsg);
                  loadAiChatsList();
                }
              };

              document.getElementById('ide-ai-send-btn')?.addEventListener('click', sendAiMessage);
              document.getElementById('ide-ai-input')?.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  sendAiMessage();
                } else {
                  setTimeout(adjustAiInputHeight, 0);
                }
              });

              // Boot invocations
              loadTree();
              loadAiSettings();
              if (aiCurrentChatId) {
                selectAiChatSession(aiCurrentChatId);
              }
              if (openFiles.length > 0) {
                renderTabs();
                if (activeTabPath) {
                  window.ideOpenTab(activeTabPath);
                } else {
                  window.ideOpenTab(openFiles[0].path);
                }
              }
            })();
          </script>

