            .hdm-preview-pane table {
              display: block;
              width: 100%;
              overflow-x: auto;
              -webkit-overflow-scrolling: touch;
              border-collapse: collapse;
              margin: 1.2rem 0;
              border: 1px solid var(--md-sys-color-outline-variant);
              border-radius: 8px;
