    <script>
      function openPermissionsModal(id, name, permsJson) {
        document.getElementById('perm-user-id').value = id;
        document.getElementById('perm-user-name').textContent = name;
        
        const checkboxes = document.querySelectorAll('#admin-permissions-modal input[type="checkbox"]');
        checkboxes.forEach(cb => cb.checked = false); // Clear previous states
        
        if (permsJson) {
          try {
            const perms = JSON.parse(permsJson);
            checkboxes.forEach(cb => {
              if (perms.includes(cb.value)) cb.checked = true;
            });
          } catch(e) {}
        }
        
        new bootstrap.Modal(document.getElementById('admin-permissions-modal')).show();
      }

      let currentRhUserId = null;
      let currentRhPage = 1;
      
      async function viewRhythmHistory(userId, artistName) {
        currentRhUserId = userId;
        currentRhPage = 1;
        document.getElementById('admin-rh-name').textContent = artistName;
        const modal = new bootstrap.Modal(document.getElementById('admin-rhythm-history-modal'));
        document.getElementById('admin-rh-body').innerHTML = '<div class="text-center py-4"><div class="spinner-border text-info"></div></div>';
        modal.show();
        loadRhythmHistory();
      }

      async function deleteRhythmScore(id) {
        if (!confirm("Are you sure you want to delete this score?")) return;
        
        const formData = new FormData();
        formData.append('delete_rhythm_score_ajax', '1');
        formData.append('score_id', id);
        formData.append('csrf_token', '<?php echo $_SESSION['admin_csrf_token']; ?>');
        
        try {
          const res = await fetch('?access=admin', {
            method: 'POST',
            body: formData
          });
          const data = await res.json();
          if (data.status === 'success') {
            const el = document.getElementById('admin-rh-score-' + id);
            if (el) el.remove();
          } else {
            alert("Failed to delete score.");
          }
        } catch (e) {
          alert("Error deleting score.");
        }
      }

      async function loadRhythmHistory(append = false) {
        const body = document.getElementById('admin-rh-body');
        if (append) {
          const btn = document.getElementById('admin-rh-load-more');
          if (btn) btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span> Loading...';
        }
        
        try {
          const res = await fetch(`?access=api&action=get_user_rhythm_scores&target_user_id=${currentRhUserId}&page=${currentRhPage}&api_key=ADMIN_SESSION_BYPASS`);
          const scores = await res.json();
          
          const oldBtn = document.getElementById('admin-rh-load-more-container');
          if (oldBtn) oldBtn.remove();

          if (scores && scores.length > 0) {
            const html = scores.map(s => {
              const total = parseInt(s.perfect) + parseInt(s.great) + parseInt(s.good) + parseInt(s.bad) + parseInt(s.miss);
              const acc = total > 0 ? ((s.perfect * 100 + s.great * 75 + s.good * 40 + s.bad * 10) / total).toFixed(2) : '0.00';
              const playedAt = s.played_at ? new Date(s.played_at.replace(' ', 'T')+'Z').toLocaleString() : 'Unknown';
                              
              // Flag suspicious bot activity (Perfect 100% precision on high combos)
              const suspicious = (acc === '100.00' && total > 50) || (s.max_combo > 500 && s.miss === 0) ? '<span class="badge bg-danger ms-2" title="Perfect Play / Bot Suspected"><i class="bi bi-exclamation-triangle-fill"></i> Suspicious</span>' : '';

              return `
                <div class="p-3 mb-3 rounded position-relative" style="background-color: var(--ytm-surface-2); border: 1px solid rgba(255,255,255,0.05);" id="admin-rh-score-${s.id}">
                  <button class="btn btn-sm btn-outline-danger border-0 position-absolute top-0 end-0 m-2" onclick="deleteRhythmScore(${s.id})" title="Delete Score"><i class="bi bi-trash2"></i></button>
                  <div class="d-flex justify-content-between align-items-start mb-2 pe-4">
                    <div>
                      <div class="fw-bold fs-6 text-white">${s.title} <span class="text-secondary small fw-normal">by ${s.artist}</span></div>
                      <div class="text-secondary small"><i class="bi bi-clock"></i> ${playedAt}</div>
                    </div>
                    <div class="text-end">
                      <span class="badge bg-info text-dark fw-bold">${s.difficulty.toUpperCase()}</span>
                      ${suspicious}
                    </div>
                  </div>
                  <div class="row g-2 mt-2 text-center small fw-bold">
                    <div class="col"><div class="bg-dark rounded p-1 text-white">Score<br><span class="text-info">${parseInt(s.score).toLocaleString()}</span></div></div>
                    <div class="col"><div class="bg-dark rounded p-1 text-white">Acc<br><span class="${acc === '100.00' ? 'text-danger' : 'text-success'}">${acc}%</span></div></div>
                    <div class="col"><div class="bg-dark rounded p-1 text-white">Combo<br>${s.max_combo}x</div></div>
                    <div class="col"><div class="bg-dark rounded p-1 text-white">P/G/M<br><span class="text-secondary">${s.perfect}/${s.great}/${s.miss}</span></div></div>
                  </div>
                </div>
              `;
            }).join('');

            if (currentRhPage === 1) body.innerHTML = html;
            else body.insertAdjacentHTML('beforeend', html);

            if (scores.length === 25) {
              body.insertAdjacentHTML('beforeend', `
                <div class="text-center mt-3 mb-2" id="admin-rh-load-more-container">
                  <button class="btn btn-outline-info rounded-pill px-4 fw-bold" id="admin-rh-load-more" onclick="currentRhPage++; loadRhythmHistory(true);">Load Older Plays</button>
                </div>
              `);
            }
          } else {
            if (currentRhPage === 1) body.innerHTML = '<div class="text-center text-secondary py-4">No rhythm game history found for this user.</div>';
          }
        } catch (e) {
          if (currentRhPage === 1) body.innerHTML = '<div class="text-center text-danger py-4">Failed to load history.</div>';
        }
      }
    </script>
    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js"></script>
  </body>
</html>
<?php
  exit;
}

function ensure_getid3() {
  $target_file = __DIR__ . '/getid3/getid3.php';
  if (file_exists($target_file)) {
    return true;
  }

  if (!class_exists('ZipArchive')) {
    return false;
  }

  $urls = [
    'james' => 'https://github.com/JamesHeinrich/getID3/archive/refs/heads/master.zip',
    'dango' => 'https://github.com/HirotakaDango/PHP-Music/archive/refs/heads/main.zip'
  ];

  $temp_zip = __DIR__ . '/getid3_temp.zip';

  // Helper function to recursively delete temporary directories
  $delete_folder = function ($dir) use (&$delete_folder) {
    if (!is_dir($dir)) return;
    $files = array_diff(scandir($dir), ['.', '..']);
    foreach ($files as $file) {
      (is_dir("$dir/$file")) ? $delete_folder("$dir/$file") : @unlink("$dir/$file");
    }
    return @rmdir($dir);
  };

  foreach ($urls as $source => $url) {
    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
    curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
    curl_setopt($ch, CURLOPT_TIMEOUT, 60);
    $data = curl_exec($ch);
    $http_code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);

    if ($http_code !== 200 || !$data) {
      $context = stream_context_create([
        'http' => ['timeout' => 60, 'follow_location' => true],
        'ssl'  => ['verify_peer' => false, 'verify_peer_name' => false]
      ]);
      $data = @file_get_contents($url, false, $context);
    }

    if ($data && strlen($data) > 1000) {
      @file_put_contents($temp_zip, $data);
      if (file_exists($temp_zip)) {
        $zip = new ZipArchive;
        if ($zip->open($temp_zip) === true) {
          $temp_extract_dir = __DIR__ . '/getid3_temp_extract';
          if (!is_dir($temp_extract_dir)) {
            @mkdir($temp_extract_dir, 0755, true);
          }
          $zip->extractTo($temp_extract_dir);
          $zip->close();

          $extracted_getid3_path = '';
          if ($source === 'james') {
            $extracted_getid3_path = $temp_extract_dir . '/getID3-master/getid3';
          } else {
            $extracted_getid3_path = $temp_extract_dir . '/PHP-Music-main/getid3';
          }

          if (is_dir($extracted_getid3_path)) {
            $target_dir = __DIR__ . '/getid3';
            if (!is_dir($target_dir)) {
              @mkdir($target_dir, 0755, true);
            }
            
            $copy_folder = function ($src, $dst) use (&$copy_folder) {
              $dir = opendir($src);
              @mkdir($dst, 0755, true);
              while (false !== ($file = readdir($dir))) {
                if (($file != '.') && ($file != '..')) {
                  if (is_dir($src . '/' . $file)) {
                    $copy_folder($src . '/' . $file, $dst . '/' . $file);
                  } else {
                    @copy($src . '/' . $file, $dst . '/' . $file);
                  }
                }
              }
              closedir($dir);
            };

            $copy_folder($extracted_getid3_path, $target_dir);
            $delete_folder($temp_extract_dir);
            @unlink($temp_zip);

            if (file_exists($target_file)) {
              return true;
            }
          }
          if (is_dir($temp_extract_dir)) {
            $delete_folder($temp_extract_dir);
          }
        }
        @unlink($temp_zip);
      }
    }
  }
  return false;
}

ensure_getid3();

// Setup Logic: If 0 users exist, first registration becomes Super Admin
try {
  $db_setup = get_db();
  if (function_exists('init_db')) { init_db($db_setup); }
  $user_count = $db_setup->query("SELECT COUNT(id) FROM users")->fetchColumn();
  
  if ($user_count == 0) {
    if (isset($_GET['action']) && $_GET['action'] === 'register') {
      $data = json_decode(file_get_contents('php://input'), true);
      $email = filter_var($data['email'], FILTER_VALIDATE_EMAIL);
      $artist = trim(htmlspecialchars($data['artist'] ?? '', ENT_QUOTES, 'UTF-8'));
      $password = $data['password'] ?? '';

      if ($email && !empty($artist) && strlen($password) >= 6) {
        $hash = password_hash($password, PASSWORD_DEFAULT);
        $initial = mb_strtoupper(mb_substr($artist, 0, 1, 'UTF-8'));
        $bg_color = '#ff0000';
        $svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><rect width="200" height="200" fill="'.$bg_color.'"/><text x="50%" y="50%" dominant-baseline="central" text-anchor="middle" font-family="Arial, sans-serif" font-size="100" font-weight="bold" fill="#ffffff">' . htmlspecialchars($initial) . '</text></svg>';
        
        $stmt = $db_setup->prepare("INSERT INTO users (email, artist, password_hash, verified, is_admin, status, profile_picture, profile_picture_type) VALUES (?, ?, ?, 'yes', 1, 'super_admin', ?, 'image/svg+xml')");
        $stmt->execute([$email, $artist, $hash, $svg]);
        
        $_SESSION['user_id'] = $db_setup->lastInsertId();
        $_SESSION['user_artist'] = $artist;
        
        header('Content-Type: application/json; charset=utf-8');
        echo json_encode(['status' => 'success', 'message' => 'Super Admin Account Created!']);
        exit;
      } else {
        header('Content-Type: application/json; charset=utf-8');
        echo json_encode(['status' => 'error', 'message' => 'Invalid data. Password needs 6+ characters.']);
        exit;
      }
    } elseif (!isset($_GET['action']) && !isset($_GET['access'])) {
      // Intercept normal page load and force Setup UI
      ?>
      <!DOCTYPE html>
      <html lang="en" data-bs-theme="dark">
        <head>
          <meta charset="UTF-8">
          <meta name="viewport" content="width=device-width, initial-scale=1.0">
          <title>Setup - PHP Music</title>
          <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet">
          <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css">
          <style>
            body { background-color: #030303; color: #fff; display: flex; align-items: center; justify-content: center; min-height: 100vh; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; }
            .setup-card { background: #121212; border: 1px solid #333; border-radius: 16px; padding: 2.5rem; width: 100%; max-width: 450px; box-shadow: 0 10px 40px rgba(0,0,0,0.8); }
            .form-control { background-color: #222; border: 1px solid #444; color: #fff; padding: 0.75rem 1rem; border-radius: 8px; }
            .form-control:focus { background-color: #2a2a2a; border-color: #ff3333; color: #fff; box-shadow: 0 0 0 0.25rem rgba(255, 51, 51, 0.25); }
          </style>
        </head>
        <body>
          <div class="setup-card">
            <div class="text-center mb-4">
              <i class="bi bi-hdd-network text-danger" style="font-size: 3.5rem;"></i>
              <h3 class="fw-bold mt-2">PHP Music Setup</h3>
              <p class="text-secondary small">Welcome! Create your initial Super Admin account to initialize the database and begin.</p>
            </div>
            <div id="setup-alert" class="alert alert-danger d-none small fw-bold"></div>
            <form id="setup-form">
              <div class="mb-3">
                <label class="form-label text-secondary small fw-bold" style="letter-spacing: 1px;">ARTIST / DISPLAY NAME</label>
                <input type="text" id="setup-artist" class="form-control" required placeholder="e.g. System Admin">
              </div>
              <div class="mb-3">
                <label class="form-label text-secondary small fw-bold" style="letter-spacing: 1px;">ADMIN EMAIL</label>
                <input type="email" id="setup-email" class="form-control" required placeholder="admin@example.com">
              </div>
              <div class="mb-4">
                <label class="form-label text-secondary small fw-bold" style="letter-spacing: 1px;">SECURE PASSWORD</label>
                <input type="password" id="setup-password" class="form-control" required minlength="6" placeholder="Minimum 6 characters">
              </div>
              <button type="submit" id="setup-btn" class="btn btn-danger w-100 fw-bold py-3 rounded-pill shadow-lg">Initialize Server</button>
            </form>
          </div>
          <script>
            document.getElementById('setup-form').addEventListener('submit', async (e) => {
              e.preventDefault();
              const btn = document.getElementById('setup-btn');
              const alertBox = document.getElementById('setup-alert');
              btn.disabled = true;
              btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span> Creating...';
              alertBox.classList.add('d-none');
              
              try {
                const res = await fetch('?action=register', {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({
                    artist: document.getElementById('setup-artist').value,
                    email: document.getElementById('setup-email').value,
                    password: document.getElementById('setup-password').value
                  })
                });
                const data = await res.json();
                if (data && data.status === 'success') {
                  btn.classList.replace('btn-danger', 'btn-success');
                  btn.innerHTML = '<i class="bi bi-check-circle-fill me-2"></i> Setup Complete!';
                  setTimeout(() => window.location.reload(), 1500);
                } else {
                  alertBox.textContent = data?.message || 'Validation error occurred';
                  alertBox.classList.remove('d-none');
                  btn.disabled = false;
                  btn.textContent = 'Initialize Server';
                }
              } catch (err) {
                alertBox.textContent = 'Network error during setup';
                alertBox.classList.remove('d-none');
                btn.disabled = false;
                btn.textContent = 'Initialize Server';
              }
            });
          </script>
        </body>
      </html>
      <?php
      exit;
    }
  }
} catch (Exception $e) {}

