function extract_safe_tag($comments, $tag, $fallback = '') {
  if (!empty($comments[$tag]) && is_array($comments[$tag])) {
    $val = $comments[$tag][0];
    if ($val === null) return $fallback;
    
    // FIX 1: Remove double-encoded Mojibake strings appended with a slash
    // 'Ãƒ' is the classic signature of a UTF-8 string corrupted into Latin-1.
    $val = preg_replace('/\s*\/\s*[ÃƒÃ£Ã¤Ã¥Ã¦Ã§Ã¨Ã©].*/', '', (string)$val);
    
    // FIX 2: Remove exact duplicate strings appended with a slash (e.g. "Title / Title")
    if (strpos($val, '/') !== false) {
      $parts = explode('/', $val, 2);
      if (isset($parts[1]) && trim($parts[0]) === trim($parts[1])) {
        $val = trim($parts[0]);
      }
    }
    
    if (!mb_check_encoding($val, 'UTF-8')) {
      $val = mb_convert_encoding($val, 'UTF-8', 'auto');
    }
    return trim($val) !== '' ? trim($val) : $fallback;
  }
  return $fallback;
}

function send_json($data) {
  header('Content-Type: application/json; charset=utf-8');
  echo json_encode($data, JSON_INVALID_UTF8_SUBSTITUTE);
  exit;
}

$is_secure = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ||
             ($_SERVER['SERVER_PORT'] == 443) ||
             (!empty($_SERVER['HTTP_X_FORWARDED_PROTO']) && strtolower($_SERVER['HTTP_X_FORWARDED_PROTO']) == 'https') ||
             (!empty($_SERVER['HTTP_X_FORWARDED_SSL']) && strtolower($_SERVER['HTTP_X_FORWARDED_SSL']) == 'on');
$protocol = $is_secure ? "https://" : "http://";
$domainName = $_SERVER['HTTP_HOST'];
$base_app_url = $protocol . $domainName . strtok($_SERVER["REQUEST_URI"], '?');
$current_url = $protocol . $domainName . $_SERVER['REQUEST_URI'];

$initialViewJS = '';
$og_title = "PHP Music";
$og_desc = "A simple, fast music player with user accounts and uploads.";
$og_image = $base_app_url . "?action=get_app_icon&size=512&ext=.jpg";

if (isset($_GET['share_type'])) {
  $db_for_share = get_db();
  $share_type = $_GET['share_type'];
  $view_config = null;

  switch ($share_type) {
    case 'blog':
      $share_id = $_GET['id'] ?? null;
      $stmt = $db_for_share->prepare("SELECT title, user_id FROM blogs WHERE public_id = ? AND status = 'public'");
      $stmt->execute([$share_id]);
      $blog = $stmt->fetch();
      if ($blog) {
        $og_title = htmlspecialchars($blog['title']) . " - Blog";
        $og_desc = "Read this blog post on PHP Music.";
        $view_config = ['type' => 'view_blog', 'param' => $share_id];
      }
      break;

    case 'song':
      $share_id = (int)($_GET['id'] ?? 0);
      $playlist_id = $_GET['playlist_id'] ?? null;
      $stmt = $db_for_share->prepare("SELECT title, artist, album, user_id FROM music WHERE id = ?");
      $stmt->execute([$share_id]);
      $song_info = $stmt->fetch();
      if ($song_info) {
        $og_title = htmlspecialchars($song_info['title']) . " - " . htmlspecialchars($song_info['artist']);
        $og_desc = "Listen to " . htmlspecialchars($song_info['title']) . " from the album " . htmlspecialchars($song_info['album']) . " on PHP Music.";
        $og_image = $base_app_url . "?action=get_image&id=" . $share_id . "&ext=.jpg";
        
        if ($playlist_id) {
          $view_config = [
            'type' => 'playlist_songs',
            'param' => $playlist_id,
            'sort' => 'manual_order',
            'highlight' => $share_id
          ];
        } else {
          $view_config = [
            'type' => 'album_songs',
            'param' => rawurlencode($song_info['album']),
            'sort' => 'title_asc',
            'highlight' => $share_id,
            'filter_user_id' => $song_info['user_id']
          ];
        }
      }
      break;

    case 'album':
      $album_name = $_GET['album_name'] ?? $_GET['id'] ?? null;
      $artist_id = $_GET['artist_id'] ?? null;
      $artist_name = $_GET['artist_name'] ?? null;
      if ($album_name) {
        $og_title = htmlspecialchars($album_name) . " - Album";
        $og_desc = "Listen to this album on PHP Music.";
        $view_config = ['type' => 'album_songs', 'param' => $album_name, 'sort' => 'title_asc'];
        
        $stmt_cover = $db_for_share->prepare("SELECT id FROM music WHERE album = ? ORDER BY id DESC LIMIT 1");
        $stmt_cover->execute([$album_name]);
        $cover_id = $stmt_cover->fetchColumn();
        if ($cover_id) {
            $og_image = $base_app_url . "?action=get_image&id=" . $cover_id . "&ext=.jpg";
        }
        
        if ($artist_id) {
          $view_config['filter_user_id'] = (int)$artist_id;
        }
        if ($artist_name) {
          $view_config['artist_name'] = $artist_name;
          $og_desc = "Listen to the album " . htmlspecialchars($album_name) . " by " . htmlspecialchars($artist_name) . " on PHP Music.";
        }
      }
      break;

    case 'artist':
      $share_id = $_GET['id'] ?? null;
      if (is_numeric($share_id)) {
        $stmt = $db_for_share->prepare("SELECT artist FROM users WHERE id = ?");
        $stmt->execute([(int)$share_id]);
        $artist_name = $stmt->fetchColumn();
        if ($artist_name) {
          $og_title = htmlspecialchars($artist_name) . " - Artist";
          $og_desc = "Listen to " . htmlspecialchars($artist_name) . " on PHP Music.";
          $og_image = $base_app_url . "?action=get_profile_picture&id=" . (int)$share_id . "&ext=.jpg";
          $view_config = ['type' => 'artist_songs', 'param' => $artist_name, 'sort' => 'album_asc', 'filter_user_id' => (int)$share_id];
        }
      } else if ($share_id) {
        $og_title = htmlspecialchars($share_id) . " - Artist";
        $og_desc = "Listen to " . htmlspecialchars($share_id) . " on PHP Music.";
        
        $stmt_cover = $db_for_share->prepare("SELECT id FROM music WHERE match_artist(artist, ?) = 1 ORDER BY id DESC LIMIT 1");
        $stmt_cover->execute([$share_id]);
        $cover_id = $stmt_cover->fetchColumn();
        if ($cover_id) {
            $og_image = $base_app_url . "?action=get_image&id=" . $cover_id . "&ext=.jpg";
        }
        
        $view_config = ['type' => 'artist_songs', 'param' => $share_id, 'sort' => 'album_asc'];
      }
      break;

    case 'playlist':
      $share_id = $_GET['id'] ?? null;
      $stmt = $db_for_share->prepare("SELECT id, name FROM playlists WHERE public_id = ?");
      $stmt->execute([$share_id]);
      $pl = $stmt->fetch();
      if ($pl) {
        $og_title = htmlspecialchars($pl['name']) . " - Playlist";
        $og_desc = "Listen to this playlist on PHP Music.";
        $view_config = ['type' => 'playlist_songs', 'param' => $share_id, 'sort' => 'manual_order'];
        
        $stmt_cover = $db_for_share->prepare("SELECT song_id FROM playlist_songs WHERE playlist_id = ? ORDER BY added_at DESC LIMIT 1");
        $stmt_cover->execute([$pl['id']]);
        $cover_id = $stmt_cover->fetchColumn();
        if ($cover_id) {
            $og_image = $base_app_url . "?action=get_image&id=" . $cover_id . "&ext=.jpg";
        }
      }
      break;

    case 'series':
    case 'manga':
      $share_id = $_GET['id'] ?? null;
      $stmt = $db_for_share->prepare("SELECT id, title, description FROM art_series WHERE public_id = ?");
      $stmt->execute([$share_id]);
      $series_data = $stmt->fetch();
      if ($series_data) {
        $og_title = htmlspecialchars($series_data['title']) . " - Manga Series";
        $og_desc = htmlspecialchars(substr($series_data['description'] ?? 'Read this manga series on PHP Music', 0, 150));
        
        $stmt_cover = $db_for_share->prepare("SELECT file_path FROM art_files WHERE art_id IN (SELECT id FROM arts WHERE series_id = ?) ORDER BY id DESC, sort_order ASC LIMIT 1");
        $stmt_cover->execute([$series_data['id']]);
        $cover_path = $stmt_cover->fetchColumn();
        if ($cover_path) {
            $og_image = $base_app_url . "?action=get_art_image&path=" . urlencode($cover_path);
        }
        $view_config = ['type' => 'view_series', 'param' => $share_id, 'sort' => ''];
      }
      break;

    case 'mix':
      $share_id = $_GET['id'] ?? null;
      $stmt = $db_for_share->prepare("SELECT id, name, image_id FROM mixes WHERE public_id = ?");
      $stmt->execute([$share_id]);
      $mix_data = $stmt->fetch();
      if ($mix_data) {
        $og_title = htmlspecialchars($mix_data['name']) . " - Mix";
        $og_desc = "Listen to this custom mix on PHP Music.";
        if ($mix_data['image_id']) {
            $og_image = $base_app_url . "?action=get_image&id=" . $mix_data['image_id'] . "&ext=.jpg";
        }
        $view_config = ['type' => 'mix_songs', 'param' => $share_id, 'sort' => 'manual_order'];
      }
      break;

    case 'game':
      $share_id = (int)($_GET['id'] ?? 0);
      $artist_id = isset($_GET['artist_id']) ? (int)$_GET['artist_id'] : null;
      $artist_name = $_GET['artist_name'] ?? null;

      if ($artist_id || $artist_name) {
        $og_title = "Play " . htmlspecialchars($artist_name ?: 'Artist') . " - Rhythm Game";
        $og_desc = "Challenge my scores on " . htmlspecialchars($artist_name ?: 'Artist') . " in PHP Music Rhythm Game!";
        if ($artist_id) {
          $og_image = $base_app_url . "?action=get_profile_picture&id=" . (int)$artist_id . "&ext=.jpg";
        }
        $view_config = [
          'type' => 'rhythm_game',
          'artist_id' => $artist_id,
          'artist_name' => $artist_name,
          'sort' => ''
        ];
      } elseif ($share_id > 0) {
        $stmt = $db_for_share->prepare("SELECT title, artist FROM music WHERE id = ?");
        $stmt->execute([$share_id]);
        $song_info = $stmt->fetch();
        if ($song_info) {
          $og_title = "Play " . htmlspecialchars($song_info['title']) . " - Rhythm Game";
          $og_desc = "Can you beat my score on " . htmlspecialchars($song_info['title']) . " by " . htmlspecialchars($song_info['artist']) . "? Play it now in PHP Music!";
          $og_image = $base_app_url . "?action=get_image&id=" . $share_id . "&ext=.jpg";
          $view_config = ['type' => 'rhythm_game', 'param' => $share_id, 'sort' => ''];
        } else {
          $og_title = "PHP Music Rhythm Game";
          $og_desc = "Play along to your favorite tracks in the interactive Rhythm Game!";
          $view_config = ['type' => 'rhythm_game', 'param' => '', 'sort' => ''];
        }
      } else {
        $og_title = "PHP Music Rhythm Game";
        $og_desc = "Play along to your favorite tracks in the interactive Rhythm Game!";
        $view_config = ['type' => 'rhythm_game', 'param' => '', 'sort' => ''];
      }
      break;
  }

  if ($view_config) {
    $initialViewJSON = json_encode($view_config);
    $initialViewJS = "<script>window.initialView = {$initialViewJSON};</script>";
  }
}

function init_db($db) {
  $users_columns = $db->query("PRAGMA table_info(users);")->fetchAll(PDO::FETCH_COLUMN, 1);
  $users_table_exists = !empty($users_columns);

  $db->exec("
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY,
      email TEXT UNIQUE,
      artist TEXT COLLATE NOCASE,
      password_hash TEXT,
      last_upload_date TEXT,
      daily_upload_count INTEGER DEFAULT 0,
      verified TEXT DEFAULT 'no',
      profile_picture BLOB,
      profile_picture_type TEXT,
      backup_key TEXT,
      banned INTEGER DEFAULT 0,
      settings TEXT
    );
  ");
  $db->exec("CREATE UNIQUE INDEX IF NOT EXISTS users_artist_idx ON users(artist);");

  if ($users_table_exists) {
    if (!in_array('is_admin', $users_columns)) $db->exec("ALTER TABLE users ADD COLUMN is_admin INTEGER DEFAULT 0;");
    if (!in_array('reset_requested', $users_columns)) $db->exec("ALTER TABLE users ADD COLUMN reset_requested INTEGER DEFAULT 0;");
    if (!in_array('last_upload_date', $users_columns)) $db->exec("ALTER TABLE users ADD COLUMN last_upload_date TEXT;");
    if (!in_array('daily_upload_count', $users_columns)) $db->exec("ALTER TABLE users ADD COLUMN daily_upload_count INTEGER DEFAULT 0;");
    if (!in_array('verified', $users_columns)) $db->exec("ALTER TABLE users ADD COLUMN verified TEXT DEFAULT 'no';");
    if (!in_array('profile_picture', $users_columns)) $db->exec("ALTER TABLE users ADD COLUMN profile_picture BLOB;");
    if (!in_array('profile_picture_type', $users_columns)) $db->exec("ALTER TABLE users ADD COLUMN profile_picture_type TEXT;");
    if (!in_array('backup_key', $users_columns)) $db->exec("ALTER TABLE users ADD COLUMN backup_key TEXT;");
    if (!in_array('banned', $users_columns)) $db->exec("ALTER TABLE users ADD COLUMN banned INTEGER DEFAULT 0;");
    if (!in_array('rhythm_strikes', $users_columns)) $db->exec("ALTER TABLE users ADD COLUMN rhythm_strikes INTEGER DEFAULT 0;");
    if (!in_array('status', $users_columns)) {
      $db->exec("ALTER TABLE users ADD COLUMN status TEXT DEFAULT 'user';");
      // Migrate existing admins
      $db->exec("UPDATE users SET status = 'super_admin' WHERE id = 1");
      $db->exec("UPDATE users SET status = 'admin' WHERE is_admin = 1 AND status != 'super_admin'");
    }
    if (!in_array('settings', $users_columns)) $db->exec("ALTER TABLE users ADD COLUMN settings TEXT;");
    if (!in_array('bio', $users_columns)) $db->exec("ALTER TABLE users ADD COLUMN bio TEXT;");
    if (!in_array('profile_background', $users_columns)) $db->exec("ALTER TABLE users ADD COLUMN profile_background BLOB;");
    if (!in_array('profile_background_type', $users_columns)) $db->exec("ALTER TABLE users ADD COLUMN profile_background_type TEXT;");
  }

  $music_columns = $db->query("PRAGMA table_info(music);")->fetchAll(PDO::FETCH_COLUMN, 1);
  $music_table_exists = !empty($music_columns);
  
  $db->exec("
    CREATE TABLE IF NOT EXISTS music (
      id INTEGER PRIMARY KEY,
      user_id INTEGER,
      file TEXT UNIQUE,
      title TEXT,
      artist TEXT COLLATE NOCASE,
      album TEXT COLLATE NOCASE,
      genre TEXT COLLATE NOCASE,
      year INTEGER,
      duration INTEGER,
      image BLOB,
      last_modified INTEGER,
      bitrate INTEGER,
      lyrics TEXT,
      is_private INTEGER DEFAULT 0,
      is_collaborative INTEGER DEFAULT 1,
      replaygain REAL DEFAULT 0,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );
  ");

  $db->exec("
    CREATE TABLE IF NOT EXISTS user_song_settings (
      user_id INTEGER NOT NULL,
      song_id INTEGER NOT NULL,
      volume_multiplier REAL DEFAULT 1.0,
      eq_bands TEXT,
      PRIMARY KEY (user_id, song_id),
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
      FOREIGN KEY (song_id) REFERENCES music(id) ON DELETE CASCADE
    );
  ");

  if ($music_table_exists) {
    if (!in_array('bitrate', $music_columns)) $db->exec("ALTER TABLE music ADD COLUMN bitrate INTEGER;");
    if (!in_array('lyrics', $music_columns)) $db->exec("ALTER TABLE music ADD COLUMN lyrics TEXT;");
    if (!in_array('replaygain', $music_columns)) $db->exec("ALTER TABLE music ADD COLUMN replaygain REAL DEFAULT 0;");
    if (!in_array('banned', $music_columns)) $db->exec("ALTER TABLE music ADD COLUMN banned INTEGER DEFAULT 0;");
  }
  
  $db->exec("
    CREATE TABLE IF NOT EXISTS offline_songs (
      user_id INTEGER NOT NULL,
      song_id INTEGER NOT NULL,
      sort_order INTEGER,
      PRIMARY KEY (user_id, song_id),
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
      FOREIGN KEY (song_id) REFERENCES music(id) ON DELETE CASCADE
    );
  ");
  $db->exec("CREATE INDEX IF NOT EXISTS offline_user_id_idx ON offline_songs(user_id);");
  $db->exec("
    CREATE TABLE IF NOT EXISTS favorites (
      user_id INTEGER NOT NULL,
      song_id INTEGER NOT NULL,
      sort_order INTEGER,
      PRIMARY KEY (user_id, song_id),
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
      FOREIGN KEY (song_id) REFERENCES music(id) ON DELETE CASCADE
    );
  ");
  $db->exec("
    CREATE TABLE IF NOT EXISTS playlists (
      id INTEGER PRIMARY KEY,
      user_id INTEGER NOT NULL,
      name TEXT NOT NULL,
      public_id TEXT UNIQUE NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );
  ");
  $playlists_columns = $db->query("PRAGMA table_info(playlists);")->fetchAll(PDO::FETCH_COLUMN, 1);
  if (!in_array('is_collaborative', $playlists_columns)) {
    $db->exec("ALTER TABLE playlists ADD COLUMN is_collaborative INTEGER DEFAULT 0;");
  }
  if (!in_array('is_private', $playlists_columns)) {
    $db->exec("ALTER TABLE playlists ADD COLUMN is_private INTEGER DEFAULT 0;");
  }
  if (!in_array('play_count', $playlists_columns)) {
    $db->exec("ALTER TABLE playlists ADD COLUMN play_count INTEGER DEFAULT 0;");
  }
  if (!in_array('description', $playlists_columns)) {
    $db->exec("ALTER TABLE playlists ADD COLUMN description TEXT;");
  }
  if ($music_table_exists && !in_array('is_private', $music_columns)) {
    $db->exec("ALTER TABLE music ADD COLUMN is_private INTEGER DEFAULT 0;");
  }
  if ($music_table_exists && !in_array('is_collaborative', $music_columns)) {
    $db->exec("ALTER TABLE music ADD COLUMN is_collaborative INTEGER DEFAULT 1;");
  }

  $db->exec("
    CREATE TABLE IF NOT EXISTS song_collaborators (
      song_id INTEGER NOT NULL,
      user_id INTEGER NOT NULL,
      PRIMARY KEY (song_id, user_id),
