      try { $db->exec("ALTER TABLE imageditor_projects ADD COLUMN category TEXT DEFAULT 'all';"); } catch(Exception $e) {}
      try { $db->exec("ALTER TABLE imageditor_projects ADD COLUMN starred INTEGER DEFAULT 0;"); } catch(Exception $e) {}
      try {
