      color: var(--text-muted);
      font-variant-numeric: tabular-nums;
      font-weight: 500;
    }

    .brand {
      position: absolute;
      top: 12px;
      right: 15px;
      font-size: 0.75rem;
      font-weight: 700;
      color: rgba(255, 255, 255, 0.4);
      text-decoration: none;
      z-index: 2;
      transition: color 0.2s;
      letter-spacing: 0.5px;
    }

    .brand:hover {
      color: rgba(255, 255, 255, 0.9);
    }

    @media (max-width: 400px) {
      .cover-art {
        width: 90px;
        height: 90px;
      }

      .play-btn {
        width: 40px;
        height: 40px;
      }

      .play-btn svg {
        width: 18px;
        height: 18px;
      }
    }
  </style>
</head>
<body>
  <div class="player-wrapper">
    <div class="bg-blur"></div>
    <a href="{$shareUrl}" target="_blank" class="brand">PHP MUSIC</a>
    <div class="content">
      <img src="{$imgUrl}" class="cover-art" alt="Cover Art">
      <div class="info-pane">
        <div class="title">{$title}</div>
        <div class="artist">{$artist}</div>
        <div class="controls">
          <button class="play-btn" id="playBtn" aria-label="Play/Pause">
            <svg class="icon-play" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
            <svg class="icon-pause" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>
            <svg class="spinner" viewBox="0 0 50 50"><circle cx="25" cy="25" r="20" fill="none" stroke-width="5"></circle></svg>
          </button>
          <div class="progress-wrapper">
            <div class="progress-bar" id="progBar">
              <div class="progress-fill" id="progFill"></div>
            </div>
            <div class="time-stamps">
              <span id="timeCurrent">0:00</span>
              <span id="timeTotal">0:00</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
  <audio id="audio" src="{$streamUrl}" preload="metadata" crossorigin="anonymous"></audio>
  <script>
    const audio = document.getElementById('audio');
    const playBtn = document.getElementById('playBtn');
    const progBar = document.getElementById('progBar');
    const progFill = document.getElementById('progFill');
    const timeCurrent = document.getElementById('timeCurrent');
    const timeTotal = document.getElementById('timeTotal');

    const formatTime = (s) => {
      if (isNaN(s) || !isFinite(s)) return '0:00';
      const min = Math.floor(s / 60);
      const sec = Math.floor(s % 60).toString().padStart(2, '0');
      return min + ':' + sec;
    };

    const updateDuration = () => {
      if (audio.duration && isFinite(audio.duration)) {
        timeTotal.textContent = formatTime(audio.duration);
      }
    };

    audio.addEventListener('loadedmetadata', updateDuration);
    audio.addEventListener('durationchange', updateDuration);

    audio.addEventListener('timeupdate', () => {
      timeCurrent.textContent = formatTime(audio.currentTime);
      if (audio.duration && isFinite(audio.duration)) {
        progFill.style.width = ((audio.currentTime / audio.duration) * 100) + '%';
      }
    });

    audio.addEventListener('waiting', () => playBtn.classList.add('loading'));
    
    audio.addEventListener('playing', () => {
      playBtn.classList.remove('loading');
      playBtn.classList.add('playing');
      updateDuration();
    });

    audio.addEventListener('pause', () => {
      playBtn.classList.remove('loading');
      playBtn.classList.remove('playing');
    });

    audio.addEventListener('error', (e) => {
      playBtn.classList.remove('loading', 'playing');
      playBtn.innerHTML = "<svg viewBox='0 0 24 24' fill='#ff4444' style='margin-left:0; width:24px; height:24px;'><path d='M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z'/></svg>";
      console.error('Audio stream error', e);
    });

    playBtn.addEventListener('click', () => {
      if (audio.paused) {
        const p = audio.play();
        if (p !== undefined) {
          playBtn.classList.add('loading');
          p.catch(e => {
            console.error('Playback failed:', e);
            playBtn.classList.remove('loading');
          });
        }
      } else {
        audio.pause();
      }
    });

    progBar.addEventListener('click', (e) => {
      if (!audio.duration || !isFinite(audio.duration)) return;
      const rect = progBar.getBoundingClientRect();
      const pos = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
      audio.currentTime = pos * audio.duration;
    });

    audio.addEventListener('ended', () => {
      progFill.style.width = '0%';
      timeCurrent.textContent = '0:00';
      audio.currentTime = 0;
      playBtn.classList.remove('playing');
    });
  </script>
</body>
</html>
HTML;
      exit;

    case 'toggle_collaborative':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $public_id = $data['public_id'];
      
      $stmt = $db->prepare("SELECT id, is_collaborative FROM playlists WHERE public_id = ? AND (user_id = ? OR {$is_super_admin} = 1)");
      $stmt->execute([$public_id, $user_id]);
      $pl = $stmt->fetch();
      
      if ($pl) {
        $new_val = $pl['is_collaborative'] ? 0 : 1;
        $db->prepare("UPDATE playlists SET is_collaborative = ? WHERE id = ?")->execute([$new_val, $pl['id']]);
        
        // If the playlist is made private, securely wipe all existing collaborators
        if ($new_val === 0) {
          $db->prepare("DELETE FROM playlist_collaborators WHERE playlist_id = ?")->execute([$pl['id']]);
        }
        
        send_json([
          'status' => 'success', 
          'is_collaborative' => $new_val, 
          'message' => $new_val ? 'Playlist is collaborative.' : 'Playlist is now private. Collaborators removed.'
        ]);
      } else {
        http_response_code(403); send_json(['status' => 'error', 'message' => 'Permission denied.']);
      }
      break;

    case 'get_radio_tracks':
      $seed_id = intval($_GET['seed_id'] ?? 0);
      $stmt = $db->prepare("SELECT artist, genre FROM music WHERE id = ?");
      $stmt->execute([$seed_id]);
      $seed = $stmt->fetch();
      
      $song_fields = "m.id, m.title, m.artist, m.album, m.genre, m.duration, m.user_id, m.is_private, m.is_collaborative, m.last_modified, CASE WHEN f.song_id IS NOT NULL THEN 1 ELSE 0 END AS is_favorite, (SELECT SUM(play_count) FROM play_counts WHERE song_id = m.id) as play_count";
      
      if ($seed) {
        $radio_stmt = $db->prepare("SELECT {$song_fields} FROM music m LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = ? WHERE (m.genre = ? OR match_artist(m.artist, ?) = 1) AND m.id != ? ORDER BY RANDOM() LIMIT 15");
        $radio_stmt->execute([$user_id, $seed['genre'], $seed['artist'], $seed_id]);
        send_json($radio_stmt->fetchAll());
      } else {
        $radio_stmt = $db->prepare("SELECT {$song_fields} FROM music m LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = ? ORDER BY RANDOM() LIMIT 15");
        $radio_stmt->execute([$user_id]);
        send_json($radio_stmt->fetchAll());
      }
      break;

    case 'get_queue_songs':
      $data = json_decode(file_get_contents('php://input'), true);
      $ids = $data['ids'] ?? [];
      if (empty($ids)) { send_json([]); }
      
      $placeholders = implode(',', array_fill(0, count($ids), '?'));
      $song_fields = "m.id, m.title, m.artist, m.album, m.genre, m.duration, m.user_id, m.is_private, m.is_collaborative, m.last_modified, CASE WHEN f.song_id IS NOT NULL THEN 1 ELSE 0 END AS is_favorite, (SELECT SUM(play_count) FROM play_counts WHERE song_id = m.id) as play_count";
      
      $stmt = $db->prepare("SELECT {$song_fields} FROM music m LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = ? WHERE m.id IN ($placeholders)");
      $params = array_merge([$user_id], $ids);
      $stmt->execute($params);
      $results = $stmt->fetchAll();
      
      // Return the data sorted perfectly to match the queue array
      $sorted_results = [];
      $map = [];
      foreach ($results as $r) { $map[$r['id']] = $r; }
      foreach ($ids as $id) { if (isset($map[$id])) $sorted_results[] = $map[$id]; }
      
      send_json($sorted_results);
      break;

    case 'check_update_code':
      error_reporting(0);
      $remote_url = "https://raw.githubusercontent.com/HirotakaDango/PHP-Music/main/index.php";
      $remote_code = false;
      
      if (function_exists('curl_version')) {
        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $remote_url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
        curl_setopt($ch, CURLOPT_USERAGENT, 'PHP-Music-Update-Checker');
        curl_setopt($ch, CURLOPT_TIMEOUT, 3);
        curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
        $remote_code = curl_exec($ch);
        curl_close($ch);
      } 
      
      if (!$remote_code) {
        $context = stream_context_create(['http' => ['timeout' => 3, 'header' => "User-Agent: PHP-Music-Update-Checker\r\n"]]);
        $remote_code = @file_get_contents($remote_url, false, $context);
      }
      
      if (!$remote_code) {
        send_json(['status' => 'error', 'message' => 'Could not connect to GitHub. Check your server firewall or internet.']);
      }
      
      $local_code = @file_get_contents(__FILE__);
      
      $remote_normalized = str_replace(["\r\n", "\r"], "\n", trim($remote_code));
      $local_normalized = str_replace(["\r\n", "\r"], "\n", trim($local_code));
      
      $is_matching = hash_equals(hash('sha256', $remote_normalized), hash('sha256', $local_normalized));
      
      while (ob_get_level() > 0) { @ob_end_clean(); }
      send_json([
        'status' => 'success',
        'update_available' => !$is_matching
      ]);
      break;

    case 'get_app_icon':
      header('Content-Type: image/svg+xml');
      header('Cache-Control: public, max-age=31536000, immutable');
      header('Pragma: cache');
      header('Expires: ' . gmdate('D, d M Y H:i:s', time() + 31536000) . ' GMT');
      $size = intval($_GET['size'] ?? 192);
      echo '<?xml version="1.0" encoding="utf-8"?><svg width="'.$size.'px" height="'.$size.'px" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><rect width="24" height="24" rx="6" fill="#0a0a0a"/><path d="M0 24L24 0V24H0Z" fill="#141414" clip-path="inset(0px round 6px)"/><path d="M4 10V13" stroke="#ffffff" stroke-width="1.7" stroke-linecap="round"/><path d="M16 10V13" stroke="#ffffff" stroke-width="1.7" stroke-linecap="round"/><path d="M7 7L7 16" stroke="#ff0044" stroke-width="1.7" stroke-linecap="round"/><path d="M13 7L13 16" stroke="#ffffff" stroke-width="1.7" stroke-linecap="round"/><path d="M19 7L19 16" stroke="#ffffff" stroke-width="1.7" stroke-linecap="round"/><path d="M10 4L10 19" stroke="#ffffff" stroke-width="1.7" stroke-linecap="round"/></svg>';
      exit;

    case 'verify_admin_dev':
      $data = json_decode(file_get_contents('php://input'), true);
      $pwd = $data['password'] ?? '';
      $is_valid = false;
      if (!empty($pwd)) {
        $stmt_v = $db->query("SELECT password_hash FROM users WHERE status = 'super_admin' OR status = 'admin' OR is_admin = 1");
        while ($row_v = $stmt_v->fetch()) {
          if (!empty($row_v['password_hash']) && password_verify($pwd, $row_v['password_hash'])) {
            $is_valid = true;
            break;
          }
        }
      }
      if ($is_valid) {
        send_json(['status' => 'success', 'valid' => true]);
      } else {
        http_response_code(401);
        send_json(['status' => 'error', 'valid' => false]);
      }
      break;

    case 'get_session':
      if ($user_id) {
        try { $db->exec("ALTER TABLE users ADD COLUMN last_active DATETIME;"); } catch(Exception $e) {}
        try { $db->exec("ALTER TABLE users ADD COLUMN rhythm_strikes INTEGER DEFAULT 0;"); } catch(Exception $e) {}
        $db->prepare("UPDATE users SET last_active = CURRENT_TIMESTAMP WHERE id = ?")->execute([$user_id]);

        $stmt = $db->prepare("SELECT id, email, artist, bio, verified, last_upload_date, daily_upload_count, banned, settings, is_admin, status, rhythm_strikes FROM users WHERE id = ?");
        $stmt->execute([$user_id]);
        $user = $stmt->fetch();
        if ($user && empty($user['banned'])) {
          $today = date('Y-m-d');
          $uploads_today = 0;
          if ($user['last_upload_date'] === $today) {
            $uploads_today = (int)$user['daily_upload_count'];
          }
          $user['uploads_remaining'] = max(0, DAILY_UPLOAD_LIMIT - $uploads_today);
          $user['profile_picture_url'] = "?action=get_profile_picture&id=" . $user['id'] . "&v=" . time();
          send_json(['status' => 'loggedin', 'user' => $user, 'upload_limit' => get_upload_limit()]);
        } else {
          session_destroy();
          send_json(['status' => 'loggedout']);
        }
      } else {
        send_json(['status' => 'loggedout']);
      }
      break;

    case 'submit_appeal':
      $data = json_decode(file_get_contents('php://input'), true);
      $appeal_text = trim(htmlspecialchars($data['appeal_text'] ?? '', ENT_QUOTES, 'UTF-8'));
      
      if (empty($appeal_text)) {
        http_response_code(400);
        send_json(['status' => 'error', 'message' => 'Appeal reasoning is required.']);
      }

      $target_user_id = null;

      // Handle Logged-out Full Ban Appeal (Requires Email)
      if (isset($data['email']) && !empty($data['email'])) {
        $email = filter_var($data['email'], FILTER_VALIDATE_EMAIL);
        if (!$email) {
          http_response_code(400);
          send_json(['status' => 'error', 'message' => 'Invalid email format.']);
        }
        $stmt = $db->prepare("SELECT id, banned FROM users WHERE email = ?");
        $stmt->execute([$email]);
        $user = $stmt->fetch();
        
        if (!$user || $user['banned'] == 0) {
          http_response_code(400);
          send_json(['status' => 'error', 'message' => 'This account is not currently permanently banned or does not exist.']);
        }
        $target_user_id = $user['id'];
      } 
      // Handle Logged-in Game Ban Appeal
      else if ($user_id) {
        $stmt = $db->prepare("SELECT id, rhythm_strikes FROM users WHERE id = ?");
        $stmt->execute([$user_id]);
        $user = $stmt->fetch();
        
        if (!$user || $user['rhythm_strikes'] == 0) {
          http_response_code(400);
          send_json(['status' => 'error', 'message' => 'Your account is not suspended from the Rhythm Game.']);
        }
        $target_user_id = $user_id;
      } else {
        http_response_code(400);
        send_json(['status' => 'error', 'message' => 'Authentication or Email required.']);
      }
      
      $db->prepare("INSERT INTO ban_appeals (user_id, appeal_text) VALUES (?, ?)")->execute([$target_user_id, $appeal_text]);
      send_json(['status' => 'success', 'message' => 'Your appeal has been submitted for administrative review.']);
      break;

    case 'forgot_password':
      $data = json_decode(file_get_contents('php://input'), true);
      $email = filter_var($data['email'], FILTER_VALIDATE_EMAIL);
      if ($email) {
        $db->prepare("UPDATE users SET reset_requested = 1 WHERE email = ?")->execute([$email]);
      }
      send_json(['status' => 'success', 'message' => 'If the email exists, an admin has been notified to send a password reset link to your email address.']);
      break;

    case 'reset_password_submit':
      $data = json_decode(file_get_contents('php://input'), true);
      $token = $data['token'] ?? '';
      $new_password = $data['new_password'] ?? '';
      
      if (strlen($new_password) < 6) {
        http_response_code(400); send_json(['status' => 'error', 'message' => 'Password must be at least 6 characters.']);
      }
      
      $stmt = $db->prepare("SELECT user_id FROM password_resets WHERE token = ? AND expires_at > datetime('now')");
      $stmt->execute([$token]);
      $uid = $stmt->fetchColumn();
      
      if ($uid) {
        $hash = password_hash($new_password, PASSWORD_DEFAULT);
        $db->prepare("UPDATE users SET password_hash = ? WHERE id = ?")->execute([$hash, $uid]);
        $db->prepare("DELETE FROM password_resets WHERE token = ?")->execute([$token]);
        send_json(['status' => 'success', 'message' => 'Password updated successfully! You can now log in.']);
      } else {
        http_response_code(400); send_json(['status' => 'error', 'message' => 'Invalid or expired reset token.']);
      }
      break;

    case 'register':
      $data = json_decode(file_get_contents('php://input'), true);
