    case 'get_projects':
      if (!$user_id) { send_json([]); }
      $proj_type = $_GET['filter'] ?? 'note';
      $stmt = $db->prepare("
        SELECT p.*, u.artist as owner_name, 
        (SELECT COUNT(*) FROM project_members pm2 WHERE pm2.project_id = p.id) as member_count,
        (SELECT COUNT(*) FROM personal_notes pn WHERE pn.project_id = p.id) as note_count,
        (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id) as task_count,
        (SELECT COUNT(*) FROM blogs b WHERE b.project_id = p.id) as blog_count,
        (SELECT COUNT(*) FROM imageditor_projects iep WHERE iep.project_id = p.id) as imageditor_count
        FROM projects p 
        JOIN project_members pm ON p.id = pm.project_id 
        JOIN users u ON p.owner_id = u.id
        WHERE pm.user_id = ? AND p.project_type = ? ORDER BY p.created_at DESC
      ");
      $stmt->execute([$user_id, $proj_type]);
      send_json($stmt->fetchAll());
      break;

    case 'manage_project':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $action_type = $data['action_type'];

      if ($action_type === 'create') {
        $name = trim(htmlspecialchars($data['name'] ?? 'Untitled Project', ENT_QUOTES, 'UTF-8'));
        $ptype = $data['project_type'] ?? 'note';
        $db->prepare("INSERT INTO projects (name, owner_id, project_type) VALUES (?, ?, ?)")->execute([$name, $user_id, $ptype]);
        $pid = $db->lastInsertId();
        $db->prepare("INSERT INTO project_members (project_id, user_id, role) VALUES (?, ?, 'owner')")->execute([$pid, $user_id]);
        send_json(['status' => 'success', 'project_id' => $pid]);
      } elseif ($action_type === 'delete') {
        $db->prepare("DELETE FROM projects WHERE id = ? AND owner_id = ?")->execute([$data['project_id'], $user_id]);
        send_json(['status' => 'success']);
      } elseif ($action_type === 'generate_link') {
        $db->exec("DELETE FROM project_invites WHERE expires_at IS NOT NULL AND expires_at <= CURRENT_TIMESTAMP");
        $expire_val = $data['expire'] ?? null;
        $expires_at = ($expire_val && is_numeric($expire_val)) ? date('Y-m-d H:i:s', time() + ((int)$expire_val * 60)) : null;
        $token = bin2hex(random_bytes(16));
        $db->prepare("INSERT INTO project_invites (token, project_id, expires_at) VALUES (?, ?, ?)")->execute([$token, $data['project_id'], $expires_at]);
        send_json(['status' => 'success', 'token' => $token]);
      } elseif ($action_type === 'list_members') {
        $page = isset($data['page']) ? max(1, (int)$data['page']) : 1;
        $offset = ($page - 1) * 25;
        $stmt_list = $db->prepare("SELECT u.id, u.artist, u.email, pm.role FROM project_members pm JOIN users u ON pm.user_id = u.id WHERE pm.project_id = ? ORDER BY pm.role = 'owner' DESC, u.artist ASC LIMIT 25 OFFSET ?");
        $stmt_list->execute([$data['project_id'], $offset]);
        send_json(['status' => 'success', 'members' => $stmt_list->fetchAll()]);
      } elseif ($action_type === 'remove_member') {
        $db->prepare("DELETE FROM project_members WHERE project_id = ? AND user_id = ? AND role != 'owner'")->execute([$data['project_id'], $data['user_id']]);
        send_json(['status' => 'success']);
      } elseif ($action_type === 'leave') {
        $db->prepare("DELETE FROM project_members WHERE project_id = ? AND user_id = ? AND role != 'owner'")->execute([$data['project_id'], $user_id]);
        send_json(['status' => 'success']);
      } elseif ($action_type === 'join') {
        $token = $data['token'] ?? '';
        $stmt_inv = $db->prepare("SELECT project_id FROM project_invites WHERE token = ? AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP)");
        $stmt_inv->execute([$token]);
        $inv_pid = $stmt_inv->fetchColumn();
        if (!$inv_pid) send_json(['status' => 'error', 'message' => 'Invalid or expired invite.']);
        
        $stmt_owner = $db->prepare("SELECT owner_id, project_type FROM projects WHERE id = ?");
        $stmt_owner->execute([$inv_pid]);
        $proj_info = $stmt_owner->fetch();
        if ($proj_info['owner_id'] == $user_id) {
          send_json(['status' => 'error', 'message' => 'Seriously? Do you have no friend that you try to invite yourself?']);
        }
        
        $db->prepare("INSERT OR IGNORE INTO project_members (project_id, user_id, role) VALUES (?, ?, 'editor')")->execute([$inv_pid, $user_id]);
        send_json(['status' => 'success', 'project_type' => $proj_info['project_type'] ?? 'note']);
      } elseif ($action_type === 'move_item') {
        $table = $data['item_type'] === 'blog' ? 'blogs' : ($data['item_type'] === 'task' ? 'tasks' : ($data['item_type'] === 'imageditor' ? 'imageditor_projects' : 'personal_notes'));
        $pid = $data['project_id'] ? (int)$data['project_id'] : null;
        if ($data['item_type'] === 'imageditor') {
          $db->prepare("UPDATE $table SET project_id = ? WHERE public_id = ? AND user_id = ?")->execute([$pid, $data['item_id'], $user_id]);
        } else {
          $db->prepare("UPDATE $table SET project_id = ? WHERE id = ? AND user_id = ?")->execute([$pid, $data['item_id'], $user_id]);
        }
        send_json(['status' => 'success']);
      }
      break;

    case 'sync_presence':
      // FALLBACK for initial presence ping
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $item_id = (int)$data['item_id'];
      $item_type = $data['item_type'];
      $db->prepare("REPLACE INTO project_presence (user_id, item_id, item_type, last_active) VALUES (?, ?, ?, CURRENT_TIMESTAMP)")->execute([$user_id, $item_id, $item_type]);
      send_json(['status' => 'success']);
      break;

    case 'sse_sync':
      // WEBSOCKET ALTERNATIVE: Persistent streaming connection without CLI
      if (!$user_id) { http_response_code(403); exit; }
      session_write_close(); // Prevent locking the session so Saves remain INSTANT
      
      header('Content-Type: text/event-stream');
      header('Cache-Control: no-cache');
      header('Connection: keep-alive');
      header('X-Accel-Buffering: no'); // Disable Nginx buffering
      
      $item_id = (int)$_GET['item_id'];
      $item_type = $_GET['item_type'];
      
      $table = 'personal_notes';
      $col = 'content';
      if ($item_type === 'blog') { $table = 'blogs'; }
      elseif ($item_type === 'task') { $table = 'tasks'; $col = 'items'; }
      elseif ($item_type === 'imageditor') { $table = 'imageditor_projects'; $col = 'state'; }
      
      $last_update = '';
      
      // Keep connection alive for 30 seconds, pushing real-time changes
      for ($i = 0; $i < 60; $i++) {
        if (connection_aborted()) break;
        
        $db = get_db(); // Re-fetch to ensure fresh data
        $db->prepare("REPLACE INTO project_presence (user_id, item_id, item_type, last_active) VALUES (?, ?, ?, CURRENT_TIMESTAMP)")->execute([$user_id, $item_id, $item_type]);
        $db->exec("DELETE FROM project_presence WHERE last_active < datetime('now', '-10 seconds')");
        
        $stmt = $db->prepare("SELECT updated_at, title, $col as content FROM $table WHERE id = ?");
        $stmt->execute([$item_id]);
        $data = $stmt->fetch();
        
        if ($data && $data['updated_at'] !== $last_update) {
          $last_update = $data['updated_at'];
          
          $stmt_u = $db->prepare("SELECT u.id, u.artist FROM project_presence pp JOIN users u ON pp.user_id = u.id WHERE pp.item_id = ? AND pp.item_type = ? AND pp.user_id != ?");
          $stmt_u->execute([$item_id, $item_type, $user_id]);
          $active_users = $stmt_u->fetchAll();
          
          echo "data: " . json_encode([
            'latest_update' => $last_update,
            'item_data' => $data,
            'active_users' => $active_users
          ]) . "\n\n";
          @ob_flush(); flush();
        }
        
        usleep(200000); // Poll DB every 0.2s for true real-time sync
      }
      exit;

    case 'get_note_categories':
