    case 'delete_phpboard_post':
      $type = $_POST['type'] ?? '';
      $id = (int)$_POST['id'];
      $pwd = $_POST['password'] ?? '';
      
      $table = $type === 'thread' ? 'phpboard_threads' : 'phpboard_replies';
