      $data = json_decode(file_get_contents('php://input'), true);
      $db->prepare("DELETE FROM blogs WHERE id = ? AND (user_id = ? OR {$is_admin} = 1)")->execute([intval($data['id']), $user_id]);
      send_json(['status' => 'success']);
      break;

    case 'get_community':
      // Failsafe: Ensure schema exists to prevent HTTP 500 errors on older databases
      try {
        $db->exec("CREATE TABLE IF NOT EXISTS community_posts (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, content TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);");
        $db->exec("CREATE TABLE IF NOT EXISTS community_reactions (user_id INTEGER NOT NULL, post_id INTEGER NOT NULL, reaction TEXT, PRIMARY KEY (user_id, post_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (post_id) REFERENCES community_posts(id) ON DELETE CASCADE);");
        $db->exec("ALTER TABLE community_posts ADD COLUMN parent_id INTEGER DEFAULT NULL;");
        $db->exec("ALTER TABLE community_posts ADD COLUMN reply_to_id INTEGER DEFAULT NULL;");
      } catch(Exception $e) {}

      $sort_key = $_GET['sort'] ?? 'newest';
      $search = $_GET['q'] ?? '';
      $order_by = 'ORDER BY p.created_at DESC';
      $join_cond = "";
      $where_cond = "WHERE p.parent_id IS NULL";
      $params = [$user_id ?? 0];
      
      if ($search !== '') {
        $where_cond .= " AND p.content LIKE ?";
        $params[] = "%$search%";
      }

      if ($sort_key === 'most_liked') {
        $order_by = 'ORDER BY like_count DESC, p.created_at DESC';
      } elseif ($sort_key === 'most_replied') {
        $order_by = 'ORDER BY reply_count DESC, p.created_at DESC';
      } elseif ($sort_key === 'following' && $user_id) {
        $join_cond = "JOIN follows f ON f.following_id = p.user_id AND f.follower_id = " . intval($user_id);
      }
      
      $root_stmt = $db->prepare("
        SELECT p.*, 
        CASE WHEN u.banned = 1 THEN 'Banned User' WHEN u.email LIKE 'deleted_%' THEN 'Deleted User' ELSE u.artist END as artist,
        CASE WHEN u.banned = 1 OR u.email LIKE 'deleted_%' THEN 1 ELSE 0 END as is_disabled,
        (SELECT p2.content FROM community_posts p2 WHERE p2.id = p.reply_to_id) as reply_content,
        (SELECT COALESCE(u2.artist, 'Anonymous') FROM community_posts p2 LEFT JOIN users u2 ON p2.user_id = u2.id WHERE p2.id = p.reply_to_id) as reply_sender,
        (SELECT COUNT(*) FROM community_reactions WHERE post_id = p.id AND reaction = 'like') as like_count,
        (SELECT COUNT(*) FROM community_reactions WHERE post_id = p.id AND reaction = 'dislike') as dislike_count,
        (SELECT COUNT(*) FROM community_posts WHERE parent_id = p.id) as reply_count,
        (SELECT reaction FROM community_reactions WHERE post_id = p.id AND user_id = ?) as my_reaction 
        FROM community_posts p JOIN users u ON p.user_id = u.id $join_cond $where_cond $order_by $limit_clause
      ");
      $root_stmt->execute($params);
      $roots = $root_stmt->fetchAll();
      
      $root_ids = array_column($roots, 'id');
      $replies_filtered = [];
      if (!empty($root_ids)) {
        $placeholders = implode(',', array_fill(0, count($root_ids), '?'));
        $reply_stmt = $db->prepare("
          SELECT p.*, 
          CASE WHEN u.banned = 1 THEN 'Banned User' WHEN u.email LIKE 'deleted_%' THEN 'Deleted User' ELSE u.artist END as artist,
          CASE WHEN u.banned = 1 OR u.email LIKE 'deleted_%' THEN 1 ELSE 0 END as is_disabled,
          (SELECT p2.content FROM community_posts p2 WHERE p2.id = p.reply_to_id) as reply_content,
          (SELECT COALESCE(u2.artist, 'Anonymous') FROM community_posts p2 LEFT JOIN users u2 ON p2.user_id = u2.id WHERE p2.id = p.reply_to_id) as reply_sender,
          (SELECT COUNT(*) FROM community_reactions WHERE post_id = p.id AND reaction = 'like') as like_count,
          (SELECT COUNT(*) FROM community_reactions WHERE post_id = p.id AND reaction = 'dislike') as dislike_count,
          (SELECT COUNT(*) FROM community_posts WHERE parent_id = p.id) as reply_count,
          (SELECT reaction FROM community_reactions WHERE post_id = p.id AND user_id = ?) as my_reaction 
          FROM community_posts p JOIN users u ON p.user_id = u.id
          WHERE p.parent_id IN ($placeholders)
          ORDER BY p.created_at ASC
        ");
        $reply_params = array_merge([$user_id ?? 0], $root_ids);
        $reply_stmt->execute($reply_params);
        $all_replies = $reply_stmt->fetchAll();
          
        $rcounts = [];
        foreach ($all_replies as $r) {
          $pid = $r['parent_id'];
          if (!isset($rcounts[$pid])) $rcounts[$pid] = 0;
          if ($rcounts[$pid] < 25) { // Strict limit of 25 replies per post
            $replies_filtered[] = $r;
            $rcounts[$pid]++;
          }
        }
      }
      
      send_json(array_merge($roots, $replies_filtered));
      break;

    case 'create_community_post':
      if (!$user_id) { http_response_code(403); exit; }
      try {
        $db->exec("CREATE TABLE IF NOT EXISTS community_posts (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, content TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);");
        $db->exec("ALTER TABLE community_posts ADD COLUMN parent_id INTEGER DEFAULT NULL;");
        $db->exec("ALTER TABLE community_posts ADD COLUMN reply_to_id INTEGER DEFAULT NULL;");
      } catch(Exception $e) {}
      $data = json_decode(file_get_contents('php://input'), true);
      $content = format_user_text($data['content']);
      $parent_id = empty($data['parent_id']) ? null : intval($data['parent_id']);
      $reply_to_id = empty($data['reply_to_id']) ? null : intval($data['reply_to_id']);
      $db->prepare("INSERT INTO community_posts (user_id, parent_id, reply_to_id, content) VALUES (?, ?, ?, ?)")->execute([$user_id, $parent_id, $reply_to_id, $content]);
      send_json(['status' => 'success']);
      break;

    case 'toggle_post_reaction':
      if (!$user_id) { http_response_code(403); exit; }
      try {
        $db->exec("CREATE TABLE IF NOT EXISTS community_reactions (user_id INTEGER NOT NULL, post_id INTEGER NOT NULL, reaction TEXT, PRIMARY KEY (user_id, post_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (post_id) REFERENCES community_posts(id) ON DELETE CASCADE);");
      } catch(Exception $e) {}
      $data = json_decode(file_get_contents('php://input'), true);
      $post_id = intval($data['post_id']);
      $reaction = $data['reaction'];
      $stmt = $db->prepare("SELECT reaction FROM community_reactions WHERE user_id = ? AND post_id = ?");
      $stmt->execute([$user_id, $post_id]);
      if ($stmt->fetchColumn() === $reaction) {
        $db->prepare("DELETE FROM community_reactions WHERE user_id = ? AND post_id = ?")->execute([$user_id, $post_id]);
      } else {
        $db->prepare("REPLACE INTO community_reactions (user_id, post_id, reaction) VALUES (?, ?, ?)")->execute([$user_id, $post_id, $reaction]);
      }
      send_json(['status' => 'success']);
      break;

    case 'toggle_block':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $blocked_id = intval($data['blocked_id']);
      if ($blocked_id === $user_id) { send_json(['status' => 'error', 'message' => 'Cannot block yourself.']); }
      
      $stmt = $db->prepare("SELECT 1 FROM blocks WHERE blocker_id = ? AND blocked_id = ?");
      $stmt->execute([$user_id, $blocked_id]);
      if ($stmt->fetch()) {
        $db->prepare("DELETE FROM blocks WHERE blocker_id = ? AND blocked_id = ?")->execute([$user_id, $blocked_id]);
        send_json(['status' => 'unblocked']);
      } else {
        $db->prepare("INSERT INTO blocks (blocker_id, blocked_id) VALUES (?, ?)")->execute([$user_id, $blocked_id]);
        // Remove mutual follows
        $db->prepare("DELETE FROM follows WHERE (follower_id = ? AND following_id = ?) OR (follower_id = ? AND following_id = ?)")->execute([$user_id, $blocked_id, $blocked_id, $user_id]);
        send_json(['status' => 'blocked']);
      }
      break;

    case 'get_inbox':
      if (!$user_id) { send_json([]); }
      
      try { $db->query("SELECT media_type FROM messages LIMIT 1"); } catch (Exception $e) { try { $db->exec("ALTER TABLE messages ADD COLUMN media_type TEXT DEFAULT 'image/webp'"); } catch(Exception $ex) {} }
      
      // FIX 500 ERROR: Ensure new tables exist immediately without needing an app version reset
      $db->exec("
        CREATE TABLE IF NOT EXISTS starred_messages (
          user_id INTEGER NOT NULL, message_id INTEGER NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          PRIMARY KEY (user_id, message_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE CASCADE
        );
        CREATE TABLE IF NOT EXISTS user_statuses (
          id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, content TEXT, image BLOB, media_type TEXT DEFAULT 'image/webp', created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
        );
      ");
      
      $inbox = [];
      
      // 1. Direct Messages (Optimized O(1) Aggregation)
      $stmt_dms = $db->prepare("
        SELECT 
          m.id, m.content, m.image, m.created_at, m.is_read, m.sender_id, m.receiver_id, m.media_type,
          u.artist as name, u.id as target_id, u.last_active,
          (SELECT COUNT(*) FROM messages unread WHERE unread.group_id IS NULL AND unread.sender_id = u.id AND unread.receiver_id = ? AND unread.is_read = 0) as unread_count
        FROM messages m
        JOIN users u ON u.id = CASE WHEN m.sender_id = ? THEN m.receiver_id ELSE m.sender_id END
        WHERE m.id IN (
          SELECT MAX(id) 
          FROM messages 
          WHERE group_id IS NULL AND (sender_id = ? OR receiver_id = ?) 
          GROUP BY CASE WHEN sender_id = ? THEN receiver_id ELSE sender_id END
        )
        AND NOT EXISTS (SELECT 1 FROM blocks b WHERE (b.blocker_id = ? AND b.blocked_id = u.id) OR (b.blocker_id = u.id AND b.blocked_id = ?))
      ");
      $stmt_dms->execute([$user_id, $user_id, $user_id, $user_id, $user_id, $user_id, $user_id]);
      
      while ($msg = $stmt_dms->fetch()) {
        $inbox[] = [
          'id' => $msg['id'],
          'content' => $msg['content'],
          'has_image' => !empty($msg['image']) ? 1 : 0,
          'media_type' => $msg['media_type'] ?? 'image/webp',
          'created_at' => $msg['created_at'],
          'is_read' => $msg['is_read'],
          'sender_id' => $msg['sender_id'],
          'receiver_id' => $msg['receiver_id'],
          'name' => $msg['name'] ?: 'Unknown',
          'target_id' => $msg['target_id'],
          'last_active' => $msg['last_active'],
          'chat_type' => 'dm',
          'unread_count' => $msg['unread_count'],
          'sender_name' => '',
          'member_count' => 0
        ];
      }
      
      // 2. Group Chats (Optimized O(1) Join with Member Count)
      $stmt_groups = $db->prepare("
        SELECT 
          cg.id as target_id, cg.name,
          m.id, m.content, m.image, m.created_at, m.sender_id, m.media_type,
          u.artist as sender_name,
          (SELECT COUNT(*) FROM chat_group_members WHERE group_id = cg.id) as member_count
        FROM chat_groups cg
        JOIN chat_group_members cgm ON cg.id = cgm.group_id
        LEFT JOIN messages m ON m.id = (SELECT MAX(id) FROM messages WHERE group_id = cg.id)
        LEFT JOIN users u ON m.sender_id = u.id
        WHERE cgm.user_id = ?
      ");
      $stmt_groups->execute([$user_id]);
      
      while ($gmsg = $stmt_groups->fetch()) {
        $inbox[] = [
          'id' => $gmsg['id'] ?: 0,
          'content' => $gmsg['content'],
          'has_image' => !empty($gmsg['image']) ? 1 : 0,
          'media_type' => $gmsg['media_type'] ?? 'image/webp',
          'created_at' => $gmsg['created_at'],
          'is_read' => 1,
          'sender_id' => $gmsg['sender_id'] ?: 0,
          'receiver_id' => 0,
          'name' => $gmsg['name'],
          'target_id' => $gmsg['target_id'],
          'last_active' => null,
          'chat_type' => 'group',
          'unread_count' => 0,
          'sender_name' => $gmsg['sender_name'] ?: '',
          'member_count' => $gmsg['member_count']
        ];
      }
      
      usort($inbox, function($a, $b) {
        $timeA = !empty($a['created_at']) ? strtotime($a['created_at']) : 0;
        $timeB = !empty($b['created_at']) ? strtotime($b['created_at']) : 0;
        return $timeB - $timeA;
      });
      
      send_json($inbox);
      break;

    case 'get_chat':
      if (!$user_id) { send_json([]); }
      $target_id = intval($_GET['target_id'] ?? 0);
      $type = $_GET['chat_type'] ?? 'dm';
      $chat_page = isset($_GET['chat_page']) ? max(1, (int)$_GET['chat_page']) : 1;
      $chat_limit = 25 * $chat_page;
      
      try { $db->query("SELECT media_type FROM messages LIMIT 1"); } catch (Exception $e) { try { $db->exec("ALTER TABLE messages ADD COLUMN media_type TEXT DEFAULT 'image/webp'"); } catch(Exception $ex) {} }
      
      // FIX 500 ERROR: Safeguard
      $db->exec("CREATE TABLE IF NOT EXISTS starred_messages (user_id INTEGER NOT NULL, message_id INTEGER NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (user_id, message_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE CASCADE);");
      
      $messages = [];
      if ($type === 'group') {
        $stmt_mem = $db->prepare("SELECT 1 FROM chat_group_members WHERE group_id = ? AND user_id = ?");
        $stmt_mem->execute([$target_id, $user_id]);
        if (!$stmt_mem->fetch() && !$is_super_admin) { http_response_code(403); send_json(['status' => 'error', 'message' => 'Not a member.']); }

        $stmt = $db->prepare("
          SELECT m.id, m.sender_id, u.artist as sender_name, m.content, m.image, m.created_at, m.is_edited, m.reply_to_id, m.media_type,
          (SELECT 1 FROM starred_messages sm WHERE sm.message_id = m.id AND sm.user_id = ?) as is_starred
          FROM messages m 
          LEFT JOIN users u ON m.sender_id = u.id 
          WHERE m.group_id = ? 
          ORDER BY m.created_at DESC LIMIT $chat_limit
        ");
        $stmt->execute([$user_id, $target_id]);
        $messages = $stmt->fetchAll();
      } else {
        $stmt_block = $db->prepare("SELECT blocker_id FROM blocks WHERE (blocker_id = ? AND blocked_id = ?) OR (blocker_id = ? AND blocked_id = ?)");
        $stmt_block->execute([$user_id, $target_id, $target_id, $user_id]);
        $blocker = $stmt_block->fetchColumn();
        if ($blocker !== false) {
          if ($blocker == $user_id) {
            send_json(['status' => 'blocked', 'message' => 'You have blocked this user. Unblock them from their profile to send messages.']);
          } else {
            send_json(['status' => 'blocked', 'message' => 'You cannot reply to this conversation.']);
          }
        }

        $db->prepare("UPDATE messages SET is_read = 1 WHERE sender_id = ? AND receiver_id = ?")->execute([$target_id, $user_id]);
        $stmt = $db->prepare("
          SELECT m.id, m.sender_id, u.artist as sender_name, m.content, m.image, m.created_at, m.is_edited, m.reply_to_id, m.media_type,
          (SELECT 1 FROM starred_messages sm WHERE sm.message_id = m.id AND sm.user_id = ?) as is_starred
          FROM messages m 
          LEFT JOIN users u ON m.sender_id = u.id 
          WHERE m.group_id IS NULL AND ((m.sender_id = ? AND m.receiver_id = ?) OR (m.sender_id = ? AND m.receiver_id = ?)) 
          ORDER BY m.created_at DESC LIMIT $chat_limit
        ");
        $stmt->execute([$user_id, $user_id, $target_id, $target_id, $user_id]);
        $messages = $stmt->fetchAll();
      }
      
      if (!empty($messages)) {
        $messages = array_reverse($messages);
      }
      
      if (!empty($messages)) {
        $stmt_reply = $db->prepare("SELECT m.content, u.artist as sender_name FROM messages m LEFT JOIN users u ON m.sender_id = u.id WHERE m.id = ?");
        $stmt_react = $db->prepare("SELECT reaction, user_id FROM message_reactions WHERE message_id = ?");

        foreach ($messages as &$msg) {
          $msg['has_image'] = !empty($msg['image']) ? 1 : 0;
          $msg['media_type'] = $msg['media_type'] ?? 'image/webp';
          unset($msg['image']);

          if (!empty($msg['reply_to_id'])) {
            $stmt_reply->execute([$msg['reply_to_id']]);
            $rep = $stmt_reply->fetch();
            $msg['reply_content'] = $rep ? $rep['content'] : null;
            $msg['reply_sender'] = $rep ? $rep['sender_name'] : null;
          } else {
            $msg['reply_content'] = null;
            $msg['reply_sender'] = null;
          }

          $stmt_react->execute([$msg['id']]);
          $msg['reactions'] = $stmt_react->fetchAll();
        }
        unset($msg);
      }
      
      send_json($messages);
      break;

    case 'send_message':
      if (!$user_id) { http_response_code(403); exit; }
      $target_id = intval($_POST['target_id'] ?? 0);
      $chat_type = $_POST['chat_type'] ?? 'dm';
      $reply_to_id = !empty($_POST['reply_to_id']) ? intval($_POST['reply_to_id']) : null;
      $raw_content = trim($_POST['content'] ?? '');

      if ($target_id <= 0) {
        send_json(['status' => 'error', 'message' => 'Invalid recipient or group selected.']);
      }

      if (mb_strlen($raw_content, 'UTF-8') > 50000) {
        send_json(['status' => 'error', 'message' => 'Message exceeds 50,000 characters limit.']);
      }

      try {
        if ($chat_type === 'dm') {
          $stmt_user_check = $db->prepare("SELECT id FROM users WHERE id = ?");
          $stmt_user_check->execute([$target_id]);
          if (!$stmt_user_check->fetch()) {
            send_json(['status' => 'error', 'message' => 'Recipient user account does not exist.']);
          }

          $stmt_block = $db->prepare("SELECT 1 FROM blocks WHERE (blocker_id = ? AND blocked_id = ?) OR (blocker_id = ? AND blocked_id = ?)");
          $stmt_block->execute([$user_id, $target_id, $target_id, $user_id]);
          if ($stmt_block->fetch()) { send_json(['status' => 'error', 'message' => 'Cannot send message. A block is active.']); }
        } else {
          $stmt_mem = $db->prepare("SELECT 1 FROM chat_group_members WHERE group_id = ? AND user_id = ?");
          $stmt_mem->execute([$target_id, $user_id]);
          if (!$stmt_mem->fetch() && !$is_super_admin) { send_json(['status' => 'error', 'message' => 'You are not a member of this group.']); }
        }

        $mediaData = null;
        $mediaType = 'image/webp';

        if (isset($_FILES['image']) && $_FILES['image']['error'] === UPLOAD_ERR_OK) {
          if ($_FILES['image']['size'] > 50 * 1024 * 1024) {
            send_json(['status' => 'error', 'message' => 'File exceeds 50MB limit.']);
          }

          $mime = strtolower($_FILES['image']['type'] ?? '');
          if (empty($mime) && function_exists('mime_content_type')) {
            $mime = strtolower(mime_content_type($_FILES['image']['tmp_name']));
          }

          if (strpos($mime, 'image/') === 0 || strpos($mime, 'video/') === 0 || strpos($mime, 'audio/') === 0) {
            $mediaType = $mime;
            $ext = 'bin';
            if (strpos($mime, 'image/') === 0) $ext = 'jpg';
            if (strpos($mime, 'video/mp4') !== false) $ext = 'mp4';
            if (strpos($mime, 'video/webm') !== false) $ext = 'webm';
            if (strpos($mime, 'audio/') === 0) $ext = 'mp3';

            $shard = substr(md5(uniqid()), 0, 2);
            $media_dir = MUSIC_DIR . '/uploads/media/' . $shard;
            $thumb_dir = MUSIC_DIR . '/thumbnails/' . $shard;
            if (!is_dir($media_dir)) @mkdir($media_dir, 0755, true);
            if (!is_dir($thumb_dir)) @mkdir($thumb_dir, 0755, true);

            $filename = uniqid('msg_') . '.' . $ext;
            $dest_path = $media_dir . '/' . $filename;
            $rel_path = 'uploads/media/' . $shard . '/' . $filename;

            if (move_uploaded_file($_FILES['image']['tmp_name'], $dest_path)) {
              $mediaData = $rel_path;

              if (strpos($mime, 'image/') === 0) {
                $thumb_data = process_image_to_webp(file_get_contents($dest_path), 400, 70, false);
                if ($thumb_data) {
                  file_put_contents($thumb_dir . '/' . $filename . '.webp', $thumb_data);
                }
              }
            } else {
              send_json(['status' => 'error', 'message' => 'Failed to save media file.']);
            }
          } else {
            send_json(['status' => 'error', 'message' => 'Invalid file format. Only Images, Audio, and Video are allowed.']);
          }
        }

        if ($raw_content !== '' || $mediaData !== null) {
          $formatted_content = format_user_text($raw_content);
          if ($chat_type === 'group') {
            $db->prepare("INSERT INTO messages (sender_id, receiver_id, group_id, reply_to_id, content, image, media_type) VALUES (?, ?, ?, ?, ?, ?, ?)")->execute([$user_id, $user_id, $target_id, $reply_to_id, $formatted_content, $mediaData, $mediaType]);
          } else {
            $db->prepare("INSERT INTO messages (sender_id, receiver_id, reply_to_id, content, image, media_type) VALUES (?, ?, ?, ?, ?, ?)")->execute([$user_id, $target_id, $reply_to_id, $formatted_content, $mediaData, $mediaType]);
          }
          send_json(['status' => 'success']);
        } else {
          send_json(['status' => 'error', 'message' => 'Empty message.']);
        }
      } catch (Exception $e) {
        http_response_code(500);
        send_json(['status' => 'error', 'message' => 'Database error: ' . $e->getMessage()]);
      }
      break;

    case 'edit_message':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $db->prepare("UPDATE messages SET content = ?, is_edited = 1 WHERE id = ? AND sender_id = ?")->execute([format_user_text($data['content']), intval($data['id']), $user_id]);
      send_json(['status' => 'success']);
      break;

    case 'delete_message':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $db->prepare("DELETE FROM messages WHERE id = ? AND sender_id = ?")->execute([intval($data['id']), $user_id]);
      send_json(['status' => 'success']);
      break;

    case 'toggle_message_reaction':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $msg_id = intval($data['message_id']);
      $reaction = $data['reaction'];
      $existing = $db->prepare("SELECT reaction FROM message_reactions WHERE user_id = ? AND message_id = ?");
      $existing->execute([$user_id, $msg_id]);
      if ($existing->fetchColumn() === $reaction) {
        $db->prepare("DELETE FROM message_reactions WHERE user_id = ? AND message_id = ?")->execute([$user_id, $msg_id]);
      } else {
        $db->prepare("REPLACE INTO message_reactions (user_id, message_id, reaction) VALUES (?, ?, ?)")->execute([$user_id, $msg_id, $reaction]);
      }
      send_json(['status' => 'success']);
      break;

    case 'toggle_star_message':
      if (!$user_id) { http_response_code(403); exit; }
      $db->exec("CREATE TABLE IF NOT EXISTS starred_messages (user_id INTEGER NOT NULL, message_id INTEGER NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (user_id, message_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE CASCADE);");
      $data = json_decode(file_get_contents('php://input'), true);
      $msg_id = intval($data['message_id']);
      $stmt = $db->prepare("SELECT 1 FROM starred_messages WHERE user_id = ? AND message_id = ?");
      $stmt->execute([$user_id, $msg_id]);
      if ($stmt->fetch()) {
        $db->prepare("DELETE FROM starred_messages WHERE user_id = ? AND message_id = ?")->execute([$user_id, $msg_id]);
        send_json(['status' => 'unstarred']);
      } else {
        $db->prepare("INSERT INTO starred_messages (user_id, message_id) VALUES (?, ?)")->execute([$user_id, $msg_id]);
        send_json(['status' => 'starred']);
      }
      break;

    case 'get_starred_messages':
      if (!$user_id) { send_json([]); }
      
      try { $db->query("SELECT media_type FROM messages LIMIT 1"); } catch (Exception $e) { try { $db->exec("ALTER TABLE messages ADD COLUMN media_type TEXT DEFAULT 'image/webp'"); } catch(Exception $ex) {} }
      
      $page = isset($_GET['page']) ? max(1, (int)$_GET['page']) : 1;
      $offset = ($page - 1) * 25;
      
      try {
        $stmt = $db->prepare("
          SELECT m.id, m.content, CASE WHEN m.image IS NOT NULL THEN 1 ELSE 0 END as has_image, m.media_type, m.created_at, m.sender_id, u.artist as sender_name, sm.created_at as starred_at
          FROM starred_messages sm
          JOIN messages m ON sm.message_id = m.id
          LEFT JOIN users u ON m.sender_id = u.id
          WHERE sm.user_id = ?
          ORDER BY sm.created_at DESC LIMIT 25 OFFSET " . (int)$offset . "
        ");
      } catch (Exception $e) {
        $stmt = $db->prepare("
          SELECT m.id, m.content, CASE WHEN m.image IS NOT NULL THEN 1 ELSE 0 END as has_image, 'image/webp' as media_type, m.created_at, m.sender_id, u.artist as sender_name, sm.created_at as starred_at
          FROM starred_messages sm
          JOIN messages m ON sm.message_id = m.id
          LEFT JOIN users u ON m.sender_id = u.id
          WHERE sm.user_id = ?
          ORDER BY sm.created_at DESC LIMIT 25 OFFSET " . (int)$offset . "
        ");
      }
      
      $stmt->execute([$user_id]);
      send_json($stmt->fetchAll());
      break;

    case 'get_statuses':
      if (!$user_id) { send_json([]); }
      $db->exec("CREATE TABLE IF NOT EXISTS user_statuses (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, content TEXT, image BLOB, media_type TEXT DEFAULT 'image/webp', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);");
      try { $db->query("SELECT media_type FROM user_statuses LIMIT 1"); } catch (Exception $e) { try { $db->exec("ALTER TABLE user_statuses ADD COLUMN media_type TEXT DEFAULT 'image/webp'"); } catch(Exception $ex) {} }
      
      // Delete old statuses (> 24 hours) automatically upon fetching
      $db->exec("DELETE FROM user_statuses WHERE created_at < datetime('now', '-1 day')");
      
      $page = isset($_GET['page']) ? max(1, (int)$_GET['page']) : 1;
      $offset = ($page - 1) * 25;
      
      try {
        $stmt = $db->prepare("
          SELECT s.id, s.content, s.image, s.media_type, s.created_at, u.id as user_id, u.artist as name
          FROM user_statuses s
          JOIN users u ON s.user_id = u.id
          WHERE s.user_id = ? OR s.user_id IN (SELECT following_id FROM follows WHERE follower_id = ?)
          ORDER BY s.created_at DESC LIMIT 25 OFFSET " . (int)$offset . "
        ");
      } catch (Exception $e) {
        $stmt = $db->prepare("
          SELECT s.id, s.content, s.image, 'image/webp' as media_type, s.created_at, u.id as user_id, u.artist as name
          FROM user_statuses s
          JOIN users u ON s.user_id = u.id
          WHERE s.user_id = ? OR s.user_id IN (SELECT following_id FROM follows WHERE follower_id = ?)
          ORDER BY s.created_at DESC LIMIT 25 OFFSET " . (int)$offset . "
        ");
      }
      
      $stmt->execute([$user_id, $user_id]);
      send_json($stmt->fetchAll());
      break;

    case 'post_status':
      if (!$user_id) { http_response_code(403); exit; }
      $db->exec("CREATE TABLE IF NOT EXISTS user_statuses (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, content TEXT, image BLOB, media_type TEXT DEFAULT 'image/webp', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);");
      try { $db->query("SELECT media_type FROM user_statuses LIMIT 1"); } catch (Exception $e) { try { $db->exec("ALTER TABLE user_statuses ADD COLUMN media_type TEXT DEFAULT 'image/webp'"); } catch(Exception $ex) {} }
      $content = trim(htmlspecialchars($_POST['content'] ?? '', ENT_QUOTES, 'UTF-8'));
      $mediaData = null;
      $mediaType = 'image/webp';
      
      if (isset($_FILES['image']) && $_FILES['image']['error'] === UPLOAD_ERR_OK) {
        $mime = strtolower($_FILES['image']['type'] ?? '');
        if (strpos($mime, 'image/') === 0 || strpos($mime, 'video/') === 0) {
          $shard = substr(md5(uniqid()), 0, 2);
          $media_dir = MUSIC_DIR . '/uploads/media/' . $shard;
          if (!is_dir($media_dir)) @mkdir($media_dir, 0755, true);
          
          if (strpos($mime, 'video/') === 0) {
            $mediaType = $mime;
            $ext = 'mp4';
            $filename = uniqid('status_') . '.' . $ext;
            $dest_path = $media_dir . '/' . $filename;
            if (move_uploaded_file($_FILES['image']['tmp_name'], $dest_path)) {
              $mediaData = 'uploads/media/' . $shard . '/' . $filename;
            }
          } else {
            $mediaType = 'image/webp';
            $ext = 'webp';
            $filename = uniqid('status_') . '.' . $ext;
            $dest_path = $media_dir . '/' . $filename;
            
            $imageData = file_get_contents($_FILES['image']['tmp_name']);
            // Compress to webp, false ensures aspect ratio is strictly maintained
            $webpData = process_image_to_webp($imageData, 1080, 80, false);
            if ($webpData) {
              if (file_put_contents($dest_path, $webpData)) {
                $mediaData = 'uploads/media/' . $shard . '/' . $filename;
              }
            } else {
              // Fallback if compression fails
              if (move_uploaded_file($_FILES['image']['tmp_name'], $dest_path)) {
                $mediaData = 'uploads/media/' . $shard . '/' . $filename;
              }
            }
          }
        }
      }
      
      if ($content !== '' || $mediaData !== null) {
        $db->prepare("INSERT INTO user_statuses (user_id, content, image, media_type) VALUES (?, ?, ?, ?)")->execute([$user_id, format_user_text($content), $mediaData, $mediaType]);
        send_json(['status' => 'success']);
      } else {
        send_json(['status' => 'error', 'message' => 'Empty status.']);
      }
      break;

    case 'delete_status':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $db->prepare("DELETE FROM user_statuses WHERE id = ? AND user_id = ?")->execute([intval($data['id']), $user_id]);
      send_json(['status' => 'success']);
      break;
      
    case 'get_status_media':
      header('Cache-Control: public, max-age=86400');
      $id = intval($_GET['id'] ?? 0);
      $stmt = $db->prepare("SELECT image, media_type FROM user_statuses WHERE id = ?");
      $stmt->execute([$id]);
      $msg = $stmt->fetch();
      if ($msg && $msg['image']) {
        $file_path = MUSIC_DIR . '/' . $msg['image'];
        if (file_exists($file_path)) {
          header('Content-Type: ' . ($msg['media_type'] ?? 'image/webp'));
          readfile($file_path);
          exit;
        }
      }
      http_response_code(404); exit;

    case 'get_group_image':
      header('Cache-Control: public, max-age=31536000, immutable');
      $group_id = intval($_GET['id'] ?? 0);
      $stmt = $db->prepare("SELECT image FROM chat_groups WHERE id = ?");
      $stmt->execute([$group_id]);
      $img = $stmt->fetchColumn();
      if ($img) {
        header('Content-Type: image/webp');
        echo $img;
        exit;
      }
      http_response_code(404); exit;

    case 'get_art_image':
      header('Cache-Control: public, max-age=31536000, immutable');
      $path = $_GET['path'] ?? '';
      $file_path = MUSIC_DIR . '/' . $path;
      // Secure traversal prevention and enforce arts directory
      if ($path && (strpos($path, 'uploads/arts/') === 0 || strpos($path, 'phpshares/') === 0) && strpos($path, '..') === false && file_exists($file_path)) {
        $ext = strtolower(pathinfo($file_path, PATHINFO_EXTENSION));
        $mime = 'image/jpeg';
        if ($ext === 'png') $mime = 'image/png';
        elseif ($ext === 'gif') $mime = 'image/gif';
        elseif ($ext === 'webp') $mime = 'image/webp';
        header('Content-Type: ' . $mime);
        readfile($file_path);
        exit;
      }
      http_response_code(404); exit;

    case 'create_chat_group':
      if (!$user_id) { http_response_code(403); exit; }
      $name = trim(htmlspecialchars($_POST['name'] ?? '', ENT_QUOTES, 'UTF-8'));
      $desc = trim(htmlspecialchars($_POST['description'] ?? '', ENT_QUOTES, 'UTF-8'));
      if (empty($name)) { send_json(['status' => 'error', 'message' => 'Name required']); }
      
      $webpData = null;
      if (isset($_FILES['image']) && $_FILES['image']['error'] === UPLOAD_ERR_OK) {
        $allowed = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
        if (in_array($_FILES['image']['type'], $allowed)) {
          $webpData = process_image_to_webp(file_get_contents($_FILES['image']['tmp_name']), 300, 80);
        }
      }

      $db->prepare("INSERT INTO chat_groups (name, description, owner_id, image) VALUES (?, ?, ?, ?)")->execute([$name, $desc, $user_id, $webpData]);
      $group_id = $db->lastInsertId();
      $db->prepare("INSERT INTO chat_group_members (group_id, user_id, role) VALUES (?, ?, 'owner')")->execute([$group_id, $user_id]);
      send_json(['status' => 'success', 'group_id' => $group_id]);
      break;
      
    case 'get_group_info':
      if (!$user_id) { send_json([]); }
      $group_id = intval($_GET['id'] ?? 0);
      $page = isset($_GET['page']) ? max(1, (int)$_GET['page']) : 1;
      $offset = ($page - 1) * 25;

      $stmt = $db->prepare("SELECT id, name, description, owner_id, created_at FROM chat_groups WHERE id = ?");
      $stmt->execute([$group_id]);
      $group = $stmt->fetch();
      if ($group) {
        $mem_stmt = $db->prepare("SELECT u.id, u.artist, m.role FROM chat_group_members m JOIN users u ON m.user_id = u.id WHERE m.group_id = ? ORDER BY m.role = 'owner' DESC, u.artist ASC LIMIT 25 OFFSET ?");
        $mem_stmt->execute([$group_id, $offset]);
        $group['members'] = $mem_stmt->fetchAll();
         
        $count_stmt = $db->prepare("SELECT COUNT(*) FROM chat_group_members WHERE group_id = ?");
        $count_stmt->execute([$group_id]);
        $group['total_members'] = $count_stmt->fetchColumn();
         
         send_json(['status' => 'success', 'group' => $group, 'page' => $page]);
      } else {
        send_json(['status' => 'error']);
      }
      break;
      
    case 'edit_chat_group':
      if (!$user_id) { http_response_code(403); exit; }
      $group_id = intval($_POST['id'] ?? 0);
      $name = trim(htmlspecialchars($_POST['name'] ?? '', ENT_QUOTES, 'UTF-8'));
      $desc = trim(htmlspecialchars($_POST['description'] ?? '', ENT_QUOTES, 'UTF-8'));
      
      $webpData = null;
      if (isset($_FILES['image']) && $_FILES['image']['error'] === UPLOAD_ERR_OK) {
        $allowed = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
        if (in_array($_FILES['image']['type'], $allowed)) {
          $webpData = process_image_to_webp(file_get_contents($_FILES['image']['tmp_name']), 300, 80);
        }
        if ($is_super_admin) {
          $db->prepare("UPDATE chat_groups SET name = ?, description = ?, image = ? WHERE id = ?")->execute([$name, $desc, $webpData, $group_id]);
        } else {
          $db->prepare("UPDATE chat_groups SET name = ?, description = ?, image = ? WHERE id = ? AND owner_id = ?")->execute([$name, $desc, $webpData, $group_id, $user_id]);
        }
      } else {
        if ($is_super_admin) {
          $db->prepare("UPDATE chat_groups SET name = ?, description = ? WHERE id = ?")->execute([$name, $desc, $group_id]);
        } else {
          $db->prepare("UPDATE chat_groups SET name = ?, description = ? WHERE id = ? AND owner_id = ?")->execute([$name, $desc, $group_id, $user_id]);
        }
      }
      
      send_json(['status' => 'success']);
      break;

    case 'delete_chat_group':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      if ($is_super_admin) {
        $db->prepare("DELETE FROM chat_groups WHERE id = ?")->execute([intval($data['id'])]);
      } else {
        $db->prepare("DELETE FROM chat_groups WHERE id = ? AND owner_id = ?")->execute([intval($data['id']), $user_id]);
      }
      send_json(['status' => 'success']);
      break;

    case 'transfer_group_ownership':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $group_id = intval($data['group_id']);
      $new_owner_id = intval($data['new_owner_id']);
      
      $stmt = $db->prepare("SELECT owner_id FROM chat_groups WHERE id = ?");
      $stmt->execute([$group_id]);
      $current_owner = $stmt->fetchColumn();
      
      if ($current_owner != $user_id && !$is_super_admin) {
        send_json(['status' => 'error', 'message' => 'Only the current owner can transfer ownership.']);
      }
      
      $db->beginTransaction();
      try {
        $db->prepare("UPDATE chat_groups SET owner_id = ? WHERE id = ?")->execute([$new_owner_id, $group_id]);
        $db->prepare("UPDATE chat_group_members SET role = 'member' WHERE group_id = ? AND user_id = ?")->execute([$group_id, $current_owner]);
        $db->prepare("UPDATE chat_group_members SET role = 'owner' WHERE group_id = ? AND user_id = ?")->execute([$group_id, $new_owner_id]);
        $db->commit();
        send_json(['status' => 'success', 'message' => 'Ownership transferred successfully.']);
      } catch (Exception $e) {
        $db->rollBack();
        send_json(['status' => 'error', 'message' => 'Database error.']);
      }
      break;

    case 'leave_chat_group':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $group_id = intval($data['id']);
      
      $stmt = $db->prepare("SELECT owner_id FROM chat_groups WHERE id = ?");
      $stmt->execute([$group_id]);
      $owner_id = $stmt->fetchColumn();
      
      if ($owner_id == $user_id) {
        $stmt_rand = $db->prepare("SELECT user_id FROM chat_group_members WHERE group_id = ? AND user_id != ? ORDER BY RANDOM() LIMIT 1");
        $stmt_rand->execute([$group_id, $user_id]);
        $new_owner = $stmt_rand->fetchColumn();
        
        if ($new_owner) {
          $db->prepare("UPDATE chat_groups SET owner_id = ? WHERE id = ?")->execute([$new_owner, $group_id]);
          $db->prepare("UPDATE chat_group_members SET role = 'owner' WHERE group_id = ? AND user_id = ?")->execute([$group_id, $new_owner]);
        } else {
          $db->prepare("DELETE FROM chat_groups WHERE id = ?")->execute([$group_id]);
          send_json(['status' => 'success', 'message' => 'Group deleted as it was empty.']);
          exit;
        }
      }
      
      $db->prepare("DELETE FROM chat_group_members WHERE group_id = ? AND user_id = ?")->execute([$group_id, $user_id]);
      send_json(['status' => 'success']);
      break;

    case 'generate_group_invite':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $group_id = intval($data['id']);
      $expire_val = $data['expire'] ?? null;
      $db->exec("DELETE FROM chat_group_invites WHERE expires_at IS NOT NULL AND expires_at <= CURRENT_TIMESTAMP");
      
      $stmt_owner = $db->prepare("SELECT 1 FROM chat_groups WHERE id = ? AND owner_id = ?");
      $stmt_owner->execute([$group_id, $user_id]);
      if (!$stmt_owner->fetch() && !$is_super_admin) { send_json(['status' => 'error', 'message' => 'Only owners can invite.']); }
      
      $expires_at = null;
      if ($expire_val && is_numeric($expire_val)) {
        $expires_at = date('Y-m-d H:i:s', time() + ((int)$expire_val * 60));
      }
      $token = bin2hex(random_bytes(16));
      $db->prepare("INSERT INTO chat_group_invites (token, group_id, expires_at) VALUES (?, ?, ?)")->execute([$token, $group_id, $expires_at]);
      send_json(['status' => 'success', 'token' => $token]);
      break;

    case 'join_group':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $token = $data['token'] ?? '';
      $stmt_inv = $db->prepare("SELECT group_id FROM chat_group_invites WHERE token = ? AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP)");
      $stmt_inv->execute([$token]);
      $inv_group_id = $stmt_inv->fetchColumn();
      
      if (!$inv_group_id) { send_json(['status' => 'error', 'message' => 'Invalid or expired invite link.']); }
      
      $db->prepare("INSERT OR IGNORE INTO chat_group_members (group_id, user_id) VALUES (?, ?)")->execute([$inv_group_id, $user_id]);
      send_json(['status' => 'success', 'group_id' => $inv_group_id]);
      break;

    case 'get_message_image':
      header('Cache-Control: public, max-age=31536000, immutable');
      $msg_id = intval($_GET['id'] ?? 0);
      $is_thumb = isset($_GET['thumb']) && $_GET['thumb'] == '1';
      
      try {
        $stmt = $db->prepare("SELECT image, sender_id, receiver_id, media_type FROM messages WHERE id = ?");
      } catch (Exception $e) {
        $stmt = $db->prepare("SELECT image, sender_id, receiver_id, 'image/webp' as media_type FROM messages WHERE id = ?");
      }
      $stmt->execute([$msg_id]);
      $msg = $stmt->fetch();
      
      if ($msg && $msg['image']) {
        $stmt_grp = $db->prepare("SELECT group_id FROM messages WHERE id = ?");
        $stmt_grp->execute([$msg_id]);
        $grp_id = $stmt_grp->fetchColumn();
        
        $has_access = false;
        if ($grp_id) {
          $stmt_mem = $db->prepare("SELECT 1 FROM chat_group_members WHERE group_id = ? AND user_id = ?");
          $stmt_mem->execute([$grp_id, $user_id]);
          if ($stmt_mem->fetch() || $is_super_admin) $has_access = true;
        } else {
          if ($msg['sender_id'] == $user_id || $msg['receiver_id'] == $user_id || $is_super_admin) $has_access = true;
        }
        
        if ($has_access) {
          $mime = $msg['media_type'] ?? 'image/webp';
          $is_filepath = (strpos($msg['image'], 'uploads/media/') === 0);

          if ($is_filepath) {
            $file_path = MUSIC_DIR . '/' . $msg['image'];
            
            if ($is_thumb && strpos($mime, 'image/') === 0) {
              $thumb_path = str_replace('uploads/media/', 'thumbnails/', $file_path) . '.webp';
              if (file_exists($thumb_path)) {
                $file_path = $thumb_path;
                $mime = 'image/webp';
              }
            }

            if (!file_exists($file_path)) {
              http_response_code(404); exit;
            }

            header('Content-Type: ' . $mime);
            header('Accept-Ranges: bytes');
            
            $filesize = filesize($file_path);
            $start = 0;
            $end = $filesize - 1;
            $length = $filesize;

            if (isset($_SERVER['HTTP_RANGE'])) {
              $range = str_replace('bytes=', '', $_SERVER['HTTP_RANGE']);
              $parts = explode('-', $range, 2);
              $start = intval($parts[0]);
              if (isset($parts[1]) && $parts[1] !== '') {
                $end = intval($parts[1]);
              }
              if ($start > $end || $start >= $filesize) {
                header('HTTP/1.1 416 Range Not Satisfiable');
                header("Content-Range: bytes */$filesize");
                exit;
              }
              $length = $end - $start + 1;
              header('HTTP/1.1 206 Partial Content');
              header("Content-Range: bytes $start-$end/$filesize");
            } else {
              header('HTTP/1.1 200 OK');
            }
            header('Content-Length: ' . $length);

            $f = @fopen($file_path, 'rb');
            if ($f) {
              fseek($f, $start);
              $chunk_size = 1024 * 8;
              $bytes_left = $length;
              while ($bytes_left > 0 && !feof($f)) {
                if (connection_aborted()) break;
                $read_size = min($chunk_size, $bytes_left);
                $data = fread($f, $read_size);
                if ($data === false) break;
                echo $data;
                @flush();
                $bytes_left -= strlen($data);
              }
              fclose($f);
            }
            exit;
          } else {
            // Legacy BLOB handler
            header('Content-Type: ' . $mime);
            if (strpos($mime, 'video/') === 0 || strpos($mime, 'audio/') === 0) {
              header('Accept-Ranges: bytes');
              $filesize = strlen($msg['image']);
              $start = 0;
              $end = $filesize - 1;
              $length = $filesize;

              if (isset($_SERVER['HTTP_RANGE'])) {
                $range = str_replace('bytes=', '', $_SERVER['HTTP_RANGE']);
                $parts = explode('-', $range, 2);
                $start = intval($parts[0]);
                if (isset($parts[1]) && $parts[1] !== '') {
                  $end = intval($parts[1]);
                }
                if ($start > $end || $start >= $filesize) {
                  header('HTTP/1.1 416 Range Not Satisfiable');
                  header("Content-Range: bytes */$filesize");
                  exit;
                }
                $length = $end - $start + 1;
                header('HTTP/1.1 206 Partial Content');
                header("Content-Range: bytes $start-$end/$filesize");
              } else {
                header('HTTP/1.1 200 OK');
              }
              header('Content-Length: ' . $length);
              echo substr($msg['image'], $start, $length);
            } else {
              echo $msg['image'];
            }
            exit;
          }
        }
      }
      http_response_code(404); exit;

    case 'toggle_follow':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $following_id = intval($data['following_id']);
      if ($following_id === $user_id) {
        send_json(['status' => 'error', 'message' => 'Cannot follow yourself.']);
      }
      $stmt = $db->prepare("SELECT 1 FROM follows WHERE follower_id = ? AND following_id = ?");
      $stmt->execute([$user_id, $following_id]);
      if ($stmt->fetch()) {
        $db->prepare("DELETE FROM follows WHERE follower_id = ? AND following_id = ?")->execute([$user_id, $following_id]);
        send_json(['status' => 'unfollowed']);
      } else {
        $db->prepare("INSERT INTO follows (follower_id, following_id) VALUES (?, ?)")->execute([$user_id, $following_id]);
        
        try { 
          $db->prepare("INSERT INTO activity_feed (user_id, action, target_name) VALUES (?, 'started following', (SELECT artist FROM users WHERE id = ?))")->execute([$user_id, $following_id]); 
        } catch(Exception $e) {}
        
        send_json(['status' => 'followed']);
      }
      break;

    case 'unfollow_all':
      if (!$user_id) { http_response_code(403); exit; }
      $db->prepare("DELETE FROM follows WHERE follower_id = ?")->execute([$user_id]);
      send_json(['status' => 'success', 'message' => 'Unfollowed all users successfully.']);
      break;

    case 'update_favorite_order':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $ordered_ids = $data['ids'];
      $db->beginTransaction();
      try {
        foreach ($ordered_ids as $index => $song_id) {
          $db->prepare("UPDATE favorites SET sort_order = ? WHERE user_id = ? AND song_id = ?")
             ->execute([$index, $user_id, $song_id]);
        }
        $db->commit();
        send_json(['status' => 'success']);
      } catch (Exception $e) {
        $db->rollBack();
        http_response_code(500);
        send_json(['status' => 'error', 'message' => 'Failed to update order.']);
      }
      break;

    case 'get_view_ids':
