        $stmt_following = $db->prepare("SELECT COUNT(*) FROM follows WHERE follower_id = ?");
        $stmt_following->execute([$user_id]);
        $details['following_count'] = $stmt_following->fetchColumn();

        $stmt_rec_art = $db->prepare("SELECT id, artist FROM users WHERE id != ? AND banned = 0 AND email NOT LIKE 'deleted_%' ORDER BY RANDOM() LIMIT 5");
        $stmt_rec_art->execute([$user_id]);
        $details['recommended_artists'] = $stmt_rec_art->fetchAll();

        // FIX: Fetch the user's playlists for the "My Profile" view
        $stmt_playlists = $db->prepare("SELECT p.name, p.public_id, p.is_collaborative, p.is_private, p.created_at, (SELECT ps.song_id FROM playlist_songs ps WHERE ps.playlist_id = p.id ORDER BY ps.added_at DESC LIMIT 1) as image_id, (SELECT m.last_modified FROM playlist_songs ps2 JOIN music m ON ps2.song_id = m.id WHERE ps2.playlist_id = p.id ORDER BY ps2.added_at DESC LIMIT 1) as image_v, (SELECT COUNT(*) FROM playlist_songs ps WHERE ps.playlist_id = p.id) as song_count FROM playlists p WHERE p.user_id = ? ORDER BY p.created_at DESC");
        $stmt_playlists->execute([$user_id]);
        $details['playlists'] = $stmt_playlists->fetchAll();

        $details['public_id'] = null;
        $details['user_id'] = $user_id;

        $sort_map = [
          'id_desc' => 'ORDER BY m.id DESC',
          'id_asc' => 'ORDER BY m.id ASC',
          'artist_asc' => 'ORDER BY m.artist COLLATE NOCASE ASC, m.album COLLATE NOCASE ASC, m.title COLLATE NOCASE ASC',
          'title_asc' => 'ORDER BY m.title COLLATE NOCASE ASC',
          'album_asc' => 'ORDER BY m.album COLLATE NOCASE ASC, m.title COLLATE NOCASE ASC',
          'year_desc' => 'ORDER BY m.year DESC',
          'year_asc' => 'ORDER BY m.year ASC',
        ];
        $order_by = $sort_map[$sort] ?? $sort_map['title_asc'];

        $search_cond = '';
        $q = $_GET['q'] ?? '';
        $params = [$user_id, $user_id, $user_id, $user_id];
        if ($q !== '') {
          $search_cond = " AND (match_text(m.title, ?) = 1 OR match_text(m.artist, ?) = 1 OR match_text(m.album, ?) = 1)";
          $params[] = $q;
          $params[] = $q;
          $params[] = $q;
        }

        $stmt_songs = $db->prepare("
          SELECT m.id, m.title, m.artist, m.album, m.genre, m.duration, m.user_id, m.is_private, m.is_collaborative, m.last_modified, CASE WHEN f.song_id IS NOT NULL THEN 1 ELSE 0 END AS is_favorite, (SELECT SUM(play_count) FROM play_counts WHERE song_id = m.id) as play_count
          FROM music m LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = ?
          WHERE (m.user_id = ? OR match_artist(m.artist, (SELECT artist FROM users WHERE id = ?)) = 1 OR m.id IN (SELECT song_id FROM song_collaborators WHERE user_id = ?)) {$search_cond} {$order_by} {$limit_clause}
        ");
        $stmt_songs->execute($params);
        $songs = $stmt_songs->fetchAll();
      } elseif ($type === 'playlist') {
        if (empty($name)) { http_response_code(400); exit; }
        $stmt_details = $db->prepare("
          SELECT p.name, p.description, p.public_id, p.user_id, p.is_private, u.artist as creator, p.play_count, p.created_at,
          (SELECT MAX(added_at) FROM playlist_songs WHERE playlist_id = p.id) as updated_at,
          (SELECT COUNT(*) FROM playlist_songs WHERE playlist_id = p.id) as song_count,
          (SELECT SUM(m.duration) FROM music m JOIN playlist_songs ps ON m.id = ps.song_id WHERE ps.playlist_id = p.id) as total_duration,
          (SELECT ps.song_id FROM playlist_songs ps WHERE ps.playlist_id = p.id ORDER BY ps.added_at DESC LIMIT 1) as image_id
          FROM playlists p JOIN users u ON p.user_id = u.id
          WHERE p.public_id = ?
        ");
        $stmt_details->execute([$name]);
        $details = $stmt_details->fetch();
        if ($details) {
          if ($details['is_private'] == 1 && $details['user_id'] != $user_id && $is_super_admin == 0) {
            http_response_code(403); send_json(['status' => 'error', 'message' => 'This playlist is private.']);
          }
          $details['image_url'] = '?action=get_image&id=' . ($details['image_id'] ?? 0);
        }
        $sort_map = [
          'manual_order' => 'ORDER BY ps.sort_order ASC', 'added_newest' => 'ORDER BY ps.added_at DESC', 'added_oldest' => 'ORDER BY ps.added_at ASC',
          'artist_asc' => 'ORDER BY m.artist COLLATE NOCASE ASC, m.album COLLATE NOCASE ASC', 'title_asc' => 'ORDER BY m.title COLLATE NOCASE ASC', 
          'album_asc' => 'ORDER BY m.album COLLATE NOCASE ASC',
        ];
        $order_by = $sort_map[$sort] ?? $sort_map['manual_order'];
        
        $q = $_GET['q'] ?? '';
        $search_cond = '';
        $params = [$user_id, $name];
        if ($q !== '') {
          $search_cond = " AND (match_text(m.title, ?) = 1 OR match_text(m.artist, ?) = 1 OR match_text(m.album, ?) = 1)";
          $params[] = $q;
          $params[] = $q;
          $params[] = $q;
        }
        
        $stmt_songs = $db->prepare("
          SELECT m.id, m.title, m.artist, m.album, m.genre, m.duration, m.user_id, m.is_private, m.is_collaborative, m.last_modified, CASE WHEN f.song_id IS NOT NULL THEN 1 ELSE 0 END AS is_favorite, (SELECT SUM(play_count) FROM play_counts WHERE song_id = m.id) as play_count
          FROM music m JOIN playlist_songs ps ON m.id = ps.song_id JOIN playlists p ON ps.playlist_id = p.id LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = ?
          WHERE p.public_id = ? {$search_cond} {$order_by} {$limit_clause}
        ");
        $stmt_songs->execute($params);
        $songs = $stmt_songs->fetchAll();
      } elseif ($type === 'mix') {
        $mix_public_id = $name;
        $stmt_details = $db->prepare("SELECT id, name, creator, image_id FROM mixes WHERE public_id = ?");
        $stmt_details->execute([$mix_public_id]);
        $mix_row = $stmt_details->fetch();
        if ($mix_row) {
          $details = [
            'name' => $mix_row['name'],
            'creator' => $mix_row['creator'],
            'image_url' => '?action=get_image&id=' . ($mix_row['image_id'] ?: 0),
            'song_count' => 0,
            'total_duration' => 0,
            'public_id' => $mix_public_id
          ];
          $q = $_GET['q'] ?? '';
          $search_cond = '';
          $params = [$user_id, $mix_row['id'], $user_id];
          if ($q !== '') {
            $search_cond = " AND (match_text(m.title, ?) = 1 OR match_text(m.artist, ?) = 1 OR match_text(m.album, ?) = 1)";
            $params[] = $q;
            $params[] = $q;
            $params[] = $q;
          }

          $stmt_songs = $db->prepare("
            SELECT m.id, m.title, m.artist, m.album, m.genre, m.duration, m.user_id, m.is_private, m.is_collaborative, m.last_modified, CASE WHEN f.song_id IS NOT NULL THEN 1 ELSE 0 END AS is_favorite, (SELECT SUM(play_count) FROM play_counts WHERE song_id = m.id) as play_count
            FROM music m 
            JOIN mix_songs ms ON m.id = ms.song_id 
            LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = ?
            WHERE ms.mix_id = ? AND (m.is_private = 0 OR m.user_id = ? OR {$is_super_admin} = 1) {$search_cond} ORDER BY ms.sort_order ASC
          ");
          $stmt_songs->execute($params);
          $songs = $stmt_songs->fetchAll();
          $details['play_count'] = 0;
          foreach($songs as $s) { 
            $details['total_duration'] += $s['duration']; 
            $details['play_count'] += $s['play_count'] ? $s['play_count'] : 0;
          }
          $details['song_count'] = count($songs);
        }
      } elseif (in_array($type, ['artist', 'album', 'genre', 'year'])) {
        if ($name === '') { http_response_code(400); exit; }
        $field = $type;
        $filter_user_id = $_GET['filter_user_id'] ?? '';
        $artist_name = $_GET['artist_name'] ?? '';
        $user_cond = "";
        $user_params = [];
        
        if ($field === 'artist') {
          if ($filter_user_id !== '') {
            $field_cond = "(match_artist(m.artist, ?) = 1 OR m.user_id = ? OR m.id IN (SELECT song_id FROM song_collaborators WHERE user_id = ?)) AND (m.is_private = 0 OR m.user_id = ? OR match_artist(m.artist, (SELECT artist FROM users WHERE id = ?)) = 1 OR m.id IN (SELECT song_id FROM song_collaborators WHERE user_id = ?) OR {$is_super_admin} = 1)";
            $user_params[] = $name;
            $user_params[] = $filter_user_id;
            $user_params[] = $filter_user_id;
            $user_params[] = $user_id;
            $user_params[] = $user_id;
            $user_params[] = $user_id;
            $filter_user_id = ''; // Processed here, prevent global append
          } else {
            $field_cond = "match_artist(m.artist, ?) = 1 AND (m.is_private = 0 OR m.user_id = ? OR match_artist(m.artist, (SELECT artist FROM users WHERE id = ?)) = 1 OR m.id IN (SELECT song_id FROM song_collaborators WHERE user_id = ?) OR {$is_super_admin} = 1)";
            $user_params[] = $name;
            $user_params[] = $user_id;
            $user_params[] = $user_id;
            $user_params[] = $user_id;
          }
        } else {
          $field_cond = "m.{$field} = ? AND (m.is_private = 0 OR m.user_id = ? OR match_artist(m.artist, (SELECT artist FROM users WHERE id = ?)) = 1 OR {$is_super_admin} = 1)";
          $user_params[] = $name;
          $user_params[] = $user_id;
          $user_params[] = $user_id;
          if ($field === 'album' && $artist_name !== '') {
            $field_cond .= " AND match_artist(m.artist, ?) = 1";
            $user_params[] = $artist_name;
          }
        }
        
        if ($filter_user_id !== '') {
          $user_cond = " AND m.user_id = ?";
          $user_params[] = $filter_user_id;
        }

        // Advanced Fallback: Fetch basic stats first
        $stmt_details = $db->prepare("SELECT COUNT(*) as song_count, SUM(duration) as total_duration, MAX(user_id) as user_id, MIN(last_modified) as uploaded_at, MAX(year) as release_year, SUM((SELECT COALESCE(SUM(play_count), 0) FROM play_counts WHERE song_id = m.id)) as play_count FROM music m WHERE {$field_cond} {$user_cond}");
        $stmt_details->execute($user_params);
        $details = $stmt_details->fetch();
        
        // Advanced Fallback: Query explicitly for the newest song that actually has a cover image
        $stmt_img = $db->prepare("SELECT id, last_modified FROM music m WHERE {$field_cond} {$user_cond} AND image IS NOT NULL ORDER BY id DESC LIMIT 1");
        $stmt_img->execute($user_params);
        $img_row = $stmt_img->fetch();
        $verified_image_id = $img_row ? $img_row['id'] : 0;
        $verified_image_v = $img_row ? $img_row['last_modified'] : 0;

        $details['name'] = $name;
        $details['image_url'] = '?action=get_image&id=' . $verified_image_id . '&v=' . $verified_image_v;
        $details['public_id'] = null;

        if ($type === 'artist') {
          $stmt_user = $db->prepare("SELECT id, banned, email, bio FROM users WHERE artist = ? COLLATE NOCASE");
          $stmt_user->execute([$name]);
          $artist_user = $stmt_user->fetch();

          if ($artist_user) {
            if ($artist_user['banned'] == 1 || strpos((string)$artist_user['email'], 'deleted_') === 0) {
              http_response_code(404);
              send_json(['status' => 'error', 'message' => 'User not found or this user already deleted.']);
            }
            $artist_user_id = $artist_user['id'];
            $details['is_user'] = true;
            $details['user_id'] = $artist_user_id;
            $stmt_followers = $db->prepare("SELECT COUNT(*) FROM follows WHERE following_id = ?");
            $stmt_followers->execute([$artist_user_id]);
            $details['followers_count'] = $stmt_followers->fetchColumn();
            
            $stmt_following = $db->prepare("SELECT COUNT(*) FROM follows WHERE follower_id = ?");
            $stmt_following->execute([$artist_user_id]);
            $details['following_count'] = $stmt_following->fetchColumn();
            
            $details['image_url'] = '?action=get_profile_picture&id=' . $artist_user_id;
            $details['background_url'] = '?action=get_profile_background&id=' . $artist_user_id;
            $details['bio'] = $artist_user['bio'] ?? '';
            
            $stmt_rec_art = $db->prepare("SELECT id, artist FROM users WHERE id != ? AND banned = 0 AND email NOT LIKE 'deleted_%' ORDER BY RANDOM() LIMIT 25");
            $stmt_rec_art->execute([$artist_user_id]);
            $details['recommended_artists'] = $stmt_rec_art->fetchAll();
    
            $stmt_rec_songs = $db->prepare("SELECT id, title, artist, last_modified FROM music WHERE user_id = ? AND is_private = 0 ORDER BY (SELECT SUM(play_count) FROM play_counts WHERE song_id = music.id) DESC LIMIT 25");
            $stmt_rec_songs->execute([$artist_user_id]);
            $details['recommended_songs'] = $stmt_rec_songs->fetchAll();

            if ($user_id) {
              $stmt_follow = $db->prepare("SELECT 1 FROM follows WHERE follower_id = ? AND following_id = ?");
              $stmt_follow->execute([$user_id, $artist_user_id]);
              $details['is_following'] = (bool)$stmt_follow->fetchColumn();

              $stmt_block = $db->prepare("SELECT 1 FROM blocks WHERE blocker_id = ? AND blocked_id = ?");
              $stmt_block->execute([$user_id, $artist_user_id]);
              $details['is_blocked'] = (bool)$stmt_block->fetchColumn();
            } else {
              $details['is_following'] = false;
            }
            // FIX: Added 'is_collaborative' and 'is_private' so the UI context menus work correctly on artist views
            $stmt_playlists = $db->prepare("SELECT p.name, p.public_id, p.is_collaborative, p.is_private, p.created_at, (SELECT ps.song_id FROM playlist_songs ps WHERE ps.playlist_id = p.id ORDER BY ps.added_at DESC LIMIT 1) as image_id, (SELECT m.last_modified FROM playlist_songs ps2 JOIN music m ON ps2.song_id = m.id WHERE ps2.playlist_id = p.id ORDER BY ps2.added_at DESC LIMIT 1) as image_v, (SELECT COUNT(*) FROM playlist_songs ps WHERE ps.playlist_id = p.id) as song_count FROM playlists p WHERE p.user_id = ? AND (p.is_private = 0 OR {$is_super_admin} = 1) ORDER BY p.created_at DESC");
            $stmt_playlists->execute([$artist_user_id]);
            $details['playlists'] = $stmt_playlists->fetchAll();
          }
        }

        $sort_map = [
          'artist_asc' => 'ORDER BY m.artist COLLATE NOCASE ASC, m.album COLLATE NOCASE ASC', 'title_asc' => 'ORDER BY m.title COLLATE NOCASE ASC',
          'album_asc' => 'ORDER BY m.album COLLATE NOCASE ASC, m.title COLLATE NOCASE ASC', 'year_desc' => 'ORDER BY m.year DESC', 'year_asc' => 'ORDER BY m.year ASC',
        ];
        $default_sort = ($type === 'album') ? 'title_asc' : 'artist_asc';
        $order_by = $sort_map[$sort] ?? $sort_map[$default_sort];
        
        $search_cond = '';
        $q = $_GET['q'] ?? '';
        $exec_params = array_merge([$user_id], $user_params);
        if ($q !== '') {
          $search_cond = " AND (match_text(m.title, ?) = 1 OR match_text(m.album, ?) = 1 OR match_text(m.artist, ?) = 1)";
          $exec_params[] = $q;
          $exec_params[] = $q;
          $exec_params[] = $q;
        }

        $stmt_songs = $db->prepare("
          SELECT m.id, m.title, m.artist, m.album, m.genre, m.duration, m.user_id, m.is_private, m.is_collaborative, m.last_modified, CASE WHEN f.song_id IS NOT NULL THEN 1 ELSE 0 END AS is_favorite, (SELECT SUM(play_count) FROM play_counts WHERE song_id = m.id) as play_count
          FROM music m LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = ?
          WHERE {$field_cond} {$user_cond} {$search_cond} {$order_by} {$limit_clause}
        ");
        
        $stmt_songs->execute($exec_params);
        $songs = $stmt_songs->fetchAll();
      }
      send_json(['details' => $details, 'songs' => $songs]);
      break;

    case 'get_user_profile':
      if (!$user_id) { http_response_code(403); exit; }
      $stmt_user = $db->prepare("SELECT artist FROM users WHERE id = ?");
      $stmt_user->execute([$user_id]);
      $profile = $stmt_user->fetch();

      if (!$profile) { http_response_code(404); exit; }
      
      $profile['image_url'] = '?action=get_profile_picture&id=' . $user_id . '&v=' . time();
      send_json($profile);
      break;

    case 'get_user_stats':
      if (!$user_id) { http_response_code(403); exit; }
      $stats = [];
      $stats_queries = [
        'uploads' => "SELECT COUNT(*) FROM music WHERE user_id = {$user_id} OR match_artist(artist, (SELECT artist FROM users WHERE id = {$user_id})) = 1",
        'favorites' => "SELECT COUNT(*) FROM favorites WHERE user_id = {$user_id}",
        'playlists' => "SELECT COUNT(*) FROM playlists WHERE user_id = {$user_id}",
        'play_count' => "SELECT SUM(play_count) FROM play_counts WHERE user_id = {$user_id}"
      ];
      foreach ($stats_queries as $key => $query) {
        $stats[$key] = $db->query($query)->fetchColumn() ?: 0;
      }
      send_json(['stats' => $stats]);
      break;

    case 'search':
      $q = $_GET['q'] ?? '';
      $query = $q;
      
      $q_rom = $_GET['rom'] ?? '';
      
      // Parse Filters
      $f_date = $_GET['f_date'] ?? '';
      $f_dur = $_GET['f_dur'] ?? '';
      $f_sort = $_GET['f_sort'] ?? 'relevance';
      $f_start_date = $_GET['f_start_date'] ?? '';
      $f_end_date = $_GET['f_end_date'] ?? '';
      
      $time_now = time();
      $date_cond_m = ""; $date_cond_p = "";
      if ($f_date === 'today') { $date_cond_m = " AND m.last_modified >= " . ($time_now - 86400); $date_cond_p = " AND p.created_at >= datetime('now', '-1 day')"; }
      elseif ($f_date === 'week') { $date_cond_m = " AND m.last_modified >= " . ($time_now - 604800); $date_cond_p = " AND p.created_at >= datetime('now', '-7 days')"; }
      elseif ($f_date === 'month') { $date_cond_m = " AND m.last_modified >= " . ($time_now - 2592000); $date_cond_p = " AND p.created_at >= datetime('now', '-1 month')"; }
      elseif ($f_date === 'year') { $date_cond_m = " AND m.last_modified >= " . ($time_now - 31536000); $date_cond_p = " AND p.created_at >= datetime('now', '-1 year')"; }

      if (!empty($f_start_date)) {
        $start_ts = strtotime($f_start_date . " 00:00:00");
        if ($start_ts !== false) {
          $date_cond_m .= " AND m.last_modified >= " . $start_ts;
          $date_cond_p .= " AND p.created_at >= " . $db->quote($f_start_date . " 00:00:00");
        }
      }
      if (!empty($f_end_date)) {
        $end_ts = strtotime($f_end_date . " 23:59:59");
        if ($end_ts !== false) {
          $date_cond_m .= " AND m.last_modified <= " . $end_ts;
          $date_cond_p .= " AND p.created_at <= " . $db->quote($f_end_date . " 23:59:59");
        }
      }

      $dur_cond_m = "";
      if ($f_dur === 'short') { $dur_cond_m = " AND m.duration < 240"; }
      elseif ($f_dur === 'long') { $dur_cond_m = " AND m.duration > 1200"; }

      $shelves = [];
      $song_fields = "m.id, m.title, m.artist, m.album, m.genre, m.duration, m.user_id, m.is_private, m.is_collaborative, m.last_modified, CASE WHEN f.song_id IS NOT NULL THEN 1 ELSE 0 END AS is_favorite, COALESCE((SELECT SUM(play_count) FROM play_counts WHERE song_id = m.id), 0) as play_count";

      // 1. TOP RESULT (Only if no specific sort is overriding)
      if ($f_sort === 'relevance' || $f_sort === '') {
        $search_sql = "(m.title LIKE ? OR m.artist LIKE ? OR m.album LIKE ?)";
        $bind_params = ["%$query%", "%$query%", "%$query%"];
            
        if ($q_rom) { $search_sql .= " OR (m.title LIKE ? OR m.artist LIKE ? OR m.album LIKE ?)"; array_push($bind_params, "%$q_rom%", "%$q_rom%", "%$q_rom%"); }

        $stmt_top = $db->prepare("
          SELECT {$song_fields} FROM music m 
          LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = ? 
          WHERE ($search_sql) AND (m.is_private = 0 OR m.user_id = ? OR match_artist(m.artist, (SELECT artist FROM users WHERE id = ?)) = 1 OR {$is_super_admin} = 1)
          $date_cond_m $dur_cond_m
          ORDER BY CASE WHEN m.title LIKE ? THEN 1 WHEN m.artist LIKE ? THEN 2 WHEN m.album LIKE ? THEN 3 ELSE 4 END ASC, m.id DESC LIMIT 1
        ");
            
        $final_params = array_merge([$user_id], $bind_params, [$user_id, $user_id, "%$query%", "%$query%", "%$query%"]);
        $stmt_top->execute($final_params);
        $top_result = $stmt_top->fetch();
        if ($top_result) $shelves[] = ['title' => 'Top Result', 'type' => 'top_result', 'items' => [$top_result]];
      }

      // 2. ARTISTS (Bypass date/duration filters since they don't apply to profiles)
      $artists = []; $added_artists = [];
      $stmt = $db->prepare("SELECT id, artist as name FROM users WHERE artist LIKE ? AND artist != '' AND artist IS NOT NULL ORDER BY artist ASC LIMIT 15");
      $stmt->execute(["%$query%"]);
      foreach ($stmt->fetchAll() as $ua) {
        $artists[] = ['name' => $ua['name'], 'id' => $ua['id'], 'is_user' => true];
        $added_artists[strtolower($ua['name'])] = true;
      }
      $stmt = $db->prepare("SELECT DISTINCT artist, MAX(id) as id FROM music WHERE artist LIKE ? AND artist != '' AND artist IS NOT NULL AND (is_private = 0 OR user_id = ? OR {$is_super_admin} = 1) GROUP BY artist LIMIT 15");
      $stmt->execute(["%$query%", $user_id]);
      foreach ($stmt->fetchAll() as $ma) {
        $parts = preg_split('/\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i', $ma['artist']);
        foreach ($parts as $p) {
          $p = trim($p);
          if ($p !== '' && stripos($p, $q) !== false && !isset($added_artists[strtolower($p)])) {
            $artists[] = ['name' => $p, 'id' => $ma['id'], 'is_user' => false];
            $added_artists[strtolower($p)] = true;
          }
        }
      }
      if (count($artists) > 0) $shelves[] = ['title' => 'Artists', 'type' => 'artists', 'items' => array_slice($artists, 0, 15)];

      // 3. ALBUMS (Dynamically aggregated and filtered)
      $stmt = $db->prepare("
        SELECT m.album, m.artist, m.user_id, m.id, m.duration, m.last_modified, COALESCE((SELECT SUM(play_count) FROM play_counts WHERE song_id = m.id), 0) as pc
        FROM music m WHERE m.album LIKE ? AND m.album != '' AND m.album != 'Unknown Album' AND m.album IS NOT NULL AND (m.is_private = 0 OR m.user_id = ? OR match_artist(m.artist, (SELECT artist FROM users WHERE id = ?)) = 1 OR {$is_super_admin} = 1) $date_cond_m
      ");
      $stmt->execute(["%$query%", $user_id, $user_id]);
      $search_albums = [];
      foreach ($stmt->fetchAll() as $row) {
        $parts = @preg_split('/\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i', $row['artist']);
        if (!is_array($parts)) $parts = [$row['artist']];
        foreach ($parts as $part) {
          $p = trim($part);
          if ($p !== '') {
            $key = strtolower($row['album'] . ':::' . $p);
            if (!isset($search_albums[$key])) {
              $search_albums[$key] = ['album' => $row['album'], 'artist' => $p, 'user_id' => $row['user_id'], 'id' => $row['id'], 'song_count' => 1, 'total_plays' => $row['pc'], 'sum_dur' => $row['duration'], 'max_date' => $row['last_modified']];
            } else {
              $search_albums[$key]['song_count']++; $search_albums[$key]['total_plays'] += $row['pc'];
              $search_albums[$key]['sum_dur'] += $row['duration']; $search_albums[$key]['max_date'] = max($search_albums[$key]['max_date'], $row['last_modified']);
            }
          }
        }
      }
      if ($f_dur === 'short') $search_albums = array_filter($search_albums, function($a) { return $a['sum_dur'] < 240; });
      elseif ($f_dur === 'long') $search_albums = array_filter($search_albums, function($a) { return $a['sum_dur'] > 1200; });
      
      usort($search_albums, function($a, $b) use ($f_sort) {
        if ($f_sort === 'date') return $b['max_date'] <=> $a['max_date'];
        if ($f_sort === 'views') return $b['total_plays'] <=> $a['total_plays'];
        return strcasecmp($a['album'], $b['album']);
      });
      $search_albums = array_slice($search_albums, 0, 15);
      if (count($search_albums) > 0) $shelves[] = ['title' => 'Albums', 'type' => 'albums', 'items' => array_values($search_albums)];

      // 4. PLAYLISTS
      $stmt = $db->prepare("
        SELECT p.name, p.public_id, p.is_collaborative, p.is_private, p.play_count, p.created_at, u.artist as creator, 
        (SELECT ps.song_id FROM playlist_songs ps WHERE ps.playlist_id = p.id ORDER BY ps.added_at DESC LIMIT 1) as image_id, 
        (SELECT m.last_modified FROM playlist_songs ps JOIN music m ON ps.song_id = m.id WHERE ps.playlist_id = p.id ORDER BY ps.added_at DESC LIMIT 1) as image_v,
        (SELECT COUNT(*) FROM playlist_songs ps WHERE ps.playlist_id = p.id) as song_count,
        (SELECT SUM(m.duration) FROM playlist_songs ps JOIN music m ON ps.song_id = m.id WHERE ps.playlist_id = p.id) as total_duration
        FROM playlists p JOIN users u ON p.user_id = u.id 
        WHERE p.name LIKE ? AND (p.is_private = 0 OR p.user_id = ? OR {$is_super_admin} = 1) $date_cond_p
      ");
      $stmt->execute(["%$query%", $user_id]);
      $playlists = $stmt->fetchAll();
      if ($f_dur === 'short') $playlists = array_filter($playlists, function($p) { return $p['total_duration'] < 240; });
      elseif ($f_dur === 'long') $playlists = array_filter($playlists, function($p) { return $p['total_duration'] > 1200; });
      usort($playlists, function($a, $b) use ($f_sort) {
        if ($f_sort === 'date') return strtotime($b['created_at']) <=> strtotime($a['created_at']);
        if ($f_sort === 'views') return $b['play_count'] <=> $a['play_count'];
        return strcasecmp($a['name'], $b['name']);
      });
      $playlists = array_slice($playlists, 0, 15);
      if (count($playlists) > 0) $shelves[] = ['title' => 'Playlists', 'type' => 'playlists', 'items' => array_values($playlists)];

      // 5. SONGS
      $order_m = "ORDER BY m.title ASC";
      $search_sql_s = "(m.title LIKE ? OR m.artist LIKE ? OR m.album LIKE ?)";
      $bind_params_s = ["%$query%", "%$query%", "%$query%"];
      
      if ($q_rom) { $search_sql_s .= " OR (m.title LIKE ? OR m.artist LIKE ? OR m.album LIKE ?)"; array_push($bind_params_s, "%$q_rom%", "%$q_rom%", "%$q_rom%"); }

      $song_params = array_merge([$user_id], $bind_params_s, [$user_id, $user_id]);

      if ($f_sort === 'relevance' || $f_sort === '') {
        $order_m = "ORDER BY CASE WHEN m.title LIKE ? THEN 1 WHEN m.artist LIKE ? THEN 2 WHEN m.album LIKE ? THEN 3 ELSE 4 END ASC, m.id DESC";
        $song_params[] = "%$query%"; $song_params[] = "%$query%"; $song_params[] = "%$query%";
      } elseif ($f_sort === 'date') {
        $order_m = "ORDER BY m.last_modified DESC";
      } elseif ($f_sort === 'views') {
        $order_m = "ORDER BY play_count DESC";
      } elseif ($f_sort === 'likes') {
        $order_m = "ORDER BY like_count DESC";
      }
      
      $song_fields_search = $song_fields . ", (SELECT COUNT(*) FROM favorites WHERE song_id = m.id) as like_count";
      $stmt = $db->prepare("SELECT {$song_fields_search} FROM music m LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = ? WHERE ($search_sql_s) AND (m.is_private = 0 OR m.user_id = ? OR match_artist(m.artist, (SELECT artist FROM users WHERE id = ?)) = 1 OR {$is_super_admin} = 1) $date_cond_m $dur_cond_m $order_m LIMIT 50");
      $stmt->execute($song_params);
      $songs = $stmt->fetchAll();
      if (count($songs) > 0) $shelves[] = ['title' => 'Songs', 'type' => 'songs_list', 'items' => $songs];

      send_json(['shelves' => $shelves]);
      break;

    case 'get_song_data':
      $id = intval($_GET['id'] ?? 0);
      $stmt = $db->prepare("
        SELECT m.id, m.file, m.title, m.artist, m.album, m.genre, m.year, m.duration, m.bitrate, m.lyrics, m.user_id, m.is_private, m.is_collaborative, m.last_modified, m.replaygain,
        CASE WHEN f.song_id IS NOT NULL THEN 1 ELSE 0 END AS is_favorite,
        uss.volume_multiplier, uss.eq_bands
        FROM music m 
        LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = ?
        LEFT JOIN user_song_settings uss ON m.id = uss.song_id AND uss.user_id = ?
        WHERE m.id = ?
      ");
      $stmt->execute([$user_id, $user_id, $id]);
      $song = $stmt->fetch();
      if ($song) {
        $is_collab = false;
        if ($user_id) {
          $stmt_art = $db->prepare("SELECT artist FROM users WHERE id = ?");
          $stmt_art->execute([$user_id]);
          $u_art = $stmt_art->fetchColumn();
          if ($u_art && $db->query("SELECT match_artist(".$db->quote($song['artist']).", ".$db->quote($u_art).")")->fetchColumn() == 1) {
            $is_collab = true;
          }
        }
        if ($song['is_private'] == 1 && $song['user_id'] != $user_id && !$is_collab && $is_super_admin == 0) {
          http_response_code(403); send_json(['status' => 'error', 'message' => 'This song is private.']);
        }
        $song['stream_url'] = '?action=get_stream&id=' . $song['id'];
        $song['image_url'] = '?action=get_image&id=' . $song['id'] . '&v=' . ($song['last_modified'] ?? 0);
        
        $file_path = $song['file'];
        if (!file_exists($file_path)) {
          $dynamic_path = MUSIC_DIR . '/uploads/' . basename(dirname(dirname($file_path))) . '/' . basename(dirname($file_path)) . '/' . basename($file_path);
          if (file_exists($dynamic_path)) $file_path = $dynamic_path;
        }
        $song['filesize'] = file_exists($file_path) ? filesize($file_path) : 0;
        
        // STRICT JSON PARSER: Forces DB Equalizer strings into Floats so the JS engine doesn't crash
        if (!empty($song['eq_bands'])) {
          $parsed_eq = json_decode($song['eq_bands'], true);
          $song['eq_bands'] = is_array($parsed_eq) ? array_map('floatval', $parsed_eq) : [0,0,0,0,0];
        } else {
          $song['eq_bands'] = null;
        }
        
        if (!empty($song['volume_multiplier'])) {
          $song['volume_multiplier'] = (float)$song['volume_multiplier'];
        }
      }
      send_json($song);
      break;

    case 'save_global_settings':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $settings_json = json_encode($data['settings']);
      $db->prepare("UPDATE users SET settings = ? WHERE id = ?")->execute([$settings_json, $user_id]);
      send_json(['status' => 'success']);
      break;

    case 'save_song_settings':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $s_id = (int)$data['song_id'];
      $vol = (float)$data['volume'];
      $eq = json_encode($data['eq']);
      $db->prepare("
        REPLACE INTO user_song_settings (user_id, song_id, volume_multiplier, eq_bands) 
        VALUES (?, ?, ?, ?)
      ")->execute([$user_id, $s_id, $vol, $eq]);
      send_json(['status' => 'success']);
      break;

    case 'reset_song_settings':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $s_id = (int)$data['song_id'];
      $db->prepare("DELETE FROM user_song_settings WHERE user_id = ? AND song_id = ?")->execute([$user_id, $s_id]);
      send_json(['status' => 'success']);
      break;

    case 'get_stream':
      $id = intval($_GET['id'] ?? 0);
      $stmt = $db->prepare("SELECT file, user_id, is_private, artist FROM music WHERE id = ?");
      $stmt->execute([$id]);
      $song_stream = $stmt->fetch();
      
      if ($song_stream) {
        $file_path = $song_stream['file'];
        // Dynamic path resolution to prevent breaking if server/folder changes
        if (!file_exists($file_path)) {
          $dynamic_path = MUSIC_DIR . '/uploads/' . basename(dirname(dirname($file_path))) . '/' . basename(dirname($file_path)) . '/' . basename($file_path);
          if (file_exists($dynamic_path)) $file_path = $dynamic_path;
        }

        if (file_exists($file_path)) {
          $is_collab = false;
          if ($user_id) {
             $stmt_art = $db->prepare("SELECT artist FROM users WHERE id = ?");
             $stmt_art->execute([$user_id]);
             $u_art = $stmt_art->fetchColumn();
             if ($u_art && $db->query("SELECT match_artist(".$db->quote($song_stream['artist']).", ".$db->quote($u_art).")")->fetchColumn() == 1) {
                 $is_collab = true;
             }
          }
          if ($song_stream['is_private'] == 1 && $song_stream['user_id'] != $user_id && !$is_collab && $is_super_admin == 0) {
            http_response_code(403); exit;
          }
          session_write_close();
          while (ob_get_level() > 0) { @ob_end_clean(); }
          $filesize = filesize($file_path);
          
          $mime_type = 'audio/mpeg';
          $ext = strtolower(pathinfo($file_path, PATHINFO_EXTENSION));
          switch ($ext) {
            case 'flac': $mime_type = 'audio/flac'; break;
            case 'ogg': $mime_type = 'audio/ogg'; break;
            case 'wav': $mime_type = 'audio/wav'; break;
            case 'm4a': $mime_type = 'audio/mp4'; break;
          }

          header('Content-Type: ' . $mime_type);
          header('Accept-Ranges: bytes');
          
          $start = 0;
          $end = $filesize - 1;
          $length = $filesize;

          if (isset($_SERVER['HTTP_RANGE'])) {
            $range = str_replace('bytes=', '', $_SERVER['HTTP_RANGE']);
            $parts = explode('-', $range, 2);
            $start = intval($parts[0]);
            if (isset($parts[1]) && $parts[1] !== '') {
              $end = intval($parts[1]);
            }
            if ($start > $end || $start >= $filesize) {
              header('HTTP/1.1 416 Range Not Satisfiable');
              header("Content-Range: bytes */$filesize");
              exit;
            }
            $length = $end - $start + 1;
            header('HTTP/1.1 206 Partial Content');
            header("Content-Range: bytes $start-$end/$filesize");
          } else {
            header('HTTP/1.1 200 OK');
          }

          header('Content-Length: ' . $length);

          $f = @fopen($file_path, 'rb');
          if ($f) {
            fseek($f, $start);
            $chunk_size = 1024 * 8;
            $bytes_left = $length;
            @flush();
            while ($bytes_left > 0 && !feof($f)) {
              if (connection_aborted()) break;
              $read_size = min($chunk_size, $bytes_left);
              $data = fread($f, $read_size);
              if ($data === false) break;
              echo $data;
              @flush();
              $bytes_left -= strlen($data);
            }
            fclose($f);
          }
          exit;
        }
      }
      http_response_code(404);
      exit;

    case 'download_cover':
      $id = intval($_GET['id'] ?? 0);
      $stmt = $db->prepare("SELECT image, title, artist FROM music WHERE id = ?");
      $stmt->execute([$id]);
      $row = $stmt->fetch();
      
      $safeTitle = preg_replace('/[^a-zA-Z0-9_]/', '_', ($row['title'] ?? 'Unknown') . '_' . ($row['artist'] ?? 'Unknown'));

      if ($row && $row['image']) {
        header('Content-Type: image/webp');
        header('Content-Disposition: attachment; filename="' . $safeTitle . '_cover.webp"');
        echo $row['image'];
      } else {
        header('Content-Type: image/svg+xml');
        header('Content-Disposition: attachment; filename="' . $safeTitle . '_cover.svg"');
        $title = $row['title'] ?? 'Unknown';
        $hash = 0;
        for ($i = 0; $i < strlen($title); $i++) {
            $char = ord($title[$i]);
            $hash = ($char + ($hash << 5) - $hash) & 0xFFFFFFFF;
            if ($hash > 0x7FFFFFFF) $hash -= 0x100000000;
        }
        $h = abs($hash % 360);
        $c1 = "hsl({$h}, 50%, 35%)";
        $c2 = "hsl(" . (($h + 40) % 360) . ", 60%, 45%)";
        $c3 = "hsl(" . (($h + 80) % 360) . ", 60%, 35%)";
        echo '<?xml version="1.0" encoding="utf-8"?>
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="100%" height="100%">
          <defs>
            <linearGradient id="grad" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stop-color="'.$c1.'" />
              <stop offset="50%" stop-color="'.$c2.'" />
              <stop offset="100%" stop-color="'.$c3.'" />
            </linearGradient>
            <filter id="shadow" x="-10%" y="-10%" width="120%" height="120%">
              <feDropShadow dx="0" dy="8" stdDeviation="12" flood-opacity="0.3"/>
            </filter>
          </defs>
          <rect width="512" height="512" fill="url(#grad)" />
          <g transform="translate(128, 128) scale(10.66)" fill="none" stroke="#ffffff" stroke-width="1.5" opacity="0.9" filter="url(#shadow)">
            <circle cx="12" cy="12" r="3"/>
            <path stroke-linecap="round" d="M21.95 13c-.501 5.054-4.765 9-9.95 9c-5.523 0-10-4.477-10-10c0-1.821.487-3.529 1.338-5M11 2.05a9.9 9.9 0 0 0-4 1.288"/>
            <path stroke-linecap="round" stroke-linejoin="round" d="M15 12V2.456a10.02 10.02 0 0 1 6.542 6.542"/>
          </g>
        </svg>';
      }
      exit;

    case 'get_image':
      header('Cache-Control: public, max-age=31536000, immutable');
      header('Pragma: cache');
      header('Expires: ' . gmdate('D, d M Y H:i:s', time() + 31536000) . ' GMT');
      $id = intval($_GET['id'] ?? 0);
      $size = $_GET['size'] ?? 'large';
      
      $stmt = $db->prepare("SELECT image, title, artist, last_modified FROM music WHERE id = ?");
      $stmt->execute([$id]);
      $row = $stmt->fetch();
      
      if ($row && $row['image']) {
        if ($size === 'small') {
          $shard = substr(md5((string)$id), 0, 2);
          $thumb_dir = MUSIC_DIR . '/thumbnails/' . $shard;
          $v = $row['last_modified'] ?? 0;
          $cache_path = $thumb_dir . '/small_' . $id . '_' . $v . '.webp';
          
          if (file_exists($cache_path)) {
            header('Content-Type: image/webp');
            readfile($cache_path);
            exit;
          }
          
          if (!is_dir($thumb_dir)) @mkdir($thumb_dir, 0755, true);
          
          // ADVANCED CLEANUP: Safely delete stale unmatched thumbnails strictly for this ID
          $all_shard_files = @scandir($thumb_dir);
          if ($all_shard_files) {
            foreach ($all_shard_files as $f) {
              if ($f !== '.' && $f !== '..' && $f !== basename($cache_path)) {
                if (preg_match('/^small_' . $id . '(?:_[0-9]+)?\.webp$/', $f)) {
                  @unlink($thumb_dir . '/' . $f);
                }
              }
            }
          }
          
          $img = @imagecreatefromstring($row['image']);
          if ($img) {
            $small = imagecreatetruecolor(200, 200);
            imagealphablending($small, false);
            imagesavealpha($small, true);
            $transparent = imagecolorallocatealpha($small, 255, 255, 255, 127);
            imagefilledrectangle($small, 0, 0, 200, 200, $transparent);
            imagecopyresampled($small, $img, 0, 0, 0, 0, 200, 200, imagesx($img), imagesy($img));
            
            ob_start();
            imagewebp($small, null, 40);
            $small_data = ob_get_clean();
            
            if (strlen($small_data) > 5120) { // Enforce 5KB max
               ob_start();
               imagewebp($small, null, 15); 
               $small_data = ob_get_clean();
            }
            
            @file_put_contents($cache_path, $small_data);
            imagedestroy($img);
            imagedestroy($small);
            
            header('Content-Type: image/webp');
            echo $small_data;
            exit;
          }
          // If image creation failed (corrupted DB image), nullify it to fallback to SVG
          $row['image'] = null;
        } else {
          header('Content-Type: image/webp');
          echo $row['image'];
          exit;
        }
      }
      
      // Unified SVG Generator
      header('Content-Type: image/svg+xml');
      $title = $row['title'] ?? 'Unknown';
      $hash = 0;
      for ($i = 0; $i < strlen($title); $i++) {
          $char = ord($title[$i]);
          $hash = ($char + ($hash << 5) - $hash) & 0xFFFFFFFF;
          if ($hash > 0x7FFFFFFF) $hash -= 0x100000000;
      }
      $h = abs($hash % 360);
      $c1 = "hsl({$h}, 50%, 35%)";
      $c2 = "hsl(" . (($h + 40) % 360) . ", 60%, 45%)";
      $c3 = "hsl(" . (($h + 80) % 360) . ", 60%, 35%)";
      echo '<?xml version="1.0" encoding="utf-8"?>
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="100%" height="100%">
        <defs>
          <linearGradient id="grad" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stop-color="'.$c1.'" />
            <stop offset="50%" stop-color="'.$c2.'" />
            <stop offset="100%" stop-color="'.$c3.'" />
          </linearGradient>
          <filter id="shadow" x="-10%" y="-10%" width="120%" height="120%">
            <feDropShadow dx="0" dy="8" stdDeviation="12" flood-opacity="0.3"/>
          </filter>
        </defs>
        <rect width="512" height="512" fill="url(#grad)" />
        <g transform="translate(128, 128) scale(10.66)" fill="none" stroke="#ffffff" stroke-width="1.5" opacity="0.9" filter="url(#shadow)">
          <circle cx="12" cy="12" r="3"/>
          <path stroke-linecap="round" d="M21.95 13c-.501 5.054-4.765 9-9.95 9c-5.523 0-10-4.477-10-10c0-1.821.487-3.529 1.338-5M11 2.05a9.9 9.9 0 0 0-4 1.288"/>
          <path stroke-linecap="round" stroke-linejoin="round" d="M15 12V2.456a10.02 10.02 0 0 1 6.542 6.542"/>
        </g>
      </svg>';
      exit;

    case 'get_user_playlists':
      if (!$user_id) { send_json([]); }
      $song_id = isset($_GET['song_id']) ? $_GET['song_id'] : '0';
      $sort_key = $_GET['sort'] ?? 'name_asc';
      $sort_map = [
        'name_asc' => 'ORDER BY p.name COLLATE NOCASE ASC',
        'name_desc' => 'ORDER BY p.name COLLATE NOCASE DESC',
        'modified_desc' => 'ORDER BY COALESCE((SELECT MAX(added_at) FROM playlist_songs WHERE playlist_id = p.id), p.created_at) DESC',
        'modified_asc' => 'ORDER BY COALESCE((SELECT MAX(added_at) FROM playlist_songs WHERE playlist_id = p.id), p.created_at) ASC',
      ];
      $order_by = $sort_map[$sort_key] ?? $sort_map['name_asc'];
      
      $is_added_sql = ", 0 as is_added";
      if ($song_id !== '0') {
        $sid = intval($song_id);
        $is_added_sql = ", (SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END FROM playlist_songs WHERE playlist_id = p.id AND song_id = {$sid}) as is_added";
      }
      
      $q = $_GET['q'] ?? '';
      $where_sql = "WHERE p.user_id = ?";
      $params = [$user_id];
      if ($q !== '') {
        $where_sql .= " AND (match_text(p.name, ?) = 1 OR match_text(p.description, ?) = 1)";
        $params[] = $q;
        $params[] = $q;
      }
      
      $stmt = $db->prepare("
        SELECT p.id, p.name, p.description, p.public_id, p.is_collaborative, p.is_private, p.user_id as owner_id, u.artist as creator, p.play_count, COUNT(ps.song_id) as song_count,
        (SELECT ps.song_id FROM playlist_songs ps WHERE ps.playlist_id = p.id ORDER BY ps.added_at DESC LIMIT 1) as image_id,
        (SELECT m.last_modified FROM playlist_songs ps2 JOIN music m ON ps2.song_id = m.id WHERE ps2.playlist_id = p.id ORDER BY ps2.added_at DESC LIMIT 1) as image_v
        {$is_added_sql}
        FROM playlists p 
        LEFT JOIN playlist_songs ps ON p.id = ps.playlist_id
        LEFT JOIN users u ON p.user_id = u.id
        $where_sql
        GROUP BY p.id, p.name, p.description, p.public_id, p.is_collaborative, p.is_private, p.user_id, u.artist, p.play_count
        {$order_by} {$limit_clause}
      ");
      $stmt->execute($params);
      send_json($stmt->fetchAll());
      break;

    case 'get_mixes':
      if (isset($_GET['refresh']) && $_GET['refresh'] == '1') {
        $db->exec("DELETE FROM mix_songs");
        $db->exec("DELETE FROM mixes");
      }
      
      $generate_count = 0;
      if (isset($_GET['refresh']) && $_GET['refresh'] == '1') {
         $generate_count = 24;
      } elseif (isset($_GET['generate']) && $_GET['generate'] == '1') {
         $generate_count = 24;
      } else {
         $mix_count = $db->query("SELECT COUNT(*) FROM mixes")->fetchColumn();
         if ($mix_count == 0) $generate_count = 24;
      }
      
      if ($generate_count > 0) {
        $mix_seeds_stmt = $db->query("
          SELECT * FROM (
            SELECT DISTINCT artist as seed_name, 'artist' as seed_type FROM music WHERE artist != 'Unknown Artist' AND artist != '' AND artist IS NOT NULL
            UNION
            SELECT DISTINCT genre as seed_name, 'genre' as seed_type FROM music WHERE genre != 'Unknown Genre' AND genre != '' AND genre IS NOT NULL
            UNION
            SELECT DISTINCT CAST(year AS TEXT) as seed_name, 'year' as seed_type FROM music WHERE year IS NOT NULL AND year > 0
          ) ORDER BY RANDOM() LIMIT $generate_count
        ");
        $seeds = $mix_seeds_stmt->fetchAll();
        foreach ($seeds as $seed) {
          $song_stmt = $db->prepare("SELECT id FROM music WHERE " . $seed['seed_type'] . " = ? ORDER BY RANDOM() LIMIT 50");
          $song_stmt->execute([$seed['seed_name']]);
          $song_ids = $song_stmt->fetchAll(PDO::FETCH_COLUMN);
          
          if (count($song_ids) < 50) {
            $needed = 50 - count($song_ids);
            $pad_stmt = $db->query("SELECT id FROM music ORDER BY RANDOM() LIMIT 100");
            $pad_candidates = $pad_stmt->fetchAll(PDO::FETCH_COLUMN);
            foreach ($pad_candidates as $cid) {
              if (!in_array($cid, $song_ids)) {
                $song_ids[] = $cid;
                $needed--;
                if ($needed <= 0) break;
              }
            }
          }
          
          if (empty($song_ids)) continue; 
          
          $img_stmt = $db->prepare("SELECT id FROM music WHERE " . $seed['seed_type'] . " = ? AND image IS NOT NULL ORDER BY RANDOM() LIMIT 1");
          $img_stmt->execute([$seed['seed_name']]);
          $img_id = $img_stmt->fetchColumn() ?: $song_ids[0];
          
          $public_id = bin2hex(random_bytes(8));
          $name = 'Mix - ' . $seed['seed_name'];
          $db->prepare("INSERT INTO mixes (public_id, name, creator, image_id) VALUES (?, ?, ?, ?)")->execute([$public_id, $name, 'PHP-Music', $img_id]);
          $mix_id = $db->lastInsertId();
          
          $order = 0;
          $insert_ms = $db->prepare("INSERT INTO mix_songs (mix_id, song_id, sort_order) VALUES (?, ?, ?)");
          foreach ($song_ids as $sid) {
            $insert_ms->execute([$mix_id, $sid, $order++]);
          }
        }
      }
      
      $sort_key = $_GET['sort'] ?? 'newest';
      $sort_map = [
        'name_asc' => 'ORDER BY name COLLATE NOCASE ASC',
        'name_desc' => 'ORDER BY name COLLATE NOCASE DESC',
        'newest' => 'ORDER BY id DESC',
        'oldest' => 'ORDER BY id ASC',
      ];
      $order_by = $sort_map[$sort_key] ?? $sort_map['newest'];
      
      $q = $_GET['q'] ?? '';
      $where_sql = "";
      $params = [];
      if ($q !== '') {
        $where_sql = "WHERE match_text(name, ?) = 1";
        $params[] = $q;
      }
      
      $stmt = $db->prepare("SELECT id, public_id, name, creator, image_id as image_id, (SELECT COUNT(*) FROM mix_songs WHERE mix_id = mixes.id) as song_count FROM mixes $where_sql $order_by $limit_clause");
      $stmt->execute($params);
      send_json($stmt->fetchAll());
      break;

    case 'get_collab_playlists':
      if (!$user_id) { send_json([]); }
      $sort_key = $_GET['sort'] ?? 'name_asc';
      $sort_map = [
        'name_asc' => 'ORDER BY p.name COLLATE NOCASE ASC',
        'name_desc' => 'ORDER BY p.name COLLATE NOCASE DESC',
        'modified_desc' => 'ORDER BY COALESCE((SELECT MAX(added_at) FROM playlist_songs WHERE playlist_id = p.id), p.created_at) DESC',
        'modified_asc' => 'ORDER BY COALESCE((SELECT MAX(added_at) FROM playlist_songs WHERE playlist_id = p.id), p.created_at) ASC',
      ];
      $order_by = $sort_map[$sort_key] ?? $sort_map['name_asc'];
      
      $stmt = $db->prepare("
        SELECT p.id, p.name, p.description, p.public_id, p.is_collaborative, p.is_private, p.user_id as owner_id, u.artist as creator, p.play_count, COUNT(ps.song_id) as song_count,
        (SELECT ps.song_id FROM playlist_songs ps WHERE ps.playlist_id = p.id ORDER BY ps.added_at DESC LIMIT 1) as image_id,
        (SELECT m.last_modified FROM playlist_songs ps2 JOIN music m ON ps2.song_id = m.id WHERE ps2.playlist_id = p.id ORDER BY ps2.added_at DESC LIMIT 1) as image_v
        FROM playlists p
        JOIN playlist_collaborators pc ON p.id = pc.playlist_id
        JOIN users u ON p.user_id = u.id
        LEFT JOIN playlist_songs ps ON p.id = ps.playlist_id
        WHERE pc.user_id = ?
        GROUP BY p.id, p.name, p.description, p.public_id, p.is_collaborative, p.is_private, p.user_id, u.artist, p.play_count
        {$order_by} {$limit_clause}
      ");
      $stmt->execute([$user_id]);
      send_json($stmt->fetchAll());
      break;

    case 'leave_collab':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $public_id = $data['public_id'];
      $stmt = $db->prepare("DELETE FROM playlist_collaborators WHERE user_id = ? AND playlist_id = (SELECT id FROM playlists WHERE public_id = ?)");
      $stmt->execute([$user_id, $public_id]);
      send_json(['status' => 'success', 'message' => 'You have left the collaboration.']);
      break;
      
    case 'manage_song_collaborators':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $song_id = intval($data['song_id'] ?? 0);
      $action_type = $data['collab_action']; 
      
      if ($action_type === 'search') {
        $q = $data['query'] ?? '';
        $stmt = $db->prepare("SELECT id, artist FROM users WHERE match_text(artist, ?) = 1 OR email LIKE ? LIMIT 10");
        $stmt->execute([$q, '%' . $q . '%']);
        send_json(['status' => 'success', 'users' => $stmt->fetchAll()]);
      }
      
      $stmt = $db->prepare("SELECT id, user_id, is_collaborative FROM music WHERE id = ?");
      $stmt->execute([$song_id]);
      $song = $stmt->fetch();
      
      if (!$song) {
        http_response_code(404); send_json(['status' => 'error', 'message' => 'Song not found.']);
      }
      
      if ($action_type === 'generate_link') {
        if ($song['user_id'] != $user_id && $is_super_admin == 0) {
          http_response_code(403); send_json(['status' => 'error', 'message' => 'Only the owner can generate links.']);
        }
        $db->exec("DELETE FROM song_invites WHERE expires_at IS NOT NULL AND expires_at <= CURRENT_TIMESTAMP");
        
        $expire_val = $data['expire'] ?? null;
        $expires_at = null;
        if ($expire_val && is_numeric($expire_val)) {
          $expires_at = date('Y-m-d H:i:s', time() + ((int)$expire_val * 60));
        }
        $token = bin2hex(random_bytes(16));
        $db->prepare("INSERT INTO song_invites (token, song_id, expires_at) VALUES (?, ?, ?)")->execute([$token, $song['id'], $expires_at]);
        send_json(['status' => 'success', 'token' => $token]);
      }

      if ($action_type === 'join') {
        $token = $data['token'] ?? '';
        $stmt_inv = $db->prepare("SELECT song_id FROM song_invites WHERE token = ? AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP)");
        $stmt_inv->execute([$token]);
        $inv_song_id = $stmt_inv->fetchColumn();
        
        if (!$inv_song_id || $inv_song_id != $song['id']) {
          send_json(['status' => 'error', 'message' => 'Invalid or expired invite link.']);
        }
        if (!$song['is_collaborative']) {
          send_json(['status' => 'error', 'message' => 'This song is not open for collaboration.']);
        }
        if ($song['user_id'] == $user_id) {
          send_json(['status' => 'error', 'message' => 'You are already the owner.']);
        }
        $db->prepare("INSERT OR IGNORE INTO song_collaborators (song_id, user_id) VALUES (?, ?)")->execute([$song['id'], $user_id]);
        
        $stmt_u = $db->prepare("SELECT artist FROM users WHERE id = ?");
        $stmt_u->execute([$user_id]);
        $new_collab_artist = $stmt_u->fetchColumn();
        
        if ($new_collab_artist) {
          $stmt_cur_artist = $db->prepare("SELECT artist FROM music WHERE id = ?");
          $stmt_cur_artist->execute([$song['id']]);
          $cur_artist = $stmt_cur_artist->fetchColumn();
            
          if (stripos($cur_artist, "(id:" . $user_id . ")") === false) {
            $updated_artist = $cur_artist . ", " . $new_collab_artist . " (id:" . $user_id . ")";
            $db->prepare("UPDATE music SET artist = ? WHERE id = ?")->execute([$updated_artist, $song['id']]);
          }
        }
        
        send_json(['status' => 'success', 'message' => 'Joined song successfully!']);
      }
      
      if ($song['user_id'] != $user_id && $is_super_admin == 0) {
        http_response_code(403); send_json(['status' => 'error', 'message' => 'Only the owner can manage collaborators.']);
      }
      
      if ($action_type === 'list') {
        $stmt_list = $db->prepare("SELECT u.id, u.artist, u.email FROM song_collaborators sc JOIN users u ON sc.user_id = u.id WHERE sc.song_id = ?");
        $stmt_list->execute([$song['id']]);
        send_json(['status' => 'success', 'collaborators' => $stmt_list->fetchAll()]);
      } elseif ($action_type === 'add') {
        $target_id = $data['target_id'] ?? null;
        if ($target_id) {
          $collab_user = $target_id;
        } else {
          $target = $data['target'];
          $stmt_find = $db->prepare("SELECT id FROM users WHERE email = ? OR artist = ? COLLATE NOCASE");
          $stmt_find->execute([$target, $target]);
          $collab_user = $stmt_find->fetchColumn();
        }
        if (!$collab_user) { send_json(['status' => 'error', 'message' => 'User not found.']); }
        if ($collab_user == $user_id) { send_json(['status' => 'error', 'message' => 'You already own this song.']); }
          
        $db->exec("DELETE FROM song_invites WHERE expires_at IS NOT NULL AND expires_at <= CURRENT_TIMESTAMP");
        $expires_at = date('Y-m-d H:i:s', time() + 3600);
        $token = bin2hex(random_bytes(16));
        $db->prepare("INSERT INTO song_invites (token, song_id, expires_at) VALUES (?, ?, ?)")->execute([$token, $song['id'], $expires_at]);
        
        $invite_url = (isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] === 'on' ? "https" : "http") . "://" . $_SERVER['HTTP_HOST'] . strtok($_SERVER["REQUEST_URI"], '?') . "?song_invite=" . $token;
        $stmt_song_title = $db->prepare("SELECT title FROM music WHERE id = ?");
        $stmt_song_title->execute([$song['id']]);
        $s_title = $stmt_song_title->fetchColumn();
        
        $msg_content = "I have invited you to collaborate on the track: [b]" . $s_title . "[/b].\n\nClick here to accept: [url]" . $invite_url . "[/url]\n\nThis invite expires in 1 hour.";
        $db->prepare("INSERT INTO messages (sender_id, receiver_id, content) VALUES (?, ?, ?)")->execute([$user_id, $collab_user, $msg_content]);

        send_json(['status' => 'success', 'message' => 'Invitation sent to the user via Direct Messages. They must accept it within 1 hour.']);
      } elseif ($action_type === 'remove') {
        $remove_id = $data['collab_user_id'];
        $db->prepare("DELETE FROM song_collaborators WHERE song_id = ? AND user_id = ?")->execute([$song['id'], $remove_id]);
        send_json(['status' => 'success', 'message' => 'Collaborator removed.']);
      }
      break;

    case 'get_song_invite_info':
      $token = $_GET['token'] ?? '';
      $stmt = $db->prepare("
        SELECT m.id, m.title, u.artist as creator, m.is_private, m.user_id 
        FROM song_invites si 
        JOIN music m ON si.song_id = m.id 
        JOIN users u ON m.user_id = u.id 
        WHERE si.token = ? AND (si.expires_at IS NULL OR si.expires_at > CURRENT_TIMESTAMP)
      ");
      $stmt->execute([$token]);
      $info = $stmt->fetch();
      if ($info) {
        send_json(['status' => 'success', 'details' => $info]);
      } else {
        http_response_code(404); send_json(['status' => 'error', 'message' => 'Invalid or expired invite link.']);
      }
      break;

    case 'manage_collaborators':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $public_id = $data['public_id'];
      $action_type = $data['collab_action']; 
      
      if ($action_type === 'search') {
        $q = $data['query'] ?? '';
        $stmt = $db->prepare("SELECT id, artist FROM users WHERE match_text(artist, ?) = 1 OR email LIKE ? LIMIT 10");
        $stmt->execute([$q, '%' . $q . '%']);
        send_json(['status' => 'success', 'users' => $stmt->fetchAll()]);
      }
      
      $stmt = $db->prepare("SELECT id, user_id, is_collaborative FROM playlists WHERE public_id = ?");
      $stmt->execute([$public_id]);
      $pl = $stmt->fetch();
      
      if (!$pl) {
        http_response_code(404); send_json(['status' => 'error', 'message' => 'Playlist not found.']);
      }
      
      if ($action_type === 'generate_link') {
