      foreach ($rec_artists_rows as $row) {
        $parts = @preg_split('/\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i', $row['name']);
        if (!is_array($parts)) $parts = [$row['name']];
        foreach ($parts as $part) {
