      $import_data = json_decode(file_get_contents('php://input'), true);
      if (json_last_error() !== JSON_ERROR_NONE || !isset($import_data['name']) || !isset($import_data['songs']) || !is_array($import_data['songs'])) {
        http_response_code(400); send_json(['status' => 'error', 'message' => 'Invalid or malformed JSON file.']);
      }

      $db->beginTransaction();
      try {
        $public_id = bin2hex(random_bytes(8));
        $stmt_create = $db->prepare("INSERT INTO playlists (user_id, name, public_id) VALUES (?, ?, ?)");
        $stmt_create->execute([$user_id, $import_data['name'], $public_id]);
        $playlist_id = $db->lastInsertId();

        $stmt_taa = $db->prepare("SELECT id FROM music WHERE title = ? COLLATE NOCASE AND artist = ? COLLATE NOCASE AND album = ? COLLATE NOCASE LIMIT 1");
        $stmt_ta = $db->prepare("SELECT id FROM music WHERE title = ? COLLATE NOCASE AND artist = ? COLLATE NOCASE LIMIT 1");
        $stmt_t_artist_match = $db->prepare("SELECT id FROM music WHERE title = ? COLLATE NOCASE AND match_artist(artist, ?) = 1 LIMIT 1");
        $stmt_ta_like = $db->prepare("SELECT id FROM music WHERE title LIKE ? COLLATE NOCASE AND artist LIKE ? COLLATE NOCASE LIMIT 1");
        $stmt_file = $db->prepare("SELECT id FROM music WHERE file LIKE ? OR file LIKE ? LIMIT 1");
        $stmt_insert = $db->prepare("INSERT OR IGNORE INTO playlist_songs (playlist_id, song_id, sort_order) VALUES (?, ?, ?)");
        
        $song_count = 0;
        $order = 0;
        foreach ($import_data['songs'] as $song) {
          $title = is_array($song) ? trim($song['title'] ?? '') : '';
          $artist = is_array($song) ? trim($song['artist'] ?? '') : '';
          $album = is_array($song) ? trim($song['album'] ?? '') : '';
          $filename = basename(str_replace('\\', '/', is_array($song) ? ($song['filename'] ?? '') : $song));
          
          $found_id = null;
          
          if ($title !== '' && $artist !== '') {
            if ($album !== '') {
              $stmt_taa->execute([$title, $artist, $album]);
              $found_id = $stmt_taa->fetchColumn();
            }
            if (!$found_id) {
              $stmt_ta->execute([$title, $artist]);
              $found_id = $stmt_ta->fetchColumn();
            }
            if (!$found_id) {
              $stmt_t_artist_match->execute([$title, $artist]);
              $found_id = $stmt_t_artist_match->fetchColumn();
            }
            if (!$found_id) {
              $stmt_ta_like->execute(['%' . $title . '%', '%' . $artist . '%']);
              $found_id = $stmt_ta_like->fetchColumn();
            }
          }
          
          if (!$found_id && $filename !== '') {
            $stmt_file->execute(['%/' . $filename, '%\\' . $filename]);
            $found_id = $stmt_file->fetchColumn();
            if (!$found_id) {
              $stmt_file->execute(['%' . $filename, '%' . $filename]);
              $found_id = $stmt_file->fetchColumn();
            }
          }
          
          if ($found_id) {
            $stmt_insert->execute([$playlist_id, $found_id, $order]);
            if ($stmt_insert->rowCount() > 0) {
              $order++;
              $song_count++;
            }
          }
        }
        $db->commit();
        send_json(['status' => 'success', 'message' => "Playlist '{$import_data['name']}' imported with {$song_count} songs."]);
      } catch (Exception $e) {
        $db->rollBack();
        http_response_code(500);
        send_json(['status' => 'error', 'message' => 'Database error during import: ' . $e->getMessage()]);
      }
      break;

    case 'copy_playlist':
      if (!$user_id) { http_response_code(403); exit; }
      $public_id = $_POST['public_id'] ?? '';
      if (empty($public_id)) { http_response_code(400); exit; }

      $stmt_source = $db->prepare("SELECT id, name, user_id FROM playlists WHERE public_id = ?");
      $stmt_source->execute([$public_id]);
      $source_playlist = $stmt_source->fetch();

      if (!$source_playlist) { http_response_code(404); send_json(['status' => 'error', 'message' => 'Playlist not found.']); }
      if ($source_playlist['user_id'] == $user_id) { http_response_code(400); send_json(['status' => 'error', 'message' => 'Cannot copy your own playlist.']); }

      $db->beginTransaction();
      try {
        $new_name = "Copy of " . $source_playlist['name'];
        $new_public_id = bin2hex(random_bytes(8));
        $stmt_create = $db->prepare("INSERT INTO playlists (user_id, name, public_id) VALUES (?, ?, ?)");
        $stmt_create->execute([$user_id, $new_name, $new_public_id]);
        $new_playlist_id = $db->lastInsertId();

        $stmt_get_songs = $db->prepare("SELECT song_id, sort_order FROM playlist_songs WHERE playlist_id = ? ORDER BY sort_order ASC");
        $stmt_get_songs->execute([$source_playlist['id']]);
        $songs = $stmt_get_songs->fetchAll();

        $stmt_insert_song = $db->prepare("INSERT INTO playlist_songs (playlist_id, song_id, sort_order) VALUES (?, ?, ?)");
        foreach ($songs as $song) {
          $stmt_insert_song->execute([$new_playlist_id, $song['song_id'], $song['sort_order']]);
        }
        $db->commit();
        send_json(['status' => 'success', 'message' => "Playlist copied successfully."]);
      } catch (Exception $e) {
        $db->rollBack();
        http_response_code(500);
        send_json(['status' => 'error', 'message' => 'Database error during copy: ' . $e->getMessage()]);
      }
      break;
  }
  exit;
}

function perform_force_rescan($db, $mode) {
  $start_time = microtime(true);
  ini_set('memory_limit', '512M');
  error_reporting(E_ALL & ~E_DEPRECATED);
  ini_set('display_errors', 1);

  header('Content-Type: text/html; charset=utf-8');
  ob_implicit_flush();

  echo "<style>
    body { color: #e0e0e0; background-color: #030303; font-family: Consolas, 'Courier New', monospace; padding: 10px; margin: 0; }
    pre { white-space: pre-wrap; word-wrap: break-word; font-family: inherit; margin-top: 75px; }
    #header-wrap { position: fixed; top: 0; left: 0; right: 0; background: #121212; border-bottom: 1px solid #333; z-index: 10; }
    #prog-wrap { padding: 12px 15px 5px 15px; display: flex; align-items: center; }
    #prog-track { flex-grow: 1; background: #000; height: 12px; border-radius: 6px; overflow: hidden; margin-right: 15px; }
    #prog-bar { width: 0%; height: 100%; background: #ff0000; transition: width 0.1s; }
    #prog-txt { font-weight: bold; min-width: 45px; text-align: right; font-size: 14px;}
    #warning-txt { padding: 0 15px 12px 15px; color: #ffc107; font-size: 12px; font-weight: bold; text-align: center; text-transform: uppercase; letter-spacing: 0.5px; }
  </style>";

  echo "<div id='header-wrap'>
          <div id='prog-wrap'><div id='prog-track'><div id='prog-bar'></div></div><div id='prog-txt'>0%</div></div>
          <div id='warning-txt'>⚠️ Forced Rescan (" . strtoupper($mode) . "). Do not close this window!</div>
        </div>";
  echo "<pre>";
  echo "PHP Music Library - Forced Metadata Rescan\n";
  echo "===========================================\n\n";

  if (!class_exists('getID3')) die("FATAL ERROR: getID3 library not found\n");
  
  $getID3 = new getID3;
  $getID3->setOption(['encoding' => 'UTF-8']);
  $getID3->option_md5_data = true;
  $getID3->option_md5_data_source = true;
  $getID3->option_sha1_data = true;
  $getID3->option_tags_html = false;

  $stmt_lib = $db->query("SELECT id FROM users WHERE status = 'super_admin' LIMIT 1");
  $library_user_id = $stmt_lib->fetchColumn() ?: 1;

  $offset = isset($_GET['offset']) ? (int)$_GET['offset'] : 0;

  $stmt = $db->query("SELECT id, file FROM music ORDER BY id ASC");
  $all_songs = $stmt->fetchAll();
  $total = count($all_songs);

  if ($offset === 0) {
    echo "Found {$total} tracks currently in the database to re-scan.\n\n";
  } else {
    echo "Resuming scan from track " . ($offset + 1) . " of {$total}...\n\n";
  }

  if ($total === 0) die("Database is empty. Please run a Standard Scan first.\n</pre>");

  $songs = array_slice($all_songs, $offset);

  $user_cache = [];
  $stmt_all_users = $db->query("SELECT id, artist FROM users");
  while ($row = $stmt_all_users->fetch()) {
    $user_cache[strtolower($row['artist'])] = $row['id'];
  }
  
  $check_email_stmt = $db->prepare("SELECT id FROM users WHERE email = ?");
  $insert_user_stmt = $db->prepare("INSERT INTO users (email, artist, password_hash, verified, profile_picture, profile_picture_type) VALUES (?, ?, ?, 'no', ?, 'image/svg+xml')");

  $update_artist_stmt = $db->prepare("UPDATE music SET artist = ?, user_id = ? WHERE id = ?");
  $update_song_stmt = $db->prepare("UPDATE music SET title = ?, album = ?, genre = ?, year = ?, duration = ?, bitrate = ?, replaygain = ? WHERE id = ?");
  $update_all_stmt = $db->prepare("UPDATE music SET artist = ?, user_id = ?, title = ?, album = ?, genre = ?, year = ?, duration = ?, bitrate = ?, replaygain = ? WHERE id = ?");

  $processed = $offset;
  $db->beginTransaction();
  try {
    foreach ($songs as $song) {
      if ((microtime(true) - $start_time) > 40) {
        $db->commit();
        echo "\nApproaching script execution limit. Re-indexing page to resume safely...\n";
        echo "<script>setTimeout(() => window.location.href = '?action=force_rescan&mode=" . urlencode($mode) . "&offset={$processed}', 1000);</script></pre>";
        exit;
      }

      $processed++;
      $percent = floor(($processed / $total) * 100);
      
      $filePath = $song['file'];
      if (!file_exists($filePath)) {
        $fallback = MUSIC_DIR . '/uploads/' . basename(dirname(dirname($filePath))) . '/' . basename(dirname($filePath)) . '/' . basename($filePath);
        if (file_exists($fallback)) {
          $filePath = $fallback;
        }
      }

      echo sprintf("[%3d%%] [%d/%d] Scanning: %s\n", $percent, $processed, $total, basename($filePath));
      echo "<script>document.getElementById('prog-bar').style.width = '{$percent}%'; document.getElementById('prog-txt').innerText = '{$percent}%'; window.scrollTo(0, document.body.scrollHeight); if (window.parent && window.parent.updateScanPill) window.parent.updateScanPill({$processed}, {$total}, 'Re-scanning " . ucfirst($mode) . "');</script>";

      if (file_exists($filePath)) {
        $info = $getID3->analyze($filePath);
        getid3_lib::CopyTagsToComments($info);

        $artist_tag = extract_safe_tag($info['comments'] ?? [], 'artist', 'Unknown Artist');
        $file_user_id = $library_user_id;

        if ($mode === 'artists' || $mode === 'all') {
          $main_artist = trim(preg_split('/\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i', $artist_tag)[0]);
          if ($main_artist !== 'Unknown Artist' && !empty($main_artist)) {
            $artist_lower = strtolower($main_artist);
            if (isset($user_cache[$artist_lower])) {
              $file_user_id = $user_cache[$artist_lower];
            } else {
              echo " -> New artist generated: '{$main_artist}'. Creating account.\n";
              $sanitized_artist_base = sanitize_for_path($main_artist);
              
              // Safely fallback to numbered unknown emails if Transliterator fails on Japanese/Non-English characters
              if ($sanitized_artist_base === 'unknown' || empty($sanitized_artist_base)) {
                $sanitized_artist_base = 'unknown';
                $email = 'unknown1@mail.com';
              } else {
                $email = $sanitized_artist_base . '@mail.com';
              }
              
              $password = $sanitized_artist_base;
              $hash = password_hash($password, PASSWORD_DEFAULT);
              
              $counter = 1;
              while (true) {
                $check_email_stmt->execute([$email]);
                if (!$check_email_stmt->fetch()) break;
                $counter++;
                $email = $sanitized_artist_base . $counter . '@mail.com';
              }
              
              $initial = mb_strtoupper(mb_substr($main_artist, 0, 1, 'UTF-8'));
              $colors = ['#f44336', '#e91e63', '#9c27b0', '#673ab7', '#3f51b5', '#2196f3', '#03a9f4', '#00bcd4', '#009688', '#4caf50', '#8bc34a', '#cddc39', '#ffeb3b', '#ffc107', '#ff9800', '#ff5722', '#795548'];
              $bg_color = $colors[array_rand($colors)];
              $svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><rect width="200" height="200" fill="'.$bg_color.'"/><text x="50%" y="50%" dominant-baseline="central" text-anchor="middle" font-family="Arial, sans-serif" font-size="100" font-weight="bold" fill="#ffffff">' . htmlspecialchars($initial) . '</text></svg>';
              
              $insert_user_stmt->execute([$email, $main_artist, $hash, $svg]);
              $file_user_id = $db->lastInsertId();
              $user_cache[$artist_lower] = $file_user_id; 
            }
          }
        }

        if ($mode === 'songs' || $mode === 'all') {
          $title = extract_safe_tag($info['comments'] ?? [], 'title', pathinfo($filePath, PATHINFO_FILENAME));
          $album = extract_safe_tag($info['comments'] ?? [], 'album', 'Unknown Album');
          $genre = extract_safe_tag($info['comments'] ?? [], 'genre', 'Unknown Genre');
          $year = (int)($info['comments']['year'][0] ?? 0);
          $duration = (int)($info['playtime_seconds'] ?? 0);
          $bitrate = (int)($info['audio']['bitrate'] ?? 0);
          
          $replaygain = 0;
          if (!empty($info['tags']['id3v2']['TXXX'])) {
            foreach($info['tags']['id3v2']['TXXX'] as $txxx) {
              if (strtoupper($txxx['description'] ?? '') === 'REPLAYGAIN_TRACK_GAIN') {
                $replaygain = (float)str_replace(' dB', '', $txxx['data']);
              }
            }
          } elseif (!empty($info['comments']['replaygain_track_gain'][0])) {
            $replaygain = (float)str_replace(' dB', '', $info['comments']['replaygain_track_gain'][0]);
          }
        }

        if ($mode === 'artists') {
          $update_artist_stmt->execute([$artist_tag, $file_user_id, $song['id']]);
        } elseif ($mode === 'songs') {
          $update_song_stmt->execute([$title, $album, $genre, $year, $duration, $bitrate, $replaygain, $song['id']]);
        } else {
          $update_all_stmt->execute([$artist_tag, $file_user_id, $title, $album, $genre, $year, $duration, $bitrate, $replaygain, $song['id']]);
        }

      } else {
        echo " -> File warning: Track path could not be found physically on disk.\n";
      }

      if ($processed % 100 === 0) {
        $db->commit();
        gc_collect_cycles();
        $db->beginTransaction();
      }
    }
    $db->commit();
  } catch (Exception $e) {
    if ($db->inTransaction()) $db->rollBack();
    die("\nFATAL TRANSACTION ERROR: " . $e->getMessage() . "\n</pre>");
  }

  echo "\n=======================\n";
  echo "Forced Rescan ($mode) complete! Processed items: $processed\n</pre>";
  echo "<script>if (window.parent && window.parent.finishScan) window.parent.finishScan('full-scan-modal');</script>";
}

function perform_full_scan($db) {
  global $auto_scan;
  // OPTIMIZATION 1: Release session lock instantly so the iframe and main app don't hang!
  session_write_close();
  
  $start_time = microtime(true);
  ini_set('memory_limit', '1024M'); // Boost memory for large libraries
  set_time_limit(0); // Prevent PHP timeout limits
  error_reporting(E_ALL & ~E_DEPRECATED);
  ini_set('display_errors', 1);

  // Remove any conflicting gzip headers before we output
  header_remove('Content-Encoding');
  header('Content-Type: text/html; charset=utf-8');
  header('Cache-Control: no-cache');
  
  // OPTIMIZATION 2: Clean output buffers instead of flushing to prevent corrupted GZIP rendering (blank white page)
  while (ob_get_level() > 0) {
    @ob_end_clean();
  }
  ob_implicit_flush(true);

  $step = isset($_GET['step']) ? (int)$_GET['step'] : 1;
  
  // OPTIMIZATION 3: Safe local temp file for queue state (Fixes Windows/XAMPP sys_get_temp_dir issues)
  $tmp_dir = __DIR__ . '/.tmp_db';
  if (!is_dir($tmp_dir)) @mkdir($tmp_dir, 0755, true);
  $queue_file = $tmp_dir . '/phpmusic_scan_queue.json';

  echo "<style>
    body { color: #e0e0e0; background-color: #030303; font-family: Consolas, 'Courier New', monospace; padding: 10px; margin: 0; }
    pre { white-space: pre-wrap; word-wrap: break-word; font-family: inherit; margin-top: 75px; }
    #header-wrap { position: fixed; top: 0; left: 0; right: 0; background: #121212; border-bottom: 1px solid #333; z-index: 10; }
    #prog-wrap { padding: 12px 15px 5px 15px; display: flex; align-items: center; }
    #prog-track { flex-grow: 1; background: #000; height: 12px; border-radius: 6px; overflow: hidden; margin-right: 15px; }
    #prog-bar { width: 0%; height: 100%; background: #ff0000; transition: width 0.1s; }
    #prog-txt { font-weight: bold; min-width: 45px; text-align: right; font-size: 14px;}
    #warning-txt { padding: 0 15px 12px 15px; color: #ffc107; font-size: 12px; font-weight: bold; text-align: center; text-transform: uppercase; letter-spacing: 0.5px; }
  </style>";
  
  echo "<div id='header-wrap'>
          <div id='prog-wrap'><div id='prog-track'><div id='prog-bar'></div></div><div id='prog-txt'>0%</div></div>
          <div id='warning-txt'>⚠️ Please wait and don't close this modal, the process can take very long!</div>
        </div>";
  echo "<pre>";
  echo "PHP Music Library - Full Scan (Optimized Queue System)\n";
  echo "========================================================\n\n";

  echo "<script>
    const setProgress = (pct) => {
      document.getElementById('prog-bar').style.width = pct + '%';
      document.getElementById('prog-txt').innerText = pct + '%';
      window.scrollTo(0, document.body.scrollHeight);
    };
  </script>";

  if (!class_exists('getID3')) {
    die("FATAL ERROR: getID3 library not found in " . __DIR__ . "/getid3/\n");
  }

  // Initialize DB schemas safely
  init_db($db);

  if ($step === 1) {
    echo "Step 1: Database ready.\n\n";
    echo "Step 2: Verifying Super Admin user...\n";
    $stmt = $db->query("SELECT id FROM users WHERE status = 'super_admin' LIMIT 1");
    $library_user_id = $stmt->fetchColumn() ?: 1;
    echo "'Music Library' user ID: {$library_user_id}\n\n";

    echo "Step 3: Discovering music files on disk...\n";
    $files_on_disk = [];
    $music_folders = [MUSIC_DIR]; 
    $file_count = 0;

    foreach ($music_folders as $folder) {
      if (!is_dir($folder)) continue;
      echo "Scanning directory: " . str_replace('\\', '/', $folder) . "\n";
      
      // OPTIMIZATION 4: Windows Localhost Fix: Force UNIX paths via Iterator to normalize slashes securely
      $dir = new RecursiveDirectoryIterator($folder, FilesystemIterator::SKIP_DOTS | FilesystemIterator::UNIX_PATHS);
      $filter = new RecursiveCallbackFilterIterator($dir, function ($current, $key, $iterator) {
        if ($current->isDir()) {
          // Exclude heavy backend folders to speed up traversal exponentially
          $exclude = ['.git', 'getid3', '.drive_trash_bin', '.drive_thumbnails', '.file_version', '.tmp_db', 'covers'];
          if (in_array($current->getFilename(), $exclude)) return false;
        }
        return true;
      });
      
      $iterator = new RecursiveIteratorIterator($filter, RecursiveIteratorIterator::LEAVES_ONLY);
      foreach ($iterator as $file) {
        if ($file->isDir()) continue;
        
        // Absolute brute-force replacement to guarantee no backslashes on Windows environments
        $filePath = str_replace('\\', '/', $file->getPathname());
        
        // Fast regex check
        if (preg_match('/\.(mp3|m4a|flac|ogg|wav)$/i', $filePath)) {
          $files_on_disk[$filePath] = $file->getMTime();
          $file_count++;
          
          // Dynamic progress feedback for massive libraries so the browser doesn't freeze
          if ($file_count % 500 === 0) {
            echo " -> Discovered {$file_count} valid audio files...\n";
            @ob_flush(); flush();
          }
        }
      }
    }
    
    echo "Found a total of {$file_count} music files on disk.\n\n";

    echo "Step 4: Aligning database file paths with current environment...\n";
    // Convert all existing DB slashes to forward slashes to normalize
    $max_retries = 15;
    for ($attempt = 0; $attempt < $max_retries; $attempt++) {
      try {
        $db->exec("UPDATE music SET file = REPLACE(file, '\\', '/')"); 
        break;
      } catch (Exception $e) {
        if (strpos(strtolower($e->getMessage()), 'locked') !== false || strpos(strtolower($e->getMessage()), 'busy') !== false) {
          usleep(rand(20000, 50000));
        } else {
          break; // Unrelated error
        }
      }
    }
    
    $sample_file = $db->query("SELECT file FROM music LIMIT 1")->fetchColumn();
    if ($sample_file) {
      $old_base = null; $new_base = null;

      if (preg_match('#^(.*?)/(uploads/.*)$#i', $sample_file, $matches)) {
        $old_base = $matches[1];
        $new_base = str_replace('\\', '/', MUSIC_DIR);
      } else {
        $basename = basename($sample_file);
        foreach ($files_on_disk as $disk_path => $mtime) {
          if (basename($disk_path) === $basename) {
            $db_parts = explode('/', $sample_file);
            $disk_parts = explode('/', $disk_path);
            $match_len = 0;
            for ($i = 1; $i <= min(count($db_parts), count($disk_parts)); $i++) {
              if ($db_parts[count($db_parts) - $i] === $disk_parts[count($disk_parts) - $i]) $match_len = $i;
              else break;
            }
            if ($match_len > 0) {
              $suffix = implode('/', array_slice($db_parts, -$match_len));
              $old_base = substr($sample_file, 0, -strlen($suffix) - 1);
              $new_base = substr($disk_path, 0, -strlen($suffix) - 1);
              break;
            }
          }
        }
      }

      if ($old_base && $new_base && strcasecmp($old_base, $new_base) !== 0) {
        echo " -> Mismatch detected: Database base path differs from Current environment.\n";
        echo "    Old: {$old_base}\n";
        echo "    New: {$new_base}\n";
        echo " -> Automatically correcting all file paths in the database...\n";
        
        $success = false;
        $last_error_msg = "";
        for ($attempt = 0; $attempt < $max_retries; $attempt++) {
          $db->beginTransaction();
          try {
            // Replace the old prefix with the new prefix natively in SQLite, heavily bound to LIKE parameters
            $db->prepare("UPDATE music SET file = ? || SUBSTR(file, ?) WHERE file LIKE ?")->execute([$new_base, strlen($old_base) + 1, $old_base . '/%']);
            $db->commit();
            $success = true;
            break;
          } catch (Exception $e) {
            $db->rollBack();
            $last_error_msg = $e->getMessage();
            if (strpos(strtolower($last_error_msg), 'locked') !== false || strpos(strtolower($last_error_msg), 'busy') !== false) {
              usleep(rand(20000, 50000));
            } else {
              break; // Unrelated error
            }
          }
        }
        
        if ($success) {
          echo " -> Successfully corrected all file paths.\n\n";
        } else {
          echo " -> Error correcting database paths: " . $last_error_msg . "\n\n";
        }
      } else {
        echo " -> Database base path is aligned perfectly.\n\n";
      }
    }

    echo "Step 5: Fetching existing music records from database...\n";
    $db_files = $db->query("SELECT file, last_modified FROM music")->fetchAll(PDO::FETCH_KEY_PAIR);
    echo "Found " . count($db_files) . " records in the database.\n\n";

    echo "Step 6: Building differential processing queue...\n";
    // Calculate the diffs
    $files_to_add = array_diff_key($files_on_disk, $db_files);
    $files_to_delete = array_diff_key($db_files, $files_on_disk);
    $files_to_update = [];

    foreach (array_intersect_key($files_on_disk, $db_files) as $filePath => $mtime) {
      if ($mtime != $db_files[$filePath]) {
        $files_to_update[$filePath] = $mtime;
      }
    }

    $unchanged_count = count(array_intersect_key($files_on_disk, $db_files)) - count($files_to_update);
    echo " - Existing (Unchanged): " . $unchanged_count . "\n";
    echo " - To add: " . count($files_to_add) . "\n";
    echo " - To update: " . count($files_to_update) . "\n";
    echo " - To delete: " . count($files_to_delete) . "\n\n";

    // Construct the sequential task queue
    $process_queue = array_merge(
      array_map(function($f, $m) { return ['type' => 'process', 'file' => $f, 'mtime' => $m]; }, array_keys($files_to_add), array_values($files_to_add)),
      array_map(function($f, $m) { return ['type' => 'process', 'file' => $f, 'mtime' => $m]; }, array_keys($files_to_update), array_values($files_to_update)),
      array_map(function($f) { return ['type' => 'delete', 'file' => $f]; }, array_keys($files_to_delete))
    );

    $total_tasks = count($process_queue);

    if ($total_tasks === 0) {
      if (file_exists($queue_file)) @unlink($queue_file);
      echo "<script>setProgress(100); if (window.parent && window.parent.finishScan) window.parent.finishScan('full-scan-modal');</script>";
      die("Scan complete. No changes detected.\n</pre>");
    }

    file_put_contents($queue_file, json_encode(['total' => $total_tasks, 'completed' => 0, 'tasks' => $process_queue]));
    
    echo "Queue built successfully! Redirecting to processing engine...\n";
    echo "<script>setTimeout(() => window.location.href = '?action=full_scan&step=2', 1000);</script></pre>";
    exit;
  }

  if ($step === 2) {
    if (!file_exists($queue_file)) {
      die("Queue file lost or scan completed. You can close this window.\n</pre>");
    }

    $queue_data = json_decode(file_get_contents($queue_file), true);
    $tasks = $queue_data['tasks'];
    $completed = $queue_data['completed'];
    $total = $queue_data['total'];

    if (empty($tasks)) {
      @unlink($queue_file);
      echo "<script>setProgress(100);</script>";
      die("\n=======================\nScan completed successfully!\nTotal processed: {$total}\n</pre>");
    }

    // OPTIMIZATION 5: Batch processing (25 items at a time) to prevent PHP max_execution_time limits!
    $batch_size = 25;
    $current_batch = array_slice($tasks, 0, $batch_size);
    $remaining_tasks = array_slice($tasks, $batch_size);

    $getID3 = new getID3;
    $getID3->setOption(['encoding' => 'UTF-8']);
    $getID3->option_md5_data = true;
    $getID3->option_md5_data_source = true;
    $getID3->option_sha1_data = true;
    $getID3->option_tags_html = false;

    $library_user_id = $db->query("SELECT id FROM users WHERE status = 'super_admin' LIMIT 1")->fetchColumn() ?: 1;

    $insert_stmt = $db->prepare("INSERT INTO music (user_id, file, title, artist, album, genre, year, duration, bitrate, image, last_modified) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
    $update_img = $db->prepare("UPDATE music SET title = ?, artist = ?, album = ?, genre = ?, year = ?, duration = ?, bitrate = ?, image = ?, last_modified = ? WHERE file = ?");
    $update_no_img = $db->prepare("UPDATE music SET title = ?, artist = ?, album = ?, genre = ?, year = ?, duration = ?, bitrate = ?, last_modified = ? WHERE file = ?");
    $delete_stmt = $db->prepare("DELETE FROM music WHERE file = ?");
    $check_file = $db->prepare("SELECT id FROM music WHERE file = ?");
    
    $user_cache = [];
    $stmt_all_users = $db->query("SELECT id, artist FROM users");
    while ($row = $stmt_all_users->fetch()) {
      $user_cache[strtolower($row['artist'])] = $row['id'];
    }
    
    $check_email = $db->prepare("SELECT id FROM users WHERE email = ?");
    $insert_user = $db->prepare("INSERT INTO users (email, artist, password_hash, verified, profile_picture, profile_picture_type) VALUES (?, ?, ?, 'no', ?, 'image/svg+xml')");

    $db->beginTransaction();

    foreach ($current_batch as $task) {
      $completed++;
      $percent = floor(($completed / $total) * 100);

      if ($task['type'] === 'delete') {
        echo sprintf("[%3d%%] [%d/%d] Deleting: %s\n", $percent, $completed, $total, basename($task['file']));
        $delete_stmt->execute([$task['file']]);
      } else {
        echo sprintf("[%3d%%] [%d/%d] Processing: %s\n", $percent, $completed, $total, basename($task['file']));
      echo "<script>if (window.parent && window.parent.updateScanPill) window.parent.updateScanPill({$completed}, {$total}, 'Scanning Library');</script>";
        
        $filePath = $task['file'];
        $mtime = $task['mtime'];

        try {
          $info = $getID3->analyze($filePath);
          getid3_lib::CopyTagsToComments($info);
          
          $title = extract_safe_tag($info['comments'] ?? [], 'title', pathinfo($filePath, PATHINFO_FILENAME));
          $artist_tag = extract_safe_tag($info['comments'] ?? [], 'artist', 'Unknown Artist');
          $album = extract_safe_tag($info['comments'] ?? [], 'album', 'Unknown Album');
          $genre = extract_safe_tag($info['comments'] ?? [], 'genre', 'Unknown Genre');
          $year = (int)($info['comments']['year'][0] ?? 0);
          $duration = (int)($info['playtime_seconds'] ?? 0);
          $bitrate = (int)($info['audio']['bitrate'] ?? 0);
          
          $raw_image_data = $info['comments']['picture'][0]['data'] ?? null;
          if (!$raw_image_data) {
            $dir = pathinfo($filePath, PATHINFO_DIRNAME);
            $filename = pathinfo($filePath, PATHINFO_FILENAME);
            $possible_covers = [$filename . '.jpg', $filename . '.png', 'cover.jpg', 'cover.png', 'folder.jpg', 'folder.png', 'artwork.jpg'];
            foreach ($possible_covers as $cfile) {
              $cpath = $dir . '/' . $cfile;
              if (file_exists($cpath)) {
                $raw_image_data = @file_get_contents($cpath);
                if ($raw_image_data) break;
              }
            }
          }
          $webp_image_data = process_image_to_webp($raw_image_data);
          
          $check_file->execute([$filePath]);
          $is_update = $check_file->fetchColumn();

          if ($is_update) {
            if ($webp_image_data !== null) {
              $update_img->execute([$title, $artist_tag, $album, $genre, $year, $duration, $bitrate, $webp_image_data, $mtime, $filePath]);
            } else {
              $update_no_img->execute([$title, $artist_tag, $album, $genre, $year, $duration, $bitrate, $mtime, $filePath]);
            }
          } else {
            $file_user_id = $library_user_id;
            $main_artist = trim(preg_split('/\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i', $artist_tag)[0]);

            if ($main_artist !== 'Unknown Artist' && !empty($main_artist)) {
              $artist_lower = strtolower($main_artist);
              if (isset($user_cache[$artist_lower])) {
                $file_user_id = $user_cache[$artist_lower];
              } else {
                echo " -> New artist: '{$main_artist}'. Creating account.\n";
                $sanitized_artist_base = sanitize_for_path($main_artist);
                $hash = password_hash($sanitized_artist_base, PASSWORD_DEFAULT);
                
                $email = $sanitized_artist_base . '@mail.com';
                if ($sanitized_artist_base === 'unknown') {
                  $email = 'unknown1@mail.com';
                }
                $counter = 1;
                while (true) {
                  $check_email->execute([$email]);
                  if (!$check_email->fetch()) break;
                  $counter++;
                  $email = $sanitized_artist_base . $counter . '@mail.com';
                }
                
                $initial = mb_strtoupper(mb_substr($main_artist, 0, 1, 'UTF-8'));
                $svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><rect width="200" height="200" fill="#ffffff"/><text x="50%" y="50%" dominant-baseline="central" text-anchor="middle" font-family="Arial, sans-serif" font-size="100" font-weight="bold" fill="#121212">' . htmlspecialchars($initial) . '</text></svg>';
                
                $insert_user->execute([$email, $main_artist, $hash, $svg]);
                $file_user_id = $db->lastInsertId();
                $user_cache[$artist_lower] = $file_user_id; 
              }
            }
            $insert_stmt->execute([$file_user_id, $filePath, $title, $artist_tag, $album, $genre, $year, $duration, $bitrate, $webp_image_data, $mtime]);
          }
        } catch (Exception $e) {
          echo " -> Error processing " . basename($filePath) . ": " . $e->getMessage() . "\n";
        }
      }

      echo "<script>setProgress({$percent}); if (window.parent && window.parent.updateScanPill) window.parent.updateScanPill({$completed}, {$total});</script>";
      @ob_flush(); flush();
    }

    $db->commit();

    $queue_data['tasks'] = $remaining_tasks;
    $queue_data['completed'] = $completed;
    file_put_contents($queue_file, json_encode($queue_data));

    if (empty($remaining_tasks)) {
      @unlink($queue_file);
      echo "<script>setProgress(100); if (window.parent && window.parent.updateScanPill) window.parent.updateScanPill({$total}, {$total}, 'Scanning Library');</script>";
      echo "\n=======================\nScan completed successfully!\nTotal processed: {$total}\n</pre>";
      echo "<script>
        if (window.parent) {
          if (window.parent.finishScan) window.parent.finishScan('full-scan-modal');
        }
      </script>";
    } else {
      echo "\nBatch complete. Loading next {$batch_size}...\n";
      echo "<script>setTimeout(() => window.location.href = '?action=full_scan&step=2', 100);</script></pre>";
    }
  }
}

function perform_cover_scan($db) {
  $start_time = microtime(true);
  ini_set('memory_limit', '512M');
  error_reporting(E_ALL & ~E_DEPRECATED);
  ini_set('display_errors', 1);

  header('Content-Type: text/html; charset=utf-8');
  ob_implicit_flush();

  echo "<style>
    body { color: #e0e0e0; background-color: #030303; font-family: Consolas, 'Courier New', monospace; padding: 10px; margin: 0; }
    pre { white-space: pre-wrap; word-wrap: break-word; font-family: inherit; margin-top: 75px; }
    #header-wrap { position: fixed; top: 0; left: 0; right: 0; background: #121212; border-bottom: 1px solid #333; z-index: 10; }
    #prog-wrap { padding: 12px 15px 5px 15px; display: flex; align-items: center; }
    #prog-track { flex-grow: 1; background: #000; height: 12px; border-radius: 6px; overflow: hidden; margin-right: 15px; }
    #prog-bar { width: 0%; height: 100%; background: #ff0000; transition: width 0.1s; }
    #prog-txt { font-weight: bold; min-width: 45px; text-align: right; font-size: 14px;}
    #warning-txt { padding: 0 15px 12px 15px; color: #ffc107; font-size: 12px; font-weight: bold; text-align: center; text-transform: uppercase; letter-spacing: 0.5px; }
  </style>";

  echo "<div id='header-wrap'>
          <div id='prog-wrap'><div id='prog-track'><div id='prog-bar'></div></div><div id='prog-txt'>0%</div></div>
          <div id='warning-txt'>⚠️ Re-scanning metadata cover arts. Do not close this window!</div>
        </div>";
  echo "<pre>";
  echo "PHP Music Library - Cover Rescan Process\n";
  echo "=========================================\n\n";

  if (!class_exists('getID3')) {
    die("FATAL ERROR: getID3 library not found in " . __DIR__ . "/getid3/\n");
  }

  $getID3 = new getID3;
  $getID3->setOption(['encoding' => 'UTF-8']);
  $getID3->option_tags_html = false;

  $stmt = $db->query("SELECT id, file, title FROM music WHERE image IS NULL");
  $songs_to_process = $stmt->fetchAll();
  $total = count($songs_to_process);

  echo "Found {$total} tracks currently missing cover images in the database.\n\n";

  if ($total === 0) {
    die("All covers are already processed! No action required.\n</pre>");
  }

  $update_stmt = $db->prepare("UPDATE music SET image = ? WHERE id = ?");
  $processed = 0;

  $db->beginTransaction();
  try {
    foreach ($songs_to_process as $song) {
      if ((microtime(true) - $start_time) > 40) {
        $db->commit();
        echo "\nApproaching script execution limit. Re-indexing page to resume safely...\n";
        echo "<script>setTimeout(() => window.location.reload(), 1000);</script></pre>";
        exit;
      }

      $processed++;
      $percent = floor(($processed / $total) * 100);
      echo sprintf("[%3d%%] [%d/%d] Scanning: %s\n", $percent, $processed, $total, basename($song['file']));
      echo "<script>document.getElementById('prog-bar').style.width = '{$percent}%'; document.getElementById('prog-txt').innerText = '{$percent}%'; window.scrollTo(0, document.body.scrollHeight); if (window.parent && window.parent.updateScanPill) window.parent.updateScanPill({$processed}, {$total}, 'Scanning Covers');</script>";

      $filePath = $song['file'];
      if (!file_exists($filePath)) {
        $fallback = MUSIC_DIR . '/uploads/' . basename(dirname(dirname($filePath))) . '/' . basename(dirname($filePath)) . '/' . basename($filePath);
        if (file_exists($fallback)) {
          $filePath = $fallback;
        }
      }

      if (file_exists($filePath)) {
        $info = $getID3->analyze($filePath);
        getid3_lib::CopyTagsToComments($info);
        $raw_image_data = $info['comments']['picture'][0]['data'] ?? null;

        if (!$raw_image_data) {
          $file_info = pathinfo($filePath);
          $dir = $file_info['dirname'];
          $filename = $file_info['filename'];
          $neighbors = [$filename . '.jpg', $filename . '.png', 'cover.jpg', 'cover.png', 'folder.jpg', 'folder.png', 'artwork.jpg'];
          foreach ($neighbors as $nfile) {
            $npath = $dir . '/' . $nfile;
            if (file_exists($npath)) {
              $raw_image_data = @file_get_contents($npath);
              if ($raw_image_data) break;
            }
          }
        }

        if ($raw_image_data) {
          $webp_data = process_image_to_webp($raw_image_data);
          if ($webp_data) {
            $update_stmt->execute([$webp_data, $song['id']]);
            echo " -> Successfully recovered and converted cover art.\n";
          }
        }
      } else {
        echo " -> File warning: Track path could not be found physically on disk.\n";
      }

      if ($processed % 100 === 0) {
        $db->commit();
        gc_collect_cycles();
        $db->beginTransaction();
      }
    }
    $db->commit();
  } catch (Exception $e) {
    if ($db->inTransaction()) $db->rollBack();
    die("\nFATAL TRANSACTION ERROR: " . $e->getMessage() . "\n</pre>");
  }

  echo "\n=======================\n";
  echo "Cover rescan process complete! Recovered items: $processed\n</pre>";
  echo "<script>if (window.parent && window.parent.finishScan) window.parent.finishScan('cover-scan-modal');</script>";
}
?>

