      }
      #artists-modal {
        z-index: 99998 !important;
      }

      .auth-modal-fullscreen {
        padding: 0 !important;
        margin: 0 !important;
      }

      .auth-modal-content {
        background: #080308 linear-gradient(180deg, #12040b 0%, #290815 35%, #541122 65%, #a82435 85%, #d94d4d 100%) no-repeat center center !important;
        background-size: cover !important;
        position: relative;
        overflow-x: hidden !important;
        overflow-y: auto !important;
        min-height: 100vh;
        min-height: 100dvh;
        border: none !important;
        color: #ffffff;
      }

      .auth-ambient-glow {
        position: absolute;
        top: 20%;
        left: 50%;
        transform: translate(-50%, -50%);
        width: 600px;
        height: 600px;
        background: radial-gradient(circle, rgba(255, 0, 51, 0.25) 0%, rgba(255, 0, 51, 0) 70%);
        filter: blur(60px);
        pointer-events: none;
        z-index: 1;
      }

      .auth-mountain-backdrop {
        position: absolute;
        bottom: 0;
        left: 0;
        right: 0;
        width: 100%;
        height: 60%;
        pointer-events: none;
        z-index: 1;
        background: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1440 600" preserveAspectRatio="none"><path fill="%232b0713" opacity="0.65" d="M0,600 L0,380 L180,260 L360,420 L580,210 L760,360 L980,140 L1180,310 L1340,240 L1440,320 L1440,600 Z"/><path fill="%231a030a" opacity="0.88" d="M0,600 L0,440 L220,330 L440,490 L680,290 L880,450 L1120,240 L1300,410 L1440,360 L1440,600 Z"/><path fill="%230a0104" d="M0,600 L0,510 L140,460 L320,530 L540,430 L740,510 L940,400 L1160,490 L1360,440 L1440,480 L1440,600 Z"/></svg>') no-repeat bottom center;
        background-size: cover;
      }

      .auth-container-shell {
        position: relative;
        z-index: 2;
        display: flex;
        align-items: center;
        justify-content: center;
        min-height: 100vh;
        min-height: 100dvh;
        padding: 1.5rem;
      }

      .auth-glass-card {
        display: flex;
        flex-direction: column;
        width: 100%;
        max-width: 440px;
        border-radius: 20px;
        overflow: hidden;
        background: rgba(15, 6, 10, 0.78);
        border: 1px solid rgba(255, 0, 51, 0.28);
        box-shadow: 0 20px 60px rgba(0, 0, 0, 0.85), 0 0 30px rgba(255, 0, 51, 0.2);
        backdrop-filter: blur(25px);
        -webkit-backdrop-filter: blur(25px);
        margin: auto;
        transition: transform 0.3s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 0.3s ease;
      }

      @media (min-width: 768px) {
        .auth-glass-card {
          flex-direction: row;
          max-width: 860px;
          min-height: 520px;
          border-radius: 24px;
        }
      }

      .auth-left-banner {
        background: linear-gradient(145deg, rgba(35, 10, 18, 0.85) 0%, rgba(15, 4, 8, 0.95) 100%);
        border-right: 1px solid rgba(255, 0, 51, 0.15);
        padding: 3rem 2.5rem;
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;
        text-align: center;
        position: relative;
        width: 42%;
      }

      .auth-left-banner::before {
        content: '';
        position: absolute;
        top: 0;
        left: 0;
        width: 4px;
        height: 100%;
        background: linear-gradient(180deg, #ff0033 0%, #7a0018 100%);
      }

      .auth-brand-badge {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        background: rgba(255, 0, 51, 0.12);
        border: 1px solid rgba(255, 0, 51, 0.3);
        border-radius: 50px;
        padding: 6px 14px;
        font-size: 0.85rem;
        font-weight: 700;
        letter-spacing: 0.5px;
        color: #ff4d66;
        box-shadow: 0 4px 15px rgba(255, 0, 51, 0.2);
      }

      .auth-banner-title {
        font-size: clamp(1.6rem, 3vw, 2.1rem);
        font-weight: 900;
        letter-spacing: -0.5px;
        line-height: 1.2;
        color: #ffffff;
        text-shadow: 0 2px 8px rgba(0, 0, 0, 0.6);
      }

      .auth-banner-sub {
        color: rgba(255, 255, 255, 0.65);
        font-size: 0.95rem;
        margin-top: 0.5rem;
        margin-bottom: 2rem;
        line-height: 1.5;
      }

      .auth-switch-box {
        background: rgba(0, 0, 0, 0.35);
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: 16px;
        padding: 1rem 1.25rem;
        width: 100%;
      }

      .auth-switch-label {
        font-size: 0.85rem;
        color: rgba(255, 255, 255, 0.7);
        font-weight: 500;
        margin-bottom: 0.75rem;
      }

      .auth-pill-btn {
        background: rgba(255, 255, 255, 0.06) !important;
        border: 1px solid rgba(255, 255, 255, 0.2) !important;
        color: #ffffff !important;
        font-size: 0.85rem !important;
        font-weight: 700 !important;
        border-radius: 50rem !important;
        padding: 0.45rem 1.2rem !important;
        transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
        text-decoration: none !important;
        display: inline-flex;
        align-items: center;
        justify-content: center;
      }

      .auth-pill-btn:hover {
        background: rgba(255, 0, 51, 0.25) !important;
        border-color: #ff0033 !important;
        color: #ffffff !important;
        transform: translateY(-2px);
        box-shadow: 0 6px 16px rgba(255, 0, 51, 0.3);
      }

      .auth-right-form {
        background: rgba(18, 7, 12, 0.6);
        padding: 2rem 1.5rem;
        display: flex;
        flex-direction: column;
        justify-content: center;
        flex-grow: 1;
        width: 100%;
      }

      @media (min-width: 768px) {
        .auth-right-form {
          width: 58%;
          padding: 3rem 2.8rem;
        }
      }

      .auth-form-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        margin-bottom: 1.75rem;
      }

      .auth-form-title {
        font-size: 1.85rem;
        font-weight: 800;
        color: #ffffff;
        margin: 0;
        display: flex;
        align-items: center;
        gap: 10px;
        letter-spacing: -0.5px;
      }

      .auth-form-title::after {
        content: '';
        display: inline-block;
        width: 32px;
        height: 4px;
        border-radius: 2px;
        background: linear-gradient(90deg, #ff0033 0%, transparent 100%);
      }

      .auth-floating-group {
        position: relative;
        margin-bottom: 1.25rem;
      }

      .auth-floating-group .form-control {
        background: rgba(0, 0, 0, 0.45) !important;
        border: 1px solid rgba(255, 255, 255, 0.12) !important;
        color: #ffffff !important;
        border-radius: 14px !important;
        height: 58px !important;
        font-size: 0.95rem !important;
        padding: 1.45rem 3rem 0.45rem 1.15rem !important;
        transition: all 0.25s ease;
        box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.4);
      }

      /* Hides placeholder when unfocused so it never overlaps the label */
      .auth-floating-group .form-control::placeholder {
        color: transparent !important;
        opacity: 0 !important;
      }

      .auth-floating-group .form-control:focus::placeholder {
        color: rgba(255, 255, 255, 0.35) !important;
        opacity: 1 !important;
      }

      .auth-floating-group .form-control:focus {
        background: rgba(0, 0, 0, 0.7) !important;
        border-color: #ff0033 !important;
        box-shadow: 0 0 0 3px rgba(255, 0, 51, 0.25), inset 0 2px 6px rgba(0, 0, 0, 0.6) !important;
      }

      .auth-floating-group label {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        padding: 1.05rem 1.15rem !important;
        color: rgba(255, 255, 255, 0.6) !important;
        font-size: 0.9rem !important;
        pointer-events: none;
        transform-origin: 0 0;
        transition: transform 0.2s cubic-bezier(0.2, 0, 0, 1), color 0.2s ease;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
      }

      .auth-floating-group .form-control:focus ~ label,
      .auth-floating-group .form-control:not(:placeholder-shown) ~ label {
        transform: translateY(-0.55rem) scale(0.78);
        color: #ff4d66 !important;
        font-weight: 700;
      }

      .auth-input-action {
        position: absolute;
        right: 14px;
        top: 50%;
        transform: translateY(-50%);
        background: none;
        border: none;
        color: rgba(255, 255, 255, 0.4);
        padding: 6px;
        cursor: pointer;
        z-index: 5;
        transition: color 0.2s ease;
      }

      .auth-input-action:hover {
        color: #ffffff;
      }

      .auth-btn-submit {
        background: linear-gradient(135deg, #ff0033 0%, #c40026 100%) !important;
        border: none !important;
        color: #ffffff !important;
        font-weight: 800 !important;
        border-radius: 14px !important;
        padding: 0.95rem 1.5rem !important;
        font-size: 1.05rem !important;
        letter-spacing: 0.5px;
        text-transform: uppercase;
        box-shadow: 0 8px 24px rgba(255, 0, 51, 0.45);
        transition: all 0.25s cubic-bezier(0.2, 0.8, 0.2, 1);
        width: 100%;
        margin-top: 0.5rem;
      }

      .auth-btn-submit:hover {
        background: linear-gradient(135deg, #ff1a47 0%, #e0002b 100%) !important;
        transform: translateY(-2px);
        box-shadow: 0 12px 30px rgba(255, 0, 51, 0.6);
      }

      .auth-btn-submit:active {
        transform: translateY(1px);
        box-shadow: 0 4px 15px rgba(255, 0, 51, 0.4);
      }

      .auth-terms-box {
        display: flex;
        align-items: flex-start;
        gap: 10px;
        margin-top: 0.5rem;
        margin-bottom: 1.25rem;
        padding: 0 4px;
      }

      .auth-terms-checkbox {
        accent-color: #ff0033 !important;
        width: 18px;
        height: 18px;
        margin-top: 2px;
        cursor: pointer;
        flex-shrink: 0;
      }

      .auth-terms-text {
        font-size: 0.82rem;
        color: rgba(255, 255, 255, 0.65);
        line-height: 1.4;
        margin: 0;
      }

      .auth-terms-text a {
        color: #ffffff;
        font-weight: 700;
        text-decoration: underline;
        transition: color 0.2s;
      }

      .auth-terms-text a:hover {
        color: #ff4d66;
      }

      .auth-footer-help {
        display: flex;
        align-items: center;
        justify-content: space-between;
        margin-top: 1.5rem;
        padding-top: 1.25rem;
        border-top: 1px solid rgba(255, 255, 255, 0.08);
      }

      .auth-help-link {
        font-size: 0.85rem;
        color: rgba(255, 255, 255, 0.6);
        text-decoration: none;
        transition: all 0.2s ease;
        display: inline-flex;
        align-items: center;
        gap: 6px;
      }

      .auth-help-link:hover {
        color: #ff4d66;
      }

      /* Card Internal Close Button */
      .auth-card-close-btn {
        position: absolute;
        top: 18px;
        right: 18px;
        width: 36px;
        height: 36px;
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.08) !important;
        border: 1px solid rgba(255, 255, 255, 0.15) !important;
        color: rgba(255, 255, 255, 0.75) !important;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 0.95rem;
        z-index: 10;
        cursor: pointer;
        backdrop-filter: blur(8px);
        transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
      }

      .auth-card-close-btn:hover {
        background: rgba(255, 0, 51, 0.35) !important;
        border-color: #ff0033 !important;
        color: #ffffff !important;
        transform: rotate(90deg) scale(1.1);
      }
    </style>
  </head>
