    <div class="modal fade" id="playlist-downloader-modal" tabindex="-1">
      <div class="modal-dialog modal-dialog-scrollable modal-fullscreen">
        <div class="modal-content" style="background-color: var(--ytm-bg);">
          <div class="modal-header border-0" style="background-color: var(--ytm-surface-2);">
            <h5 class="modal-title"><i class="bi bi-cloud-arrow-down-fill"></i> Playlist Downloader</h5>
            <button type="button" class="btn-close-white" data-bs-dismiss="modal"></button>
          </div>
          <div class="modal-body p-2 p-md-4">
            <div class="container-fluid mx-auto" style="max-width: 1000px;">
              <div class="card mb-4" style="background-color: var(--ytm-surface); border: none;">
                <div class="card-header" style="background-color: var(--ytm-surface-2); font-weight: bold; border: none; color: #ffffff !important;">Load Playlist / Song</div>
                <div class="card-body">
                  <form id="pd-load-form" class="mb-4">
                    <div class="mb-3">
                      <label for="pd-playlist-id" class="form-label" style="color: #ffffff !important;">Playlist ID</label>
                      <input type="text" class="form-control" id="pd-playlist-id" placeholder="Enter Playlist Public ID">
                    </div>
                    <button type="submit" class="btn btn-danger">Load Playlist</button>
                  </form>
                  <hr class="text-secondary">
                  <div class="mb-3">
                    <label for="pd-song-id" class="form-label" style="color: #ffffff !important;">Download a single song by ID</label>
                    <div class="input-group">
                      <input type="number" class="form-control" id="pd-song-id" placeholder="Song ID">
                      <button class="btn btn-outline-light" type="button" id="pd-download-single" style="color: #ffffff !important;">Download</button>
                    </div>
                  </div>
                </div>
              </div>

              <div id="pd-results-card" class="card d-none" style="background-color: var(--ytm-surface); border: none;">
                <div class="card-header" style="background-color: var(--ytm-surface-2); font-weight: bold; border: none; color: #ffffff !important;" id="pd-playlist-title">
                  Playlist Details
                </div>
                <div class="card-body">
                  <button class="btn btn-danger w-100 mb-3" id="pd-start-auto" style="color: #ffffff !important;">
                    <i class="bi bi-play-fill" style="color: #ffffff !important;"></i> Download All Songs (Sequential)
                  </button>
                  <div class="mb-3">
                    <div class="d-flex justify-content-between align-items-center mb-2" style="color: #ffffff !important;">
                      <span><i class="bi bi-terminal" style="color: #ffffff !important;"></i> Download Log</span>
                      <button class="btn btn-sm btn-outline-secondary" id="pd-clear-log" style="color: #ffffff !important; border-color: #ffffff;">Clear</button>
                    </div>
                    <div class="log-area" id="pd-log" style="background-color: var(--ytm-surface-2); border-radius: 8px; padding: 1rem; font-family: monospace; font-size: 0.85rem; height: 300px; overflow-y: auto; color: #ffffff !important;"></div>
                  </div>
                  <div>
                    <strong style="color: #ffffff !important;">Song List</strong>
                    <div class="song-list mt-2" style="background-color: var(--ytm-surface); border-radius: 12px; overflow: hidden;">
                      <div class="song-item small d-none d-md-grid pd-song-row" style="color: #ffffff !important;">
                        <div style="color: #ffffff !important;" class="d-flex align-items-center"><input class="form-check-input me-2" type="checkbox" id="pd-select-all" checked> #</div>
                        <div style="color: #ffffff !important;">Title</div><div style="color: #ffffff !important;">Artist</div><div style="color: #ffffff !important;">Duration</div><div></div>
                      </div>
                      <div id="pd-song-rows"></div>
                    </div>
                    <div id="pd-infinite-scroll-loader" class="text-center p-3 d-none" style="color: var(--ytm-secondary-text);">Loading more...</div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    
    <div class="modal fade" id="song-audio-settings-modal" tabindex="-1">
      <div class="modal-dialog modal-dialog-scrollable modal-dialog-centered modal-lg">
        <div class="modal-content" style="background: rgba(30, 30, 30, 0.95); backdrop-filter: blur(10px); border: 1px solid #444;">
          <div class="modal-header border-0 pb-0">
            <h5 class="modal-title w-100 text-center text-white">Audio Settings for <br><small id="sas-song-title" class="text-secondary"></small></h5>
            <button type="button" class="btn-close btn-close-white position-absolute end-0 me-3" data-bs-dismiss="modal"></button>
          </div>
          <div class="modal-body text-white">
            <input type="hidden" id="sas-song-id">
            
            <div class="mb-4">
              <label class="form-label d-flex justify-content-between">
                <span>Song Volume Multiplier</span>
                <span id="sas-vol-val">1.0x</span>
              </label>
              <input type="range" class="form-range" id="sas-vol-slider" min="0" max="3" step="0.1" value="1">
              <small class="text-secondary d-block mt-1">Adjust if this specific song is too quiet or loud compared to others.</small>
            </div>
            
            <div class="mb-3">
              <label class="form-label d-flex justify-content-between align-items-center">
                <span>Per-Song Equalizer</span>
                <select class="form-select form-select-sm w-auto" id="sas-eq-preset-select">
                  <option value="Custom">Custom</option>
                  <option value="Flat">Flat</option>
                  <option value="Rock">Rock</option>
                  <option value="Jazz">Jazz</option>
                  <option value="Classical">Classical</option>
                  <option value="Pop">Pop</option>
                  <option value="Bass Boost">Bass Boost</option>
                </select>
              </label>
              <div class="d-flex justify-content-between text-center small text-secondary mt-3 mb-5">
                <span style="width:18%;">60Hz</span><span style="width:18%;">230Hz</span><span style="width:18%;">910Hz</span><span style="width:18%;">3.6kHz</span><span style="width:18%;">14kHz</span>
              </div>
              <div class="d-flex justify-content-between mt-2 mb-5">
                <input type="range" class="form-range sas-eq-band" data-band="0" min="-12" max="12" step="1" value="0" style="width:18%; transform: rotate(-90deg); margin-top: 40px; margin-bottom: 40px;">
                <input type="range" class="form-range sas-eq-band" data-band="1" min="-12" max="12" step="1" value="0" style="width:18%; transform: rotate(-90deg); margin-top: 40px; margin-bottom: 40px;">
                <input type="range" class="form-range sas-eq-band" data-band="2" min="-12" max="12" step="1" value="0" style="width:18%; transform: rotate(-90deg); margin-top: 40px; margin-bottom: 40px;">
                <input type="range" class="form-range sas-eq-band" data-band="3" min="-12" max="12" step="1" value="0" style="width:18%; transform: rotate(-90deg); margin-top: 40px; margin-bottom: 40px;">
                <input type="range" class="form-range sas-eq-band" data-band="4" min="-12" max="12" step="1" value="0" style="width:18%; transform: rotate(-90deg); margin-top: 40px; margin-bottom: 40px;">
              </div>
            </div>

            <div class="d-flex gap-2">
              <button type="button" class="btn btn-outline-secondary w-50" id="sas-reset-btn">Reset to Global</button>
              <button type="button" class="btn btn-danger w-50" id="sas-save-btn">Save to Song</button>
            </div>
          </div>
        </div>
      </div>
    </div>

    <div id="sleep-timer-bubble" class="d-none">
      <i class="bi bi-moon-stars-fill text-info"></i>
      <span class="time" id="sleep-timer-countdown">00:00</span>
      <button class="action-btn text-secondary" id="sleep-timer-wake-btn" title="Toggle Screen Awake"><i class="bi bi-display"></i></button>
      <button class="action-btn text-secondary" id="sleep-timer-cancel-btn" title="Cancel Timer"><i class="bi bi-x-circle-fill"></i></button>
    </div>

    <!-- Fullscreen Presentation Mode -->
    <div id="presentation-mode">
      <div class="position-absolute top-0 start-0 w-100 d-flex justify-content-between align-items-center p-3 px-4 z-3" style="background: linear-gradient(to bottom, rgba(0,0,0,0.8), transparent);">
        <div class="d-flex align-items-center gap-2 text-white-50 small fw-bold text-uppercase" style="letter-spacing: 1px;">
          <i class="bi bi-easel-fill text-danger fs-5"></i> Presentation Mode
        </div>
        <button class="btn btn-outline-secondary border-0 text-light p-1" onclick="window.closePresentation()" title="Exit Presentation (Esc)">
          <i class="bi bi-x-lg fs-4"></i>
        </button>
      </div>
      
      <div id="presentation-content">
        <div class="slide-inner" id="presentation-slide-container"></div>
      </div>
      
      <div class="position-absolute bottom-0 w-100 p-3 pb-4 d-flex justify-content-between align-items-center text-muted z-3" style="background: linear-gradient(transparent, #0a0a0a);">
        <div>
          <button class="btn btn-sm btn-outline-secondary border-0" onclick="window.prevSlide()" title="Previous Slide (Left Arrow)"><i class="bi bi-chevron-left fs-5"></i></button>
          <span class="mx-3 fw-medium font-monospace" id="presentation-indicator">1 / 1</span>
          <button class="btn btn-sm btn-outline-secondary border-0" onclick="window.nextSlide()" title="Next Slide (Right Arrow)"><i class="bi bi-chevron-right fs-5"></i></button>
        </div>
        <span class="small opacity-50 d-none d-sm-inline">Use ← / → / Space to navigate. Esc to exit.</span>
      </div>
      
      <!-- Progress Bar -->
      <div class="position-absolute bottom-0 start-0 w-100" style="height: 4px; background: #1e1e1e;">
        <div id="presentation-progress" class="h-100" style="width: 0%; background: var(--ytm-accent); transition: width 0.3s ease;"></div>
      </div>
    </div>

    <!-- Main Client Floating Mini Player -->
    <div id="main-mini-player" class="d-none shadow-lg" style="position: fixed; bottom: 80px; right: 20px; width: 210px; height: 210px; background: #000; border-radius: 12px; z-index: 9999; overflow: hidden; color: #fff; aspect-ratio: 1 / 1; box-shadow: 0 16px 40px rgba(0,0,0,0.8);" onmouseenter="document.getElementById('mmp-overlay').style.opacity='1'" onmouseleave="document.getElementById('mmp-overlay').style.opacity='0'">

      <!-- Media Background -->
      <div style="position: absolute; top:0; left:0; right:0; bottom:0; display: flex; align-items: center; justify-content: center; background: #000;">
        <img id="mmp-cover" src="data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg'/>" style="width: 100%; height: 100%; object-fit: cover;">
        <canvas class="visualizer-canvas" style="position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; z-index: 5; opacity: 0.7;"></canvas>
      </div>

      <!-- Overlay Container -->
      <div id="mmp-overlay" style="position: absolute; top:0; left:0; right:0; bottom:0; background: rgba(0,0,0,0.5); opacity: 0; transition: opacity 0.2s; display: flex; flex-direction: column; justify-content: space-between; z-index: 10;">

        <!-- Drag Header, PiP & Close -->
        <div id="mmp-header" style="height: 34px; padding: 6px 10px; cursor: move; display: flex; align-items: center; justify-content: flex-end; gap: 6px; background: linear-gradient(to bottom, rgba(0,0,0,0.7), transparent);">
          <button class="btn btn-sm text-white p-0 border-0 rounded-circle d-flex align-items-center justify-content-center" id="mmp-pip" style="width: 24px; height: 24px; background: rgba(255,255,255,0.2); backdrop-filter: blur(4px);" title="Pop Out Mini Player (PiP)"><i class="bi bi-pip" style="font-size: 0.75rem;"></i></button>
          <button class="btn btn-sm text-white p-0 border-0 rounded-circle d-flex align-items-center justify-content-center" id="mmp-close" style="width: 24px; height: 24px; background: rgba(255,255,255,0.2); backdrop-filter: blur(4px);" title="Close Mini Player"><i class="bi bi-x-lg" style="font-size: 0.75rem;"></i></button>
        </div>

        <!-- Center Controls -->
        <div class="d-flex align-items-center justify-content-center gap-3">
          <button class="btn text-white p-0 border-0" id="mmp-prev" title="Previous"><i class="bi bi-skip-start-fill" style="text-shadow: 0 2px 8px rgba(0,0,0,0.6);"></i></button>
          <button class="btn text-white p-0 border-0" id="mmp-play-pause" title="Play/Pause"><i class="bi bi-play-fill" id="mmp-play-icon" style="text-shadow: 0 2px 8px rgba(0,0,0,0.6);"></i></button>
          <button class="btn text-white p-0 border-0" id="mmp-next" title="Next"><i class="bi bi-skip-end-fill" style="text-shadow: 0 2px 8px rgba(0,0,0,0.6);"></i></button>
        </div>

        <!-- Title, Artist & Timeline (Matching IDE style) -->
        <div style="padding: 8px 12px; background: linear-gradient(to top, rgba(0,0,0,0.85), transparent);">
          <div id="mmp-title" class="fw-bold text-truncate text-white text-center mb-0" style="font-size: 0.8rem; text-shadow: 0 1px 3px rgba(0,0,0,0.8);">Track Title</div>
          <div id="mmp-artist" class="text-truncate text-white-50 text-center mb-1 hover-underline" style="font-size: 0.7rem; text-shadow: 0 1px 3px rgba(0,0,0,0.8); cursor: pointer;">Artist Name</div>
          <div style="position: relative; height: 10px; display: flex; align-items: center;">
            <div style="width: 100%; height: 4px; background: rgba(255,255,255,0.3); border-radius: 2px; pointer-events: none;">
              <div id="mmp-progress" style="width: 0%; height: 100%; background: #ff0000; border-radius: 2px;"></div>
            </div>
            <input type="range" id="mmp-seek" min="0" max="100" value="0" step="0.1" style="-webkit-appearance: none; width: 100%; height: 100%; background: transparent; position: absolute; top: 0; left: 0; margin: 0; cursor: pointer; outline: none; opacity: 0;">
          </div>
          <!-- Hidden time elements to prevent JS crashes -->
          <span id="mmp-cur-time" class="d-none"></span>
          <span id="mmp-time-left" class="d-none"></span>
        </div>
      </div>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/sortablejs@latest/Sortable.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/cropperjs/1.6.1/cropper.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/fabric.js/5.3.1/fabric.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/nosleep/0.12.0/NoSleep.min.js"></script>
    <script>
      // Global Hashchange Interceptor for Playground
      window.addEventListener("hashchange", () => {
        // If the hash changes to playground and we are inside the main app (where the template exists), boot it seamlessly.
        if (
          window.location.hash.startsWith("#playground") &&
          document.getElementById("play-client-template")
        ) {
          const tpl = document.getElementById("play-client-template");
    
          // Inject a seamless full-screen spinner overlay
          const spinnerOverlay = document.createElement("div");
          spinnerOverlay.style.cssText =
            "position: fixed; top: 0; left: 0; right: 0; bottom: 0; background-color: var(--ytm-bg, #030303); z-index: 999999; display: flex; align-items: center; justify-content: center; flex-direction: column; opacity: 0; transition: opacity 0.3s ease;";
          spinnerOverlay.innerHTML =
            '<div class="spinner-border text-danger" style="width: 3.5rem; height: 3.5rem; border-width: 0.25em;" role="status"></div><div class="text-white mt-4 fw-bold font-monospace fs-5">Booting Playground...</div>';
          document.body.appendChild(spinnerOverlay);
    
          // Trigger CSS fade-in
          requestAnimationFrame(() => {
            spinnerOverlay.style.opacity = "1";
          });
    
          // Replace the DOM seamlessly using document.write (acts like a reload without the white flash)
          setTimeout(() => {
            const htmlContent = tpl.innerHTML;
            document.open();
            document.write(htmlContent);
            document.close();
          }, 400);
        }
      });
    
      document.addEventListener("DOMContentLoaded", () => {
        // Main Site: Mobile Header Offcanvas Background Logic
        const mainOffcanvasEl = document.getElementById('main-nav-offcanvas');
        const mobileHeaderEl = document.querySelector('.mobile-header');
        if (mainOffcanvasEl && mobileHeaderEl) {
          mainOffcanvasEl.addEventListener('show.bs.offcanvas', () => {
            mobileHeaderEl.classList.add('solid-bg');
          });
          mainOffcanvasEl.addEventListener('hide.bs.offcanvas', () => {
            mobileHeaderEl.classList.remove('solid-bg');
          });
        }

        // Main Sidebar Toggle Logic
        const mainSidebarToggle = document.getElementById('main-desktop-sidebar-toggle');
        if (mainSidebarToggle) {
          const updateMainToggleIcon = (isMin) => {
            const icon = mainSidebarToggle.querySelector('i');
            if (icon) {
              icon.className = isMin ? 'bi bi-layout-sidebar-reverse fs-4' : 'bi bi-layout-sidebar fs-4';
            }
          };
          if (localStorage.getItem('main_sidebar_minimized') === 'true') {
            document.body.classList.add('sidebar-minimized');
            mainSidebarToggle.classList.add('mx-auto');
            updateMainToggleIcon(true);
          }
          mainSidebarToggle.addEventListener('click', () => {
            document.body.classList.toggle('sidebar-minimized');
            const isMin = document.body.classList.contains('sidebar-minimized');
            mainSidebarToggle.classList.toggle('mx-auto', isMin);
            updateMainToggleIcon(isMin);
            localStorage.setItem('main_sidebar_minimized', isMin);
            setTimeout(() => { window.dispatchEvent(new Event('resize')); }, 300);
          });
        }

        window.applyMarquee = (el, contentHTML) => {
          if (!el) return;

          const container = el.closest('.marquee-container');
          if (!container) {
            el.innerHTML = contentHTML;
            return;
          }

          const contentChanged = el._marqueeContent !== contentHTML;
          el._marqueeContent = contentHTML;

          const checkAndToggle = (force = false) => {
            const currentHTML = el._marqueeContent || contentHTML;
            const containerWidth = container.clientWidth;

            if (containerWidth === 0) return;

            // Prevent restarting active animations unless width changed significantly (>10px) or new track loaded
            if (!force && !contentChanged && container._lastWidth && Math.abs(containerWidth - container._lastWidth) < 10 && el.classList.contains('marquee-anim')) {
              return;
            }

            container._lastWidth = containerWidth;

            // Reset state to accurately measure un-duplicated content
            el.classList.remove('marquee-anim');
            el.style.animationDuration = '';
            el.style.transform = '';
            el.innerHTML = currentHTML;
            container.classList.remove('is-overflowing');

            const contentWidth = el.scrollWidth;

            if (contentWidth > (containerWidth + 4)) {
              el.innerHTML = `<span class="marquee-text-span" style="padding-right: 3rem; display: inline-block;">${currentHTML}</span><span class="marquee-text-span" style="padding-right: 3rem; display: inline-block;">${currentHTML}</span>`;

              const singleSpan = el.querySelector('.marquee-text-span');
              const textWidth = singleSpan ? singleSpan.offsetWidth : contentWidth;
              const duration = Math.max(6, parseFloat((textWidth / 30).toFixed(2)));

              el.style.animationDuration = `${duration}s`;
              el.classList.add('marquee-anim');
              container.classList.add('is-overflowing');
            }
          };

          if (contentChanged) {
            el.innerHTML = contentHTML;
          }

          // Double RAF ensures flexbox layout is settled
          requestAnimationFrame(() => {
            requestAnimationFrame(() => {
              checkAndToggle(contentChanged);
            });
          });

          // Debounced ResizeObserver prevents animation restarts during smooth window resizes
          if (!container._marqueeObserver && typeof ResizeObserver !== 'undefined') {
            let resizeTimer;
            container._marqueeObserver = new ResizeObserver(() => {
              clearTimeout(resizeTimer);
              resizeTimer = setTimeout(() => {
                checkAndToggle(false);
              }, 150);
            });
            container._marqueeObserver.observe(container);
          }
        };

        // PLAYGROUND ROUTER INTERCEPTOR
        // If the URL contains #playground, halt main app boot and swap out the DOM for the client template.
        if (window.location.hash.startsWith("#playground")) {
          const tpl = document.getElementById("play-client-template");
          if (tpl) {
            document.open();
            document.write(tpl.innerHTML);
            document.close();
          }
          return; // Strictly abort further execution of the main app
        }
    
        ("use strict");
    
        const escapeAttr = (str) =>
          str ? String(str).replace(/'/g, "&apos;").replace(/"/g, "&quot;") : "";
    
        const getSvgPlaceholder = (title) => {
          let hash = 0;
          for (let i = 0; i < title.length; i++) {
            hash = title.charCodeAt(i) + ((hash << 5) - hash);
          }
          const h = Math.abs(hash % 360);
          const c1 = `hsl(${h}, 50%, 35%)`;
          const c2 = `hsl(${(h + 40) % 360}, 60%, 45%)`;
          const c3 = `hsl(${(h + 80) % 360}, 60%, 35%)`;
          const svgString = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="100%" height="100%"><defs><linearGradient id="grad" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stop-color="${c1}"/><stop offset="50%" stop-color="${c2}"/><stop offset="100%" stop-color="${c3}"/></linearGradient><filter id="shadow" x="-10%" y="-10%" width="120%" height="120%"><feDropShadow dx="0" dy="8" stdDeviation="12" flood-opacity="0.3"/></filter></defs><rect width="512" height="512" fill="url(#grad)"/><g transform="translate(128, 128) scale(10.66)" fill="none" stroke="#ffffff" stroke-width="1.5" opacity="0.9" filter="url(#shadow)"><circle cx="12" cy="12" r="3"/><path stroke-linecap="round" d="M21.95 13c-.501 5.054-4.765 9-9.95 9c-5.523 0-10-4.477-10-10c0-1.821.487-3.529 1.338-5M11 2.05a9.9 9.9 0 0 0-4 1.288"/><path stroke-linecap="round" stroke-linejoin="round" d="M15 12V2.456a10.02 10.02 0 0 1 6.542 6.542"/></g></svg>`;
          return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svgString)}`;
        };
    
        window.scrollToCenter = (container, element, smooth = true) => {
          if (!container || !element) return false;
    
          const containerRect = container.getBoundingClientRect();
          const elementRect = element.getBoundingClientRect();
    
          // If the element or container is not visible (e.g. display: none), heights will be 0
          if (containerRect.height === 0 || elementRect.height === 0) return false;
    
          // Accurately calculate the scroll target using absolute bounding box coordinates
          const targetScroll =
            container.scrollTop +
            (elementRect.top - containerRect.top) -
            container.clientHeight / 2 +
            elementRect.height / 2;
    
          container.scrollTo({
            top: targetScroll,
            behavior: smooth ? "smooth" : "auto",
          });
          return true;
        };
    
        window.enforceScrollToActive = (paneId, queueListId, smooth = false) => {
          let attempts = 0;
          const tryScroll = () => {
            attempts++;
            const pane = document.getElementById(paneId);
            const activeItem = document.querySelector(
              `#${queueListId} .song-item.now-playing`,
            );
    
            if (pane && activeItem) {
              const success = window.scrollToCenter(pane, activeItem, smooth);
              // Double check after 150ms to counteract layout shifts from images loading or modal fading in
              if (success && attempts === 1) {
                setTimeout(tryScroll, 150);
              } else if (!success && attempts < 15) {
                setTimeout(tryScroll, 50);
              }
            } else if (attempts < 15) {
              setTimeout(tryScroll, 50);
            }
          };
          // Start the first attempt slightly deferred to allow initial DOM render
          setTimeout(tryScroll, 20);
        };

        const adjustSidebarPadding = () => {
          const sbBody = document.querySelector('#main-nav-offcanvas .offcanvas-body');
          if (sbBody) {
            if (document.body.classList.contains('player-visible') && window.innerWidth <= 768) {
              sbBody.style.paddingBottom = '175px';
            } else {
              sbBody.style.paddingBottom = '0px';
            }
          }
        };
        window.addEventListener('resize', adjustSidebarPadding);

        const mainContent = document.getElementById("main-content");
        const contentArea = document.getElementById("content-area");
        const contentTitle = document.getElementById("content-title");
        const searchInputDesktop = document.getElementById("search-input-desktop");
        const searchInputMobile = document.getElementById("search-input-mobile");
        const searchBtnDesktop = document.getElementById("search-btn-desktop");
        const searchBtnMobile = document.getElementById("search-btn-mobile");
        const sortControls = document.getElementById("sort-controls");
        const sortSelect = document.getElementById("sort-select");
        const historyControls = document.getElementById("history-controls");
        const clearHistoryBtn = document.getElementById("clear-history-btn");
        const allNavLinks = document.querySelectorAll(".sidebar .nav-link");
        const contextMenu = document.getElementById("context-menu");
        const playerBar = document.getElementById("player-bar");
        const infiniteScrollLoader = document.getElementById(
          "infinite-scroll-loader",
        );
        const installPwaBtn = document.getElementById("install-pwa-btn");
        const checkUpdateBtn = document.getElementById("check-update-btn");
        const updateModalEl = document.getElementById("update-modal");
        const updateModal = updateModalEl ? new bootstrap.Modal(updateModalEl) : null;
        const updateModalBody = document.getElementById("update-modal-body");
    
        const pipBtnDesktop = document.getElementById("pip-btn-desktop");
        const pipBtnMobile = document.getElementById("pip-btn-mobile");
    
        const pipCanvas = document.createElement("canvas");
        pipCanvas.width = 500;
        pipCanvas.height = 500;
        const pipCtx = pipCanvas.getContext("2d", {
          willReadFrequently: true,
        });
        const pipVideo = document.createElement("video");
        pipVideo.muted = true;
        pipVideo.playsInline = true;
    
        // FIX INFINITE SPINNER: Do not assign endless MediaStreams to video elements before the window finishes loading!
        // Chromium treats captureStream() as a pending network resource if attached too early.
        window.addEventListener("load", () => {
          try {
            const supportsPiP =
              "documentPictureInPicture" in window ||
              document.pictureInPictureEnabled ||
              (pipVideo.webkitSupportsPresentationMode &&
                typeof pipVideo.webkitSetPresentationMode === "function");
            if (pipCanvas.captureStream && supportsPiP) {
              pipVideo.srcObject = pipCanvas.captureStream(1);
            } else {
              if (pipBtnDesktop) pipBtnDesktop.style.display = "none";
              if (pipBtnMobile) pipBtnMobile.style.display = "none";
            }
          } catch (e) {
            if (pipBtnDesktop) pipBtnDesktop.style.display = "none";
            if (pipBtnMobile) pipBtnMobile.style.display = "none";
          }
        });
    
        const clearCacheBtn = document.getElementById("clear-cache-btn");
        const fullscreenBtn = document.getElementById("fullscreen-btn");
        const fullScanModalEl = document.getElementById("full-scan-modal");
        const fullScanIframe = document.getElementById("full-scan-iframe");
        const scanProgressPill = document.getElementById("scan-progress-pill");
        const showScanModalBtn = document.getElementById("show-scan-modal-btn");
        
        window.activeScanModalId = 'full-scan-modal';

        document.querySelectorAll('.hide-any-scan-btn').forEach(btn => {
          btn.addEventListener('click', (e) => {
            const targetId = e.currentTarget.dataset.target;
            window.activeScanModalId = targetId;
            window.isHidingScan = true;
            bootstrap.Modal.getOrCreateInstance(document.getElementById(targetId)).hide();
            if (scanProgressPill) {
              scanProgressPill.classList.remove('d-none');
              scanProgressPill.classList.add('d-flex');
            }
          });
        });

        if (showScanModalBtn && scanProgressPill) {
          showScanModalBtn.addEventListener('click', () => {
            scanProgressPill.classList.add('d-none');
            scanProgressPill.classList.remove('d-flex');
            if (window.activeScanModalId) {
              bootstrap.Modal.getOrCreateInstance(document.getElementById(window.activeScanModalId)).show();
            }
          });
        }
        
        window.updateScanPill = (completed, total, taskName = 'Scanning') => {
          const pillTitle = document.getElementById('scan-pill-title');
          const pillStats = document.getElementById('scan-pill-stats');
          if (pillTitle) pillTitle.innerText = taskName;
          if (pillStats) {
            if (total === 0) pillStats.innerText = `Preparing...`;
            else pillStats.innerText = `${completed} / ${total}`;
          }
        };

        window.finishScan = (modalId) => {
          const pillTitle = document.getElementById('scan-pill-title');
          const pillStats = document.getElementById('scan-pill-stats');
          const pillSpinner = document.getElementById('scan-pill-spinner');
          
          if (pillTitle) {
            pillTitle.innerText = 'COMPLETED!';
            pillTitle.style.color = '#fff';
          }
          if (pillStats) {
            pillStats.innerText = '100%';
          }
          if (pillSpinner) {
            pillSpinner.outerHTML = '<i class="bi bi-check-circle-fill text-danger" id="scan-pill-spinner" style="font-size: 20px; width: 20px; height: 20px; display: inline-flex; align-items: center; justify-content: center; margin: 0; flex-shrink: 0; line-height: 1;"></i>';
          }
          
          setTimeout(() => {
            if (scanProgressPill) {
              scanProgressPill.classList.add('d-none');
              scanProgressPill.classList.remove('d-flex');
              
              // Reset the spinner for the next task
              const newSpinner = document.getElementById('scan-pill-spinner');
              if (newSpinner) {
                newSpinner.outerHTML = '<div id="scan-pill-spinner" class="spinner-border text-danger" role="status" style="width: 20px; height: 20px; border-width: 2.5px; flex-shrink: 0; margin: 0;"></div>';
              }
            }
            const modalEl = document.getElementById(modalId);
            if (modalEl) {
              const inst = bootstrap.Modal.getInstance(modalEl);
              if (inst) inst.hide();
            }
            // Auto-refresh main UI to reflect database mutations
            if (window.requestCache) window.requestCache.clear();
            
            window.cachedExploreData = null; // Clear frontend explore cache
            
            if (window.emergencyScanPrompted) {
              window.emergencyScanPrompted = false; // Reset emergency flag
              if (window.loadView) {
                // Only force navigate to all songs if we are recovering from an empty database
                window.loadView({ type: 'get_songs', param: '', sort: 'id_desc', filter_user_id: '' });
              }
            } else if (window.loadView && window.currentView) {
              // Standard auto_scan: silently refresh the current page to stay where we are
              window.loadView(window.currentView);
            }
          }, 3000);
        };
    
        ['full-scan-modal', 'chart-scan-modal', 'cover-scan-modal'].forEach(id => {
          const el = document.getElementById(id);
          if (el) {
            el.addEventListener('shown.bs.modal', () => {
              const titleEl = el.querySelector('.scan-title-marquee');
              if (titleEl && typeof window.applyMarquee === 'function') {
                window.applyMarquee(titleEl, titleEl.textContent.trim());
              }
            });
          }
        });

        const genresModalEl = document.getElementById("genres-modal");
        const genresModal = genresModalEl ? new bootstrap.Modal(genresModalEl) : null;
        const genresModalBody = document.getElementById("genres-modal-body");
        const createPlaylistModalEl = document.getElementById(
          "create-playlist-modal",
        );
        const createPlaylistModal = createPlaylistModalEl
          ? new bootstrap.Modal(createPlaylistModalEl)
          : null;
        const editPlaylistModalEl = document.getElementById("edit-playlist-modal");
        const editPlaylistModal = editPlaylistModalEl
          ? new bootstrap.Modal(editPlaylistModalEl)
          : null;
        const importPlaylistModalEl = document.getElementById(
          "import-playlist-modal",
        );
        const importPlaylistModal = importPlaylistModalEl
          ? new bootstrap.Modal(importPlaylistModalEl)
          : null;
        const importFavoritesModalEl = document.getElementById(
          "import-favorites-modal",
        );
        const importFavoritesModal = importFavoritesModalEl
          ? new bootstrap.Modal(importFavoritesModalEl)
          : null;
        const importFollowingModalEl = document.getElementById(
          "import-following-modal",
        );
        const importFollowingModal = importFollowingModalEl
          ? new bootstrap.Modal(importFollowingModalEl)
          : null;
        const addToPlaylistModalEl = document.getElementById("add-to-playlist-modal");
        const addToPlaylistModal = addToPlaylistModalEl
          ? new bootstrap.Modal(addToPlaylistModalEl)
          : null;
        const addToPlaylistModalBody = document.getElementById(
          "add-to-playlist-modal-body",
        );
        const metadataModalEl = document.getElementById("metadata-modal");
        const metadataModal = metadataModalEl
          ? new bootstrap.Modal(metadataModalEl)
          : null;
        const metadataModalBody = document.getElementById("metadata-modal-body");
        const editMetadataModalEl = document.getElementById("edit-metadata-modal");
        const editMetadataModal = editMetadataModalEl
          ? new bootstrap.Modal(editMetadataModalEl)
          : null;
        const artistsModalEl = document.getElementById("artists-modal");
        const artistsModal = artistsModalEl
          ? new bootstrap.Modal(artistsModalEl)
          : null;
        const artistsModalBody = document.getElementById("artists-modal-body");
        const shareModalEl = document.getElementById("share-modal");
        const shareModal = shareModalEl ? new bootstrap.Modal(shareModalEl) : null;
        const shareModalTitle = document.getElementById("share-modal-title");
        const shareModalText = document.getElementById("share-modal-text");
        const shareUrlInput = document.getElementById("share-url-input");
        const copyShareUrlBtn = document.getElementById("copy-share-url-btn");
        const activityModalEl = document.getElementById("activity-modal");
    
        if (activityModalEl) {
          const body = document.getElementById("activity-modal-body");
    
          let activityPage = 1;
          const loadActivityFeed = async (append = false) => {
            if (!append) {
              activityPage = 1;
              body.innerHTML =
                '<div class="text-center p-4"><div class="spinner-border text-secondary" role="status"></div></div>';
            } else {
              const btn = document.getElementById("load-more-activity-btn");
              if (btn)
                btn.innerHTML =
                  '<span class="spinner-border spinner-border-sm"></span> Loading...';
            }
    
            const feed = await fetchData(
              `?action=get_activity_feed&page=${activityPage}`,
            );
    
            const loadMoreBtnContainer = document.getElementById(
              "load-more-activity-container",
            );
            if (loadMoreBtnContainer) loadMoreBtnContainer.remove();
    
            if (feed && feed.length > 0) {
              const htmlStr = feed
                .map((item) => {
                  if (item.type === "message_notif") {
                    const unreadBadge = item.is_unread
                      ? '<span class="badge bg-danger ms-2" style="font-size: 0.65rem;">New</span>'
                      : "";
                    const bgClass = item.is_unread ? "bg-dark" : "bg-transparent";
                    const cleanContent = item.content
                      ? parseUserText(item.content).replace(/<[^>]*>?/gm, "")
                      : "Sent an image";
    
                    return `
                          <li class="list-group-item ${bgClass} text-white border-secondary py-3 open-chat-btn" data-userid="${item.sender_id}" data-artist="${escapeHTML(item.commenter_name)}" style="cursor: pointer;">
                            <div class="d-flex align-items-start gap-3">
                              <div class="mt-1"><i class="bi bi-chat-dots-fill text-info fs-5"></i></div>
                              <div class="flex-grow-1" style="min-width: 0;">
                                <div style="font-size: 0.95rem;"><span class="fw-bold">${escapeHTML(item.commenter_name)}</span> sent you a message${unreadBadge}</div>
                                <div class="text-secondary fst-italic my-1 text-truncate" style="font-size: 0.9rem; border-left: 2px solid #555; padding-left: 8px;">"${cleanContent}"</div>
                                <div class="d-flex justify-content-between align-items-center mt-2">
                                  <small class="text-secondary" style="font-size: 0.75rem;">${timeAgo(item.created_at)}</small>
                                  <button class="btn btn-sm btn-outline-light"><i class="bi bi-reply-fill"></i> Reply</button>
                                </div>
                              </div>
                            </div>
                          </li>
                        `;
                  } else if (
                    item.type === "comment_notif" ||
                    item.type === "community_notif" ||
                    item.type === "blog_notif"
                  ) {
                    const isCommunity = item.type === "community_notif";
                    const isBlog = item.type === "blog_notif";
                    const isReply =
                      item.notif_type === "reply" ||
                      item.notif_type === "community_reply";
                    const unreadBadge = item.is_unread
                      ? '<span class="badge bg-danger ms-2" style="font-size: 0.65rem;">New</span>'
                      : "";
                    const bgClass = item.is_unread ? "bg-dark" : "bg-transparent";
    
                    let actionText = "";
                    let iconHTML = "";
                    let replyBtnHTML = "";
    
                    if (isCommunity) {
                      actionText = `<span class="fw-bold">${escapeHTML(item.commenter_name)}</span> replied to your community post${unreadBadge}`;
                      iconHTML = `<i class="bi bi-people-fill text-info fs-5"></i>`;
                      replyBtnHTML = `<button class="btn btn-sm btn-outline-light notif-comm-reply-btn" data-post-id="${item.post_id}" data-username="${escapeHTML(item.commenter_name)}"><i class="bi bi-reply-fill"></i> Reply</button>`;
                    } else if (isBlog) {
                      actionText = isReply
                        ? `<span class="fw-bold">${escapeHTML(item.commenter_name)}</span> replied to your comment on <span class="text-info">${escapeHTML(item.song_title)}</span>${unreadBadge}`
                        : `<span class="fw-bold">${escapeHTML(item.commenter_name)}</span> commented on your blog <span class="text-info">${escapeHTML(item.song_title)}</span>${unreadBadge}`;
                      iconHTML = `<i class="bi bi-journal-album text-warning fs-5"></i>`;
                      replyBtnHTML = `<button class="btn btn-sm btn-outline-light notif-blog-reply-btn" data-blog-id="${item.blog_public_id}" data-comment-id="${item.comment_id}" data-username="${escapeHTML(item.commenter_name)}"><i class="bi bi-reply-fill"></i> Reply</button>`;
                    } else {
                      actionText = isReply
                        ? `<span class="fw-bold">${escapeHTML(item.commenter_name)}</span> replied to your comment on <span class="text-info">${escapeHTML(item.song_title)}</span>${unreadBadge}`
                        : `<span class="fw-bold">${escapeHTML(item.commenter_name)}</span> commented on your song <span class="text-info">${escapeHTML(item.song_title)}</span>${unreadBadge}`;
                      iconHTML = `<i class="bi bi-chat-dots-fill text-primary fs-5"></i>`;
                      replyBtnHTML = `<button class="btn btn-sm btn-outline-light notif-reply-btn" data-song-id="${item.song_id}" data-comment-id="${item.comment_id}" data-username="${escapeHTML(item.commenter_name)}"><i class="bi bi-reply-fill"></i> Reply</button>`;
                    }
    
                    const cleanContent = parseUserText(item.content).replace(
                      /<[^>]*>?/gm,
                      "",
                    );
    
                    return `
                          <li class="list-group-item ${bgClass} text-white border-secondary py-3">
                            <div class="d-flex align-items-start gap-3">
                              <div class="mt-1">${iconHTML}</div>
                              <div class="flex-grow-1" style="min-width: 0;">
                                <div style="font-size: 0.95rem;">${actionText}</div>
                                <div class="text-secondary fst-italic my-1 text-truncate" style="font-size: 0.9rem; border-left: 2px solid #555; padding-left: 8px;">"${cleanContent}"</div>
                                <div class="d-flex justify-content-between align-items-center mt-2">
                                  <small class="text-secondary" style="font-size: 0.75rem;">${timeAgo(item.created_at)}</small>
                                  ${replyBtnHTML}
                                </div>
                              </div>
                            </div>
                          </li>
                        `;
                  } else {
                    const unreadBadge = item.is_unread
                      ? '<span class="badge bg-danger ms-2" style="font-size: 0.65rem;">New</span>'
                      : "";
                    const bgClass = item.is_unread ? "bg-dark" : "bg-transparent";
                    return `
                          <li class="list-group-item ${bgClass} text-white border-secondary py-3">
                            <div class="d-flex align-items-center gap-3">
                              <div class="mt-1"><i class="bi bi-clock-history text-secondary fs-5"></i></div>
                              <div>
                                <div style="font-size: 0.95rem;">You ${escapeHTML(item.action)} ${item.target_name ? `<span class="text-info">${escapeHTML(item.target_name)}</span>` : ""}${unreadBadge}</div>
                                <small class="text-secondary" style="font-size: 0.75rem;">${timeAgo(item.created_at)}</small>
                              </div>
                            </div>
                          </li>
                        `;
                  }
                })
                .join("");
    
              if (!append) {
                body.innerHTML =
                  '<ul class="list-group list-group-flush" id="activity-list">' +
                  htmlStr +
                  "</ul>";
              } else {
                document
                  .getElementById("activity-list")
                  .insertAdjacentHTML("beforeend", htmlStr);
              }
    
              if (feed.length === 25) {
                body.insertAdjacentHTML(
                  "beforeend",
                  `
                        <div class="text-center p-3" id="load-more-activity-container">
                          <button class="btn btn-outline-light rounded-pill px-4 btn-sm fw-bold" id="load-more-activity-btn">Load More Activity</button>
                        </div>
                      `,
                );
                document
                  .getElementById("load-more-activity-btn")
                  .addEventListener("click", () => {
                    activityPage++;
                    loadActivityFeed(true);
                  });
              }
    
              if (!append) {
                setTimeout(async () => {
                  document
                    .querySelectorAll(".notif-badge")
                    .forEach((b) => b.classList.add("d-none"));
                  await fetchData("?action=mark_notifs_read", {
                    method: "POST",
                  });
                  updateNotifBadge();
                }, 1500);
              }
            } else {
              if (!append)
                body.innerHTML =
                  '<p class="text-secondary text-center p-4">No recent activity.</p>';
            }
          };
    
          activityModalEl.addEventListener("show.bs.modal", () =>
            loadActivityFeed(false),
          );
    
          const connectionsModalEl = document.getElementById("connections-modal");
          if (connectionsModalEl) {
            connectionsModalEl.addEventListener("click", async (e) => {
              const loadMoreBtn = e.target.closest("#load-more-conn-btn");
              if (loadMoreBtn) {
                e.preventDefault();
                window.connPage++;
                window.loadConnections(true);
                return;
              }
    
              const followBtn = e.target.closest(".follow-btn-modal");
              if (followBtn) {
                e.preventDefault();
                e.stopPropagation();
                if (!currentUser) return showToast("Please log in", "error");
                const userId = followBtn.dataset.userId;
                const res = await fetchData("?action=toggle_follow", {
                  method: "POST",
                  headers: {
                    "Content-Type": "application/json",
                  },
                  body: JSON.stringify({
                    following_id: userId,
                  }),
                });
    
                if (
                  res &&
                  (res.status === "followed" || res.status === "unfollowed")
                ) {
                  const isFollowing = res.status === "followed";
                  if (isFollowing) window.triggerFollowEffect(followBtn);
                  followBtn.textContent = isFollowing ? "Unfollow" : "Follow";
                  followBtn.className = `btn btn-sm rounded-pill fw-bold follow-btn-modal px-3 flex-shrink-0 ${isFollowing ? "btn-outline-light" : "btn-danger"}`;
    
                  if (
                    currentView.type === "artist_songs" ||
                    currentView.type === "user_profile" ||
                    currentView.type === "get_following"
                  ) {
                    loadView(currentView); // Sync background view numbers
                  }
                } else {
                  showToast(res?.message || "Error toggling follow", "error");
                }
                return;
              }
            });
          }
    
          // --- FULL PAGE CHAT APP LOGIC ---
          window.getPreviewText = (htmlStr) => {
            if (!htmlStr) return "";
            const tmp = document.createElement("div");
            tmp.innerHTML = htmlStr;
            return tmp.textContent || tmp.innerText || "";
          };
    
          if (!window.chatAudioObj) {
            window.chatAudioObj = new Audio();
            window.chatAudioActiveMsgId = null;
    
            window.chatAudioObj.addEventListener("timeupdate", () => {
              if (
                window.chatAudioActiveMsgId &&
                isFinite(window.chatAudioObj.duration)
              ) {
                const playerEl = document.querySelector(
                  `.chat-audio-player[data-msg-id="${window.chatAudioActiveMsgId}"]`,
                );
                if (playerEl) {
                  const pct =
                    (window.chatAudioObj.currentTime / window.chatAudioObj.duration) *
                    100;
                  const track = playerEl.querySelector(".chat-audio-progress");
                  const timeDisplay = playerEl.querySelector(".chat-audio-time");
                  const icon = playerEl.querySelector(".chat-audio-play-btn i");
    
                  if (track) track.style.width = pct + "%";
                  if (timeDisplay) {
                    const cur = window.chatAudioObj.currentTime;
                    const m = Math.floor(cur / 60);
                    const s = Math.floor(cur % 60)
                      .toString()
                      .padStart(2, "0");
                    timeDisplay.innerText = `${m}:${s}`;
                  }
                  if (icon && !window.chatAudioObj.paused) {
                    icon.className = "bi bi-pause-fill fs-4";
                  }
                }
              }
            });
            window.chatAudioObj.addEventListener("ended", () => {
              const playerEl = document.querySelector(
                `.chat-audio-player[data-msg-id="${window.chatAudioActiveMsgId}"]`,
              );
              if (playerEl) {
                const icon = playerEl.querySelector(".chat-audio-play-btn i");
                const track = playerEl.querySelector(".chat-audio-progress");
                const timeDisplay = playerEl.querySelector(".chat-audio-time");
                if (icon) icon.className = "bi bi-play-fill fs-4";
                if (track) track.style.width = "0%";
                if (timeDisplay) timeDisplay.innerText = "0:00";
              }
              window.chatAudioActiveMsgId = null;
            });
          }
    
          window.playChatAudio = (msgId, url) => {
            const isPlayingThis =
              window.chatAudioActiveMsgId == msgId && !window.chatAudioObj.paused;
    
            document
              .querySelectorAll(".chat-audio-play-btn i")
              .forEach((i) => (i.className = "bi bi-play-fill fs-4"));
    
            if (isPlayingThis) {
              window.chatAudioObj.pause();
            } else {
              if (window.chatAudioActiveMsgId != msgId) {
                window.chatAudioObj.src = url;
                window.chatAudioActiveMsgId = msgId;
              }
    
              const mainAudio = document.getElementById("audio-player");
              if (mainAudio && !mainAudio.paused) {
                document.getElementById("btn-play-pause").click();
              }
    
              window.chatAudioObj.play().catch((e) => console.error(e));
            }
          };
    
          window.seekChatAudio = (e, msgId) => {
            if (window.chatAudioActiveMsgId != msgId) return;
            const playerEl = document.querySelector(
              `.chat-audio-player[data-msg-id="${msgId}"]`,
            );
            if (!playerEl) return;
            const trackContainer = playerEl.querySelector(".chat-audio-track");
            const rect = trackContainer.getBoundingClientRect();
            const pos = Math.max(
              0,
              Math.min(1, (e.clientX - rect.left) / rect.width),
            );
            if (isFinite(window.chatAudioObj.duration)) {
              window.chatAudioObj.currentTime = pos * window.chatAudioObj.duration;
            }
          };
    
          window.openChatFull = async (targetId, type, name) => {
            requestNotificationPermission(); // Ask OS permission to send Push Notifications
            activeChatConfig = {
              id: targetId,
              type: type,
              name: name,
            };
            window.currentChatPage = 1; // Reset pagination bounds on new chat
            window.lastMessagesString = null; // Reset comparison state
            window.forceScrollToBottomNext = true; // Flag to snap scroll to bottom
            const mainArea = document.querySelector(".chat-main");
            const sidebarArea = document.querySelector(".chat-sidebar");
    
            const mentionBtn = document.getElementById("chat-mention-btn");
            const chatInput = document.getElementById("chat-input");
            if (mentionBtn) {
              if (type === "group") mentionBtn.classList.remove("d-none");
              else mentionBtn.classList.add("d-none");
            }
            if (chatInput) {
              chatInput.placeholder =
                type === "group" ? "Type a message..." : "Type a message...";
            }
    
            const chatInputArea = document.querySelector(".chat-input-area");
            if (chatInputArea) chatInputArea.style.display = "flex";
    
            if (mainArea) mainArea.classList.add("active");
            if (sidebarArea && window.innerWidth < 768)
              sidebarArea.classList.add("hidden");
    
            const headerTitle = document.getElementById("chat-header-title");
            if (headerTitle) {
              const cacheBuster = Math.floor(Date.now() / 60000);
              headerTitle.innerHTML =
                (type === "group"
                  ? `<div class="d-flex align-items-center justify-content-center rounded-circle me-3 overflow-hidden bg-dark" style="width: 44px; height: 44px; min-width: 44px; flex-shrink: 0; line-height: 1;"><img src="?action=get_group_image&id=${targetId}&v=${cacheBuster}" onerror="this.outerHTML='<i class=\\'bi bi-people-fill text-info fs-4\\'></i>'" style="width: 100%; height: 100%; object-fit: cover; display: block;"></div>`
                  : `<img src="?action=get_profile_picture&id=${targetId}&v=${cacheBuster}" class="rounded-circle me-3" style="width: 44px; height: 44px; min-width: 44px; object-fit: cover; flex-shrink: 0; display: block;">`) +
                `<div class="d-flex flex-column justify-content-center" style="min-width: 0;">
                         <span class="text-truncate fw-bold" style="font-size: 1.1rem; line-height: 1.2;">${escapeHTML(name)}</span>
                         <span class="text-success small fw-medium" style="font-size: 0.8rem;">${type === "group" ? "Group Chat" : "Active"}</span>
                       </div>`;
            }
    
            const pipBtn = document.getElementById("chat-pip-btn");
            if (pipBtn) {
              if ("documentPictureInPicture" in window && window.innerWidth >= 768) {
                pipBtn.classList.remove("d-none");
              } else {
                pipBtn.classList.add("d-none");
                pipBtn.classList.remove("d-md-flex");
              }
            }
            const headerDropdown = document.getElementById("chat-header-dropdown");
            if (headerDropdown) {
              headerDropdown.classList.remove("d-none");
    
              const optInfo = document.getElementById("chat-opt-info");
              if (optInfo) {
                optInfo.onclick = (e) => {
                  e.preventDefault();
                  if (type === "group") window.showGroupInfo(targetId);
                  else
                    window.loadView({
                      type: "artist_songs",
                      param: name,
                      sort: "album_asc",
                      filter_user_id: targetId,
                      artist_name: "",
                    });
                };
              }
    
              const optSearch = document.getElementById("chat-opt-search");
              if (optSearch) {
                optSearch.onclick = (e) => {
                  e.preventDefault();
                  const searchContainer = document.getElementById(
                    "chat-floating-search",
                  );
                  if (searchContainer) {
                    searchContainer.classList.remove("d-none");
                    searchContainer.classList.add("d-flex");
                    const input = document.getElementById("chat-inner-search");
                    if (input) input.focus();
                  }
                };
              }
            }
    
            const closeChatSearchBtn = document.getElementById("close-chat-search");
            if (closeChatSearchBtn) {
              closeChatSearchBtn.onclick = (e) => {
                e.preventDefault();
                const searchContainer = document.getElementById(
                  "chat-floating-search",
                );
                searchContainer.classList.remove("d-flex");
                searchContainer.classList.add("d-none");
                const input = document.getElementById("chat-inner-search");
                if (input) {
                  input.value = "";
                  input.dispatchEvent(new Event("input"));
                }
              };
            }
    
            const msgContainer = document.getElementById("chat-messages-container");
            if (msgContainer) {
              msgContainer.innerHTML =
                '<div class="text-center p-5"><div class="spinner-border text-secondary"></div></div>';
            }
            if (typeof window.clearChatReply === "function") window.clearChatReply();
    
            await window.refreshChatFull();
            if (window.chatPollingInterval) clearInterval(window.chatPollingInterval);
            window.chatPollingInterval = setInterval(window.refreshChatFull, 1500); // Ultra-fast real-time sync
          };
    
          window.currentChatFetchId = 0;
    
          window.loadOlderChatMessages = (e) => {
            if (e) {
              e.preventDefault();
              e.stopPropagation();
            }
            const listEl = document.getElementById("chat-messages-container");
            if (!listEl) return;
    
            const oldScrollHeight = listEl.scrollHeight;
            window.currentChatPage = (window.currentChatPage || 1) + 1;
    
            window.refreshChatFull(true).then(() => {
              // Exact scroll correction so position remains static
              setTimeout(() => {
                if (listEl) listEl.scrollTop = listEl.scrollHeight - oldScrollHeight;
              }, 50);
            });
          };
    
          window.refreshChatFull = async (forceSync = false) => {
            if (!activeChatConfig.id) return;
            // Prevent polling if user is reacting
            if (window.isReacting && !forceSync) return;
    
            let isMediaPlaying = false;
            if (window.chatAudioObj && !window.chatAudioObj.paused)
              isMediaPlaying = true;
            document.querySelectorAll(".chat-main video").forEach((v) => {
              if (!v.paused && !v.ended) isMediaPlaying = true;
            });
            if (isMediaPlaying && !forceSync) return;
    
            window.currentChatFetchId++;
            const fetchId = window.currentChatFetchId;
            const page = window.currentChatPage || 1;
    
            try {
              // Add silent fetch (true) to prevent global error toasts blocking UI during rapid polls
              const messages = await fetchData(
                `?action=get_chat&target_id=${activeChatConfig.id}&chat_type=${activeChatConfig.type}&chat_page=${page}`,
                {},
                true,
              );
    
              if (
                fetchId !== window.currentChatFetchId ||
                (window.isReacting && !forceSync)
              )
                return;
    
              // Prevent DOM flickering: Compare raw JSON state and skip if identical
              const newMessagesString = JSON.stringify(messages);
              if (!forceSync && window.lastMessagesString === newMessagesString) {
                return; // Nothing changed, skip DOM re-render!
              }
              window.lastMessagesString = newMessagesString;
    
              const doc = window.chatPipWindow
                ? window.chatPipWindow.document
                : document;
              const listEl = doc.getElementById("chat-messages-container");
              if (!listEl) return;
    
              const chatInputArea = doc.querySelector(".chat-input-area");
    
              if (messages && messages.status === "blocked") {
                listEl.innerHTML = `<div class="text-center text-secondary opacity-75 p-4 mt-auto mb-auto"><i class="bi bi-slash-circle fs-1 d-block mb-3"></i>${escapeHTML(messages.message)}</div>`;
                if (chatInputArea) chatInputArea.style.display = "none";
                return;
              } else if (messages && messages.status === "error") {
                listEl.innerHTML = `<div class="text-center text-danger p-4 mt-auto mb-auto">${escapeHTML(messages.message)}</div>`;
                if (chatInputArea) chatInputArea.style.display = "none";
                return;
              } else {
                if (chatInputArea) chatInputArea.style.display = "flex";
              }
    
              if (messages && Array.isArray(messages) && messages.length > 0) {
                const isScrolledToBottom =
                  listEl.scrollHeight - listEl.clientHeight <= listEl.scrollTop + 50;
    
                let olderBtnHtml = "";
                if (messages.length >= page * 25) {
                  olderBtnHtml = `<div class="text-center w-100 mb-4 mt-2" id="load-older-chat-container"><button class="btn btn-sm btn-outline-secondary rounded-pill px-4" onclick="window.loadOlderChatMessages(event)"><i class="bi bi-clock-history"></i> Load Older Messages</button></div>`;
                }
    
                listEl.innerHTML =
                  olderBtnHtml +
                  messages
                    .map((m) => {
                      const isMe = m.sender_id == currentUser.id;
                      const bubbleClass = isMe ? "me" : "other";
    
                      let mediaHtml = "";
                      if (m.has_image) {
                        const mediaUrl = `?action=get_message_image&id=${m.id}`;
                        const thumbUrl = `?action=get_message_image&id=${m.id}&thumb=1`;
                        if (m.media_type && m.media_type.startsWith("video/")) {
                          mediaHtml = window.buildLazyMediaHtml(
                            mediaUrl,
                            m.media_type,
                            thumbUrl,
                            false,
                          );
                        } else if (
                          m.media_type &&
                          m.media_type.startsWith("audio/")
                        ) {
                          mediaHtml = `
                              <div class="chat-audio-player d-flex align-items-center gap-3 mb-2 p-2 rounded shadow-sm" data-msg-id="${m.id}" style="background: rgba(0,0,0,0.25); border: 1px solid rgba(255,255,255,0.05); min-width: 220px;">
                                <button class="btn btn-danger rounded-circle d-flex align-items-center justify-content-center flex-shrink-0 chat-audio-play-btn" onclick="window.playChatAudio(${m.id}, '${mediaUrl}')" style="width: 38px; height: 38px; padding: 0; transition: transform 0.1s;" onmouseover="this.style.transform='scale(1.05)'" onmouseout="this.style.transform='scale(1)'">
                                  <i class="bi bi-${window.chatAudioActiveMsgId == m.id && !window.chatAudioObj.paused ? "pause" : "play"}-fill fs-4"></i>
                                </button>
                                <div class="chat-audio-track flex-grow-1 position-relative" style="height: 6px; background: rgba(255,255,255,0.2); border-radius: 3px; cursor: pointer;" onclick="window.seekChatAudio(event, ${m.id})">
                                  <div class="chat-audio-progress" style="width: ${window.chatAudioActiveMsgId == m.id && isFinite(window.chatAudioObj.duration) ? (window.chatAudioObj.currentTime / window.chatAudioObj.duration) * 100 : 0}%; height: 100%; background: var(--ytm-accent); border-radius: 3px; pointer-events: none; transition: width 0.1s linear;"></div>
                                </div>
                                <span class="chat-audio-time small fw-bold" style="font-size: 0.75rem; min-width: 35px; user-select: none; color: rgba(255,255,255,0.8);">
                                  ${
                                    window.chatAudioActiveMsgId == m.id
                                      ? Math.floor(
                                          window.chatAudioObj.currentTime / 60,
                                        ) +
                                        ":" +
                                        Math.floor(
                                          window.chatAudioObj.currentTime % 60,
                                        )
                                          .toString()
                                          .padStart(2, "0")
                                      : "0:00"
                                  }
                                </span>
                              </div>`;
                        } else {
                          mediaHtml = window.buildLazyMediaHtml(
                            mediaUrl,
                            m.media_type || "image/webp",
                            thumbUrl,
                            false,
                          );
                        }
                      }
    
                      const editedHtml = m.is_edited
                        ? '<small class="text-white-50 ms-2" style="font-size: 0.65rem;">(Edited)</small>'
                        : "";
    
                      let replyHtml = "";
                      if (m.reply_to_id) {
                        const cleanRep = (m.reply_content || "Photo").replace(
                          /<[^>]*>?/gm,
                          "",
                        );
                        replyHtml = `
                            <div class="chat-reply-quote" onclick="document.querySelector('.msg-anchor-${m.reply_to_id}')?.scrollIntoView({behavior:'smooth', block:'center'})">
                              <strong style="color: ${isMe ? "#fff" : "var(--ytm-accent)"};">${escapeHTML(m.reply_sender || "Someone")}</strong><br>
                              <span class="text-truncate d-block">${escapeHTML(cleanRep)}</span>
                            </div>
                          `;
                      }
    
                      let reactionsHtml = "";
                      if (m.reactions && m.reactions.length > 0) {
                        const reactMap = {};
                        m.reactions.forEach((r) => {
                          if (!reactMap[r.reaction])
                            reactMap[r.reaction] = {
                              count: 0,
                              me: false,
                            };
                          reactMap[r.reaction].count++;
                          if (r.user_id == currentUser.id)
                            reactMap[r.reaction].me = true;
                        });
    
                        const pills = Object.keys(reactMap)
                          .map(
                            (emoji) => `
                            <span class="reaction-pill ${reactMap[emoji].me ? "reacted" : ""}" onclick="window.toggleMsgReaction(${m.id}, '${emoji}')">
                              ${emoji} <small>${reactMap[emoji].count}</small>
                            </span>
                           `,
                          )
                          .join("");
                        reactionsHtml = `<div class="reactions-container">${pills}</div>`;
                      }
    
                      let senderNameHtml = "";
                      if (!isMe && activeChatConfig.type === "group") {
                        senderNameHtml = `<div class="fw-bold mb-1 user-profile-link" data-userid="${m.sender_id}" data-artist="${encodeURIComponent(m.sender_name)}" style="font-size: 0.8rem; color: var(--ytm-accent); cursor: pointer;">${escapeHTML(m.sender_name)}</div>`;
                      }
    
                      const safeSender = m.sender_name
                        ? escapeHTML(m.sender_name).replace(/&#39;/g, "\\'")
                        : "Someone";
                      const safeContent = m.content
                        ? escapeHTML(m.content)
                            .replace(/&#39;/g, "\\'")
                            .replace(/\n/g, " ")
                            .replace(/\r/g, "")
                        : "";
    
                      // Format standard readable time (e.g. 10:45 AM)
                      const dateObj = m.created_at
                        ? new Date(m.created_at.replace(" ", "T") + "Z")
                        : new Date();
                      const timeString = dateObj.toLocaleTimeString([], {
                        hour: "2-digit",
                        minute: "2-digit",
                      });
    
                      // Set data attributes directly on the wrapper so we can catch interactions dynamically
                      return `
                          <div class="chat-bubble ${bubbleClass} msg-anchor-${m.id} chat-bubble-interact"
                               data-msg-id="${m.id}" 
                               data-is-me="${isMe ? 1 : 0}" 
                               data-is-starred="${m.is_starred ? 1 : 0}" 
                               data-sender="${encodeURIComponent(safeSender)}" 
                               data-content="${encodeURIComponent(safeContent)}"
                               style="cursor: pointer;">
                            ${senderNameHtml}
                            ${replyHtml}
                            ${mediaHtml}
                            ${m.content ? `<div style="white-space: pre-wrap; margin-top: ${m.has_image ? "4px" : "0"};" id="msg-content-${m.id}">${parseUserText(m.content)}</div>` : ""}
                            ${reactionsHtml}
                            <div class="msg-time-stamp">${timeString} ${editedHtml}</div>
                          </div>
                        `;
                    })
                    .join("");
    
                // Force continuous downward scroll tracking during active PiP sessions [1]
                if (
                  window.chatPipWindow ||
                  window.forceScrollToBottomNext ||
                  isScrolledToBottom
                ) {
                  const scrollBottom = () => {
                    if (listEl) listEl.scrollTop = listEl.scrollHeight + 10000;
                  };
                  scrollBottom();
                  setTimeout(scrollBottom, 50);
                  setTimeout(scrollBottom, 150);
                  setTimeout(scrollBottom, 300); // 300ms accounts for late image/video renders expanding height
                  window.forceScrollToBottomNext = false;
                }

                // Bind Right-Click and Long-Press to chat bubbles
                listEl.querySelectorAll('.chat-bubble-interact:not(.bound)').forEach(bubble => {
                  bubble.classList.add('bound');
                  let pressTimer;
                  let startX = 0, startY = 0;

                  const doToggle = (e) => {
                    if (e && e.preventDefault) e.preventDefault();
                    window.buildAndShowChatContextMenu(bubble);
                  };

                  const startTouch = (e) => {
                    if (e.target.closest('a') || e.target.closest('button')) return;
                    if (e.touches && e.touches.length > 0) {
                      startX = e.touches[0].clientX;
                      startY = e.touches[0].clientY;
                    }
                    pressTimer = setTimeout(() => {
                      doToggle(e);
                      if (navigator.vibrate) navigator.vibrate(50);
                    }, 400);
                  };
                  const cancelTouch = () => clearTimeout(pressTimer);
                  const moveTouch = (e) => {
                    if (!e.touches) return;
                    const dx = Math.abs(e.touches[0].clientX - startX);
                    const dy = Math.abs(e.touches[0].clientY - startY);
                    if (dx > 10 || dy > 10) clearTimeout(pressTimer);
                  };

                  bubble.addEventListener("touchstart", startTouch, { passive: true });
                  bubble.addEventListener("touchend", cancelTouch);
                  bubble.addEventListener("touchcancel", cancelTouch);
                  bubble.addEventListener("touchmove", moveTouch, { passive: true });
                  bubble.addEventListener("contextmenu", (e) => {
                    if (e.target.closest('a') || e.target.closest('button')) return;
                    doToggle(e);
                  });
                });

              } else {
                listEl.innerHTML =
                  '<div class="text-center text-secondary p-4 mt-auto mb-auto">Start the conversation!</div>';
              }
              updateNotifBadge();
              window.checkMediaCache();
            } catch (err) {
              const listEl = document.getElementById("chat-messages-container");
              if (listEl)
                listEl.innerHTML =
                  '<div class="text-center text-danger p-4 mt-auto mb-auto">Failed to load messages.</div>';
            }
          };
    
          window.setChatReply = (id, sender, content) => {
            const doc = window.chatPipWindow
              ? window.chatPipWindow.document
              : document;
            doc.getElementById("chat-reply-id").value = id;
            const preview = doc.getElementById("chat-reply-preview");
            preview.innerHTML = `<strong>Replying to ${sender}:</strong><br><span class="text-secondary text-truncate d-block">${content.replace(/<[^>]*>?/gm, "")}</span>`;
            doc.getElementById("chat-reply-bar").classList.add("active");
            doc.getElementById("chat-input").focus();
          };
    
          window.showFormattingHelp = (targetDoc) => {
            const doc = targetDoc || document;
            let helpBox = doc.getElementById("dynamic-formatting-help");
            if (!helpBox) {
              helpBox = doc.createElement("div");
              helpBox.id = "dynamic-formatting-help";
              helpBox.style.cssText =
                "position:fixed; top:50%; left:50%; transform:translate(-50%, -50%); background:#1a1a1a; border:1px solid #444; border-radius:12px; padding:24px; z-index:9999; box-shadow:0 10px 40px rgba(0,0,0,0.9); max-width:90%; width:380px; color:#fff;";
              helpBox.innerHTML = `
                      <h6 class="fw-bold mb-3 border-bottom border-secondary pb-3"><i class="bi bi-info-circle text-info me-2"></i>Formatting Help</h6>
                      <ul class="list-unstyled small text-secondary mb-4" style="line-height: 1.8; font-size: 0.9rem;">
                        <li class="mb-2"><strong class="text-white">Links:</strong> <code class="bg-black px-2 py-1 rounded border border-secondary">[url] link.com [/url]</code></li>
                        <li class="mb-2"><strong class="text-white">Images:</strong> <code class="bg-black px-2 py-1 rounded border border-secondary">[img] image.jpg [/img]</code></li>
                        <li class="mb-2"><strong class="text-white">Video:</strong> <code class="bg-black px-2 py-1 rounded border border-secondary">[video] link.mp4 [/video]</code></li>
                        <li class="mb-2"><strong class="text-white">Mentions:</strong> <code class="bg-black px-2 py-1 rounded border border-secondary">@Username</code></li>
                      </ul>
                      <button class="btn btn-outline-light btn-sm w-100 fw-bold py-2 rounded-pill" onclick="this.parentElement.remove()">Close</button>
                    `;
              doc.body.appendChild(helpBox);
            }
          };
    
          window.handleManualDropdownClick = (e) => {
            const activeDoc = e.target.ownerDocument;
            const toggle = e.target.closest('[data-bs-toggle="dropdown"]');

            if (
              toggle &&
              (toggle.id === "profile-picture-header-desktop" ||
                toggle.id === "profile-picture-header-mobile")
            ) {
              return;
            }

            if (toggle) {
              e.preventDefault();
              e.stopPropagation();
              e.stopImmediatePropagation(); // Prevents Bootstrap event listener collision

              const menu = toggle
                .closest(".dropdown, .dropup")
                ?.querySelector(".dropdown-menu");
              if (!menu) return;
              const isOpen = menu.classList.contains("show");

              activeDoc.querySelectorAll(".dropdown-menu.show").forEach((m) => {
                m.classList.remove("show");
                m.style.display = "";
              });

              if (!isOpen) {
                menu.classList.add("show");
                menu.style.display = "block";

                const rect = toggle.getBoundingClientRect();
                const winHeight = activeDoc.defaultView.innerHeight;

                const menuHeight = menu.offsetHeight || 200;
                const menuWidth = menu.offsetWidth || 180;

                const offsetParent = menu.offsetParent || activeDoc.body;
                const parentRect = offsetParent.getBoundingClientRect();

                let topPos;
                if (
                  rect.bottom + menuHeight > winHeight &&
                  rect.top - menuHeight > 0
                ) {
                  topPos = rect.top - parentRect.top - menuHeight - 4;
                } else {
                  topPos = rect.bottom - parentRect.top + 4;
                }

                let leftPos = rect.right - parentRect.left - menuWidth;
                if (leftPos < 8) {
                  leftPos = Math.max(8, rect.left - parentRect.left);
                }

                menu.style.position = "absolute";
                menu.style.top = topPos + "px";
                menu.style.left = leftPos + "px";
                menu.style.zIndex = "99999";
              }
            } else if (
              !e.target.closest(".dropdown-menu") ||
              e.target.closest(".dropdown-item")
            ) {
              const activeDoc = e.target.ownerDocument;
              activeDoc.querySelectorAll(".dropdown-menu.show").forEach((m) => {
                m.classList.remove("show");
                m.style.display = "";
              });
            }
          };
          document.addEventListener("click", window.handleManualDropdownClick, true);
    
          // Custom dropdown logic for comments & community posts to bypass Bootstrap conflicts
          document.addEventListener("click", (e) => {
            const toggle = e.target.closest(".custom-opt-toggle");
            if (toggle) {
              e.preventDefault();
              e.stopPropagation();
              const menu = toggle.nextElementSibling;
              const isVisible = menu.style.display === "block";
    
              // Hide all other custom menus
              document
                .querySelectorAll(".custom-opt-menu")
                .forEach((m) => (m.style.display = "none"));
    
              if (!isVisible) {
                menu.style.display = "block";
              }
              return;
            }
    
            // If clicking anywhere else or an item, hide the menus
            if (
              !e.target.closest(".custom-opt-menu") ||
              e.target.closest(".dropdown-item")
            ) {
              document
                .querySelectorAll(".custom-opt-menu")
                .forEach((m) => (m.style.display = "none"));
            }
          });
    
          // Back button logic bridging PiP and normal window
          document.addEventListener("click", (e) => {
            const backBtn = e.target.closest("#chat-back-btn");
            if (backBtn) {
              e.preventDefault();
              if (window.chatPipWindow) {
                window.chatPipWindow.close();
              } else {
                const main = document.querySelector(".chat-main");
                const sidebar = document.querySelector(".chat-sidebar");
                if (main) main.classList.remove("active");
                if (sidebar) sidebar.classList.remove("hidden");
                if (window.chatPollingInterval)
                  clearInterval(window.chatPollingInterval);
              }
            }
          });
    
          // Auto-hide drop menus on chat scroll so they don't float around disconnected
          document.addEventListener(
            "scroll",
            (e) => {
              if (
                e.target.classList &&
                e.target.classList.contains("chat-messages")
              ) {
                const activeDoc = e.target.ownerDocument;
                activeDoc.querySelectorAll(".dropdown-menu.show").forEach((m) => {
                  m.classList.remove("show");
                  m.style.display = "none";
                });
              }
            },
            true,
          );
    
          window.toggleMsgReaction = async (msgId, emoji) => {
            window.isReacting = true; // Lock background polling
            window.currentChatFetchId++; // Invalidate any currently running background polls
    
            // Optimistic UI Update: Apply visually before network confirms
            const doc = window.chatPipWindow
              ? window.chatPipWindow.document
              : document;
            const msgBubble = doc.querySelector(`.msg-anchor-${msgId}`);
            if (msgBubble) {
              let container = msgBubble.querySelector(".reactions-container");
              if (!container) {
                container = document.createElement("div");
                container.className = "reactions-container";
                msgBubble.appendChild(container);
              }
    
              let foundPill = false;
              container.querySelectorAll(".reaction-pill").forEach((pill) => {
                const pillEmoji = pill.textContent.replace(/[0-9]/g, "").trim(); // Safely extract emoji
    
                if (pillEmoji === emoji) {
                  foundPill = true;
                  const countEl = pill.querySelector("small");
                  let count = parseInt(countEl.textContent) || 0;
                  if (pill.classList.contains("reacted")) {
                    pill.classList.remove("reacted");
                    count--;
                    if (count <= 0) pill.remove();
                    else countEl.textContent = count;
                  } else {
                    pill.classList.add("reacted");
                    count++;
                    countEl.textContent = count;
                  }
                } else if (pill.classList.contains("reacted")) {
                  pill.classList.remove("reacted");
                  const countEl = pill.querySelector("small");
                  let count = parseInt(countEl.textContent) || 0;
                  count--;
                  if (count <= 0) pill.remove();
                  else countEl.textContent = count;
                }
              });
    
              if (!foundPill) {
                container.insertAdjacentHTML(
                  "beforeend",
                  `<span class="reaction-pill reacted" onclick="window.toggleMsgReaction(${msgId}, '${emoji}')">${emoji} <small>1</small></span>`,
                );
              }
            }
    
            // Dispatch async mutation
            await fetchData("?action=toggle_message_reaction", {
              method: "POST",
              body: JSON.stringify({
                message_id: msgId,
                reaction: emoji,
              }),
            });
    
            window.isReacting = false; // Unlock polling
            window.refreshChatFull(true); // Force an immediate fresh sync from DB
          };
    
          window.copyChatMsg = (id) => {
            const contentEl = document.getElementById("msg-content-" + id);
            if (contentEl) {
              const text = contentEl.innerText || contentEl.textContent;
              if (navigator.clipboard && window.isSecureContext) {
                navigator.clipboard
                  .writeText(text)
                  .then(() => showToast("Message copied!", "success"));
              }
            }
          };
    
          // Advanced Edit Modal Logic with Undo/Redo Array
          let chatEditHistory = [];
          let chatEditIndex = -1;
          let chatEditTimeout = null;
    
          window.delChatMsg = (id) => {
            document.getElementById("delete-chat-msg-id").value = id;
            bootstrap.Modal.getOrCreateInstance(
              document.getElementById("delete-chat-msg-modal"),
            ).show();
          };
    
          const confirmDeleteChatBtn = document.getElementById(
            "confirm-delete-chat-btn",
          );
          if (confirmDeleteChatBtn) {
            confirmDeleteChatBtn.addEventListener("click", async () => {
              const id = document.getElementById("delete-chat-msg-id").value;
              const originalHtml = confirmDeleteChatBtn.innerHTML;
              confirmDeleteChatBtn.disabled = true;
              confirmDeleteChatBtn.innerHTML =
                '<span class="spinner-border spinner-border-sm"></span>';
    
              const res = await fetchData("?action=delete_message", {
                method: "POST",
                body: JSON.stringify({
                  id: id,
                }),
              });
    
              confirmDeleteChatBtn.disabled = false;
              confirmDeleteChatBtn.innerHTML = originalHtml;
              bootstrap.Modal.getInstance(
                document.getElementById("delete-chat-msg-modal"),
              ).hide();
    
              if (res && res.status === "success") {
                window.refreshChatFull(true);
                showToast("Message deleted", "success");
              }
            });
          }
    
          window.editChatMsg = (id, content) => {
            const decodedContent = decodeHTML(content);
            document.getElementById("edit-chat-msg-id").value = id;
            const inputEl = document.getElementById("edit-chat-msg-input");
            inputEl.value = decodedContent;
    
            // Reset History Array for Undo/Redo operations
            chatEditHistory = [decodedContent];
            chatEditIndex = 0;
    
            bootstrap.Modal.getOrCreateInstance(
              document.getElementById("edit-chat-msg-modal"),
            ).show();
          };
    
          const editChatInput = document.getElementById("edit-chat-msg-input");
          if (editChatInput) {
            editChatInput.addEventListener("input", (e) => {
              clearTimeout(chatEditTimeout);
              chatEditTimeout = setTimeout(() => {
                const val = e.target.value;
                if (chatEditHistory[chatEditIndex] !== val) {
                  chatEditHistory = chatEditHistory.slice(0, chatEditIndex + 1);
                  chatEditHistory.push(val);
                  if (chatEditHistory.length > 30)
                    chatEditHistory.shift(); // Cap history to 30 states
                  else chatEditIndex++;
                }
              }, 400);
            });
          }
    
          const chatEditUndoBtn = document.getElementById("chat-edit-undo-btn");
          if (chatEditUndoBtn) {
            chatEditUndoBtn.addEventListener("click", () => {
              if (chatEditIndex > 0) {
                chatEditIndex--;
                document.getElementById("edit-chat-msg-input").value =
                  chatEditHistory[chatEditIndex];
              }
            });
          }
    
          const chatEditRedoBtn = document.getElementById("chat-edit-redo-btn");
          if (chatEditRedoBtn) {
            chatEditRedoBtn.addEventListener("click", () => {
              if (chatEditIndex < chatEditHistory.length - 1) {
                chatEditIndex++;
                document.getElementById("edit-chat-msg-input").value =
                  chatEditHistory[chatEditIndex];
              }
            });
          }
    
          const editChatForm = document.getElementById("edit-chat-msg-form");
          if (editChatForm) {
            editChatForm.addEventListener("submit", async (e) => {
              e.preventDefault();
              const id = document.getElementById("edit-chat-msg-id").value;
              const newContent = document.getElementById("edit-chat-msg-input").value;
    
              if (newContent.trim() !== "") {
                const btn = editChatForm.querySelector('button[type="submit"]');
                const origHtml = btn.innerHTML;
                btn.disabled = true;
                btn.innerHTML =
                  '<span class="spinner-border spinner-border-sm"></span> Saving...';
    
                await fetchData("?action=edit_message", {
                  method: "POST",
                  body: JSON.stringify({
                    id: id,
                    content: newContent,
                  }),
                });
    
                btn.disabled = false;
                btn.innerHTML = origHtml;
                bootstrap.Modal.getInstance(
                  document.getElementById("edit-chat-msg-modal"),
                ).hide();
                window.refreshChatFull(true);
              }
            });
          }
    
          // Chat Media Preview logic
          window.handleChatImageSelection = (file, targetDoc = document) => {
            if (file) {
              if (file.size > 50 * 1024 * 1024) {
                showToast("File exceeds 50MB limit.", "error");
                return;
              }
              const doc =
                targetDoc ||
                (window.chatPipWindow ? window.chatPipWindow.document : document);
              const dataTransfer = new DataTransfer();
              dataTransfer.items.add(file);
              doc.getElementById("chat-image-input").files = dataTransfer.files;
    
              const previewBar = doc.getElementById("chat-img-preview-bar");
              const previewImg = doc.getElementById("chat-img-preview-src");
              const previewVid = doc.getElementById("chat-video-preview-src");
              const previewAud = doc.getElementById("chat-audio-preview-src");
    
              previewImg.classList.add("d-none");
              previewVid.classList.add("d-none");
              previewAud.classList.add("d-none");
    
              if (previewVid.src) URL.revokeObjectURL(previewVid.src);
              if (previewAud.src) URL.revokeObjectURL(previewAud.src);
    
              let fileType = file.type;
              if (!fileType) {
                const ext = file.name.split(".").pop().toLowerCase();
                if (["mp3", "wav", "ogg", "m4a"].includes(ext))
                  fileType = "audio/" + ext;
                else if (["mp4", "webm", "mov"].includes(ext))
                  fileType = "video/" + ext;
              }
    
              if (fileType.startsWith("image/")) {
                const reader = new FileReader();
                reader.onload = (ev) => {
                  previewImg.src = ev.target.result;
                  previewImg.classList.remove("d-none");
                  previewBar.classList.add("active");
                };
                reader.readAsDataURL(file);
              } else if (fileType.startsWith("video/")) {
                previewVid.src = URL.createObjectURL(file);
                previewVid.classList.remove("d-none");
                previewBar.classList.add("active");
              } else if (fileType.startsWith("audio/")) {
                previewAud.src = URL.createObjectURL(file);
                previewAud.classList.remove("d-none");
                previewBar.classList.add("active");
              } else {
                showToast("Format not supported.", "error");
                doc.getElementById("chat-image-input").value = "";
              }
            }
          };
    
          window.handleChatChangeGlob = (e) => {
            if (e.target.id === "chat-image-input") {
              window.handleChatImageSelection(
                e.target.files[0],
                e.target.ownerDocument,
              );
            }
          };
          document.addEventListener("change", window.handleChatChangeGlob);
    
          // Drag and Drop Images into Chat
          const chatMainArea = document.querySelector(".chat-main");
          if (chatMainArea) {
            chatMainArea.addEventListener("dragover", (e) => {
              e.preventDefault();
              e.stopPropagation();
              chatMainArea.style.opacity = "0.7";
            });
            chatMainArea.addEventListener("dragleave", (e) => {
              e.preventDefault();
              e.stopPropagation();
              chatMainArea.style.opacity = "1";
            });
            chatMainArea.addEventListener("drop", (e) => {
              e.preventDefault();
              e.stopPropagation();
              chatMainArea.style.opacity = "1";
              if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
                handleChatImageSelection(
                  e.dataTransfer.files[0],
                  e.target.ownerDocument,
                );
              }
            });
          }
    
          window.clearChatImage = (targetDoc) => {
            const doc =
              targetDoc ||
              (window.chatPipWindow ? window.chatPipWindow.document : document);
            doc.getElementById("chat-image-input").value = "";
            doc.getElementById("chat-img-preview-bar").classList.remove("active");
            doc.getElementById("chat-img-preview-src").classList.add("d-none");
            const vid = doc.getElementById("chat-video-preview-src");
            const aud = doc.getElementById("chat-audio-preview-src");
            vid.classList.add("d-none");
            aud.classList.add("d-none");
            vid.pause();
            aud.pause();
            if (vid.src) URL.revokeObjectURL(vid.src);
            if (aud.src) URL.revokeObjectURL(aud.src);
          };
    
          window.clearChatReply = (targetDoc) => {
            const doc =
              targetDoc ||
              (window.chatPipWindow ? window.chatPipWindow.document : document);
            doc.getElementById("chat-reply-id").value = "";
            doc.getElementById("chat-reply-bar").classList.remove("active");
          };
    
          window.handleChatInputGlob = (e) => {
            if (e.target.id === "chat-input") {
              e.target.style.height = "22px";
              if (e.target.scrollHeight > 26) {
                e.target.style.height = e.target.scrollHeight + "px";
              }
            }
          };
          document.addEventListener("input", window.handleChatInputGlob);
    
          window.handleChatKeydownGlob = (e) => {
            if (e.target.id === "chat-input" && e.key === "Enter" && !e.shiftKey) {
              e.preventDefault();
              const form = e.target.ownerDocument.getElementById("chat-form-full");
              if (form)
                form.dispatchEvent(
                  new Event("submit", {
                    cancelable: true,
                    bubbles: true,
                  }),
                );
            }
          };
          document.addEventListener("keydown", window.handleChatKeydownGlob);
    
          // Group Chat Management
          window.showGroupInfo = async (id, page = 1) => {
            const res = await fetchData(
              `?action=get_group_info&id=${id}&page=${page}`,
            );
            if (res && res.status === "success") {
              const g = res.group;
              if (page === 1) {
                document.getElementById("group-info-name").textContent = g.name;
                document.getElementById("group-info-desc").textContent =
                  g.description || "No description provided.";
                document.getElementById("group-info-count").textContent =
                  g.total_members || g.members.length;
              }
    
              // Set the group profile picture
              const groupImgContainer = document.getElementById(
                "group-info-img-container",
              );
              if (groupImgContainer) {
                groupImgContainer.innerHTML = `<img src="?action=get_group_image&id=${g.id}&t=${Date.now()}" onerror="this.outerHTML='<i class=\\'bi bi-people-fill text-secondary\\' style=\\'font-size: 3rem;\\'></i>'" style="width: 100%; height: 100%; object-fit: cover;">`;
              }
    
              const isOwner =
                g.owner_id == currentUser.id ||
                (currentUser && currentUser.status === "super_admin");
              const controls = document.getElementById("group-owner-controls");
              if (isOwner) {
                controls.classList.remove("d-none");
                document.getElementById("group-btn-edit").onclick = async () => {
                  document.getElementById("group-manage-title").innerHTML =
                    '<i class="bi bi-pencil-square text-warning me-2"></i>Edit Group';
                  document.getElementById("group-manage-id").value = g.id;
                  document.getElementById("group-manage-name").value = g.name;
                  document.getElementById("group-manage-desc").value =
                    g.description || "";
    
                  const previewImg = document.getElementById(
                    "group-manage-image-preview",
                  );
                  previewImg.src = `?action=get_group_image&id=${g.id}&t=${Date.now()}`;
                  previewImg.style.display = "block";
                  if (groupCropper) {
                    groupCropper.destroy();
                    groupCropper = null;
                  }
                  if (document.getElementById("group-manage-image"))
                    document.getElementById("group-manage-image").value = "";
    
                  document.getElementById("group-manage-submit").textContent =
                    "Save Changes";
                  document.getElementById("group-manage-submit").className =
                    "btn btn-warning text-dark fw-bold w-100";
                  bootstrap.Modal.getOrCreateInstance(
                    document.getElementById("group-info-modal"),
                  ).hide();
                  bootstrap.Modal.getOrCreateInstance(
                    document.getElementById("group-manage-modal"),
                  ).show();
                };
                document.getElementById("group-btn-delete").onclick = async () => {
                  if (confirm("Permanently delete this group?")) {
                    await fetchData("?action=delete_chat_group", {
                      method: "POST",
                      body: JSON.stringify({
                        id: g.id,
                      }),
                    });
                    bootstrap.Modal.getInstance(
                      document.getElementById("group-info-modal"),
                    ).hide();
                    loadView(currentView);
                  }
                };
                document.getElementById("group-btn-invite").onclick = async () => {
                  const exp = document.getElementById("group-invite-expire").value;
                  const iRes = await fetchData("?action=generate_group_invite", {
                    method: "POST",
                    body: JSON.stringify({
                      id: g.id,
                      expire: exp === "forever" ? null : exp,
                    }),
                  });
                  if (iRes && iRes.status === "success") {
                    const link =
                      window.location.origin +
                      window.location.pathname +
                      "?chat_invite=" +
                      iRes.token;
                    navigator.clipboard.writeText(link);
                    showToast("Invite link copied!", "success");
                  }
                };
              } else {
                controls.classList.add("d-none");
              }
    
              const membersHtml = g.members
                .map(
                  (m) => `
                      <div class="list-group-item bg-transparent text-white px-0 d-flex justify-content-between align-items-center border-secondary">
                         <div class="d-flex align-items-center gap-3 user-profile-link" data-userid="${m.id}" data-artist="${encodeURIComponent(m.artist)}" style="cursor: pointer;">
                           <img src="?action=get_profile_picture&id=${m.id}" class="rounded-circle" style="width:32px; height:32px; object-fit:cover;">
                           <div>
                             <div class="fw-bold fs-6 hover-underline">${escapeHTML(m.artist)}</div>
                             <small class="text-secondary" style="font-size:0.75rem;">ID: ${m.id}</small>
                           </div>
                         </div>
                         <div class="d-flex align-items-center gap-2">
                           ${isOwner && m.role !== "owner" ? `<button class="btn btn-sm btn-outline-warning fw-bold transfer-owner-btn" data-userid="${m.id}">Make Owner</button>` : ""}
                           ${m.role === "owner" ? '<span class="badge bg-warning text-dark"><i class="bi bi-star-fill"></i> Owner</span>' : ""}
                         </div>
                      </div>
                    `,
                )
                .join("");
    
              const container = document.getElementById("group-info-members");
              if (page === 1) {
                container.innerHTML = membersHtml;
              } else {
                container.insertAdjacentHTML("beforeend", membersHtml);
              }
    
              container.onclick = async (e) => {
                const transferBtn = e.target.closest(".transfer-owner-btn");
                if (transferBtn) {
                  const newOwnerId = transferBtn.dataset.userid;
                  if (
                    confirm(
                      "Transfer ownership to this member? You will become a regular member.",
                    )
                  ) {
                    const res = await fetchData("?action=transfer_group_ownership", {
                      method: "POST",
                      body: JSON.stringify({
                        group_id: g.id,
                        new_owner_id: newOwnerId,
                      }),
                    });
                    if (res && res.status === "success") {
                      showToast(res.message, "success");
                      window.showGroupInfo(g.id, 1);
                    } else {
                      showToast(
                        res?.message || "Error transferring ownership",
                        "error",
                      );
                    }
                  }
                }
              };
    
              const existingLoadMore = document.getElementById("group-load-more-btn");
              if (existingLoadMore) existingLoadMore.remove();
    
              if (g.members.length === 25) {
                container.insertAdjacentHTML(
                  "afterend",
                  `
                        <button class="btn btn-outline-light btn-sm w-100 mt-2 mb-3 fw-bold" id="group-load-more-btn" onclick="window.showGroupInfo(${id}, ${page + 1})">
                          Load More Members
                        </button>
                      `,
                );
              }
    
              document.getElementById("group-btn-leave").onclick = async () => {
                const confirmMsg = isOwner
                  ? "As the owner, if you leave, ownership will be given to a random member. Leave group?"
                  : "Leave this group?";
                if (confirm(confirmMsg)) {
                  await fetchData("?action=leave_chat_group", {
                    method: "POST",
                    body: JSON.stringify({
                      id: g.id,
                    }),
                  });
                  bootstrap.Modal.getInstance(
                    document.getElementById("group-info-modal"),
                  ).hide();
                  loadView({
                    type: "get_inbox",
                    param: "",
                    sort: "",
                    filter_user_id: "",
                  });
                }
              };
              bootstrap.Modal.getOrCreateInstance(
                document.getElementById("group-info-modal"),
              ).show();
            }
          };
    
          document.addEventListener("submit", async (e) => {
            if (e.target.id === "group-manage-form") {
              e.preventDefault();
              const submitBtn = document.getElementById("group-manage-submit");
              submitBtn.disabled = true;
              submitBtn.innerHTML =
                '<span class="spinner-border spinner-border-sm"></span> Saving...';
    
              const id = document.getElementById("group-manage-id").value;
              const name = document.getElementById("group-manage-name").value;
              const desc = document.getElementById("group-manage-desc").value;
              const imgInput = document.getElementById("group-manage-image");
    
              const formData = new FormData();
              formData.append("name", name);
              formData.append("description", desc);
              if (id) formData.append("id", id);
    
              const processUpload = async () => {
                try {
                  const res = await fetch(
                    `?action=${id ? "edit_chat_group" : "create_chat_group"}`,
                    {
                      method: "POST",
                      body: formData,
                    },
                  );
                  const result = await res.json();
    
                  if (result && result.status === "success") {
                    showToast(id ? "Group updated" : "Group created", "success");
                    bootstrap.Modal.getInstance(
                      document.getElementById("group-manage-modal"),
                    ).hide();
                    loadView(currentView);
                  } else {
                    showToast(result.message || "Action failed", "error");
                  }
                } catch (err) {
                  showToast("Network error", "error");
                }
                submitBtn.disabled = false;
                submitBtn.textContent = id ? "Save Changes" : "Create Group";
              };
    
              if (groupCropper) {
                groupCropper
                  .getCroppedCanvas({
                    width: 300,
                    height: 300,
                  })
                  .toBlob(
                    (blob) => {
                      formData.append("image", blob, "group.jpg");
                      processUpload();
                    },
                    "image/jpeg",
                    0.85,
                  );
              } else if (imgInput && imgInput.files.length > 0) {
                formData.append("image", imgInput.files[0]);
                processUpload();
              } else {
                processUpload();
              }
            }
          });
    
          window.handleChatSubmitGlob = async (e) => {
            if (e.target.id === "chat-form-full") {
              e.preventDefault();
              const doc = e.target.ownerDocument;
              const input = doc.getElementById("chat-input");
              const imgInput = doc.getElementById("chat-image-input");
              const replyId = doc.getElementById("chat-reply-id").value;

              if (!activeChatConfig || !activeChatConfig.id || !activeChatConfig.type) {
                showToast("Please select a chat conversation first.", "error");
                return;
              }

              if (!input.value.trim() && imgInput.files.length === 0) return;
    
              const formData = new FormData();
              formData.append("target_id", activeChatConfig.id);
              formData.append("chat_type", activeChatConfig.type);
              formData.append("content", input.value);
              if (replyId) formData.append("reply_to_id", replyId);
              if (imgInput.files.length > 0)
                formData.append("image", imgInput.files[0]);
    
              const submitBtn = doc.getElementById("chat-submit-btn");
              const originalBtnHtml = submitBtn.innerHTML;
              submitBtn.disabled = true;
              submitBtn.innerHTML =
                '<span class="spinner-border spinner-border-sm" style="width: 1.2rem; height: 1.2rem;"></span>';
    
              const progContainer = doc.getElementById(
                "chat-upload-progress-container",
              );
              const progBar = doc.getElementById("chat-upload-progress");
              if (imgInput.files.length > 0) {
                progContainer.classList.remove("d-none");
                progBar.style.width = "0%";
              }
    
              const xhr = new XMLHttpRequest();
              xhr.upload.onprogress = (evt) => {
                if (evt.lengthComputable && imgInput.files.length > 0) {
                  const pct = Math.round((evt.loaded / evt.total) * 100);
                  progBar.style.width = pct + "%";
                }
              };
    
              xhr.open("POST", "?action=send_message", true);
              xhr.onload = async () => {
                submitBtn.disabled = false;
                submitBtn.innerHTML = originalBtnHtml;
                progContainer.classList.add("d-none");
    
                if (xhr.status === 200) {
                  try {
                    const result = JSON.parse(xhr.responseText);
                    if (result && result.status === "success") {
                      requestCache.clear();
                      input.value = "";
                      input.style.height = "22px"; // Reset textarea height
                      window.clearChatImage(doc);
                      window.clearChatReply(doc);
                      window.forceScrollToBottomNext = true;
                      await window.refreshChatFull(true);
                    } else {
                      showToast(result.message || "Failed to send", "error");
                    }
                  } catch (err) {
                    showToast("Invalid server response.", "error");
                  }
                } else {
                  showToast("Network error during upload", "error");
                }
              };
              xhr.onerror = () => {
                submitBtn.disabled = false;
                submitBtn.innerHTML = originalBtnHtml;
                progContainer.classList.add("d-none");
                showToast("Network error during upload", "error");
              };
              xhr.send(formData);
            }
          };
          document.addEventListener("submit", async (e) => {
            if (e.target.id === "chat-form-full") {
              await window.handleChatSubmitGlob(e);
            }
          });
    
          window.chatPipWindow = null;
          document.addEventListener("click", async (e) => {
            const pipBtn = e.target.closest("#chat-pip-btn");
            if (pipBtn) {
              if (window.chatPipWindow) {
                window.chatPipWindow.close();
                return;
              }
              if (!("documentPictureInPicture" in window)) return;
    
              try {
                window.chatPipWindow =
                  await window.documentPictureInPicture.requestWindow({
                    width: 450,
                    height: 700,
                  });
    
                [...document.styleSheets].forEach((styleSheet) => {
                  try {
                    const cssRules = [...styleSheet.cssRules]
                      .map((rule) => rule.cssText)
                      .join("");
                    const style = document.createElement("style");
                    style.textContent = cssRules;
                    window.chatPipWindow.document.head.appendChild(style);
                  } catch (err) {
                    if (styleSheet.href) {
                      const link = document.createElement("link");
                      link.rel = "stylesheet";
                      link.href = styleSheet.href;
                      window.chatPipWindow.document.head.appendChild(link);
                    }
                  }
                });
    
                const iconLink = document.createElement("link");
                iconLink.rel = "stylesheet";
                iconLink.href =
                  "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css";
                window.chatPipWindow.document.head.appendChild(iconLink);
    
                const chatMain = document.querySelector(".chat-main");
                const chatWrapper = document.querySelector(".chat-wrapper");
    
                window.chatPipWindow.document.body.style.background = "var(--ytm-bg)";
                window.chatPipWindow.document.body.style.margin = "0";
                window.chatPipWindow.document.body.classList.add("pip-active");
                window.chatPipWindow.document.body.appendChild(chatMain);
    
                // Directly hide the PiP trigger button in the PiP window's document
                const pipBtnInPip =
                  window.chatPipWindow.document.getElementById("chat-pip-btn");
                if (pipBtnInPip) {
                  pipBtnInPip.style.setProperty("display", "none", "important");
                }
                const backBtnInPip =
                  window.chatPipWindow.document.getElementById("chat-back-btn");
                if (backBtnInPip) {
                  backBtnInPip.style.setProperty("display", "none", "important");
                }
                const formatHelpInPip = window.chatPipWindow.document.querySelector(
                  ".chat-formatting-help",
                );
                if (formatHelpInPip) {
                  formatHelpInPip.style.setProperty("display", "none", "important");
                }
    
                // Force downward scroll on initialization
                setTimeout(() => {
                  const listEl = window.chatPipWindow.document.getElementById(
                    "chat-messages-container",
                  );
                  if (listEl) listEl.scrollTop = listEl.scrollHeight + 10000;
                }, 100);
    
                window.chatPipWindow.document.addEventListener(
                  "input",
                  window.handleChatInputGlob,
                );
                window.chatPipWindow.document.addEventListener(
                  "change",
                  window.handleChatChangeGlob,
                );
                window.chatPipWindow.document.addEventListener(
                  "keydown",
                  window.handleChatKeydownGlob,
                );
                window.chatPipWindow.document.addEventListener(
                  "submit",
                  window.handleChatSubmitGlob,
                );
                window.chatPipWindow.document.addEventListener(
                  "click",
                  window.handleManualDropdownClick,
                );
    
                window.chatPipWindow.addEventListener("pagehide", () => {
                  if (chatWrapper && chatMain) chatWrapper.appendChild(chatMain);
    
                  // CRITICAL FIX: Restore PiP button visibility in main document!
                  const mainPipBtn = document.getElementById("chat-pip-btn");
                  if (mainPipBtn) mainPipBtn.style.removeProperty("display");
    
                  const mainBackBtn = document.getElementById("chat-back-btn");
                  if (mainBackBtn) mainBackBtn.style.removeProperty("display");
    
                  const mainFormatHelp = document.querySelector(
                    ".chat-formatting-help",
                  );
                  if (mainFormatHelp) mainFormatHelp.style.removeProperty("display");
    
                  window.chatPipWindow = null;
                });
              } catch (err) {
                console.error(err);
                showToast("Failed to open Chat PiP", "error");
              }
              return;
            }
          });
    
          // --- END FULL PAGE CHAT APP LOGIC ---
          const clearBtn = document.getElementById("clear-activity-btn");
          if (clearBtn) {
            clearBtn.addEventListener("click", async () => {
              if (confirm("Are you sure you want to clear all your notifications?")) {
                const res = await fetchData("?action=clear_activity_feed", {
                  method: "POST",
                });
                if (res && res.status === "success") {
                  showToast("Notifications cleared.", "success");
                  loadActivityFeed();
                  updateNotifBadge();
                }
              }
            });
          }
    
          body.addEventListener("click", async (e) => {
            const openChatBtn = e.target.closest(".open-chat-btn");
            if (openChatBtn) {
              bootstrap.Modal.getInstance(activityModalEl).hide();
              await loadView({
                type: "get_inbox",
                param: "",
                sort: "",
                filter_user_id: "",
              });
              window.openChatFull(
                openChatBtn.dataset.userid,
                "dm",
                openChatBtn.dataset.artist,
              );
              return;
            }
            const replyBtn = e.target.closest(".notif-reply-btn");
            if (replyBtn) {
              const songId = parseInt(replyBtn.dataset.songId);
              const commentId = parseInt(replyBtn.dataset.commentId);
              const username = replyBtn.dataset.username;
    
              bootstrap.Modal.getInstance(activityModalEl).hide();
              window.openCommentsModal(songId, commentId, username);
              return;
            }
            const commReplyBtn = e.target.closest(".notif-comm-reply-btn");
            if (commReplyBtn) {
              bootstrap.Modal.getInstance(activityModalEl).hide();
              loadView({
                type: "get_community",
                param: "",
                sort: "newest",
                filter_user_id: "",
                artist_name: "",
              });
              setTimeout(() => {
                const input = document.getElementById("reply-community-post-input");
                const parentId = document.getElementById(
                  "reply-community-post-parent-id",
                );
                if (input && parentId) {
                  parentId.value = commReplyBtn.dataset.postId;
                  const username = commReplyBtn.dataset.username.replace(/\s+/g, "");
                  input.value = `@${username} `;
                  const preview = document.getElementById(
                    "reply-community-post-preview",
                  );
                  if (preview) {
                    preview.innerHTML = `<strong class="text-white">Replying to ${escapeHTML(commReplyBtn.dataset.username)}</strong>`;
                  }
                  bootstrap.Modal.getOrCreateInstance(
                    document.getElementById("reply-community-post-modal"),
                  ).show();
                  setTimeout(() => input.focus(), 500);
                }
              }, 800);
            }
          });
        }
    
        // API Modal logic
        const apiUrlInput = document.getElementById("api-url-input");
        const copyApiBtn = document.getElementById("copy-api-btn");
        const apiModalEl = document.getElementById("api-modal");
        const apiActionSelect = document.getElementById("api-action-select");
        const apiMethodBadge = document.getElementById("api-method-badge");
        const apiPayloadContainer = document.getElementById("api-payload-container");
        const apiPayloadCode = document.getElementById("api-payload-code");
    
        const updateApiUrl = () => {
          if (!apiUrlInput || !apiActionSelect) return;
          const selectedOption =
            apiActionSelect.options[apiActionSelect.selectedIndex];
          const actionVal = selectedOption.value;
    
          const userKeyInput = document.getElementById("custom-api-key-input");
          const finalKey =
            userKeyInput && userKeyInput.value ? userKeyInput.value.trim() : "";
    
          let baseAppUrl = window.location.href.split("?")[0].split("#")[0];
          if (
            baseAppUrl.includes("null") ||
            baseAppUrl.includes("srcdoc") ||
            baseAppUrl === "about:blank"
          ) {
            baseAppUrl = "";
          }
          baseAppUrl = baseAppUrl.replace(/\/+$/, ""); // Strip trailing slashes to prevent double slash bug
    
          let url = baseAppUrl + "/?access=api&action=" + actionVal;
          if (finalKey) url += "&api_key=" + encodeURIComponent(finalKey);
          apiUrlInput.value = url;
    
          const apiVisualOpenTabBtn = document.getElementById(
            "api-visual-open-tab-btn",
          );
          if (apiVisualOpenTabBtn) {
            let sourceType = "all";
            let idName = "";
            if (actionVal.includes("playlist")) {
              sourceType = "playlist";
              idName = "1";
            } else if (actionVal.includes("artist")) {
              sourceType = "artist";
              idName = "1";
            }
            let absoluteBaseUrl =
              window.location.protocol +
              "//" +
              window.location.host +
              window.location.pathname;
            if (
              absoluteBaseUrl.includes("null") ||
              absoluteBaseUrl.includes("srcdoc")
            ) {
              absoluteBaseUrl = "";
            }
            absoluteBaseUrl = absoluteBaseUrl.replace(/\/+$/, ""); // Clean absolute URL for Playground injection
    
            apiVisualOpenTabBtn.dataset.sourceType = sourceType;
            apiVisualOpenTabBtn.dataset.idName = idName;
            apiVisualOpenTabBtn.dataset.backendUrl = absoluteBaseUrl;
            apiVisualOpenTabBtn.dataset.apiKey = finalKey;
          }
    
          const method = selectedOption.getAttribute("data-method") || "GET";
          if (apiMethodBadge) {
            apiMethodBadge.textContent = method;
            apiMethodBadge.className =
              method === "POST" ? "badge bg-warning text-dark" : "badge bg-primary";
          }
    
          const payload = selectedOption.getAttribute("data-body");
          if (payload && apiPayloadContainer && apiPayloadCode) {
            apiPayloadCode.textContent = payload;
            apiPayloadContainer.classList.remove("d-none");
          } else if (apiPayloadContainer) {
            apiPayloadContainer.classList.add("d-none");
          }
    
          // VISUAL CLIENT TESTER INJECTION (Iframe 2)
          const visualIframe = document.getElementById("api-visual-iframe");
          const templateEl = document.getElementById("play-client-template");
    
          if (visualIframe && templateEl) {
            // Unconditionally render playground client UI, letting it gracefully query using session cookie
            if (
              !visualIframe.srcdoc ||
              visualIframe.srcdoc.includes("Access Denied")
            ) {
              visualIframe.srcdoc = templateEl.innerHTML;
            }
    
            let sourceType = "all";
            let idName = "";
            if (actionVal.includes("playlist")) {
              sourceType = "playlist";
              idName = "1";
            } else if (actionVal.includes("artist")) {
              sourceType = "artist";
              idName = "1";
            }
            const safeApiKey = finalKey ? encodeURIComponent(finalKey) : "";
            const hash = `#sourcetype=${sourceType}&id/name=${idName}&backendurl=${encodeURIComponent(baseAppUrl)}&apikey=${safeApiKey}`;
    
            if (
              visualIframe.contentWindow &&
              visualIframe.contentWindow.location &&
              visualIframe.contentWindow.document.readyState === "complete"
            ) {
              visualIframe.contentWindow.location.hash = hash;
            } else {
              visualIframe.onload = () => {
                visualIframe.contentWindow.location.hash = hash;
              };
            }
          }
    
          // RAW JSON VIEWER LOGIC (Iframe 1)
          const apiExampleIframe = document.getElementById("api-example-iframe");
          if (apiExampleIframe) {
            apiExampleIframe.srcdoc = `<html><body style="background-color: #000000; color: #aaaaaa; font-family: monospace; font-size: 13px; margin: 0; padding: 12px;">Querying database for real data...</body></html>`;
    
            const injectIframe = (dataObj, color) => {
              const jsonString = JSON.stringify(dataObj, null, 2);
              apiExampleIframe.srcdoc = `<html><body style="background-color: #000000; color: ${color}; font-family: monospace; font-size: 13px; margin: 0; padding: 12px; white-space: pre-wrap; word-wrap: break-word;">${jsonString}</body></html>`;
            };
    
            const fallbackToFakeData = () => {
              const randomData = {
                status: "success",
                action_requested: actionVal,
                method: method,
                results: [
                  {
                    id: Math.floor(Math.random() * 9000) + 1000,
                    title: "Example Track " + Math.floor(Math.random() * 100),
                    artist: "Random Artist " + Math.floor(Math.random() * 50),
                    album: "Awesome Album Vol " + Math.floor(Math.random() * 10),
                    duration: Math.floor(Math.random() * 200) + 120,
                    is_favorite: Math.random() > 0.5 ? 1 : 0,
                  },
                ],
              };
              injectIframe(randomData, "#4ade80"); // Green text means FAKE data
            };
    
            if (method === "GET") {
              let testUrl = apiUrlInput.value;
    
              // ADVANCED: Safely request an actual database entity to populate variables so you don't query empty/invalid IDs
              const fetchRealExample = async () => {
                try {
                  if (
                    testUrl.includes("SONG_ID") ||
                    testUrl.includes("USER_ID") ||
                    testUrl.includes("PLAYLIST_ID")
                  ) {
                    const realSongs = await fetch(
                      "?access=api&action=get_songs&limit=1&api_key=" +
                        encodeURIComponent(finalKey),
                    ).then((r) => r.json());
                    const realPlaylists = await fetch(
                      "?access=api&action=get_user_playlists&api_key=" +
                        encodeURIComponent(finalKey),
                    ).then((r) => r.json());
    
                    const sId =
                      realSongs && realSongs.length > 0 ? realSongs[0].id : "1";
                    const uId =
                      realSongs && realSongs.length > 0 ? realSongs[0].user_id : "1";
                    const pId =
                      realPlaylists && realPlaylists.length > 0
                        ? realPlaylists[0].public_id
                        : "1";
    
                    testUrl = testUrl
                      .replace("SONG_ID", sId)
                      .replace("USER_ID", uId)
                      .replace("PLAYLIST_ID", pId)
                      .replace("YOUR_QUERY", "a");
                  }
    
                  const res = await fetch(testUrl);
                  const data = await res.json();
    
                  if (
                    !data ||
                    data.status === "error" ||
                    (Array.isArray(data) && data.length === 0)
                  ) {
                    fallbackToFakeData();
                  } else {
                    let displayData = Array.isArray(data) ? data.slice(0, 3) : data;
                    injectIframe(displayData, "#60a5fa"); // Blue text means REAL database data
                  }
                } catch (e) {
                  fallbackToFakeData();
                }
              };
    
              fetchRealExample();
            } else {
              fallbackToFakeData();
            }
          }
        };
    
