            .forEach((el) => {
              if (!openReplies.includes(el.id)) openReplies.push(el.id);
            });
    
          const container = document.getElementById(containerId);
          if (container) container.innerHTML = htmlString;
    
          openReplies.forEach((id) => {
            const el = document.getElementById(id);
            if (el) {
              el.classList.remove("d-none");
              const btn = document.querySelector(`[data-target="${id}"]`);
              if (btn) {
                btn.innerHTML = `<div class="d-flex align-items-center justify-content-center bg-info text-dark rounded-circle shadow-sm" style="width: 24px; height: 24px;"><i class="bi bi-chevron-up" style="font-size: 0.85rem;"></i></div> Hide replies`;
              }
            }
          });
        };
    
        const formatTime = (seconds) => {
          if (isNaN(seconds) || seconds < 0) return "0:00";
          const min = Math.floor(seconds / 60);
          const sec = Math.floor(seconds % 60)
            .toString()
            .padStart(2, "0");
          return `${min}:${sec}`;
        };
    
        const formatSongCount = (count) => {
          let num = parseInt(count, 10);
          if (isNaN(num)) return "0";
          if (num >= 1000000000000) {
            return (num / 1000000000000).toFixed(1).replace(/\.0$/, "") + "t";
          }
          if (num >= 1000000000) {
            return (num / 1000000000).toFixed(1).replace(/\.0$/, "") + "b";
          }
          if (num >= 1000000) {
            return (num / 1000000).toFixed(1).replace(/\.0$/, "") + "m";
          }
          if (num >= 1000) {
            return (num / 1000).toFixed(1).replace(/\.0$/, "") + "k";
          }
          return num.toString();
        };
    
        const parseLRC = (lrc) => {
          if (!lrc) return [];
          const lines = lrc.split("\n");
          const parsed = [];
          const timeReg = /\[\d{2,}:\d{2}(?:\.\d{1,3})?\]/g;
          for (let line of lines) {
            const times = line.match(timeReg);
            if (times) {
              const text = line.replace(timeReg, "").trim();
              times.forEach((t) => {
                const min = parseInt(t.slice(1, 3));
                const sec = parseFloat(t.slice(4, -1));
                parsed.push({
                  time: min * 60 + sec,
                  text: text || "♪",
                });
              });
            }
          }
          return parsed.sort((a, b) => a.time - b.time);
        };
    
        const escapeHTML = (str) => {
          if (!str) return "";
          return str.replace(
            /[&<>'"]/g,
            (tag) =>
              ({
                "&": "&amp;",
                "<": "&lt;",
                ">": "&gt;",
                "'": "&#39;",
                '"': "&quot;",
              })[tag],
          );
        };
    
        window.openMediaPreview = (url, type) => {
          const rootDoc = window.document;
          const body = rootDoc.getElementById("media-preview-body");
          if (!body) return;
    
          // Use 100vh to ensure it scales correctly inside the fullscreen modal bounds
          if (type && type.startsWith("video/")) {
            body.innerHTML = `<video src="${url}" controls autoplay style="max-width: 100%; max-height: 100vh; object-fit: contain;"></video>`;
          } else {
            body.innerHTML = `<img src="${url}" style="max-width: 100%; max-height: 100vh; object-fit: contain;">`;
          }
    
          const dlBtn = rootDoc.getElementById("media-preview-download-btn");
          if (dlBtn) {
            const newDlBtn = dlBtn.cloneNode(true);
            dlBtn.parentNode.replaceChild(newDlBtn, dlBtn);
            newDlBtn.addEventListener("click", async () => {
              try {
                // Blob URLs cross-origin can fail basic <a> download tags depending on browser restrictions
                const a = rootDoc.createElement("a");
                a.href = url;
                const ext = type.startsWith("video/") ? "mp4" : "png";
                a.download = `media_${Date.now()}.${ext}`;
                rootDoc.body.appendChild(a);
                a.click();
                rootDoc.body.removeChild(a);
              } catch (e) {
                // Safe fallback to just opening the raw blob
                window.open(url, "_blank");
              }
            });
          }
    
          bootstrap.Modal.getOrCreateInstance(
            rootDoc.getElementById("media-preview-modal"),
          ).show();
        };
    
        document
          .getElementById("media-preview-modal")
          ?.addEventListener("hidden.bs.modal", () => {
            document.getElementById("media-preview-body").innerHTML = "";
          });
    
        window.buildLazyMediaHtml = (url, type, thumbUrl, isExternal) => {
          let displayThumb = thumbUrl || url;
          if (isExternal && type.startsWith("video/")) {
            displayThumb =
              "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=";
          }
    
          let hash = 0;
          for (let i = 0; i < url.length; i++)
            hash = url.charCodeAt(i) + ((hash << 5) - hash);
          const h1 = Math.abs(hash % 360);
          const bgStyle = `background: hsl(${h1}, 20%, 30%);`;
    
          const isVideo = type.startsWith("video/");
          const isAudio = type.startsWith("audio/");
          const videoIcon = isVideo
            ? `<div class="lazy-video-icon"><i class="bi bi-camera-video-fill"></i></div>`
            : "";
    
          const mediaId = "media_" + Math.random().toString(36).substr(2, 9);
          let btnText = "View Image";
          let btnIcon = "bi-image";
          if (isVideo) {
            btnText = "View Video";
            btnIcon = "bi-camera-video";
          }
          if (isAudio) {
            btnText = "Listen Audio";
            btnIcon = "bi-music-note";
          }
    
          return `
                  <div class="mt-2 mb-2 w-100">
                    <button type="button" class="btn btn-sm btn-outline-secondary fw-bold mb-2" onclick="const wrapper = document.getElementById('${mediaId}'); wrapper.classList.toggle('d-none'); this.innerHTML = wrapper.classList.contains('d-none') ? '<i class=\\'bi ${btnIcon}\\'></i> ${btnText}' : '<i class=\\'bi bi-chevron-up\\'></i> Hide Media'; event.stopPropagation();">
                      <i class="bi ${btnIcon}"></i> ${btnText}
                    </button>
                    <div id="${mediaId}" class="lazy-media-wrapper shadow-sm w-100 d-none" data-media-src="${url}" data-media-type="${type}" style="${bgStyle} max-width: 400px; min-height: 150px; display: block;">
                      ${videoIcon}
                      <img src="${displayThumb}" class="lazy-blur" alt="Media" loading="lazy" style="width: 100%; height: auto; min-height: 150px; max-height: 400px; object-fit: contain; display: block; margin: 0 auto;">
                      <div class="lazy-overlay" onclick="window.downloadLazyMedia(this); event.stopPropagation();">
                         <i class="bi bi-download lazy-download-icon"></i>
                         <div class="spinner-border text-light d-none lazy-download-spinner" style="width: 1.5rem; height: 1.5rem; border-width: 0.2em;"></div>
                         <span class="lazy-download-text">Download</span>
                      </div>
                    </div>
                  </div>`;
        };
    
        const getOpfsMediaDir = async () => {
          const root = await navigator.storage.getDirectory();
          return await root.getDirectoryHandle("chat_media_cache", {
            create: true,
          });
        };
    
        window.downloadLazyMedia = async (overlayEl) => {
          const wrapper = overlayEl.closest(".lazy-media-wrapper");
          if (wrapper.dataset.loading === "true") return;
          wrapper.dataset.loading = "true";
    
          const url = wrapper.dataset.mediaSrc;
          const type = wrapper.dataset.mediaType;
    
          const icon = overlayEl.querySelector(".lazy-download-icon");
          const text = overlayEl.querySelector(".lazy-download-text");
          const spinner = overlayEl.querySelector(".lazy-download-spinner");
    
          if (icon) icon.classList.add("d-none");
          if (text) text.classList.add("d-none");
          if (spinner) spinner.classList.remove("d-none");
    
          try {
            let blobUrl;
            try {
              if (!navigator.storage || !navigator.storage.getDirectory)
                throw new Error("No OPFS Support");
    
              const mediaDir = await getOpfsMediaDir();
              const fileName =
                (url.split("/").pop().split("?")[0] || "media_unknown") +
                "_" +
                (url.split("id=")[1] || Date.now());
    
              try {
                // Try to grab it from OPFS first
                const fileHandle = await mediaDir.getFileHandle(fileName);
                const file = await fileHandle.getFile();
                blobUrl = URL.createObjectURL(file);
              } catch (e) {
                // File doesn't exist in OPFS, fetch it over network
                const res = await fetch(url);
                if (!res.ok) throw new Error("Network download failed");
                const blob = await res.blob();
    
                // Save raw blob heavily into OPFS
                const fileHandle = await mediaDir.getFileHandle(fileName, {
                  create: true,
                });
                const writable = await fileHandle.createWritable();
                await writable.write(blob);
                await writable.close();
    
                blobUrl = URL.createObjectURL(blob);
              }
            } catch (opfsError) {
              // Fallback for browsers/Private Mode blocking OPFS: Directly download to RAM
              console.warn("OPFS caching bypassed, buffering to RAM.");
              const res = await fetch(url);
              if (!res.ok) throw new Error("Network download failed");
              const blob = await res.blob();
              blobUrl = URL.createObjectURL(blob);
            }
    
            if (type.startsWith("video/")) {
              wrapper.innerHTML = `<video src="${blobUrl}" controls class="w-100 h-100 rounded" style="max-height: 400px; display: block; object-fit: contain; cursor: pointer;" onclick="window.openMediaPreview('${blobUrl}', '${type}')"></video>`;
            } else {
              wrapper.innerHTML = `<img src="${blobUrl}" class="w-100 h-100 rounded" style="max-height: 400px; display: block; object-fit: contain; cursor: zoom-in;" onclick="window.openMediaPreview('${blobUrl}', '${type}')">`;
            }
            wrapper.classList.add("loaded");
            wrapper.style.background = "transparent";
          } catch (err) {
            console.error(err);
            if (icon) icon.classList.remove("d-none");
            if (text) {
              text.classList.remove("d-none");
              text.textContent = "Retry";
            }
            if (spinner) spinner.classList.add("d-none");
            wrapper.dataset.loading = "false";
          }
        };
    
        window.checkMediaCache = async () => {
          if (!navigator.storage || !navigator.storage.getDirectory) return;
          try {
            const mediaDir = await getOpfsMediaDir();
            const docs = [document];
            if (window.chatPipWindow) docs.push(window.chatPipWindow.document);
    
            for (let doc of docs) {
              const wrappers = doc.querySelectorAll(
                ".lazy-media-wrapper:not(.cache-checked)",
              );
              for (let wrapper of wrappers) {
                wrapper.classList.add("cache-checked");
                const url = wrapper.dataset.mediaSrc;
                const type = wrapper.dataset.mediaType || "image/webp";
                const fileName =
                  (url.split("/").pop().split("?")[0] || "media_unknown") +
                  "_" +
                  (url.split("id=")[1] || Date.now());
    
                try {
                  const fileHandle = await mediaDir.getFileHandle(fileName);
                  const file = await fileHandle.getFile();
                  const blobUrl = URL.createObjectURL(file);
    
                  if (type.startsWith("video/")) {
                    wrapper.innerHTML = `<video src="${blobUrl}" controls class="w-100 h-100 rounded" style="max-height: 400px; display: block; object-fit: contain; cursor: pointer;" onclick="window.openMediaPreview('${blobUrl}', '${type}')"></video>`;
                  } else {
                    wrapper.innerHTML = `<img src="${blobUrl}" class="w-100 h-100 rounded" style="max-height: 400px; display: block; object-fit: contain; cursor: zoom-in;" onclick="window.openMediaPreview('${blobUrl}', '${type}')">`;
                  }
                  wrapper.classList.add("loaded");
                  wrapper.style.background = "transparent";
                } catch (e) {
                  // Not cached in OPFS yet
                }
              }
            }
          } catch (e) {}
        };
    
        // Safely decodes HTML entities back into symbols (like I&#039;m -> I'm) before pasting them into Input fields.
        // Configure Mermaid & Marked with SVG Pan Zoom logic
        if (typeof mermaid !== "undefined") {
          mermaid.initialize({ startOnLoad: false, theme: 'dark', securityLevel: 'loose' });
          window.mermaid = mermaid;
        }

        const initMermaidPanZoom = (container) => {
          const svg = container.querySelector('svg');
          if (!svg) return;

          const controls = document.createElement('div');
          controls.className = 'mermaid-controls position-absolute top-0 end-0 m-2 bg-dark rounded shadow-lg border border-secondary p-1 d-flex flex-column gap-1';
          controls.innerHTML = `
            <div class="btn-group btn-group-sm">
              <button class="btn btn-outline-light pan-left" title="Move Left"><i class="bi bi-arrow-left"></i></button>
              <button class="btn btn-outline-light pan-up" title="Move Up"><i class="bi bi-arrow-up"></i></button>
              <button class="btn btn-outline-light pan-down" title="Move Down"><i class="bi bi-arrow-down"></i></button>
              <button class="btn btn-outline-light pan-right" title="Move Right"><i class="bi bi-arrow-right"></i></button>
            </div>
            <div class="btn-group btn-group-sm">
              <button class="btn btn-outline-light zoom-in" title="Zoom In (Scroll Up)"><i class="bi bi-zoom-in"></i></button>
              <button class="btn btn-outline-light zoom-out" title="Zoom Out (Scroll Down)"><i class="bi bi-zoom-out"></i></button>
              <button class="btn btn-outline-light reset" title="Reset View"><i class="bi bi-arrow-counterclockwise"></i></button>
            </div>
          `;
          container.appendChild(controls);

          let vb = svg.getAttribute('viewBox');
          let x = 0, y = 0, w = 1000, h = 1000;
          
          if (vb) {
            const parts = vb.split(' ').map(Number);
            if (parts.length === 4 && !parts.some(isNaN)) {
              [x, y, w, h] = parts;
            }
          } else {
            w = parseFloat(svg.getAttribute('width') || container.clientWidth || 1000);
            h = parseFloat(svg.getAttribute('height') || container.clientHeight || 1000);
            svg.setAttribute('viewBox', `${x} ${y} ${w} ${h}`);
          }
          
          const origX = x, origY = y, origW = w, origH = h;
          svg.style.maxWidth = 'none';
          svg.removeAttribute('width');
          svg.removeAttribute('height');

          const updateViewBox = () => svg.setAttribute('viewBox', `${x} ${y} ${w} ${h}`);
          const pan = (dx, dy) => { x += dx * (w / container.clientWidth); y += dy * (h / container.clientHeight); updateViewBox(); };
          const zoom = (factor, cx = container.clientWidth / 2, cy = container.clientHeight / 2) => {
            const svgX = x + (cx / container.clientWidth) * w;
            const svgY = y + (cy / container.clientHeight) * h;
            w *= factor; h *= factor;
            x = svgX - (cx / container.clientWidth) * w;
            y = svgY - (cy / container.clientHeight) * h;
            updateViewBox();
          };

          controls.querySelector('.pan-up').addEventListener('click', () => pan(0, -50));
          controls.querySelector('.pan-down').addEventListener('click', () => pan(0, 50));
          controls.querySelector('.pan-left').addEventListener('click', () => pan(-50, 0));
          controls.querySelector('.pan-right').addEventListener('click', () => pan(50, 0));
          controls.querySelector('.zoom-in').addEventListener('click', () => zoom(0.8));
          controls.querySelector('.zoom-out').addEventListener('click', () => zoom(1.2));
          controls.querySelector('.reset').addEventListener('click', () => { x = origX; y = origY; w = origW; h = origH; updateViewBox(); });

          let isDragging = false;
          let lastMouseX, lastMouseY;

          svg.addEventListener('pointerdown', (e) => {
            isDragging = true; lastMouseX = e.clientX; lastMouseY = e.clientY; svg.setPointerCapture(e.pointerId);
          });
          svg.addEventListener('pointermove', (e) => {
            if (!isDragging) return;
            pan(lastMouseX - e.clientX, lastMouseY - e.clientY);
            lastMouseX = e.clientX; lastMouseY = e.clientY;
          });
          svg.addEventListener('pointerup', (e) => { isDragging = false; svg.releasePointerCapture(e.pointerId); });

          container.addEventListener('wheel', (e) => {
            e.preventDefault(); 
            const rect = container.getBoundingClientRect();
            zoom(e.deltaY > 0 ? 1.1 : 0.9, e.clientX - rect.left, e.clientY - rect.top);
          }, { passive: false });
        };

        const parseMermaidBlocks = async (previewArea) => {
          if (window.mermaid) {
            const mermaidBlocks = previewArea.querySelectorAll('code.language-mermaid');
            for (let i = 0; i < mermaidBlocks.length; i++) {
              const block = mermaidBlocks[i];
              const code = block.textContent;
              const id = `mermaid-preview-${Date.now()}-${i}`;
              try {
                const { svg } = await window.mermaid.render(id, code);
                const pre = block.parentElement;
                const div = document.createElement('div');
                div.className = 'mermaid-container shadow-sm';
                div.innerHTML = svg;
                pre.replaceWith(div);
                initMermaidPanZoom(div);
              } catch (e) {
                const pre = block.parentElement;
                pre.innerHTML = `<div class="text-danger p-2 mb-2 bg-dark border border-danger rounded" style="font-size: 0.8rem">Mermaid Syntax Error</div><pre><code>${escapeHTML(code)}</code></pre>`;
              }
            }
          }
        };

        // Presentation Mode Engine
        let presentationSlides = [];
        let currentSlideIdx = 0;
        
        window.openPresentation = (content) => {
          const overlay = document.getElementById("presentation-mode");
          if (!overlay || !content) return;
          
          const rawSlides = content
            .split(/^_{3,}\s*$|^\*{3,}\s*$|^-{3,}\s*$/gm)
            .map(slide => slide.trim())
            .filter(slide => slide.length > 0);
          
          presentationSlides = rawSlides.map(slide => {
            if (typeof marked !== "undefined") return marked.parse(slide);
            return `<div style="white-space: pre-wrap;">${escapeHTML(slide)}</div>`;
          });
          
          if (presentationSlides.length === 0) {
            presentationSlides = ["<h2 class='text-secondary text-center'>Empty Document</h2>"];
          }
          
          currentSlideIdx = 0;
          overlay.classList.add("active");
          window.renderCurrentSlide();
          document.body.style.overflow = "hidden";
          
          window.removeEventListener('keydown', presentationKeyListener);
          window.addEventListener('keydown', presentationKeyListener);
        };
        
        window.closePresentation = () => {
          const overlay = document.getElementById("presentation-mode");
          if (overlay) overlay.classList.remove("active");
          document.body.style.overflow = "";
          window.removeEventListener('keydown', presentationKeyListener);
        };
        
        window.renderCurrentSlide = async () => {
          const container = document.getElementById("presentation-slide-container");
          const progress = document.getElementById("presentation-progress");
          const indicator = document.getElementById("presentation-indicator");
          if (!container || !progress) return;
          
          container.style.opacity = "0";
          setTimeout(async () => {
            container.innerHTML = `<div style="max-width: 1400px; width: 100%; text-align: center;">${presentationSlides[currentSlideIdx] || "End of presentation."}</div>`;
            container.style.opacity = "1";
            
            await parseMermaidBlocks(container);
            
            progress.style.width = `${((currentSlideIdx + 1) / presentationSlides.length) * 100}%`;
            if (indicator) indicator.textContent = `${currentSlideIdx + 1} / ${presentationSlides.length}`;
          }, 150);
        };
        
        window.prevSlide = () => {
          if (currentSlideIdx > 0) {
            currentSlideIdx--;
            window.renderCurrentSlide();
          }
        };
        
        window.nextSlide = () => {
          if (currentSlideIdx < presentationSlides.length - 1) {
            currentSlideIdx++;
            window.renderCurrentSlide();
          }
        };
        
        const presentationKeyListener = (e) => {
          const overlay = document.getElementById("presentation-mode");
          if (overlay && overlay.classList.contains("active")) {
            if (e.key === "Escape") { e.preventDefault(); window.closePresentation(); }
            if (e.key === "ArrowRight" || e.key === " ") { e.preventDefault(); window.nextSlide(); }
            if (e.key === "ArrowLeft") { e.preventDefault(); window.prevSlide(); }
          }
        };

        const decodeHTML = (html) => {
          if (!html) return "";
          const txt = document.createElement("textarea");
          txt.innerHTML = html;
          return txt.value;
        };
    
        // Parses DB content to active HTML at runtime (Applies [video], [url] and @mentions)
        const parseUserText = (text) => {
          if (!text) return "";
          let parsed = text;

          if (parsed.includes("[img]")) {
            parsed = parsed.replace(/\[img\]\s*([^\s<>\[\]]+)\s*\[\/img\]/gi, (match, url) => window.buildLazyMediaHtml(url, "image/jpeg", "", true));
          }
          if (parsed.includes("[video]")) {
            parsed = parsed.replace(/\[video\]\s*([^\s<>\[\]]+)\s*\[\/video\]/gi, (match, url) => {
              const ytMatch = url.match(/(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]{11})/i);
              if (ytMatch && ytMatch[1]) {
                const mediaId = "yt_" + Math.random().toString(36).substr(2, 9);
                return `<div class="mt-2 mb-2 w-100"><button type="button" class="btn btn-sm btn-outline-secondary fw-bold mb-2" onclick="const wrapper = document.getElementById('${mediaId}'); wrapper.classList.toggle('d-none'); this.innerHTML = wrapper.classList.contains('d-none') ? '<i class=\\'bi bi-play-btn\\'></i> View YouTube' : '<i class=\\'bi bi-chevron-up\\'></i> Hide YouTube'; event.stopPropagation();"><i class="bi bi-play-btn"></i> View YouTube</button><div id="${mediaId}" class="position-relative w-100 rounded overflow-hidden shadow-sm d-none" style="padding-top: 56.25%; max-width: 500px;"><iframe src="https://www.youtube.com/embed/${ytMatch[1]}" class="position-absolute top-0 start-0 w-100 h-100" frameborder="0" allowfullscreen></iframe></div></div>`;
              }
              return window.buildLazyMediaHtml(url, "video/mp4", "", true);
            });
          }
          if (parsed.includes("[url]")) {
            parsed = parsed.replace(/\[url\]\s*([^\s<>\[\]]+)\s*\[\/url\]/gi, (match, url) => {
              let href = url.match(/^https?:\/\//i) ? url : "https://" + url;
              return `<a href="${href}" target="_blank" class="text-info text-decoration-none hover-underline">${url}</a>`;
            });
          }
          if (parsed.includes("http://") || parsed.includes("https://")) {
            parsed = parsed.replace(/(^|[^"'])(https?:\/\/[^\s<]+)/gi, '$1<a href="$2" target="_blank" class="text-info text-decoration-none hover-underline">$2</a>');
          }
          if (parsed.includes("@")) {
            parsed = parsed.replace(/@([\w\.\-_]+)/g, '<strong class="text-info mention-link" data-artist="$1" style="cursor:pointer;" title="Go to Profile">@$1</strong>');
          }
          if (parsed.includes("#")) {
            parsed = parsed.replace(/(^|\n)###\s+([^\n]+)/g, '$1<strong class="fs-5 d-block my-1">$2</strong>');
            parsed = parsed.replace(/(^|\n)##\s+([^\n]+)/g, '$1<strong class="fs-4 d-block my-1">$2</strong>');
            parsed = parsed.replace(/(^|\n)#\s+([^\n]+)/g, '$1<strong class="fs-3 d-block my-1">$2</strong>');
          }
          if (parsed.includes("*")) {
            parsed = parsed.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
            parsed = parsed.replace(/\*([^*]+)\*/g, "<em>$1</em>");
          }
          if (parsed.includes("~~")) {
            parsed = parsed.replace(/~~([^~]+)~~/g, "<del>$1</del>");
          }
          if (parsed.includes("[spoiler]")) {
            parsed = parsed.replace(/\[spoiler\]([\s\S]*?)\[\/spoiler\]/gi, '<span class="spoiler" onclick="this.classList.toggle(\'revealed\')">$1</span>');
          }
          if (parsed.includes(">")) {
            parsed = parsed.replace(/(^|\n)(>[^\n]+)/g, '$1<span class="greentext">$2</span>');
            parsed = parsed.replace(/(?:&gt;&gt;|>>)(\d+)/g, "<a onclick=\"const el=document.querySelector('.reply-anchor-$1'); if(el) el.scrollIntoView({behavior:'smooth'', block:'center'});\" class=\"post-quote-link\" title=\"Click to jump to post\">&gt;&gt;$1</a>");
          }

          return parsed;
        };
    
        // Global Event listener for toggling nested replies in Comments/Community
        document.addEventListener("click", (e) => {
          const toggleBtn = e.target.closest(".toggle-replies-btn");
          if (toggleBtn) {
            const targetId = toggleBtn.dataset.target;
            const container = document.getElementById(targetId);
            if (container) {
              container.classList.toggle("d-none");
              if (container.classList.contains("d-none")) {
                toggleBtn.innerHTML = `<div class="d-flex align-items-center justify-content-center bg-info text-dark rounded-circle shadow-sm" style="width: 24px; height: 24px;"><i class="bi bi-chevron-down" style="font-size: 0.85rem;"></i></div> View ${container.children.length} ${container.children.length === 1 ? "reply" : "replies"}`;
              } else {
                toggleBtn.innerHTML = `<div class="d-flex align-items-center justify-content-center bg-info text-dark rounded-circle shadow-sm" style="width: 24px; height: 24px;"><i class="bi bi-chevron-up" style="font-size: 0.85rem;"></i></div> Hide replies`;
              }
            }
          }
        });
    
        const timeAgo = (isoString) => {
          if (!isoString) return "";
          const date = new Date(isoString);
          if (isNaN(date)) return isoString;
    
          const seconds = Math.floor((new Date() - date) / 1000);
          let interval = seconds / 31536000;
          if (interval > 1) return Math.floor(interval) + " years ago";
          interval = seconds / 2592000;
          if (interval > 1) return Math.floor(interval) + " months ago";
          interval = seconds / 86400;
          if (interval > 1) return Math.floor(interval) + " days ago";
          interval = seconds / 3600;
          if (interval > 1) return Math.floor(interval) + " hours ago";
          interval = seconds / 60;
          if (interval > 1) return Math.floor(interval) + " minutes ago";
          return "Just now";
        };
    
        window.exportData = async (url, defaultFilename) => {
          showToast("Exporting...", "info");
          try {
            const res = await fetch(url);
            if (!res.ok) throw new Error("Export failed");
            const blob = await res.blob();
            const urlBlob = URL.createObjectURL(blob);
            const a = document.createElement("a");
            a.href = urlBlob;
    
            const disposition = res.headers.get("Content-Disposition");
            let filename = defaultFilename;
            if (disposition && disposition.indexOf("filename=") !== -1) {
              const matches = /filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/.exec(
                disposition,
              );
              if (matches != null && matches[1]) {
                filename = matches[1].replace(/['"]/g, "");
              }
            }
            a.download = filename;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(urlBlob);
          } catch (err) {
            showToast("Failed to export", "error");
          }
        };
    
        // Setup Custom Console Interceptor
        const consoleOutput = document.getElementById("custom-console-output");
        const customConsoleLog = (msg, type = "info") => {
          if (!consoleOutput) return;
          const colorMap = {
            error: "#ff3b30",
            warn: "#ffcc00",
            info: "#00ff00",
          };
          const time = new Date().toLocaleTimeString();
          const logLine = document.createElement("div");
          logLine.style.color = colorMap[type];
          logLine.style.marginBottom = "4px";
          logLine.style.borderBottom = "1px solid #222";
          logLine.textContent = `[${time}] ${msg}`;
          consoleOutput.appendChild(logLine);
          consoleOutput.scrollTop = consoleOutput.scrollHeight;
        };
    
        const origConsoleError = console.error;
        console.error = function (...args) {
          customConsoleLog(
            args
              .map((a) => (typeof a === "object" ? JSON.stringify(a) : a))
              .join(" "),
            "error",
          );
          origConsoleError.apply(console, args);
        };
        const origConsoleWarn = console.warn;
        console.warn = function (...args) {
          customConsoleLog(
            args
              .map((a) => (typeof a === "object" ? JSON.stringify(a) : a))
              .join(" "),
            "warn",
          );
          origConsoleWarn.apply(console, args);
        };
    
        window.addEventListener("error", (e) =>
          customConsoleLog(`${e.message} at ${e.filename}:${e.lineno}`, "error"),
        );
        window.addEventListener("unhandledrejection", (e) =>
          customConsoleLog(`Unhandled Rejection: ${e.reason}`, "error"),
        );
    
        document
          .getElementById("clear-console-btn")
          ?.addEventListener("click", () => {
            if (consoleOutput) consoleOutput.innerHTML = "";
          });
    
        // Setup Virtual Scrolling Request Cache
        const requestCache = new Map();
    
        const fetchData = async (url, options = {}, silent = false) => {
          const isGet = !options.method || options.method === "GET";
          const bypassCache = options.noCache || url.includes("get_chat") || url.includes("get_inbox") || url.includes("get_unread_notif_count") || url.includes("get_activity_feed") || url.includes("get_statuses") || url.includes("get_starred_messages");
          const cacheKey = url;

          // Invalidate cache on any POST/Mutation request to ensure fresh data mapping
          if (!isGet) {
            requestCache.clear();
          } else if (!bypassCache && requestCache.has(cacheKey)) {
            const cached = requestCache.get(cacheKey);
            if (Date.now() - cached.timestamp < 300000) {
              // 5 minutes TTL
              return cached.data;
            } else {
              requestCache.delete(cacheKey);
            }
          }
    
          try {
            options.cache = "no-store";
            const response = await fetch(url, options);
            if (!response.ok) {
              const errorData = await response.json().catch(() => null);
              const message = errorData
                ? errorData.message
                : `HTTP error! status: ${response.status}`;
              throw new Error(message);
            }
            let data;
            if (response.headers.get("content-type")?.includes("application/json")) {
              data = await response.json();
            } else {
              data = await response.text();
            }
    
            if (isGet && !bypassCache) {
              // Deep clone the object to prevent reference pollution when caching DOM lists
              requestCache.set(cacheKey, {
                timestamp: Date.now(),
                data: JSON.parse(JSON.stringify(data)),
              });
            }
            return data;
          } catch (error) {
            console.error("Fetch error for " + url, error);
            if (!silent) showToast(error.message, "error");
            return null;
          }
        };
    
        const updateAppFavicon = (url) => {
          document.querySelectorAll("link[rel*='icon']").forEach((el) => el.remove());
          const link = document.createElement("link");
          link.id = "app-favicon";
          link.rel = "icon";
          link.type = url.includes("get_app_icon") ? "image/svg+xml" : "image/webp";
          link.href = url;
          document.head.appendChild(link);
        };
    
        document.addEventListener("click", (e) => {
          const copyBtn = e.target.closest(".copy-api-token-btn");
          if (copyBtn) {
            e.preventDefault();
            e.stopPropagation();
            const token = copyBtn.dataset.token;
            if (!token) return;
    
            const onSuccess = () => {
              const origHTML = copyBtn.innerHTML;
              copyBtn.innerHTML = '<i class="bi bi-check-lg text-success"></i>';
              showToast("API Key copied to clipboard!", "success");
              setTimeout(() => {
                copyBtn.innerHTML = origHTML;
              }, 2000);
            };
    
            if (navigator.clipboard && window.isSecureContext) {
              navigator.clipboard.writeText(token).then(onSuccess);
            } else {
              const ta = document.createElement("textarea");
              ta.value = token;
              ta.style.position = "fixed";
              ta.style.opacity = "0";
              document.body.appendChild(ta);
              ta.select();
              document.execCommand("copy");
              document.body.removeChild(ta);
              onSuccess();
            }
          }
        });
    
        const showToast = (message, type = "info") => {
          const toastContainer = document.createElement("div");
          toastContainer.className = `toast-container position-fixed bottom-0 end-0 p-3`;
          toastContainer.style.zIndex = "1100";
          const toastEl = document.createElement("div");
          toastEl.className = `toast align-items-center text-white bg-${type === "error" ? "danger" : "success"} border-0`;
          toastEl.setAttribute("role", "alert");
          toastEl.setAttribute("aria-live", "assertive");
          toastEl.setAttribute("aria-atomic", "true");
          toastEl.innerHTML = `<div class="d-flex"><div class="toast-body">${message}</div><button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast" aria-label="Close"></button></div>`;
    
          document.body.appendChild(toastContainer);
          toastContainer.appendChild(toastEl);
    
          const toast = new bootstrap.Toast(toastEl);
          toast.show();
          toastEl.addEventListener("hidden.bs.toast", () => toastContainer.remove());
        };
    
        const showLoader = (isInitial = true) => {
          if (isInitial) {
            contentArea.innerHTML = `<div class="loader">Loading...</div>`;
            contentTitle.classList.remove("d-none");
          } else {
            infiniteScrollLoader.classList.remove("d-none");
          }
        };
    
        const hideLoader = () => {
          infiniteScrollLoader.classList.add("d-none");
        };
    
        const updateContentTitle = (text, show = true) => {
          let decodedText = text;
          try {
            decodedText = decodeURIComponent(text.replace(/\+/g, " "));
          } catch (e) {}
    
          if (decodedText) {
            document.title = decodedText + " - PHP Music";
          }
    
          if (!show) {
            contentTitle.classList.add("d-none");
            return;
          }
          contentTitle.classList.remove("d-none");
          contentTitle.textContent = decodedText;
        };
    
        const updateMultiSelectUI = () => {
          if (selectedSongs.size > 0) {
            multiSelectBar.classList.remove("d-none");
            multiSelectCount.textContent = selectedSongs.size;
            if (sortable) sortable.option("disabled", true);
          } else {
            multiSelectBar.classList.add("d-none");
            multiSelectMode = false;
            document
              .querySelectorAll(".song-item.multi-selected")
              .forEach((el) => el.classList.remove("multi-selected"));
            if (sortable) sortable.option("disabled", false);
          }
        };
    
        const toggleSongSelection = (songItem) => {
          const songId = songItem.dataset.songId;
          if (selectedSongs.has(songId)) {
            selectedSongs.delete(songId);
            songItem.classList.remove("multi-selected");
          } else {
            selectedSongs.add(songId);
            songItem.classList.add("multi-selected");
          }
          updateMultiSelectUI();
        };
    
        let isDragging = false;
        let startX = 0,
          startY = 0;
    
        const startHold = (e) => {
          const songItem = e.target.closest(".song-item");
          if (!songItem || e.target.closest(".song-more")) return;
    
          isDragging = false;
          if (e.touches && e.touches.length > 0) {
            startX = e.touches[0].clientX;
            startY = e.touches[0].clientY;
          }
    
          holdTimer = setTimeout(() => {
            if (isDragging) return;
            if (!currentUser) {
              showToast("Please log in to use multi-select mode.", "error");
              return;
            }
            multiSelectMode = true;
            if (sortable) {
              sortable.option("disabled", true);
              if (window.TouchEvent) {
                document.dispatchEvent(new TouchEvent("touchend"));
              }
            }
            if (!selectedSongs.has(songItem.dataset.songId)) {
              toggleSongSelection(songItem);
            }
          }, 1000);
        };
    
        const moveHold = (e) => {
          if (holdTimer && e.touches && e.touches.length > 0) {
            const dx = Math.abs(e.touches[0].clientX - startX);
            const dy = Math.abs(e.touches[0].clientY - startY);
            if (dx > 10 || dy > 10) {
              isDragging = true;
              clearTimeout(holdTimer);
            }
          }
        };
    
        const endHold = () => {
          if (holdTimer) clearTimeout(holdTimer);
        };
    
        contentArea.addEventListener("touchstart", startHold, {
          passive: true,
        });
        contentArea.addEventListener("touchmove", moveHold, {
          passive: true,
        });
        contentArea.addEventListener("touchend", endHold);
        contentArea.addEventListener("touchcancel", endHold);
    
        contentArea.addEventListener("contextmenu", (e) => {
          const songItem = e.target.closest(".song-item");
          const moreBtn = e.target.closest(".song-more");
          if (songItem || e.target.closest(".shelf-item")) {
            e.preventDefault();
            if (songItem && !moreBtn) {
              if (!currentUser) {
                showToast("Please log in to use multi-select mode.", "error");
                return;
              }
              if (!multiSelectMode) {
                multiSelectMode = true;
                if (sortable) sortable.option("disabled", true);
              }
              toggleSongSelection(songItem);
            }
          }
        });
    
        document
          .getElementById("multi-action-dropdown-btn")
          .addEventListener("click", (e) => {
            e.stopPropagation();
            const menu = document.getElementById("multi-action-dropdown-menu");
            menu.classList.toggle("show");
            menu.style.display = menu.classList.contains("show") ? "block" : "none";
          });
    
        document.addEventListener("click", (e) => {
          const menu = document.getElementById("multi-action-dropdown-menu");
          if (
            menu &&
            menu.classList.contains("show") &&
            !e.target.closest("#multi-action-dropdown-btn")
          ) {
            menu.classList.remove("show");
            menu.style.display = "none";
          }
        });
    
        document.getElementById("multi-cancel-btn").addEventListener("click", () => {
          selectedSongs.clear();
          updateMultiSelectUI();
        });
    
        document
          .getElementById("multi-select-all-btn")
          .addEventListener("click", () => {
            const songItems = document.querySelectorAll("#content-area .song-item");
            if (songItems.length === 0) return;
    
            let allSelected = true;
            songItems.forEach((item) => {
              if (!selectedSongs.has(item.dataset.songId)) allSelected = false;
            });
    
            if (allSelected) {
              selectedSongs.clear();
              songItems.forEach((item) => item.classList.remove("multi-selected"));
            } else {
              songItems.forEach((item) => {
                const songId = item.dataset.songId;
                if (songId) {
                  selectedSongs.add(songId);
                  item.classList.add("multi-selected");
                }
              });
            }
            updateMultiSelectUI();
          });
    
        document
          .getElementById("multi-add-favorite-btn")
          .addEventListener("click", async () => {
            if (!currentUser || selectedSongs.size === 0) return;
            let added = 0;
    
            const favBtn = document.getElementById("multi-add-favorite-btn");
            const originalBtnHtml = favBtn.innerHTML;
            favBtn.innerHTML =
              '<i class="bi bi-hourglass-split text-danger" style="animation: spinner-border 1s linear infinite;"></i> <span class="text-white">Adding...</span>';
    
            for (let songId of selectedSongs) {
              let isFav = false;
              if (globalSongCache[songId]) {
                isFav = globalSongCache[songId].is_favorite == 1;
              } else {
                const el = document.querySelector(
                  `.song-item[data-song-id="${songId}"]`,
                );
                if (el && el.dataset.isFavorite === "1") isFav = true;
              }
    
              if (!isFav) {
                const result = await fetchData("?action=toggle_favorite", {
                  method: "POST",
                  headers: {
                    "Content-Type": "application/json",
                  },
                  body: JSON.stringify({
                    id: parseInt(songId),
                  }),
                });
    
                if (result && result.is_favorite) {
                  added++;
                  if (globalSongCache[songId])
                    globalSongCache[songId].is_favorite = 1;
    
                  const songItemsInView = document.querySelectorAll(
                    `.song-item[data-song-id="${songId}"], .shelf-item[data-song-id="${songId}"]`,
                  );
                  songItemsInView.forEach((item) => {
                    item.dataset.isFavorite = "1";
                  });
    
                  if (currentSong && currentSong.id == songId) {
                    currentSong.is_favorite = 1;
                    updateFavoriteIcons(true);
                  }
                }
              }
            }
    
            favBtn.innerHTML = originalBtnHtml;
            if (added > 0) {
              showToast(`Added ${added} new songs to favorites!`, "success");
            } else {
              showToast(`Selected songs are already in favorites.`, "info");
            }
            selectedSongs.clear();
            updateMultiSelectUI();
          });
    
        const recacheOfflineSong = async (id, isNew = false) => {
          const actionText = isNew ? "Caching" : "Re-caching";
          const successText = isNew ? "Song is now available offline!" : "Successfully re-cached!";
          const failText = isNew ? "Failed to cache." : "Failed to re-cache.";

          let tco = document.querySelector(".toast-container");
          if (!tco) {
            tco = document.createElement("div");
            tco.className = "toast-container position-fixed bottom-0 end-0 p-3";
            tco.style.zIndex = "1100";
            document.body.appendChild(tco);
          }
          const pToast = document.createElement("div");
          pToast.className = "toast align-items-center text-white bg-warning text-dark border-0 show mb-2";
          pToast.innerHTML = `<div class="d-flex"><div class="toast-body" id="re-offline-progress-${id}">${actionText} song (0%)...</div></div>`;
          tco.appendChild(pToast);
    
          try {
            const cache = await caches.open("php-music-offline");
    
            const keys = await cache.keys();
            for (let req of keys) {
              const u = new URL(req.url);
              if (u.searchParams.get("id") == id || u.searchParams.get("song_id") == id)
                await cache.delete(req);
            }
    
            const v = globalSongCache[id] ? globalSongCache[id].last_modified || 0 : 0;
            
            // OPTIMIZATION: Run all metadata and chart fetches concurrently
            const cachePromises = [
              cache.add(`?action=get_image&id=${id}&v=${v}`),
              cache.add(`?action=get_song_data&id=${id}`),
              cache.add(`?action=get_all_rhythm_levels`).catch(() => {}),
              cache.add(`?action=get_rhythm_levels&song_id=${id}`).catch(() => {})
            ];
            
            const rgDiffs = ["easy", "medium", "hard", "expert", "master", "demon"];
            for (let d of rgDiffs) {
              cachePromises.push(cache.add(`?action=get_rhythm_chart&song_id=${id}&difficulty=${d}`).catch(() => {}));
            }
            
            await Promise.all(cachePromises);
    
            const response = await fetch(`?action=get_stream&id=${id}`);
            if (!response.ok) throw new Error("Stream fetch failed");

            let opfsUsed = false;
            try {
              if (navigator.storage && navigator.storage.getDirectory) {
                const root = await navigator.storage.getDirectory();
                const dir = await root.getDirectoryHandle("offline_music_cache", { create: true });
                const fileHandle = await dir.getFileHandle(`song_${id}`, { create: true });
                if (fileHandle.createWritable) {
                  const writable = await fileHandle.createWritable();
                  const contentLength = response.headers.get("content-length");
                  
                  if (!contentLength) {
                    await writable.write(await response.clone().blob());
                  } else {
                    const total = parseInt(contentLength, 10);
                    let loaded = 0;
                    const reader = response.clone().body.getReader();
                    while (true) {
                      const { done, value } = await reader.read();
                      if (done) break;
                      loaded += value.length;
                      // Throttle DOM updates to prevent layout thrashing on massive files
                      if (loaded % (1024 * 512) < 65536 || loaded === total) { 
                        const pct = Math.round((loaded / total) * 100);
                        const pctText = document.getElementById(`re-offline-progress-${id}`);
                        if (pctText) pctText.innerText = `${actionText} song (${pct}%)...`;
                      }
                      await writable.write(value);
                    }
                  }
                  await writable.close();
                  opfsUsed = true;
                }
              }
            } catch(opfsErr) {
              console.warn("OPFS write failed, falling back to standard Cache API", opfsErr);
            }

            // OPTIMIZATION: Bypass JS memory bridging. Put directly into native Cache API.
            if (!opfsUsed) {
              const pctText = document.getElementById(`re-offline-progress-${id}`);
              if (pctText) pctText.innerText = `${actionText} song (Finalizing cache)...`;
              await cache.put(`?action=get_stream&id=${id}`, response.clone());
            }
    
            pToast.classList.replace("bg-warning", "bg-success");
            pToast.classList.replace("text-dark", "text-white");
            document.getElementById(`re-offline-progress-${id}`).innerText = successText;
            setTimeout(() => pToast.remove(), 3000);
    
            const itemRows = document.querySelectorAll(`.song-item[data-song-id="${id}"]`);
            itemRows.forEach(itemRow => {
              itemRow.classList.remove("offline-missing");
              itemRow.style.opacity = "1";
              const warningIcon = itemRow.querySelector(".offline-missing-icon");
              if (warningIcon) warningIcon.remove();
            });
            offlineSongsSet.add(parseInt(id));
          } catch (e) {
            console.error(e);
            pToast.classList.replace("bg-warning", "bg-danger");
            pToast.classList.replace("text-dark", "text-white");
            document.getElementById(`re-offline-progress-${id}`).innerText = failText;
            setTimeout(() => pToast.remove(), 3000);
          }
        };
    
        document
          .getElementById("multi-offline-btn")
          .addEventListener("click", async () => {
            if (!currentUser || selectedSongs.size === 0) return;
            let processed = 0;
            const songIdsArray = Array.from(selectedSongs);
    
            const offlineBtn = document.getElementById("multi-offline-btn");
            offlineBtn.disabled = true;
            const originalBtnHtml = offlineBtn.innerHTML;
            offlineBtn.innerHTML =
              '<span class="spinner-border spinner-border-sm me-2"></span> Processing...';
    
            for (let songId of songIdsArray) {
              let isNew = false;
              if (!offlineSongsSet.has(parseInt(songId))) {
                await fetchData("?action=toggle_offline", {
                  method: "POST",
                  headers: {
                    "Content-Type": "application/json",
                  },
                  body: JSON.stringify({
                    id: parseInt(songId),
                  }),
                });
                offlineSongsSet.add(parseInt(songId));
                isNew = true;
              }
              await recacheOfflineSong(parseInt(songId), isNew);
              processed++;
            }
    
            offlineBtn.disabled = false;
            offlineBtn.innerHTML = originalBtnHtml;
            window.offlineViewSongsData = null; // Invalidate offline cache list dynamically
            showToast(
              `Processed ${processed} songs for offline playback!`,
              "success",
            );
            selectedSongs.clear();
            updateMultiSelectUI();
            
            if (currentView.type === "get_offline_songs") {
              loadView(currentView);
            }
          });
    
        document
          .getElementById("multi-remove-btn")
          .addEventListener("click", async () => {
            if (!currentUser || selectedSongs.size === 0) return;
            if (
              ["playlist_songs", "get_favorites", "get_offline_songs"].indexOf(
                currentView.type,
              ) === -1
            ) {
              showToast(
                "This action is only available inside a Playlist, Favorites, or Offline Library.",
                "error",
              );
              return;
            }
            if (
              !confirm(
                "Are you sure you want to remove the selected songs from this view?",
              )
            )
              return;
    
            let removed = 0;
            for (let songId of selectedSongs) {
              if (currentView.type === "playlist_songs") {
                await fetchData("?action=remove_from_playlist", {
                  method: "POST",
                  headers: {
                    "Content-Type": "application/json",
                  },
                  body: JSON.stringify({
                    song_id: parseInt(songId),
                    playlist_public_id: decodeURIComponent(currentView.param),
                  }),
                });
                removed++;
              } else if (currentView.type === "get_favorites") {
                await fetchData("?action=toggle_favorite", {
                  method: "POST",
                  headers: {
                    "Content-Type": "application/json",
                  },
                  body: JSON.stringify({
                    id: parseInt(songId),
                  }),
                });
                if (globalSongCache[songId]) globalSongCache[songId].is_favorite = 0;
                if (currentSong && currentSong.id == songId) {
                  currentSong.is_favorite = 0;
                  updateFavoriteIcons(false);
                }
                removed++;
              } else if (currentView.type === "get_offline_songs") {
                await fetchData("?action=toggle_offline", {
                  method: "POST",
                  headers: {
                    "Content-Type": "application/json",
                  },
                  body: JSON.stringify({
                    id: parseInt(songId),
                  }),
                });
                try {
                  const cache = await caches.open("php-music-offline");
                  const keys = await cache.keys();
                  for (let req of keys) {
                    const u = new URL(req.url);
                    if (
                      u.searchParams.get("id") == songId ||
                      u.searchParams.get("song_id") == songId
                    )
                      await cache.delete(req);
                  }
                  if (navigator.storage && navigator.storage.getDirectory) {
                    const root = await navigator.storage.getDirectory();
                    const dir = await root.getDirectoryHandle("offline_music_cache");
                    await dir.removeEntry(`song_${songId}`).catch(() => {});
                  }
                } catch (e) {}
                offlineSongsSet.delete(parseInt(songId));
                removed++;
              }
            }
    
            window.offlineViewSongsData = null; // Invalidate offline cache list dynamically
            showToast(`Removed ${removed} songs.`, "success");
            selectedSongs.clear();
            updateMultiSelectUI();
            loadView(currentView);
          });
    
        const buildPlaylistModalContent = (playlists) => {
          let html = `
                  <div class="mb-3 d-flex gap-2">
                    <input type="text" id="quick-create-playlist-input" class="form-control bg-transparent text-white border-secondary" placeholder="New Playlist Name">
                    <button class="btn btn-danger" id="quick-create-playlist-btn"><i class="bi bi-plus"></i></button>
                  </div>
                `;
          if (playlists && playlists.length > 0) {
            html += `
                    <div class="list-group list-group-flush">
                      ${playlists
                        .map(
                          (p) => `
                        <button type="button" class="list-group-item list-group-item-action d-flex align-items-center gap-3 add-to-playlist-item my-1 p-2 rounded ${p.is_added == 1 ? "bg-secondary text-white border-0 opacity-75" : "bg-transparent text-white border border-secondary"}" data-playlist-id="${p.id}" data-public-id="${p.public_id}" data-is-added="${p.is_added || 0}">
                          <img src="?action=get_image&id=${p.image_id || 0}&v=${p.image_v || 0}" class="rounded" style="width: 48px; height: 48px; object-fit: cover; background-color: var(--ytm-surface-2);">
                          <div class="d-flex flex-column flex-grow-1 text-start overflow-hidden">
                            <span class="text-truncate fw-medium">${escapeHTML(p.name)}</span>
                            <span class="small ${p.is_added == 1 ? "text-white-50" : "text-secondary"}">${p.song_count} songs</span>
                          </div>
                          ${p.is_added == 1 ? '<i class="bi bi-check-circle-fill text-success fs-5"></i>' : '<i class="bi bi-plus-circle fs-5"></i>'}
                        </button>
                      `,
                        )
                        .join("")}
                    </div>
                  `;
          } else {
            html += `<p class="text-secondary text-center p-4">No playlists found. Create one above!</p>`;
          }
          return html;
        };
    
        const reRenderPlaylistModal = async () => {
          const songId =
            songIdForPlaylist && songIdForPlaylist.length === 1
              ? songIdForPlaylist[0]
              : "0";
          const playlists = await fetchData(
            `?action=get_user_playlists&song_id=${songId}&sort=modified_desc`,
