                                <li class="nav-item" role="presentation">
                                  <button class="nav-link fw-bold w-100 m-0" data-target="#tab-status" type="button" role="tab">Status</button>
                                </li>
                              </ul>
                            </div>
    
                            <div class="tab-content flex-grow-1 overflow-hidden position-relative">
                              <div class="tab-pane fade show active position-absolute top-0 bottom-0 start-0 w-100" id="tab-chats" role="tabpanel" style="display: flex; flex-direction: column;">
                                <div class="p-2 flex-shrink-0"><input type="text" id="inbox-search-input" class="form-control bg-dark text-white border-secondary rounded-pill" placeholder="Search Users & Groups..."></div>
                                <div id="inbox-list" class="flex-grow-1 overflow-auto p-2" style="scrollbar-width: none;">
                                  <div class="text-center p-4"><div class="spinner-border text-secondary"></div></div>
                                </div>
                              </div>
    
                              <div class="tab-pane fade position-absolute top-0 bottom-0 start-0 w-100" id="tab-starred" role="tabpanel" style="display: none; flex-direction: column; opacity: 0; transition: opacity 0.2s;">
                                <div class="p-2 flex-shrink-0"><input type="text" id="starred-search-input" class="form-control bg-dark text-white border-secondary rounded-pill" placeholder="Search starred messages..."></div>
                                <div id="starred-msgs-list" class="flex-grow-1 overflow-auto p-2 d-flex flex-column gap-2 m-0" style="scrollbar-width: none;">
                                  <div class="text-center p-4"><div class="spinner-border text-secondary"></div></div>
                                </div>
                              </div>
    
                              <div class="tab-pane fade position-absolute top-0 bottom-0 start-0 w-100" id="tab-status" role="tabpanel" style="display: none; flex-direction: column; opacity: 0; transition: opacity 0.2s;">
                                <div class="p-2 flex-shrink-0">
                                  <button class="btn btn-danger rounded-pill w-100 fw-bold py-2 shadow-sm" id="add-status-btn" onclick="bootstrap.Modal.getOrCreateInstance(document.getElementById('status-manage-modal')).show();"><i class="bi bi-camera-fill me-2"></i> Create Status</button>
                                </div>
                                <div id="status-list" class="flex-grow-1 overflow-auto p-2 d-flex flex-column gap-2 m-0" style="scrollbar-width: none;">
                                  <div class="text-center p-4"><div class="spinner-border text-secondary"></div></div>
                                </div>
                              </div>
                            </div>
                          </div>
    
                          <div class="chat-main">
                            <div class="chat-header position-relative">
                              <div class="d-flex align-items-center gap-3">
                                <button class="btn btn-link text-white p-0 d-md-none" id="chat-back-btn"><i class="bi bi-arrow-left fs-4"></i></button>
                                <h5 class="text-white fw-bold m-0 d-flex align-items-center" id="chat-header-title" style="font-size: 1.3rem;">Select a chat</h5>
                              </div>
                              <div class="d-flex align-items-center gap-2 ms-auto">
                                <button class="btn btn-link text-secondary hover-white p-0 border-0 d-none align-items-center justify-content-center" id="chat-info-btn" style="width: 44px; height: 44px; text-decoration: none;" title="Details"><i class="bi bi-info-circle fs-5"></i></button>
                                <button class="btn btn-link text-secondary hover-white p-0 border-0 d-none d-md-flex align-items-center justify-content-center" id="chat-pip-btn" style="width: 44px; height: 44px; text-decoration: none;" title="Pop Out Chat"><i class="bi bi-pip fs-5"></i></button>
                                <div class="position-relative flex-shrink-0 d-none custom-opt-dropdown" id="chat-header-dropdown">
                                  <button class="btn btn-link text-white p-0 border-0 custom-opt-toggle" type="button" style="width: 44px; height: 44px;" title="Options">
                                    <i class="bi bi-three-dots-vertical fs-5"></i>
                                  </button>
                                  <ul class="dropdown-menu dropdown-menu-dark shadow-lg border-secondary custom-opt-menu" style="position: absolute; right: 0; top: 100%; display: none; background-color: #1e1e1e; border-radius: 16px; z-index: 1060;">
                                    <li><a class="dropdown-item text-white d-flex align-items-center gap-3 py-2" href="#" id="chat-opt-search"><i class="bi bi-search text-secondary"></i> Search Messages</a></li>
                                    <li><a class="dropdown-item text-white d-flex align-items-center gap-3 py-2" href="#" id="chat-opt-info"><i class="bi bi-info-circle text-info"></i> View Details</a></li>
                                  </ul>
                                </div>
                              </div>
    
                              <div id="chat-floating-search" class="position-absolute d-none align-items-center" style="top: 0; left: 0; right: 0; bottom: 0; background: var(--ytm-surface); z-index: 20; padding: 0 1.5rem;">
                                <button class="btn btn-link text-secondary p-0 me-3" id="close-chat-search"><i class="bi bi-arrow-left fs-4"></i></button>
                                <input type="text" id="chat-inner-search" class="form-control bg-dark text-white border-secondary rounded-pill ps-3 w-100" placeholder="Search messages...">
                              </div>
                            </div>
    
                            <div class="chat-messages" id="chat-messages-container">
                              <div class="d-flex flex-column align-items-center justify-content-center h-100 text-secondary opacity-50">
                                <i class="bi bi-chat-heart" style="font-size: 5rem;"></i>
                                <h4 class="mt-3">Your Messages</h4>
                                <p>Send private photos and messages to a friend or group.</p>
                              </div>
                            </div>
    
                            <div class="chat-input-area">
                              <div class="d-flex justify-content-end w-100 mb-1 chat-formatting-help">
                                <a href="#" class="text-info small text-decoration-none" onclick="window.showFormattingHelp(event.target.ownerDocument); return false;"><i class="bi bi-info-circle"></i> Formatting Help</a>
                              </div>
                              <div class="reply-preview-bar" id="chat-reply-bar">
                                 <div id="chat-reply-preview" class="text-truncate" style="max-width: 85%;"></div>
                                 <button class="btn-close btn-close-white" type="button" onclick="window.clearChatReply(event.target.ownerDocument)"></button>
                              </div>
    
                              <div class="chat-img-upload-preview" id="chat-img-preview-bar">
                                 <img src="" id="chat-img-preview-src" class="d-none">
                                 <video src="" id="chat-video-preview-src" controls class="d-none"></video>
                                 <audio src="" id="chat-audio-preview-src" controls class="d-none w-100 mt-2"></audio>
                                 <button class="chat-img-remove" type="button" onclick="window.clearChatImage(event.target.ownerDocument)"><i class="bi bi-x"></i></button>
                                 <div class="progress mt-3 d-none" id="chat-upload-progress-container" style="height: 8px; background-color: var(--ytm-bg);">
                                   <div class="progress-bar bg-danger progress-bar-striped progress-bar-animated" id="chat-upload-progress" role="progressbar" style="width: 0%;"></div>
                                 </div>
                              </div>
    
                              <form id="chat-form-full" class="d-flex gap-2 w-100 position-relative align-items-end">
                                <input type="hidden" id="chat-reply-id">
                                <div class="chat-input-wrapper flex-grow-1 mb-0">
                                  <div class="dropup d-flex align-items-center justify-content-center">
                                    <button class="btn btn-link text-secondary p-0 border-0 d-flex align-items-center justify-content-center" type="button" data-bs-toggle="dropdown" data-bs-boundary="window" aria-expanded="false" style="width: 28px; height: 28px; transition: color 0.2s;" onmouseover="this.style.color='var(--ytm-primary-text)'" onmouseout="this.style.color='var(--ytm-secondary-text)'" title="Attach Media">
                                      <i class="bi bi-paperclip fs-4"></i>
                                    </button>
                                    <ul class="dropdown-menu dropdown-menu-dark shadow-lg mb-2" style="background-color: #1e1e1e; border: 1px solid #333; border-radius: 16px; min-width: 160px; padding: 0.5rem 0; z-index: 1070;">
                                      <li>
                                        <a class="dropdown-item d-flex align-items-center gap-3 py-2 text-white" href="#" onclick="document.getElementById('chat-image-input').accept='image/*'; document.getElementById('chat-image-input').click(); return false;">
                                          <i class="bi bi-image fs-5 text-info"></i> Photo
                                        </a>
                                      </li>
                                      <li>
                                        <a class="dropdown-item d-flex align-items-center gap-3 py-2 text-white" href="#" onclick="document.getElementById('chat-image-input').accept='video/*'; document.getElementById('chat-image-input').click(); return false;">
                                          <i class="bi bi-camera-video fs-5 text-danger"></i> Video
                                        </a>
                                      </li>
                                      <li>
                                        <a class="dropdown-item d-flex align-items-center gap-3 py-2 text-white" href="#" onclick="document.getElementById('chat-image-input').accept='audio/*'; document.getElementById('chat-image-input').click(); return false;">
                                          <i class="bi bi-headphones fs-5 text-warning"></i> Audio
                                        </a>
                                      </li>
                                    </ul>
                                  </div>
                                  <button id="chat-mention-btn" class="btn btn-link text-secondary p-0 border-0 d-flex align-items-center justify-content-center ms-1" type="button" onclick="const i = document.getElementById('chat-input'); i.value += '@'; i.focus();" style="width: 28px; height: 28px; transition: color 0.2s;" onmouseover="this.style.color='var(--ytm-primary-text)'" onmouseout="this.style.color='var(--ytm-secondary-text)'" title="Mention User">
                                    <i class="bi bi-at fs-4"></i>
                                  </button>
                                  <input type="file" id="chat-image-input" class="d-none">
                                  <textarea id="chat-input" placeholder="Type a message..." autocomplete="off" maxlength="50000" rows="1" style="height: 22px;"></textarea>
                                </div>
                                <button type="submit" class="btn btn-danger rounded-circle d-flex align-items-center justify-content-center flex-shrink-0 my-auto" id="chat-submit-btn" style="width: 44px; height: 44px; box-shadow: 0 4px 12px rgba(225, 29, 72, 0.4); transition: all 0.2s ease;" onmouseover="this.style.transform='scale(1.08)';" onmouseout="this.style.transform='scale(1)';"><i class="bi bi-send-fill fs-5" style="margin-left: -2px;"></i></button>
                              </form>
                            </div>
                          </div>
                        </div>
                      `;
    
                // Initialize Drag and Drop for Chat
                const chatMainEl = document.querySelector(".chat-main");
                if (chatMainEl) {
                  chatMainEl.addEventListener("dragover", (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    chatMainEl.style.boxShadow = "inset 0 0 20px var(--ytm-accent)";
                  });
                  chatMainEl.addEventListener("dragleave", (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    chatMainEl.style.boxShadow = "none";
                  });
                  chatMainEl.addEventListener("drop", (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    chatMainEl.style.boxShadow = "none";
                    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
                      if (typeof window.handleChatImageSelection === "function") {
                        window.handleChatImageSelection(e.dataTransfer.files[0]);
                      }
                    }
                  });
                }
    
                // Load Inbox List
                const loadInboxList = async (query = "") => {
                  const listEl = document.getElementById("inbox-list");
                  if (!listEl) return;
    
                  let inbox = await fetchData("?action=get_inbox");
                  if (!Array.isArray(inbox)) inbox = []; // Protect against SQL error strings
    
                  if (query) {
                    inbox = inbox.filter(
                      (i) =>
                        i.name && i.name.toLowerCase().includes(query.toLowerCase()),
                    );
                  }
    
                  if (inbox.length > 0) {
                    listEl.innerHTML = inbox
                      .map((m) => {
                        const isGroup = m.chat_type === "group";
                        let previewText = window.getPreviewText(m.content);
                        if (m.has_image) {
                          if (m.media_type && m.media_type.startsWith("video/"))
                            previewText = "Video";
                          else if (m.media_type && m.media_type.startsWith("audio/"))
                            previewText = "Audio";
                          else previewText = "Photo";
                        }
                        const isMe = m.sender_id == currentUser.id;
    
                        let activeHtml = "";
                        if (!isGroup && m.last_active) {
                          const mins = Math.floor(
                            (new Date() - new Date(m.last_active + "Z")) / 60000,
                          );
                          activeHtml = `<span class="position-absolute bottom-0 end-0 p-1 ${mins < 5 ? "bg-success" : "bg-secondary"} border border-dark rounded-circle" title="Active"></span>`;
                        }
    
                        const cacheBuster = Math.floor(Date.now() / 60000);
                        return `
                            <div class="list-group-item bg-transparent text-white border-0 px-3 py-3 d-flex align-items-center gap-3 rounded-4 mb-2" style="cursor: pointer; transition: all 0.2s ease;" onmouseover="this.style.backgroundColor='rgba(255,255,255,0.05)'; this.style.transform='translateY(-1px)';" onmouseout="this.style.backgroundColor='transparent'; this.style.transform='none';" onclick="window.openChatFull(${m.target_id}, '${m.chat_type}', '${escapeHTML(m.name).replace(/&#39;/g, "\\'")}')">
                              <div class="position-relative flex-shrink-0">
                                ${isGroup ? `<div class="rounded-circle bg-dark d-flex align-items-center justify-content-center border border-secondary overflow-hidden shadow-sm" style="width: 52px; height: 52px;"><img src="?action=get_group_image&id=${m.target_id}&v=${cacheBuster}" onerror="this.outerHTML='<i class=\\'bi bi-people-fill text-info fs-4\\'></i>'" style="width: 100%; height: 100%; object-fit: cover;"></div>` : `<img src="?action=get_profile_picture&id=${m.target_id}&v=${cacheBuster}" class="rounded-circle shadow-sm" style="width: 52px; height: 52px; object-fit: cover; border: 2px solid rgba(255,255,255,0.05);">`}
                                ${activeHtml}
                              </div>
                              <div class="flex-grow-1 overflow-hidden">
                                <div class="d-flex justify-content-between align-items-center mb-1">
                                  <span class="fw-bold text-truncate" style="font-size: 1.05rem;">${escapeHTML(m.name)}${isGroup && m.member_count ? ` <small class="text-secondary fw-normal" style="font-size: 0.8rem;">(${m.member_count})</small>` : ""}</span>
                                  <small class="text-secondary" style="font-size: 0.75rem;">${timeAgo(m.created_at)}</small>
                                </div>
                                <div class="text-secondary small text-truncate ${m.unread_count > 0 ? "text-white fw-bold" : ""}" style="font-size: 0.85rem;">
                                   ${isGroup && !isMe && m.content ? `<span class="text-info">${m.sender_name || "Someone"}:</span> ` : ""}
                                   ${isMe && !isGroup ? "You: " : ""}${m.has_image ? '<i class="bi bi-image"></i> ' : ""}${escapeHTML(previewText) || "New Chat"}
                                </div>
                              </div>
                              ${m.unread_count > 0 ? `<span class="badge bg-danger rounded-pill shadow-sm py-1 px-2" style="font-size: 0.75rem;">${m.unread_count}</span>` : ""}
                            </div>
                          `;
                      })
                      .join("");
                  } else {
                    listEl.innerHTML =
                      '<div class="p-4 text-center text-secondary">No conversations. Search to start one!</div>';
                  }
                };
    
                loadInboxList();
    
                let inboxSearchTimeout = null;
                document
                  .getElementById("inbox-search-input")
                  .addEventListener("input", (e) => {
                    clearTimeout(inboxSearchTimeout);
                    inboxSearchTimeout = setTimeout(async () => {
                      const q = e.target.value.trim();
                      await loadInboxList(q); // Must await the inbox rendering FIRST
    
                      if (q.length > 1) {
                        const res = await fetchData(
                          `?action=search&q=${encodeURIComponent(q)}`,
                        );
                        if (res && res.shelves) {
                          const artistShelf = res.shelves.find(
                            (s) => s.type === "artists",
                          );
                          if (artistShelf && artistShelf.items.length > 0) {
                            const users = artistShelf.items.filter((u) => u.is_user);
                            if (users.length > 0) {
                              const listEl = document.getElementById("inbox-list");
                              const extraHtml =
                                `<h6 class="text-secondary small fw-bold mt-3 mb-2 px-2">NEW CHATS</h6>` +
                                users
                                  .map(
                                    (u) => `
                                      <div class="list-group-item bg-transparent text-white border-0 px-3 py-2 d-flex align-items-center gap-3 rounded-4 mb-2" style="cursor: pointer; transition: all 0.2s ease;" onmouseover="this.style.backgroundColor='rgba(255,255,255,0.05)'; this.style.transform='translateY(-1px)';" onmouseout="this.style.backgroundColor='transparent'; this.style.transform='none';" onclick="window.openChatFull(${u.id}, 'dm', '${escapeHTML(u.name).replace(/&#39;/g, "\\'")}')">
                                        <img src="?action=get_profile_picture&id=${u.id}&v=${Math.floor(Date.now() / 60000)}" class="rounded-circle shadow-sm" style="width: 46px; height: 46px; object-fit: cover; border: 2px solid rgba(255,255,255,0.05);">
                                        <span class="fw-bold" style="font-size: 1.05rem;">${escapeHTML(u.name)}</span>
                                      </div>
                                   `,
                                  )
                                  .join("");
                              listEl.innerHTML += extraHtml;
                            }
                          }
                        }
                      }
                    }, 400); // 400ms debounce prevents SQLite from locking and wiping the UI
                  });
    
                // Real-time client-side Starred messages filter
                document.addEventListener("input", (e) => {
                  if (e.target.id === "starred-search-input") {
                    const q = e.target.value.toLowerCase().trim();
                    const items = document.querySelectorAll(
                      "#starred-msgs-list .list-group-item",
                    );
                    items.forEach((item) => {
                      const text = item.textContent.toLowerCase();
                      if (text.includes(q)) {
                        item.classList.remove("d-none");
                        item.style.setProperty("display", "flex", "important");
                      } else {
                        item.classList.add("d-none");
                        item.style.setProperty("display", "none", "important");
                      }
                    });
                  }
                });
    
                // INNER CHAT SEARCH LOGIC
                const chatInnerSearch = document.getElementById("chat-inner-search");
                if (chatInnerSearch) {
                  chatInnerSearch.addEventListener("input", (e) => {
                    const q = e.target.value.toLowerCase();
                    const bubbles = document.querySelectorAll(".chat-bubble");
                    bubbles.forEach((b) => {
                      if (b.textContent.toLowerCase().includes(q))
                        b.style.display = "";
                      else b.style.display = "none";
                    });
                  });
                }
    
                // FORCE MANUAL TAB SWITCHING AND CSS DISPLAY OVERRIDES
                document.querySelectorAll("#chat-tabs .nav-link").forEach((btn) => {
                  btn.addEventListener("click", (e) => {
                    e.preventDefault();
                    document
                      .querySelectorAll("#chat-tabs .nav-link")
                      .forEach((b) => b.classList.remove("active"));
                    document
                      .querySelectorAll(".chat-sidebar .tab-pane")
                      .forEach((p) => {
                        p.classList.remove("show", "active");
                        p.style.display = "none";
                        p.style.opacity = "0";
                      });
    
                    const targetId = btn.getAttribute("data-target");
                    btn.classList.add("active");
                    const pane = document.querySelector(targetId);
                    if (pane) {
                      pane.classList.add("show", "active");
                      pane.style.display = "flex"; // Enforce flex globally for perfect layout
                      setTimeout(() => {
                        pane.style.opacity = "1";
                      }, 50);
                    }
    
                    if (targetId === "#tab-starred") window.loadStarredMessages(1);
                    if (targetId === "#tab-status") window.loadStatuses(1);
                  });
                });
    
                // INJECT STATUS MODAL IF NOT EXISTS
                if (!document.getElementById("status-manage-modal")) {
                  const modalHtml = `
                          <div class="modal fade" id="status-manage-modal" tabindex="-1">
                            <div class="modal-dialog modal-dialog-scrollable modal-dialog-centered modal-lg">
                              <div class="modal-content" style="background-color: var(--ytm-surface); border: 1px solid #404040; border-radius: 16px; box-shadow: 0 10px 30px rgba(0,0,0,0.8);">
                                <div class="modal-header border-0 pb-2">
                                  <h5 class="modal-title text-white fw-bold"><i class="bi bi-camera-fill text-danger me-2"></i>Create Status</h5>
                                  <button type="button" class="btn-close btn-close-white" data-bs-dismiss="modal"></button>
                                </div>
                                <div class="modal-body p-4">
                                  <form id="status-post-form-modal" onsubmit="window.submitStatusForm(event)">
                                    <textarea id="status-input-text" class="form-control bg-dark text-white border-secondary mb-3" rows="3" placeholder="What's happening?"></textarea>
                                    <label class="form-label text-secondary small fw-bold mb-2">ATTACH MEDIA (OPTIONAL)</label>
                                    <input type="file" id="status-input-media" class="form-control bg-dark text-white border-secondary mb-4" accept="image/*,video/mp4,video/webm">
                                    <button type="submit" class="btn btn-danger w-100 fw-bold rounded-pill py-2 shadow-sm">Post Status</button>
                                  </form>
                                </div>
                              </div>
                            </div>
                          </div>
                        `;
                  document.body.insertAdjacentHTML("beforeend", modalHtml);
                }
    
                const listStarred = document.getElementById("starred-msgs-list");
                if (listStarred) {
                  listStarred.addEventListener("scroll", () => {
                    if (
                      listStarred.scrollTop + listStarred.clientHeight >=
                      listStarred.scrollHeight - 50
                    ) {
                      const btn = document.getElementById("load-more-starred-btn");
                      if (btn && !btn.disabled) {
                        btn.disabled = true;
                        btn.click();
                      }
                    }
                  });
                }
    
                const listStatus = document.getElementById("status-list");
                if (listStatus) {
                  listStatus.addEventListener("scroll", () => {
                    if (
                      listStatus.scrollTop + listStatus.clientHeight >=
                      listStatus.scrollHeight - 50
                    ) {
                      const btn = document.getElementById("load-more-status-btn");
                      if (btn && !btn.disabled) {
                        btn.disabled = true;
                        btn.click();
                      }
                    }
                  });
                }
    
                window.toggleStarMsg = async (msgId) => {
                  const res = await fetchData("?action=toggle_star_message", {
                    method: "POST",
                    body: JSON.stringify({
                      message_id: msgId,
                    }),
                  });
                  if (res && res.status) {
                    showToast(
                      res.status === "starred"
                        ? "Message starred"
                        : "Message unstarred",
                      "success",
                    );
                    window.refreshChatFull(true);
                    if (
                      document
                        .getElementById("tab-starred")
                        .classList.contains("active")
                    ) {
                      window.loadStarredMessages(1);
                    }
                  }
                };
    
                window.currentStarredPage = 1;
                window.loadStarredMessages = async (page = 1) => {
                  window.currentStarredPage = page;
                  const listEl = document.getElementById("starred-msgs-list");
                  if (!listEl) return;
    
                  if (page === 1) {
                    const searchInp = document.getElementById("starred-search-input");
                    if (searchInp) searchInp.value = "";
                    listEl.innerHTML =
                      '<div class="text-center p-4"><div class="spinner-border text-secondary"></div></div>';
                  } else {
                    const btn = document.getElementById("load-more-starred-btn");
                    if (btn)
                      btn.innerHTML =
                        '<span class="spinner-border spinner-border-sm"></span> Loading...';
                  }
    
                  let msgs = await fetchData(
                    `?action=get_starred_messages&page=${page}`,
                  );
                  if (!Array.isArray(msgs)) msgs = [];
    
                  const btnContainer = document.getElementById(
                    "load-more-starred-container",
                  );
                  if (btnContainer) btnContainer.remove();
    
                  if (msgs.length > 0) {
                    const cacheBuster = Math.floor(Date.now() / 60000);
                    const html = msgs
                      .map((m) => {
                        const isMe = m.sender_id == currentUser.id;
                        let mediaHtml = "";
                        if (m.has_image) {
                          const mediaUrl = `?action=get_message_image&id=${m.id}`;
                          const thumbUrl = `?action=get_message_image&id=${m.id}&thumb=1`;
                          if (m.media_type && m.media_type.startsWith("video/")) {
                            mediaHtml = window.buildLazyMediaHtml(
                              mediaUrl,
                              m.media_type,
                              thumbUrl,
                              false,
                            );
                          } else if (
                            m.media_type &&
                            m.media_type.startsWith("audio/")
                          ) {
                            mediaHtml = `<div class="p-2 bg-dark rounded border border-secondary mt-2"><i class="bi bi-file-earmark-music text-warning"></i> Audio Message</div>`;
                          } else {
                            mediaHtml = window.buildLazyMediaHtml(
                              mediaUrl,
                              m.media_type || "image/webp",
                              thumbUrl,
                              false,
                            );
                          }
                        }
                        const safeDate = m.created_at
                          ? new Date(
                              m.created_at.replace(" ", "T") + "Z",
                            ).toLocaleDateString()
                          : "Just now";
                        return `
                            <div class="list-group-item bg-transparent text-white px-3 py-3 d-flex flex-column gap-2 rounded mb-3 shadow-sm border border-secondary" style="background: linear-gradient(145deg, rgba(255,193,7,0.05), rgba(0,0,0,0.2)); border-left: 4px solid var(--ytm-accent) !important;">
                              <div class="d-flex justify-content-between align-items-center mb-1">
                                <div class="d-flex align-items-center gap-2 user-profile-link" data-userid="${m.sender_id}" data-artist="${encodeURIComponent(m.sender_name || "You")}" style="cursor: pointer;">
                                  <img src="?action=get_profile_picture&id=${m.sender_id}&v=${cacheBuster}" class="rounded-circle shadow-sm" style="width: 36px; height: 36px; object-fit: cover;">
                                  <div class="d-flex flex-column">
                                    <span class="fw-bold fs-6 text-warning"><i class="bi bi-star-fill me-1"></i>${escapeHTML(m.sender_name || "You")}</span>
                                  </div>
                                </div>
                                <small class="text-secondary" style="font-size: 0.75rem;">${safeDate}</small>
                              </div>
                              ${m.content ? `<div class="text-light px-1" style="font-size: 0.95rem; white-space: pre-wrap; line-height: 1.5;">${parseUserText(m.content)}</div>` : ""}
                              ${mediaHtml}
                              <div class="d-flex justify-content-end mt-2 pt-2 border-top border-secondary opacity-75">
                                <button class="btn btn-sm btn-link text-secondary text-decoration-none py-0 px-2 fw-bold" onclick="window.toggleStarMsg(${m.id})"><i class="bi bi-star-fill"></i> Unstar</button>
                              </div>
                            </div>
                          `;
                      })
                      .join("");
    
                    if (page === 1) listEl.innerHTML = html;
                    else listEl.insertAdjacentHTML("beforeend", html);
    
                    if (msgs.length === 25) {
                      listEl.insertAdjacentHTML(
                        "beforeend",
                        `
                              <div class="text-center mt-3 mb-2" id="load-more-starred-container">
                                <button class="btn btn-sm btn-outline-light rounded-pill px-4 fw-bold" id="load-more-starred-btn" onclick="window.loadStarredMessages(${page + 1})">Load Older Messages</button>
                              </div>
                            `,
                      );
                    } else if (page > 1) {
                      listEl.insertAdjacentHTML(
                        "beforeend",
                        '<div class="text-center p-3 text-secondary small">No more starred messages.</div>',
                      );
                    }
                  } else {
                    if (page === 1)
                      listEl.innerHTML =
                        '<div class="p-4 text-center text-secondary">No starred messages.</div>';
                  }
                };
    
                window.currentStatusPage = 1;
                window.loadStatuses = async (page = 1) => {
                  window.currentStatusPage = page;
                  const listEl = document.getElementById("status-list");
                  if (!listEl) return;
    
                  if (page === 1)
                    listEl.innerHTML =
                      '<div class="text-center p-4"><div class="spinner-border text-secondary"></div></div>';
                  else {
                    const btn = document.getElementById("load-more-status-btn");
                    if (btn)
                      btn.innerHTML =
                        '<span class="spinner-border spinner-border-sm"></span> Loading...';
                  }
    
                  let stats = await fetchData(`?action=get_statuses&page=${page}`);
                  if (!Array.isArray(stats)) stats = [];
    
                  const btnContainer = document.getElementById(
                    "load-more-status-container",
                  );
                  if (btnContainer) btnContainer.remove();
    
                  if (stats.length > 0) {
                    const html = stats
                      .map((s) => {
                        let mediaHtml = "";
                        if (s.image) {
                          const mUrl = `?action=get_status_media&id=${s.id}`;
                          const mType = s.media_type || "image/webp"; // Safe fallback prevents crash
                          const mediaId =
                            "status_media_" + Math.random().toString(36).substr(2, 9);
                          const isVideo = mType.startsWith("video/");
                          const btnText = isVideo ? "View Video" : "View Image";
                          const btnIcon = isVideo ? "bi-camera-video" : "bi-image";
    
                          let innerHtml = "";
                          if (isVideo) {
                            innerHtml = `<video src="${mUrl}" controls class="w-100 rounded" style="max-height: 250px; background: #000;"></video>`;
                          } else {
                            innerHtml = `<img src="${mUrl}" class="w-100 rounded" style="max-height: 250px; object-fit: contain; background: #000; cursor: pointer;" onclick="window.openMediaPreview('${mUrl}', 'image'); event.stopPropagation();">`;
                          }
    
                          mediaHtml = `
                                <div class="mt-2 mb-1 w-100">
                                  <button class="btn btn-sm btn-outline-secondary fw-bold mb-2" onclick="const wrapper = document.getElementById('${mediaId}'); wrapper.classList.toggle('d-none'); this.innerHTML = wrapper.classList.contains('d-none') ? '<i class=\\'bi ${btnIcon}\\'></i> ${btnText}' : '<i class=\\'bi bi-chevron-up\\'></i> Hide Media'; event.stopPropagation();">
                                    <i class="bi ${btnIcon}"></i> ${btnText}
                                  </button>
                                  <div id="${mediaId}" class="d-none w-100">
                                    ${innerHtml}
                                  </div>
                                </div>
                              `;
                        }
                        return `
                            <div class="list-group-item bg-transparent text-white border-secondary px-3 py-3 d-flex flex-column gap-2 rounded mb-2 shadow-sm" style="background: rgba(255,255,255,0.05) !important;">
                              <div class="d-flex justify-content-between align-items-center">
                                <div class="d-flex align-items-center gap-2 user-profile-link" data-userid="${s.user_id}" data-artist="${encodeURIComponent(s.name)}" style="cursor: pointer;">
                                  <img src="?action=get_profile_picture&id=${s.user_id}" class="rounded-circle" style="width: 32px; height: 32px; object-fit: cover;">
                                  <span class="fw-bold">${escapeHTML(s.name)}</span>
                                </div>
                                <div class="d-flex align-items-center gap-2">
                                  <small class="text-secondary" style="font-size: 0.75rem;">${timeAgo(s.created_at)}</small>
                                  ${s.user_id == currentUser.id ? `<button class="btn btn-sm btn-link text-danger p-0" onclick="window.deleteStatus(${s.id})"><i class="bi bi-trash2"></i></button>` : ""}
                                </div>
                              </div>
                              ${s.content ? `<div class="text-light mt-1" style="font-size: 1rem; white-space: pre-wrap;">${parseUserText(s.content)}</div>` : ""}
                              ${mediaHtml}
                            </div>
                          `;
                      })
                      .join("");
    
                    if (page === 1) listEl.innerHTML = html;
                    else listEl.insertAdjacentHTML("beforeend", html);
    
                    if (stats.length === 25) {
                      listEl.insertAdjacentHTML(
                        "beforeend",
                        `
                              <div class="text-center mt-3 mb-2" id="load-more-status-container">
                                <button class="btn btn-sm btn-outline-light rounded-pill px-4 fw-bold" id="load-more-status-btn" onclick="window.loadStatuses(${page + 1})">Load Older Statuses</button>
                              </div>
                            `,
                      );
                    } else if (page > 1) {
                      listEl.insertAdjacentHTML(
                        "beforeend",
                        '<div class="text-center p-3 text-secondary small">No more statuses.</div>',
                      );
                    }
                  } else {
                    if (page === 1)
                      listEl.innerHTML =
                        '<div class="p-4 text-center text-secondary">No recent status updates from your network.</div>';
                  }
                };
    
                window.deleteStatus = async (id) => {
                  if (confirm("Delete this status update?")) {
                    await fetchData("?action=delete_status", {
                      method: "POST",
                      body: JSON.stringify({
                        id,
                      }),
                    });
                    window.loadStatuses(1);
                  }
                };
    
                window.submitStatusForm = async (e) => {
                  e.preventDefault();
                  const form = e.target;
                  const txt = document.getElementById("status-input-text").value;
                  const fileInput = document.getElementById("status-input-media");
                  const submitBtn = form.querySelector('button[type="submit"]');
    
                  if (!txt.trim() && fileInput.files.length === 0) return;
    
                  submitBtn.disabled = true;
                  const origHTML = submitBtn.innerHTML;
                  submitBtn.innerHTML =
                    '<span class="spinner-border spinner-border-sm"></span>';
    
                  const fd = new FormData();
                  fd.append("content", txt);
                  if (fileInput.files.length > 0)
                    fd.append("image", fileInput.files[0]);
    
                  try {
                    const response = await fetch("?action=post_status", {
                      method: "POST",
                      body: fd,
                    });
                    const res = await response.json();
    
                    if (res && res.status === "success") {
                      form.reset();
                      const statusModal = bootstrap.Modal.getInstance(
                        document.getElementById("status-manage-modal"),
                      );
                      if (statusModal) statusModal.hide();
                      if (typeof window.loadStatuses === "function")
                        window.loadStatuses(1);
                      showToast("Status posted!", "success");
                    } else {
                      showToast(res.message || "Failed to post status", "error");
                    }
                  } catch (err) {
                    showToast("Upload failed. Connection error.", "error");
                  }
    
                  submitBtn.disabled = false;
                  submitBtn.innerHTML = origHTML;
                };
              } else {
                contentArea.innerHTML = `<div class="text-center p-5 text-secondary">Log in to view messages.</div>`;
              }
              allContentloaded = true;
              break;
            case "get_songs":
              updateContentTitle("All Songs", false);
              if (!cachedExploreData) {
                cachedExploreData = await fetchData(`?action=get_explore`);
              }
              if (
                cachedExploreData &&
                cachedExploreData.shelves &&
                cachedExploreData.shelves.length > 0
              ) {
                renderRecommendations(cachedExploreData);
              } else {
                contentArea.innerHTML = "";
              }
              const allTracksHeader = `
                      <div class="d-flex justify-content-between align-items-center mt-5 mb-3 px-2">
                        <h3 class="m-0 fw-bold">All Tracks</h3>
                        <div class="d-flex align-items-center gap-2">
                          <label for="sort-select-all" class="text-secondary small d-none d-sm-block">Sort by</label>
                          <select id="sort-select-all" class="form-select form-select-sm" style="width: auto;">
                            <option value="random" ${currentView.sort === "random" ? "selected" : ""}>Random Shuffle</option>
                            <option value="id_desc" ${currentView.sort === "id_desc" ? "selected" : ""}>Recently Added</option>
                            <option value="artist_asc" ${currentView.sort === "artist_asc" ? "selected" : ""}>Artist</option>
                            <option value="title_asc" ${currentView.sort === "title_asc" ? "selected" : ""}>Title</option>
                            <option value="album_asc" ${currentView.sort === "album_asc" ? "selected" : ""}>Album</option>
                            <option value="year_desc" ${currentView.sort === "year_desc" ? "selected" : ""}>Year (Newest)</option>
                            <option value="year_asc" ${currentView.sort === "year_asc" ? "selected" : ""}>Year (Oldest)</option>
                          </select>
                        </div>
                      </div>
                    `;
              contentArea.insertAdjacentHTML("beforeend", allTracksHeader);
              document
                .getElementById("sort-select-all")
                .addEventListener("change", (e) => {
                  loadView({
                    ...currentView,
                    sort: e.target.value,
                  });
                });
              data = await fetchData(`?action=get_songs&${pageParams.toString()}`);
              renderSongs(data, true);
              document.getElementById("sort-controls").classList.add("d-none");
              break;
            case "user_profile":
              updateContentTitle("", false);
    
              if (currentView.searchQuery)
                pageParams.set("q", currentView.searchQuery);
    
              const profileViewData = await fetchData(
                `?action=get_view_data&type=profile&${pageParams.toString()}`,
              );
              contentArea.innerHTML = "";
              if (profileViewData && profileViewData.details) {
                renderViewDetailsHeader(profileViewData.details, "profile");
    
                const existingCustomSort = document.getElementById(
                  "artist-custom-sort-container",
                );
                if (existingCustomSort) existingCustomSort.remove();
    
                const customSortHTML = `
                          <div id="artist-custom-sort-container" class="d-none align-items-center gap-2">
                            <label for="artist-custom-sort-select" class="text-secondary small">Sort by</label>
                            <select id="artist-custom-sort-select" class="form-select form-select-sm" style="width: auto;"></select>
                          </div>
                      `;
                document
                  .querySelector(".header-controls")
                  .insertAdjacentHTML("afterbegin", customSortHTML);
    
                const searchHTML = `
                        <div class="px-3 mb-3 mt-4 d-flex flex-wrap gap-3 align-items-center justify-content-between w-100">
                          <div class="position-relative" style="max-width: 400px; width: 100%;">
                            <i class="bi bi-search position-absolute top-50 start-0 translate-middle-y ms-3 text-secondary"></i>
                            <input type="text" id="view-songs-search-input" class="form-control bg-dark text-white border-secondary rounded-pill ps-5" placeholder="Search songs..." value="${escapeHTML(currentView.searchQuery || "")}">
                          </div>
                          <div id="artist-custom-cat-container" class="d-none align-items-center gap-2 ms-auto"></div>
                        </div>
                      `;
                const targetPane =
                  document.getElementById("artistTabsContent") || contentArea;
                targetPane.insertAdjacentHTML("beforebegin", searchHTML);
    
                // Define the sorting and filtering engines (matching the artist profile engine)
                window.filterAndSortArtistPlaylists = () => {
                  const sInp = document.getElementById("view-songs-search-input");
                  const sSel = document.getElementById("artist-custom-sort-select");
                  if (!sInp || !sSel) return;
                  const query = sInp.value.toLowerCase().trim();
                  const sortVal = sSel.value;
                  let filtered = [...(window.artistPlaylistsData || [])];
                  if (query)
                    filtered = filtered.filter(
                      (p) =>
                        p.name.toLowerCase().includes(query) ||
                        (p.description &&
                          p.description.toLowerCase().includes(query)),
                    );
                  filtered.sort((a, b) => {
                    if (sortVal === "newest")
                      return (
                        new Date(b.created_at || 0) - new Date(a.created_at || 0)
                      );
                    if (sortVal === "modified")
                      return new Date(b.image_v || 0) - new Date(a.image_v || 0);
                    if (sortVal === "name_asc") return a.name.localeCompare(b.name);
                    if (sortVal === "name_desc") return b.name.localeCompare(a.name);
                    if (sortVal === "songs_desc")
                      return (b.song_count || 0) - (a.song_count || 0);
                    if (sortVal === "songs_asc")
                      return (a.song_count || 0) - (b.song_count || 0);
                    return 0;
                  });
                  const pane = document.getElementById("playlists-pane");
                  if (!pane) return;
                  if (filtered.length === 0) {
                    pane.innerHTML =
                      '<div class="text-center p-5 text-secondary">No playlists found.</div>';
                    return;
                  }
                  pane.innerHTML = `<div class="row row-cols-2 row-cols-sm-3 row-cols-md-4 g-4">${filtered
                    .map(
                      (p) => `
                          <div class="col">
                            <div class="card h-100 bg-transparent text-white border-0 playlist-card" data-playlist="${encodeURIComponent(p.public_id)}" style="cursor: pointer;">
                              ${currentUser && (currentUser.id == currentViewOwnerId || currentUser.status === "super_admin" || currentUser.is_admin == 1) ? `<button class="playlist-more-btn" data-public-id="${p.public_id}" data-name="${escapeHTML(p.name)}" data-is-collab="${p.is_collaborative || 0}" data-is-private="${p.is_private || 0}" data-owner-id="${currentViewOwnerId}"><i class="bi bi-three-dots-vertical"></i></button>` : ""}
                              <div style="position: relative; display: block; border-radius: 6px; overflow: hidden;">
                                <img src="?action=get_image&id=${p.image_id || 0}&v=${p.image_v || 0}&size=small" class="card-img-top" alt="${escapeHTML(p.name)}" style="aspect-ratio: 1/1; object-fit: cover; background-color: var(--ytm-surface-2); margin-bottom: 0 !important;">
                                ${p.song_count !== undefined ? `<div class="position-absolute bottom-0 start-0 ms-2 mb-1 px-2 py-1 bg-dark bg-opacity-75 text-white rounded fw-bold" style="font-size: 0.75rem; backdrop-filter: blur(4px); line-height: 1;"><i class="bi bi-music-note-list"></i> ${formatSongCount(p.song_count)}</div>` : ""}
                              </div>
                              <div class="card-body px-0 py-2"><h5 class="card-title fs-6 fw-normal text-truncate">${escapeHTML(p.name)}</h5></div>
                            </div>
                          </div>
                        `,
                    )
                    .join("")}</div>`;
                };
    
                window.filterAndSortArtistBlogs = () => {
                  const sInp = document.getElementById("view-songs-search-input");
                  const sSel = document.getElementById("artist-custom-sort-select");
                  const catSel = document.getElementById("artist-custom-cat-sort");
                  if (!sInp || !sSel) return;
                  const query = sInp.value.toLowerCase().trim();
                  const sortVal = sSel.value;
                  const catVal = catSel ? catSel.value : "";
    
                  let filtered = [...(window.artistBlogsData || [])];
                  if (query)
                    filtered = filtered.filter(
                      (b) =>
                        b.title.toLowerCase().includes(query) ||
                        (b.content && b.content.toLowerCase().includes(query)),
                    );
                  if (catVal)
                    filtered = filtered.filter(
                      (b) => (b.category || "all") === catVal,
                    );
    
                  filtered.sort((a, b) => {
                    if (sortVal === "newest")
                      return (
                        new Date(b.created_at.replace(" ", "T") + "Z") -
                        new Date(a.created_at.replace(" ", "T") + "Z")
                      );
                    if (sortVal === "oldest")
                      return (
                        new Date(a.created_at.replace(" ", "T") + "Z") -
                        new Date(b.created_at.replace(" ", "T") + "Z")
                      );
                    if (sortVal === "modified")
                      return (
                        new Date(b.updated_at.replace(" ", "T") + "Z") -
                        new Date(a.updated_at.replace(" ", "T") + "Z")
                      );
                    if (sortVal === "title_asc")
                      return a.title.localeCompare(b.title);
                    return 0;
                  });
                  const pane = document.getElementById("blogs-pane");
                  if (!pane) return;
                  if (filtered.length === 0) {
                    pane.innerHTML =
                      '<div class="text-center p-5 text-secondary">No blogs found.</div>';
                    return;
                  }
                  pane.innerHTML = `<div class="notes-grid" style="display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 16px;">${filtered
                    .map(
                      (b) => `
                          <div class="note-card bg-dark text-white border-secondary hover-bg-dark blog-card-item" data-id="${b.public_id}" style="border-radius: 12px; cursor: pointer; transition: transform 0.2s;" onmouseover="this.style.transform='translateY(-4px)'" onmouseout="this.style.transform='translateY(0)'">
                            <div class="d-flex justify-content-between mb-2">
                              <span class="badge bg-primary text-white">Public Blog</span>
                              <span class="small text-secondary">${new Date(b.updated_at.replace(" ", "T") + "Z").toLocaleDateString()}</span>
                            </div>
                            <div class="fw-bold fs-5 mb-2 text-truncate">${escapeHTML(b.title && b.title.trim() !== "" ? decodeHTML(b.title) : "Untitled")}</div>
                            <div class="text-secondary small overflow-hidden" style="display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical;">${escapeHTML(
                              decodeHTML(b.content)
                                .replace(/<[^>]*>?/gm, "")
                                .replace(/[^a-zA-Z0-9\s.,!?]/g, ""),
                            )}</div>
                            <div class="mt-auto pt-3 d-flex justify-content-between align-items-center">
                              ${b.category && b.category !== "all" ? `<span class="note-chip">${escapeHTML(b.category_name || "Uncategorized")}</span>` : "<span></span>"}
                            </div>
                          </div>
                        `,
                    )
                    .join("")}</div>`;
                };
    
                const updateArtistSearchAndSortUI = (activeTabId) => {
                  const sInp = document.getElementById("view-songs-search-input");
                  const sCont = document.getElementById(
                    "artist-custom-sort-container",
                  );
                  const sSel = document.getElementById("artist-custom-sort-select");
                  const gSort = document.getElementById("sort-controls");
                  const cCont = document.getElementById(
                    "artist-custom-cat-container",
                  );
                  if (!sInp) return;
    
                  sInp.value = "";
    
                  if (activeTabId === "songs-tab") {
                    sInp.placeholder = "Search songs...";
                    if (sCont) sCont.classList.replace("d-flex", "d-none");
                    if (cCont) cCont.classList.replace("d-flex", "d-none");
                    if (gSort) gSort.classList.remove("d-none");
                  } else if (activeTabId === "playlists-tab") {
                    sInp.placeholder = "Search playlists...";
                    if (gSort) gSort.classList.add("d-none");
                    if (cCont) cCont.classList.replace("d-flex", "d-none");
                    if (sCont && sSel) {
                      sSel.innerHTML =
                        '<option value="newest">Newest</option><option value="modified">Recently Modified</option><option value="name_asc">Name (A-Z)</option><option value="name_desc">Name (Z-A)</option><option value="songs_desc">Most Songs</option><option value="songs_asc">Least Songs</option>';
                      sCont.classList.replace("d-none", "d-flex");
                      if (!sCont.classList.contains("d-flex"))
                        sCont.classList.add("d-flex");
                    }
                    window.filterAndSortArtistPlaylists();
                  } else if (activeTabId === "blogs-tab") {
                    sInp.placeholder = "Search blogs...";
                    if (gSort) gSort.classList.add("d-none");
                    if (sCont && sSel) {
                      sSel.innerHTML =
                        '<option value="newest">Newest</option><option value="oldest">Oldest</option><option value="modified">Recently Modified</option><option value="title_asc">Title (A-Z)</option>';
                      sCont.classList.replace("d-none", "d-flex");
                      if (!sCont.classList.contains("d-flex"))
                        sCont.classList.add("d-flex");
                    }
    
                    if (cCont) {
                      const uniqueCategories = [];
                      const categoryMap = new Set();
                      (window.artistBlogsData || []).forEach((b) => {
                        const catId = b.category || "all";
                        if (catId !== "all" && !categoryMap.has(catId)) {
                          categoryMap.add(catId);
                          uniqueCategories.push({
                            id: catId,
                            name: b.category_name || "Unknown",
                          });
                        }
                      });
    
                      const truncateText = (str, len = 20) =>
                        str.length > len ? str.substring(0, len - 2) + "..." : str;
    
                      cCont.innerHTML = `
                              <label for="artist-custom-cat-sort" class="text-secondary small ms-1">Category</label>
                              <select id="artist-custom-cat-sort" class="form-select form-select-sm" style="width: auto; max-width: 200px;">
                                <option value="">All Categories</option>
                                ${uniqueCategories.map((c) => `<option value="${escapeHTML(c.id)}" title="${escapeHTML(c.name)}">${escapeHTML(truncateText(c.name))}</option>`).join("")}
                              </select>
                            `;
                    document
                        .getElementById("artist-custom-cat-sort")
                        .addEventListener("change", window.filterAndSortArtistBlogs);
                      cCont.classList.replace("d-none", "d-flex");
                    }
    
                    window.filterAndSortArtistBlogs();
                  } else if (activeTabId === "arts-tab") {
                    sInp.placeholder = "Search artworks...";
                    if (gSort) gSort.classList.add("d-none");
                    if (sCont && sSel) {
                      sSel.innerHTML = '<option value="newest">Newest</option><option value="oldest">Oldest</option><option value="most_liked">Most Favorited</option><option value="popular">Most Viewed</option>';
                      sCont.classList.replace("d-none", "d-flex");
