                let mediaHtml = "";
                if (t.image) {
                  const ext = t.image.split(".").pop().toLowerCase();
                  let mType = "image";
                  if (["mp4", "webm", "mov"].includes(ext)) mType = "video";
                  else if (["mp3", "wav", "ogg"].includes(ext)) mType = "audio";
                  mediaHtml = renderBoardMedia(t.image, mType);
