          menuItems += `<li class="context-menu-item" data-action="advanced_edit" data-id="${songId}"><i class="bi bi-scissors text-warning"></i> Advanced Edit</li>`;
          menuItems += `<li class="context-menu-item" data-action="edit_metadata" data-id="${songId}" data-title="${encodeURIComponent(title || "")}" data-album="${encodeURIComponent(album || "")}" data-genre="${encodeURIComponent(genre || "")}"><i class="bi bi-pencil-fill"></i> Edit Info</li>`;
          menuItems += `<li class="context-menu-item text-danger" data-action="delete_song" data-id="${songId}"><i class="bi bi-trash2-fill"></i> Delete Song</li>`;
        }
      }

      menuItems += `<hr class="dropdown-divider bg-secondary mx-2 my-1"><li class="context-menu-item" data-action="close_menu"><i class="bi bi-x-lg"></i> Close Menu</li>`;
    
          contextMenu.innerHTML = menuItems;
          contextMenu.style.display = "block";
          positionContextMenu(buttonEl);
        };
    
        const showPlayerContextMenu = (e) => {
          e.preventDefault();
          e.stopPropagation();
          buildAndShowSongContextMenu(e.currentTarget, currentSong);
        };
    
        const showSongItemContextMenu = (buttonEl) => {
          const songItem = buttonEl.closest(".song-item, .shelf-item, .search-dropdown-item");
          if (!songItem) return;
    
          const songData = {
            id: parseInt(songItem.dataset.songId),
            is_offline_missing: songItem.classList.contains("offline-missing"),
            is_favorite: songItem.dataset.isFavorite === "1",
            is_collaborative: songItem.dataset.isCollaborative === "1",
            title: songItem.dataset.songTitle,
            artist: songItem.dataset.songArtist,
            album: songItem.dataset.songAlbum,
            genre: songItem.dataset.songGenre,
            user_id: parseInt(songItem.dataset.songUserId),
          };
          globalSongCache[songData.id] = songData;
    
          buildAndShowSongContextMenu(buttonEl, songData);
        };
    
        let visAnimId;
        let visTime = 0;
        let cachedColor = {
          r: 255,
          g: 50,
          b: 50,
        }; // default theme red
        let lastColorSongId = null;
        let currentCoverImageObj = null;
    
        const getAverageColor = (imgEl) => {
          if (!imgEl || !imgEl.complete || imgEl.naturalWidth === 0)
            return {
              r: 255,
              g: 50,
              b: 50,
            };
          try {
            const tempCanvas = document.createElement("canvas");
            const tempCtx = tempCanvas.getContext("2d");
            tempCanvas.width = 10;
            tempCanvas.height = 10;
            tempCtx.drawImage(imgEl, 0, 0, 10, 10);
            const data = tempCtx.getImageData(0, 0, 10, 10).data;
            let r = 0,
              g = 0,
              b = 0,
              count = 0;
            for (let i = 0; i < data.length; i += 4) {
              const brightness = (data[i] + data[i + 1] + data[i + 2]) / 3;
              if (brightness > 15 && brightness < 240) {
                // Skip near-black and near-white
                r += data[i];
                g += data[i + 1];
                b += data[i + 2];
                count++;
              }
            }
            if (count === 0) {
              for (let i = 0; i < data.length; i += 4) {
                r += data[i];
                g += data[i + 1];
                b += data[i + 2];
              }
              count = data.length / 4;
            }
            return {
              r: Math.round(r / count),
              g: Math.round(g / count),
              b: Math.round(b / count),
            };
          } catch (e) {
            return {
              r: 255,
              g: 50,
              b: 50,
            };
          }
        };
    
        const drawVisualizer = () => {
          visTime += 1;
    
          // Locate canvases inside both Main DOM and Document PiP windows
          let canvases = Array.from(document.querySelectorAll(".visualizer-canvas"));
          if (docPipWindow) {
            const pipCanvases =
              docPipWindow.document.querySelectorAll(".visualizer-canvas");
            canvases = canvases.concat(Array.from(pipCanvases));
          }
    
          let activeCanvas = null;
          canvases.forEach((c) => {
            if (c.offsetParent) activeCanvas = c;
          });
    
          // Extract dominant color of current song cover art if it changed
          if (currentSong && currentSong.id !== lastColorSongId) {
            const activeImg = document.getElementById("player-art-desktop");
            if (activeImg && activeImg.complete) {
              cachedColor = getAverageColor(activeImg);
              lastColorSongId = currentSong.id;
            }
          }
    
          const activeBins = 24; // Lower bins stretching curves horizontally for extra gentle waves
          let rawData = [];
    
          if (isPlaying && analyser) {
            analyser.getByteFrequencyData(visualizerDataArray);
            for (let i = 0; i < activeBins; i++) {
              rawData.push(visualizerDataArray[i]);
            }
          } else {
            // Generate organic sinusoidal idle breathing movement during pause
            for (let i = 0; i < activeBins; i++) {
              const wave1 = Math.sin(i * 0.12 + visTime * 0.035) * 45;
              const wave2 = Math.cos(i * 0.07 - visTime * 0.02) * 20;
              rawData.push(Math.max(15, 65 + wave1 + wave2));
            }
          }
    
          // Symmetrical mapping: treble on outer edges, deep bass in the center (perfectly horizontal)
          const mirroredData = [];
          for (let i = activeBins - 1; i >= 0; i--) {
            mirroredData.push(rawData[i]);
          }
          for (let i = 0; i < activeBins; i++) {
            mirroredData.push(rawData[i]);
          }
    
          const totalPoints = mirroredData.length;
    
          // GENTLE SMOOTHING: Moving average filter to form smooth liquid peaks
          const smoothedData = [];
          const smoothWindow = 2;
          for (let i = 0; i < mirroredData.length; i++) {
            let sum = 0,
              count = 0;
            for (let w = -smoothWindow; w <= smoothWindow; w++) {
              if (mirroredData[i + w] !== undefined) {
                sum += mirroredData[i + w];
                count++;
              }
            }
            smoothedData.push(sum / count);
          }
    
          const sliceWidths = canvases.map((c) => c.offsetWidth / (totalPoints - 1));
          const { r, g, b } = cachedColor;
    
          // Process and Draw standard Page View & Document PiP canvases
          canvases.forEach((canvas, cIdx) => {
            if (!canvas.offsetParent) return;
            const ctx = canvas.getContext("2d");
    
            // Fix memory leak: Only reallocate canvas buffer if size actually changed
            if (
              canvas.width !== canvas.offsetWidth ||
              canvas.height !== canvas.offsetHeight
            ) {
              canvas.width = canvas.offsetWidth;
              canvas.height = canvas.offsetHeight;
            }
    
            ctx.clearRect(0, 0, canvas.width, canvas.height);
    
            // Darken bottom half slightly so translucent waves pop elegantly
            const baseGrad = ctx.createLinearGradient(
              0,
              canvas.height * 0.5,
              0,
              canvas.height,
            );
            baseGrad.addColorStop(0, "transparent");
            baseGrad.addColorStop(1, "rgba(0, 0, 0, 0.55)");
            ctx.fillStyle = baseGrad;
            ctx.fillRect(0, canvas.height * 0.5, canvas.width, canvas.height * 0.5);
    
            const sliceWidth = sliceWidths[cIdx];
    
            const drawWave = (baseAmplitude, colorGrad, baseOffset, layerIdx) => {
              ctx.beginPath();
              ctx.moveTo(-50, canvas.height);
    
              // DYNAMIC RANDOMIZED BREATHING: Modulate amplitude and phase shifts over time per-layer
              const waveBreathe =
                Math.sin(visTime * 0.012 * (layerIdx + 1) + layerIdx) * 0.15;
              const amplitude = baseAmplitude * (1.0 + waveBreathe);
              const xOffset =
                baseOffset + Math.cos(visTime * 0.008 * (layerIdx + 1)) * 35;
    
              let firstVal = smoothedData[0] || 0;
              let yStart =
                canvas.height - (firstVal / 255) * canvas.height * amplitude;
              ctx.lineTo(-50, yStart);
    
              for (let i = 0; i < totalPoints - 1; i++) {
                let val = smoothedData[i] || 0;
                let nextVal = smoothedData[i + 1] || 0;
    
                let xc = xOffset + sliceWidth * i;
                let yc = canvas.height - (val / 255) * canvas.height * amplitude;
    
                let nextX = xOffset + sliceWidth * (i + 1);
                let nextY =
                  canvas.height - (nextVal / 255) * canvas.height * amplitude;
    
                let midX = (xc + nextX) / 2;
                let midY = (yc + nextY) / 2;
    
                ctx.quadraticCurveTo(xc, yc, midX, midY);
              }
    
              ctx.lineTo(canvas.width + 50, canvas.height);
              ctx.closePath();
              ctx.fillStyle = colorGrad;
              ctx.fill();
            };
    
            const makeGrad = (opacity, rOff = 0, gOff = 0, bOff = 0) => {
              const gr = Math.max(0, Math.min(255, r + rOff));
              const gg = Math.max(0, Math.min(255, g + gOff));
              const gb = Math.max(0, Math.min(255, b + bOff));
              const gInst = ctx.createLinearGradient(
                0,
                canvas.height * 0.5,
                0,
                canvas.height,
              );
              gInst.addColorStop(0, `rgba(${gr}, ${gg}, ${gb}, ${opacity})`);
              gInst.addColorStop(1, `rgba(${gr}, ${gg}, ${gb}, 0.0)`);
              return gInst;
            };
    
            const waves = [
              {
                amp: 0.5,
                grad: makeGrad(0.12, -40, -40, -40),
                xOff: -40,
              },
              {
                amp: 0.46,
                grad: makeGrad(0.18, -20, -10, 20),
                xOff: 30,
              },
              {
                amp: 0.42,
                grad: makeGrad(0.24, 20, -20, -10),
                xOff: -20,
              },
              {
                amp: 0.38,
                grad: makeGrad(0.3, -10, 30, -20),
                xOff: 40,
              },
              {
                amp: 0.34,
                grad: makeGrad(0.38, 30, 10, 30),
                xOff: -10,
              },
              {
                amp: 0.3,
                grad: makeGrad(0.48, 10, -30, 40),
                xOff: 20,
              },
              {
                amp: 0.25,
                grad: makeGrad(0.6, 50, 50, 50),
                xOff: 0,
              },
            ];
    
            waves.forEach((w, idx) => {
              drawWave(w.amp, w.grad, w.xOff, idx);
            });
          });
    
          // Draw on standard Video PiP canvas if active
          if (document.pictureInPictureElement === pipVideo && currentCoverImageObj) {
            pipCtx.clearRect(0, 0, 500, 500);
            pipCtx.drawImage(currentCoverImageObj, 0, 0, 500, 500);
    
            // Darken bottom half
            const baseGrad = pipCtx.createLinearGradient(0, 250, 0, 500);
            baseGrad.addColorStop(0, "transparent");
            baseGrad.addColorStop(1, "rgba(0, 0, 0, 0.55)");
            pipCtx.fillStyle = baseGrad;
            pipCtx.fillRect(0, 250, 500, 250);
    
            const pipSliceWidth = 500 / (totalPoints - 1);
    
            const drawPipWave = (amplitude, colorGrad, xOffset) => {
              pipCtx.beginPath();
              pipCtx.moveTo(-50, 500);
    
              let firstVal = smoothedData[0] || 0;
              let yStart = 500 - (firstVal / 255) * 500 * amplitude;
              pipCtx.lineTo(-50, yStart);
    
              for (let i = 0; i < totalPoints - 1; i++) {
                let val = smoothedData[i] || 0;
                let nextVal = smoothedData[i + 1] || 0;
    
                let xc = xOffset + pipSliceWidth * i;
                let yc = 500 - (val / 255) * 500 * amplitude;
    
                let nextX = xOffset + pipSliceWidth * (i + 1);
                let nextY = 500 - (nextVal / 255) * 500 * amplitude;
    
                let midX = (xc + nextX) / 2;
                let midY = (yc + nextY) / 2;
    
                pipCtx.quadraticCurveTo(xc, yc, midX, midY);
              }
    
              pipCtx.lineTo(550, 500);
              pipCtx.closePath();
              pipCtx.fillStyle = colorGrad;
              pipCtx.fill();
            };
    
            const makePipGrad = (opacity, rOff = 0, gOff = 0, bOff = 0) => {
              const gr = Math.max(0, Math.min(255, r + rOff));
              const gg = Math.max(0, Math.min(255, g + gOff));
              const gb = Math.max(0, Math.min(255, b + bOff));
              const gInst = pipCtx.createLinearGradient(0, 250, 0, 500);
              gInst.addColorStop(0, `rgba(${gr}, ${gg}, ${gb}, ${opacity})`);
              gInst.addColorStop(1, `rgba(${gr}, ${gg}, ${gb}, 0.0)`);
              return gInst;
            };
    
            const waveBreathe = (idx) =>
              Math.sin(visTime * 0.012 * (idx + 1) + idx) * 0.15;
            const xSway = (idx) => Math.cos(visTime * 0.008 * (idx + 1)) * 35;
    
            drawPipWave(
              0.5 * (1.0 + waveBreathe(0)),
              makePipGrad(0.12, -40, -40, -40),
              -40 + xSway(0),
            );
            drawPipWave(
              0.46 * (1.0 + waveBreathe(1)),
              makePipGrad(0.18, -20, -10, 20),
              30 + xSway(1),
            );
            drawPipWave(
              0.42 * (1.0 + waveBreathe(2)),
              makePipGrad(0.24, 20, -20, -10),
              -20 + xSway(2),
            );
            drawPipWave(
              0.38 * (1.0 + waveBreathe(3)),
              makePipGrad(0.3, -10, 30, -20),
              40 + xSway(3),
            );
            drawPipWave(
              0.34 * (1.0 + waveBreathe(4)),
              makePipGrad(0.38, 30, 10, 30),
              -10 + xSway(4),
            );
            drawPipWave(
              0.3 * (1.0 + waveBreathe(5)),
              makePipGrad(0.48, 10, -30, 40),
              20 + xSway(5),
            );
            drawPipWave(
              0.25 * (1.0 + waveBreathe(6)),
              makePipGrad(0.6, 50, 50, 50),
              0 + xSway(6),
            );
    
            // Overlay Metadata Text
            const textGrad = pipCtx.createLinearGradient(0, 380, 0, 500);
            textGrad.addColorStop(0, "transparent");
            textGrad.addColorStop(1, "rgba(0,0,0,0.85)");
            pipCtx.fillStyle = textGrad;
            pipCtx.fillRect(0, 380, 500, 120);
    
            pipCtx.fillStyle = "#ffffff";
            pipCtx.font = "bold 28px sans-serif";
            pipCtx.shadowColor = "rgba(0,0,0,0.8)";
            pipCtx.shadowBlur = 4;
            const safeTitle =
              currentSong.title.length > 28
                ? currentSong.title.substring(0, 25) + "..."
                : currentSong.title;
            pipCtx.fillText(safeTitle, 20, 440);
    
            pipCtx.fillStyle = "#cccccc";
            pipCtx.font = "22px sans-serif";
            const safeArtist =
              currentSong.artist.length > 35
                ? currentSong.artist.substring(0, 32) + "..."
                : currentSong.artist;
            pipCtx.fillText(safeArtist, 20, 475);
          }
    
          visAnimId = requestAnimationFrame(drawVisualizer);
        };
    
        const togglePlayPause = () => {
          if (!currentSong) return;
          isPlaying = !isPlaying;
          isPlaying ? audio.play() : audio.pause();
          updatePlayPauseIcons();
          if (!visAnimId) drawVisualizer();
        };
    
        let isRadioLoading = false;
        const playNext = async () => {
          if (queue.length === 0) return;
          if (isRadioLoading) return;
    
          queueIndex++;
          if (queueIndex >= queue.length) {
            if (repeatMode === "all") {
              queueIndex = 0;
            } else {
              isRadioLoading = true;
              const lastSongId = queue[queue.length - 1];
              showToast("Starting Autoplay Station...", "info");
              const newTracks = await fetchData(
                `?action=get_radio_tracks&seed_id=${lastSongId}`,
              );
              isRadioLoading = false;
    
              if (newTracks && newTracks.length > 0) {
                newTracks.forEach((song) => {
                  globalSongCache[song.id] = song; // Cache full song objects!
                  queue.push(parseInt(song.id));
                  originalQueue.push(parseInt(song.id));
                });
                queueDirty = true;
                renderQueue(); // Dynamically updates the Up Next UI!
              } else {
                isPlaying = false;
                audio.pause();
                updatePlayPauseIcons();
                queueIndex = queue.length - 1;
                return;
              }
            }
          }
          playSongById(queue[queueIndex]);
        };
    
        const playPrev = () => {
          if (queue.length === 0) return;
          if (audio.currentTime > 3) {
            audio.currentTime = 0;
            return;
          }
          if (queueIndex === 0) {
            if (repeatMode === "all") {
              queueIndex = queue.length - 1;
            } else {
              audio.currentTime = 0;
              return;
            }
          } else {
            queueIndex--;
          }
          playSongById(queue[queueIndex]);
        };
    
        const toggleShuffle = () => {
          isShuffle = !isShuffle;
          if (queue.length > 0 && currentSong) {
            const currentSongId = currentSong.id;
            if (isShuffle) {
              queue = [...originalQueue];
              for (let i = queue.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [queue[i], queue[j]] = [queue[j], queue[i]];
              }
              const shuffledCurrentIndex = queue.findIndex(
                (id) => id === currentSongId,
              );
              if (shuffledCurrentIndex > -1) {
                [queue[0], queue[shuffledCurrentIndex]] = [
                  queue[shuffledCurrentIndex],
                  queue[0],
                ];
              }
            } else {
              queue = [...originalQueue];
            }
            queueIndex = queue.findIndex((id) => id === currentSongId);
          }
          updateShuffleButtons();
          localStorage.setItem("isShuffle", isShuffle);
          showToast(isShuffle ? "Shuffle enabled" : "Shuffle disabled", "info");
        };
    
        let queueDebounceTimer = null;
        let queueRequestCounter = 0;
        const setQueueAndPlay = async (startId, view) => {
          queueRequestCounter++;
          const currentQueueId = queueRequestCounter;
    
          // DEBOUNCE: Prevent massive array generation and queue fetches from rapid clicks
          if (queueDebounceTimer) clearTimeout(queueDebounceTimer);
          await new Promise((resolve) => {
            queueDebounceTimer = setTimeout(resolve, 200);
          });
          if (currentQueueId !== queueRequestCounter) return;
    
          const contextView = view || currentView;
          let fetchedQueue = [];
    
          if (
            contextView.type === "get_offline_songs" &&
            offlineViewSongsData &&
            offlineViewSongsData.length > 0
          ) {
            fetchedQueue = offlineViewSongsData.map((song) => parseInt(song.id));
          } else if (
            contextView.type === "get_recommendations" ||
            contextView.type === "search"
          ) {
            const allShelfSongs = [
              ...document.querySelectorAll(
                ".shelf-item[data-song-id], .song-item[data-song-id], .top-result-card[data-song-id]",
              ),
            ];
            const allSongIds = allShelfSongs.map((item) =>
              parseInt(item.dataset.songId),
            );
            fetchedQueue = [...new Set(allSongIds)];
          } else {
            let viewTypeForIds = contextView.type;
            if (contextView.type === "user_profile")
              viewTypeForIds = "get_profile_songs";
            const allIds = await fetchData(
              "?action=get_view_ids",
              {
                method: "POST",
                headers: {
                  "Content-Type": "application/json",
                },
                body: JSON.stringify({
                  view_type: viewTypeForIds,
                  param: contextView.param,
                  sort: contextView.sort,
                  filter_user_id: contextView.filter_user_id || "",
                  artist_name: contextView.artist_name || "",
                }),
              },
              true,
            );
    
            if (Array.isArray(allIds) && allIds.length > 0) {
              fetchedQueue = allIds.map((id) => parseInt(id));
            }
          }
    
          if (!fetchedQueue || fetchedQueue.length === 0) {
            fetchedQueue = [startId];
          }
    
          originalQueue = fetchedQueue;
          queue = [...originalQueue];
          window.activeQueueContext = {
            type: contextView.type,
            param: contextView.param,
          };
    
          if (isShuffle) {
            isShuffle = false;
            toggleShuffle();
          }
    
          queueIndex = queue.findIndex((id) => id === startId);
          if (queueIndex === -1) {
            queue.unshift(startId);
            originalQueue = [...queue];
            queueIndex = 0;
          }
          playSongById(startId);
          renderQueue(true);
        };
    
        const hideMobileSidebar = () => {
          const offcanvasEl = document.getElementById("main-nav-offcanvas");
          if (offcanvasEl) {
            const offcanvas = bootstrap.Offcanvas.getOrCreateInstance(offcanvasEl);
            if (offcanvas) offcanvas.hide();
          }
        };
    
        const setupHoldToSkip = (buttons, direction, defaultAction) => {
          buttons.forEach((btn) => {
            let holdTimerSkip = null;
            let skipInterval = null;
            let isHolding = false;
    
            const startHoldSkip = (e) => {
              if (e.type === "touchstart") e.preventDefault();
              isHolding = false;
              holdTimerSkip = setTimeout(() => {
                isHolding = true;
                skipInterval = setInterval(() => {
                  if (!audio.duration || !isFinite(audio.duration)) return;
                  const change = direction === "next" ? 5 : -5;
                  audio.currentTime = Math.max(
                    0,
                    Math.min(audio.duration, audio.currentTime + change),
                  );
                }, 200);
              }, 400);
            };
    
            const endHoldSkip = (e) => {
              if (e.type === "touchend" || e.type === "touchcancel")
                e.preventDefault();
              if (holdTimerSkip) clearTimeout(holdTimerSkip);
              if (skipInterval) clearInterval(skipInterval);
    
              if (!isHolding) {
                defaultAction();
              }
              isHolding = false;
            };
    
            btn.addEventListener("mousedown", startHoldSkip);
            btn.addEventListener("mouseup", endHoldSkip);
            btn.addEventListener("mouseleave", () => {
              if (holdTimerSkip) clearTimeout(holdTimerSkip);
              if (skipInterval) clearInterval(skipInterval);
            });
    
            btn.addEventListener("touchstart", startHoldSkip, {
              passive: false,
            });
            btn.addEventListener("touchend", endHoldSkip, {
              passive: false,
            });
            btn.addEventListener("touchcancel", endHoldSkip, {
              passive: false,
            });
    
            btn.addEventListener("keydown", (e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                defaultAction();
              }
            });
          });
        };
    
        allNavLinks.forEach((link) => {
          if (
            !link.hasAttribute("data-view") ||
            link.classList.contains("cat-nav-link") ||
            link.classList.contains("note-filter-link") ||
            link.classList.contains("task-filter-link") ||
            link.classList.contains("blog-filter-link") ||
            link.getAttribute("data-bs-toggle") === "collapse" ||
            link.getAttribute("data-bs-toggle") === "modal" ||
            [
              "nav-random-play",
              "logout-btn",
              "clear-cache-btn",
              "clear-cookies-btn",
              "clear-session-btn",
              "fullscreen-btn",
              "install-pwa-btn",
              "check-update-btn",
              "nav-upload-btn",
              "get-api-btn",
            ].includes(link.id)
          )
            return;
          link.addEventListener("click", (e) => {
            e.preventDefault();
            const navLink = e.currentTarget;
    
            const viewType = navLink.dataset.view;
            let sort = "artist_asc";
            if (
              [
                "get_favorites",
                "playlist_songs",
                "get_offline_songs",
                "get_listen_later",
              ].includes(viewType)
            )
              sort = "manual_order";
            if (viewType === "get_user_playlists") sort = "modified_desc";
            if (viewType === "get_mixes") sort = "newest";
            if (viewType === "get_albums") sort = "album_asc";
            if (viewType === "get_artists") sort = "name_asc";
            if (viewType === "user_profile") sort = "id_desc";
            if (viewType === "get_history") sort = "history_desc";
            if (viewType === "get_songs") sort = "random";
            if (viewType === "get_my_apis") sort = "newest";
            if (viewType === "get_community") sort = "newest";
    
            loadView({
              type: viewType,
              param: "",
              sort: sort,
              filter_user_id: "",
            });
            hideMobileSidebar();
          });
        });
    
        const navRandomPlayBtn = document.getElementById("nav-random-play");
        if (navRandomPlayBtn) {
          navRandomPlayBtn.addEventListener("click", async (e) => {
            e.preventDefault();
            hideMobileSidebar();
            showToast("Loading random mix...", "info");
            const data = await fetchData("?action=get_songs&sort=random&page=1");
            if (data && data.length > 0) {
              // Instantly queue and play without changing the current page view
              globalSongCache[data[0].id] = data[0]; // Ensure it's cached
              setQueueAndPlay(parseInt(data[0].id), {
                type: "get_songs",
                param: "",
                sort: "random",
              });
            } else {
              showToast("No songs found in library.", "error");
            }
          });
        }
    
        const getSearchHistory = () => {
          try {
            return JSON.parse(localStorage.getItem("ytm_searchHistory")) || [];
          } catch (e) {
            return [];
          }
        };
    
        const saveSearchHistory = (query) => {
          if (!query || query.trim() === "") return;
          let history = getSearchHistory();
          history = history.filter(
            (item) => item.toLowerCase() !== query.toLowerCase(),
          ); // Remove duplicates
          history.unshift(query); // Add to the top
          if (history.length > 25) history.pop(); // Keep only the last 25
          localStorage.setItem("ytm_searchHistory", JSON.stringify(history));
        };
    
        const removeSearchHistory = (query) => {
          let history = getSearchHistory();
          history = history.filter(
            (item) => item.toLowerCase() !== query.toLowerCase(),
          );
          localStorage.setItem("ytm_searchHistory", JSON.stringify(history));
        };
    
        const renderSearchHistory = (dropdownEl) => {
          const history = getSearchHistory();
          if (history.length === 0) {
            dropdownEl.classList.add("d-none");
            return;
          }
          let html = `<div class="search-dropdown-header text-secondary d-flex justify-content-between mb-1"><span>Recent Searches</span></div>`;
          history.forEach((q) => {
            html += `
                    <div class="search-dropdown-item history-dropdown-item d-flex justify-content-between align-items-center py-2" data-query="${escapeHTML(q)}">
                      <div class="d-flex align-items-center gap-3 flex-grow-1" style="min-width:0;">
                        <i class="bi bi-clock-history text-secondary fs-5"></i>
                        <span class="text-white text-truncate fw-medium" style="font-size: 0.95rem;">${escapeHTML(q)}</span>
                      </div>
                      <button class="delete-history-btn" data-query="${escapeHTML(q)}"><i class="bi bi-x-lg"></i></button>
                    </div>
                  `;
          });
          dropdownEl.innerHTML = html;
          dropdownEl.classList.remove("d-none");
        };
    
        const performSearch = (query) => {
          if (query.trim() !== "") {
            saveSearchHistory(query.trim());
            document
              .getElementById("search-dropdown-desktop")
              .classList.add("d-none");
            document.getElementById("search-dropdown-mobile").classList.add("d-none");
            searchInputDesktop.value = query;
            searchInputMobile.value = query;
            hideMobileSidebar();
            
            if (currentView.type === "get_arts") {
              if (currentView.exact_filter) {
                currentView.exact_val = query.trim();
                currentView.searchQuery = "";
              } else {
                currentView.searchQuery = query.trim();
                currentView.exact_val = "";
              }
              currentView.page = 1;
              loadView(currentView);
              return;
            }
            
            loadView({
              type: "search",
              param: query.trim(),
              sort: "artist_asc",
              filter_user_id: "",
              f_date: "",
              f_dur: "",
              f_sort: "relevance",
              f_start_date: "",
              f_end_date: "",
            });
          }
        };
    
        const renderSearchDropdown = (dropdownEl, data) => {
          dropdownEl.innerHTML = "";
          if (!data || !data.shelves || data.shelves.length === 0) {
            dropdownEl.innerHTML =
              '<div class="p-3 text-secondary text-center small">No results found</div>';
            dropdownEl.classList.remove("d-none");
            return;
          }
    
          let html = "";
          const escapeAttr = (str) =>
            str ? String(str).replace(/'/g, "&apos;").replace(/"/g, "&quot;") : "";

          let topResultSongId = null;

          data.shelves.forEach((shelf) => {
            if (shelf.type === "top_result") {
              const song = shelf.items[0];
              if (song) {
                topResultSongId = song.id;
                const coverSvg = getSvgPlaceholder(song.title || "Unknown");
                html += `<div class="search-dropdown-header text-danger">Top Result</div>
                          <div class="search-dropdown-item top-result-item d-flex align-items-center justify-content-between"
                            data-id="${song.id}"
                            data-song-id="${song.id}"
                            data-is-favorite="${song.is_favorite == 1 ? "1" : "0"}"
                            data-is-collaborative="${song.is_collaborative == 1 ? "1" : "0"}"
                            data-song-title="${escapeAttr(song.title)}"
                            data-song-artist="${escapeAttr(song.artist)}"
                            data-song-album="${escapeAttr(song.album)}"
                            data-song-genre="${escapeAttr(song.genre)}"
                            data-song-user-id="${song.user_id}">
                            <div class="d-flex align-items-center gap-3 overflow-hidden flex-grow-1">
                              <img src="?action=get_image&id=${song.id}&v=${song.last_modified || 0}&size=small" onerror="this.onerror=null; this.src='${coverSvg}';" class="search-dropdown-img" style="width: 50px; height: 50px; border-radius: 50%;">
                              <div class="search-dropdown-text">
                                <div class="search-dropdown-title fw-bold" style="font-size: 1rem;">${escapeHTML(song.title)}</div>
                                <div class="search-dropdown-subtitle">Song • ${escapeHTML(song.artist)}</div>
                              </div>
                            </div>
                            <button class="more-btn p-1 border-0 bg-transparent text-secondary flex-shrink-0 ms-2" data-song-id="${song.id}"><i class="bi bi-three-dots-vertical fs-5"></i></button>
                          </div>`;
              }
            } else if (shelf.type === "songs_list") {
              html += `<div class="search-dropdown-header">Songs</div>`;
              const songsList = shelf.items.filter((s) => s.id !== topResultSongId);
              songsList.slice(0, 4).forEach((song) => {
                const coverSvg = getSvgPlaceholder(song.title || "Unknown");
                html += `<div class="search-dropdown-item song-dropdown-item d-flex align-items-center justify-content-between"
                          data-id="${song.id}"
                          data-song-id="${song.id}"
                          data-is-favorite="${song.is_favorite == 1 ? "1" : "0"}"
                          data-is-collaborative="${song.is_collaborative == 1 ? "1" : "0"}"
                          data-song-title="${escapeAttr(song.title)}"
                          data-song-artist="${escapeAttr(song.artist)}"
                          data-song-album="${escapeAttr(song.album)}"
                          data-song-genre="${escapeAttr(song.genre)}"
                          data-song-user-id="${song.user_id}">
                          <div class="d-flex align-items-center gap-3 overflow-hidden flex-grow-1">
                            <img src="?action=get_image&id=${song.id}&v=${song.last_modified || 0}&size=small" onerror="this.onerror=null; this.src='${coverSvg}';" class="search-dropdown-img">
                            <div class="search-dropdown-text">
                              <div class="search-dropdown-title">${escapeHTML(song.title)}</div>
                              <div class="search-dropdown-subtitle">${escapeHTML(song.artist)}</div>
                            </div>
                          </div>
                          <button class="more-btn p-1 border-0 bg-transparent text-secondary flex-shrink-0 ms-2" data-song-id="${song.id}"><i class="bi bi-three-dots-vertical fs-5"></i></button>
                        </div>`;
              });
            } else if (shelf.type === "artists") {
              html += `<div class="search-dropdown-header">Artists</div>`;
              shelf.items.slice(0, 3).forEach((artist) => {
                const img = artist.is_user
                  ? `?action=get_profile_picture&id=${artist.id}`
                  : `?action=get_image&id=${artist.id || 0}&size=small`;
                html += `<div class="search-dropdown-item artist-dropdown-item" data-artist="${encodeURIComponent(artist.name)}" data-userid="${artist.is_user ? artist.id : ""}">
                          <img src="${img}" class="search-dropdown-img" style="border-radius: 50%;">
                          <div class="search-dropdown-text">
                            <div class="search-dropdown-title">${escapeHTML(artist.name)}</div>
                            <div class="search-dropdown-subtitle">Artist</div>
                          </div>
                        </div>`;
              });
            } else if (shelf.type === "albums") {
              html += `<div class="search-dropdown-header">Albums</div>`;
              shelf.items.slice(0, 2).forEach((album) => {
                html += `<div class="search-dropdown-item album-dropdown-item d-flex align-items-center justify-content-between" data-album="${encodeURIComponent(album.album)}" data-userid="${album.user_id || ""}" data-artistname="${encodeURIComponent(album.artist || "")}">
                          <div class="d-flex align-items-center gap-3 overflow-hidden flex-grow-1">
                            <img src="?action=get_image&id=${album.id || 0}&v=${album.image_v || 0}&size=small" class="search-dropdown-img">
                            <div class="search-dropdown-text">
                              <div class="search-dropdown-title">${escapeHTML(album.album)}</div>
                              <div class="search-dropdown-subtitle">${escapeHTML(album.artist)}</div>
                            </div>
                          </div>
                          <button class="album-more-btn p-1 border-0 bg-transparent text-secondary flex-shrink-0 ms-2 hover-white" data-album="${encodeURIComponent(album.album)}" data-userid="${album.user_id || ""}" data-artistname="${encodeURIComponent(album.artist || "")}" data-id="${album.id || 0}"><i class="bi bi-three-dots-vertical fs-5"></i></button>
                        </div>`;
              });
            }
          });
    
          dropdownEl.innerHTML = html;
          dropdownEl.classList.remove("d-none");
        };
    
        let searchTimeout;
        const liveSearchHandler = (e) => {
          clearTimeout(searchTimeout);
          const query = e.target.value;
          const isDesktop = e.target === searchInputDesktop;
          const targetDropdown = isDesktop
            ? document.getElementById("search-dropdown-desktop")
            : document.getElementById("search-dropdown-mobile");
    
          if (isDesktop) searchInputMobile.value = query;
          else searchInputDesktop.value = query;
    
          if (currentView.type === "get_arts") {
            clearTimeout(window.artAdvSearchTimeout);
            window.artAdvSearchTimeout = setTimeout(() => {
              if (currentView.exact_filter) {
                currentView.exact_val = query;
                currentView.searchQuery = "";
              } else {
                currentView.searchQuery = query;
                currentView.exact_val = "";
              }
              currentView.page = 1;
              loadView(currentView);
            }, 400);
            return;
          }
    
          if (query.trim() === "") {
            renderSearchHistory(targetDropdown);
            if (currentView.type === "search")
              loadView({
                type: "get_songs",
                param: "",
                sort: "random",
                filter_user_id: "",
                artist_name: "",
              });
            return;
          }
    
          searchTimeout = setTimeout(async () => {
            const data = await fetchData(
              `?action=search&q=${encodeURIComponent(query.trim())}`,
            );
    
            renderSearchDropdown(targetDropdown, data);
    
            // Properly teardown full-screen apps to transition into the search view
            if (
              ["rhythm_game", "photo_editor", "get_inbox"].includes(currentView.type)
            ) {
              if (localRhythmGame) localRhythmGame.destroy();
    
              const pageHeaderEl = document.querySelector(".page-header");
              const mainContentEl = document.getElementById("main-content");
              if (pageHeaderEl) pageHeaderEl.classList.remove("d-none");
    
              contentArea.style.padding = "";
              contentArea.style.margin = "";
              contentArea.style.width = "";
              contentArea.style.maxWidth = "";
              contentArea.style.height = "";
    
              if (mainContentEl) {
                mainContentEl.style.height = "";
                mainContentEl.style.overflow = "";
              }
              if (playerBar && currentSong) {
                playerBar.classList.remove("d-none");
                document.body.classList.add("player-visible");
              }
            }
    
            currentView = {
              type: "search",
              param: query.trim(),
              sort: "artist_asc",
              filter_user_id: "",
              artist_name: "",
              f_date: "",
              f_dur: "",
              f_sort: "relevance",
            };
            updateContentTitle(`Search: "${query.trim()}"`);
            renderRecommendations(data);
            allContentloaded = true;

            if (history.state && history.state.viewConfig && history.state.viewConfig.type === 'search') {
                history.replaceState({ viewConfig: currentView }, "", window.location.pathname);
            } else {
                history.pushState({ viewConfig: currentView }, "", window.location.pathname);
            }
          }, 350);
        };

        window.triggerFollowEffect = (btnEl) => {
          // 1. YouTube-style button pop animation
          if (btnEl) {
            btnEl.style.transition = 'transform 0.15s cubic-bezier(0.175, 0.885, 0.32, 1.275)';
            btnEl.style.transform = 'scale(1.15)';
            setTimeout(() => {
              btnEl.style.transform = 'scale(1)';
            }, 150);
          }

          // 2. Direct button origin confetti burst
          if (typeof confetti !== 'undefined' && btnEl) {
            const rect = btnEl.getBoundingClientRect();
            const x = (rect.left + rect.width / 2) / window.innerWidth;
            const y = (rect.top + rect.height / 2) / window.innerHeight;

            // YouTube-style circular burst effect
            confetti({
              particleCount: 50,
              spread: 360,
              startVelocity: 20,
              origin: { x, y },
              colors: ['#ff0000', '#ffffff', '#cccccc', '#555555'],
              ticks: 80,
              gravity: 0.9,
              scalar: 0.7,
              disableForReducedMotion: true,
              zIndex: 99999
            });
          }
        };
    
        const mobileSearchToggleBtn = document.getElementById("mobile-search-toggle-btn");
        const mobileSearchBackBtn = document.getElementById("mobile-search-back-btn");
        const mobileSearchContainer = document.getElementById("mobile-search-container");

        if (mobileSearchToggleBtn && mobileSearchBackBtn && mobileSearchContainer) {
          mobileSearchToggleBtn.addEventListener("click", () => {
            mobileSearchContainer.classList.remove("d-none");
            mobileSearchContainer.classList.add("d-flex");
            setTimeout(() => {
              const mobileInput = document.getElementById("search-input-mobile");
              if (mobileInput) mobileInput.focus();
            }, 100);
          });
          
          mobileSearchBackBtn.addEventListener("click", () => {
            mobileSearchContainer.classList.remove("d-flex");
            mobileSearchContainer.classList.add("d-none");
            const mobileInput = document.getElementById("search-input-mobile");
            if (mobileInput) mobileInput.value = "";
            const mobileDropdown = document.getElementById("search-dropdown-mobile");
            if (mobileDropdown) mobileDropdown.classList.add("d-none");
          });
        }

        searchInputDesktop.addEventListener("input", liveSearchHandler);
        searchInputMobile.addEventListener("input", liveSearchHandler);
    
        const focusSearchHandler = (e) => {
          const parent = e.target.closest('.search-bar');
          if (parent) parent.classList.add('is-focused');

          const query = e.target.value.trim();
          if (query === "") {
            const isDesktop = e.target === searchInputDesktop;
            const targetDropdown = isDesktop
              ? document.getElementById("search-dropdown-desktop")
              : document.getElementById("search-dropdown-mobile");
            renderSearchHistory(targetDropdown);
          }
        };

        const blurSearchHandler = (e) => {
          const parent = e.target.closest('.search-bar');
          if (parent) parent.classList.remove('is-focused');
        };

        searchInputDesktop.addEventListener("focus", focusSearchHandler);
        searchInputMobile.addEventListener("focus", focusSearchHandler);
        searchInputDesktop.addEventListener("blur", blurSearchHandler);
        searchInputMobile.addEventListener("blur", blurSearchHandler);
    
        const instantSearchHandler = (e) => {
          if (e.key === "Enter") {
            clearTimeout(searchTimeout);
            performSearch(e.target.value);
            e.target.blur();
          }
        };
    
        searchInputDesktop.addEventListener("keyup", instantSearchHandler);
        searchInputMobile.addEventListener("keyup", instantSearchHandler);
        searchBtnDesktop.addEventListener("click", () => {
          clearTimeout(searchTimeout);
          performSearch(searchInputDesktop.value);
        });
        searchBtnMobile.addEventListener("click", () => {
          clearTimeout(searchTimeout);
          performSearch(searchInputMobile.value);
        });
    
        document.addEventListener("click", (e) => {
          const deleteHistBtn = e.target.closest(".delete-history-btn");
          if (deleteHistBtn) {
            e.preventDefault();
            e.stopPropagation();
            removeSearchHistory(deleteHistBtn.dataset.query);
            const dropdownDesktop = document.getElementById(
              "search-dropdown-desktop",
            );
            const dropdownMobile = document.getElementById("search-dropdown-mobile");
            if (!dropdownDesktop.classList.contains("d-none"))
              renderSearchHistory(dropdownDesktop);
            if (!dropdownMobile.classList.contains("d-none"))
              renderSearchHistory(dropdownMobile);
            return;
          }
    
          if (!e.target.closest(".search-bar") && !e.target.closest(".context-menu")) {
            document
              .getElementById("search-dropdown-desktop")
              .classList.add("d-none");
            document.getElementById("search-dropdown-mobile").classList.add("d-none");
          }
    
          const dropdownMoreBtn = e.target.closest(".search-dropdown-item .more-btn");
          if (dropdownMoreBtn) {
            e.preventDefault();
            e.stopPropagation();
            showSongItemContextMenu(dropdownMoreBtn);
            return;
          }

          const dropdownAlbumMoreBtn = e.target.closest(".search-dropdown-item .album-more-btn");
          if (dropdownAlbumMoreBtn) {
            e.preventDefault();
            e.stopPropagation();
            const cardData = {
              type: "album",
              album: decodeURIComponent(dropdownAlbumMoreBtn.dataset.album),
              userid: dropdownAlbumMoreBtn.dataset.userid,
              artistname: decodeURIComponent(dropdownAlbumMoreBtn.dataset.artistname),
              imageId: dropdownAlbumMoreBtn.dataset.id,
            };
            buildAndShowAlbumOrMixContextMenu(dropdownAlbumMoreBtn, cardData);
            return;
          }

          const dropItem = e.target.closest(".search-dropdown-item");
          if (dropItem) {
            document
              .getElementById("search-dropdown-desktop")
              .classList.add("d-none");
            document.getElementById("search-dropdown-mobile").classList.add("d-none");

            if (dropItem.classList.contains("history-dropdown-item")) {
              const query = dropItem.dataset.query;
              searchInputDesktop.value = query;
              searchInputMobile.value = query;
              performSearch(query);
            } else if (
              dropItem.classList.contains("song-dropdown-item") ||
              dropItem.classList.contains("top-result-item")
            ) {
              setQueueAndPlay(parseInt(dropItem.dataset.id));
            } else if (dropItem.classList.contains("artist-dropdown-item")) {
              loadView({
                type: "artist_songs",
                param: dropItem.dataset.artist,
                sort: "album_asc",
                filter_user_id: dropItem.dataset.userid,
              });
            } else if (dropItem.classList.contains("album-dropdown-item")) {
              loadView({
                type: "album_songs",
                param: dropItem.dataset.album,
                sort: "title_asc",
                filter_user_id: dropItem.dataset.userid,
                artist_name: dropItem.dataset.artistname,
              });
            }
          }
        });
    
        sortSelect.addEventListener("change", (e) => {
          loadView({
            ...currentView,
            sort: e.target.value,
          });
        });
    
        if (fullScanModalEl && fullScanIframe) {
          fullScanModalEl.addEventListener("hidden.bs.modal", () => {
            if (!window.isHidingScan) {
              fullScanIframe.src = "about:blank";
              if (currentView.type === "get_songs") {
                loadView(currentView);
              }
            }
            window.isHidingScan = false;
          });
        }
    
        const btnRescanArtists = document.getElementById("btn-rescan-artists");
        const btnRescanSongs = document.getElementById("btn-rescan-songs");
        const btnRescanAll = document.getElementById("btn-rescan-all");
        const btnRescanStandard = document.getElementById("btn-rescan-standard");
    
        if (btnRescanArtists && fullScanModalEl && fullScanIframe) {
          btnRescanArtists.addEventListener("click", () => {
            fullScanIframe.src = "?action=force_rescan&mode=artists";
            bootstrap.Modal.getOrCreateInstance(fullScanModalEl).show();
          });
        }
        if (btnRescanSongs && fullScanModalEl && fullScanIframe) {
          btnRescanSongs.addEventListener("click", () => {
            fullScanIframe.src = "?action=force_rescan&mode=songs";
            bootstrap.Modal.getOrCreateInstance(fullScanModalEl).show();
          });
        }
        if (btnRescanAll && fullScanModalEl && fullScanIframe) {
          btnRescanAll.addEventListener("click", () => {
            fullScanIframe.src = "?action=force_rescan&mode=all";
            bootstrap.Modal.getOrCreateInstance(fullScanModalEl).show();
          });
        }
        if (btnRescanStandard && fullScanModalEl && fullScanIframe) {
          btnRescanStandard.addEventListener("click", () => {
            fullScanIframe.src = "?action=full_scan";
            bootstrap.Modal.getOrCreateInstance(fullScanModalEl).show();
          });
        }
    
        const emergencyTrigger = document.getElementById(
          "trigger-emergency-scan-btn",
        );
        if (emergencyTrigger && fullScanModalEl && fullScanIframe) {
          emergencyTrigger.addEventListener("click", () => {
            fullScanIframe.src = "?action=full_scan";
            bootstrap.Modal.getOrCreateInstance(fullScanModalEl).show();
          });
        }
    
        const saveDensityBtn = document.getElementById(
          "save-rhythm-global-density-btn",
        );
        if (saveDensityBtn) {
          const densitySelect = document.getElementById(
            "rhythm-global-density-select",
          );
          if (densitySelect) {
            densitySelect.value =
              localStorage.getItem("rhythm_scan_density") || "1.0";
          }
          saveDensityBtn.addEventListener("click", () => {
            localStorage.setItem("rhythm_scan_density", densitySelect.value);
            showToast("Global scanner density updated!", "success");
            bootstrap.Modal.getInstance(
              document.getElementById("chart-config-modal"),
            ).hide();
          });
        }
    
        const vacuumModalEl = document.getElementById("vacuum-modal");
        const vacuumIframe = document.getElementById("vacuum-iframe");
        if (vacuumModalEl && vacuumIframe) {
          vacuumModalEl.addEventListener("show.bs.modal", () => {
            vacuumIframe.src = "?action=vacuum_database";
          });
          vacuumModalEl.addEventListener("hidden.bs.modal", () => {
            vacuumIframe.src = "about:blank";
          });
        }
    
        const chartScanModalEl = document.getElementById("chart-scan-modal");
        const chartScanIframe = document.getElementById("chart-scan-iframe");
        if (chartScanModalEl && chartScanIframe) {
          chartScanModalEl.addEventListener("hidden.bs.modal", () => {
            if (!window.isHidingScan) {
              // Save current progress dynamically before unloading
              try {
                const currentUrl = chartScanIframe.contentWindow.location.href;
                const urlParams = new URLSearchParams(currentUrl.split("?")[1]);
                const activeStep = urlParams.get("step");
                if (activeStep) {
                  localStorage.setItem("rhythm_scan_step", activeStep);
                }
              } catch (e) {}
      
              chartScanIframe.src = "about:blank";
              if (currentView.type === "rhythm_game") loadView(currentView);
            }
            window.isHidingScan = false;
          });
        }
    
        // Custom validation binders for both Scanner and Configurator to prevent empty database loops
        const bindRhythmAdminControls = () => {
          const scanBtn = document.getElementById("nav-chart-scan");
          const configBtn = document.getElementById("nav-chart-config");
    
          const validateAndOpen = (modalId, loadIframe) => {
            try {
              const modal = bootstrap.Modal.getOrCreateInstance(
                document.getElementById(modalId),
              );
              if (loadIframe && chartScanIframe) {
                const lastStep = localStorage.getItem("rhythm_scan_step") || "1";
                const density = localStorage.getItem("rhythm_scan_density") || "1.0";
                chartScanIframe.src = `?action=rescan_charts&step=${lastStep}&run=1&density=${density}`;
              }
              modal.show();
            } catch (err) {
              alert("Error opening interface.");
            }
          };
    
          if (scanBtn) {
            scanBtn.addEventListener("click", (e) => {
              e.preventDefault();
              e.stopPropagation();
              localStorage.setItem("rhythm_scan_step", "1");
              validateAndOpen("chart-scan-modal", true);
            });
          }
          if (configBtn) {
            configBtn.addEventListener("click", (e) => {
              e.preventDefault();
              e.stopPropagation();
              validateAndOpen("chart-config-modal", false);
            });
          }
        };
        bindRhythmAdminControls();
    
        const coverScanModalEl = document.getElementById("cover-scan-modal");
        const coverScanIframe = document.getElementById("cover-scan-iframe");
        const coverScanBtn = document.getElementById("nav-cover-scan");

        if (coverScanBtn && coverScanModalEl && coverScanIframe) {
          coverScanBtn.addEventListener("click", (e) => {
            e.preventDefault();
            coverScanIframe.src = "?action=rescan_covers";
            bootstrap.Modal.getOrCreateInstance(coverScanModalEl).show();
          });
        }

        if (coverScanModalEl && coverScanIframe) {
          coverScanModalEl.addEventListener("hidden.bs.modal", () => {
            if (!window.isHidingScan) {
              coverScanIframe.src = "about:blank";
              if (currentView.type === "get_songs") loadView(currentView);
            }
            window.isHidingScan = false;
          });
        }
    
        playerElements.playPauseBtn.forEach((btn) =>
          btn.addEventListener("click", togglePlayPause),
        );
        setupHoldToSkip(playerElements.prevBtn, "prev", playPrev);
        setupHoldToSkip(playerElements.nextBtn, "next", playNext);
        playerElements.shuffleBtn.forEach((btn) =>
          btn.addEventListener("click", toggleShuffle),
        );
        playerElements.repeatBtn.forEach((btn) =>
          btn.addEventListener("click", () => {
            repeatMode =
              repeatMode === "none" ? "all" : repeatMode === "all" ? "one" : "none";
            localStorage.setItem("repeatMode", repeatMode);
            updateRepeatIcons();
          }),
        );
    
        playerElements.moreBtn.forEach((btn) =>
          btn.addEventListener("click", showPlayerContextMenu),
        );

        const playerModalFavBtn = document.getElementById("player-modal-favorite-btn");
        if (playerModalFavBtn) {
          playerModalFavBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            if (currentSong) toggleFavorite(currentSong.id);
          });
        }
    
        if (playerElements.volumeSlider) {
          playerElements.volumeSlider.addEventListener("input", (e) => {
            audio.volume = e.target.value;
            audio.muted = false;
            updateVolumeSliderFill();
          });
        }
        if (playerElements.volumeBtn) {
          playerElements.volumeBtn.addEventListener("click", () => {
            if (audio.volume === 0 || audio.muted) {
              audio.muted = false;
              audio.volume = previousVolume > 0 ? previousVolume : 1;
              playerElements.volumeSlider.value = audio.volume;
            } else {
              previousVolume = audio.volume;
              audio.muted = true;
              audio.volume = 0;
              playerElements.volumeSlider.value = 0;
            }
            updateVolumeSliderFill();
            updateVolumeIcon();
          });
        }
        audio.addEventListener("volumechange", () => {
          if (!audio.muted && audio.volume > 0) {
            previousVolume = audio.volume;
          }
          playerElements.volumeSlider.value = audio.muted ? 0 : audio.volume;
          updateVolumeSliderFill();
          updateVolumeIcon();
        });
    
        if (playerTrackInfoMobile) {
          playerTrackInfoMobile.addEventListener("click", (e) => {
            if (!e.target.closest("button") && playerModal) {
              if (typeof renderQueue === "function") renderQueue(); // <--- Forces the queue to draw!
              playerModal.show();
            }
          });
        }
    
        const closeOpenModals = () => {
          [
            playerModalEl,
            genresModalEl,
            artistsModalEl,
            document.getElementById("desktop-player-modal"),
            document.getElementById("metadata-modal"),
          ].forEach((el) => {
            if (!el) return;
            const instance = bootstrap.Modal.getInstance(el);
            if (instance && instance._isShown) instance.hide();
          });
        };
    
        const closeChoiceModals = () => {
          [genresModalEl, artistsModalEl].forEach((el) => {
            if (!el) return;
            const instance = bootstrap.Modal.getInstance(el);
            if (instance && instance._isShown) instance.hide();
          });
        };
    
        playerElements.artist.forEach((el) => {
          el.addEventListener("click", (e) => {
            e.stopPropagation();
            if (!currentSong) return;
            const artistRaw = currentSong.artist;
            const userId = currentSong.user_id || "";
            const artistsList = artistRaw
              .split(
                /\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+|\s*,\s*(?!(?:the|a|an|jr|sr)\b))\s*/i,
              )
              .filter((a) => a && a.trim() !== "");
            if (artistsList.length > 1) {
              if (artistsModalBody) {
                const modalTitle = artistsModalEl.querySelector(".modal-title");
                if (modalTitle) modalTitle.textContent = "Artists";
                artistsModalBody.innerHTML = `
                        <div class="list-group list-group-flush rounded">
                          ${artistsList.map((a, idx) => `<button type="button" class="list-group-item list-group-item-action bg-transparent text-white border-secondary artist-modal-item py-3" data-artist="${encodeURIComponent(a)}" data-userid="${idx === 0 ? userId || "" : ""}">${a}</button>`).join("")}
                        </div>
                      `;
                if (artistsModal) artistsModal.show();
              }
            } else {
              // FIX: Close all modals so the artist view is immediately visible
              closeOpenModals();
              hideMobileSidebar();
              loadView({
                type: "artist_songs",
                param: artistRaw,
                sort: "album_asc",
                filter_user_id: userId,
              });
            }
          });
        });
    
        if (artistsModalBody) {
          artistsModalBody.addEventListener("click", (e) => {
            const artistBtn = e.target.closest(".artist-modal-item");
            const albumBtn = e.target.closest(".album-modal-item");
    
            if (artistBtn) {
              const artistName = decodeURIComponent(artistBtn.dataset.artist);
              const userId = artistBtn.dataset.userid;
              // Automatically close all modals (including the player modal) when an artist option is selected
              closeOpenModals();
              setTimeout(() => {
                loadView({
                  type: "artist_songs",
                  param: artistName,
                  sort: "album_asc",
                  filter_user_id: userId,
                  artist_name: "",
                });
                hideMobileSidebar();
              }, 200);
            } else if (albumBtn) {
              const albumName = decodeURIComponent(albumBtn.dataset.album);
              const artistName = decodeURIComponent(albumBtn.dataset.artist);
              let validUserId = parseInt(albumBtn.dataset.userid, 10);
              let safeUserId =
                isNaN(validUserId) || validUserId <= 0 ? "" : validUserId;
              // Automatically close all modals (including the player modal) when an album option is selected
              closeOpenModals();
              setTimeout(() => {
                loadView({
                  type: "album_songs",
                  param: albumName,
                  sort: "title_asc",
                  filter_user_id: safeUserId,
                  artist_name: artistName,
                });
                hideMobileSidebar();
              }, 200);
            }
          });
        }
        let activeCommentSongId = null;
        let currentCommentsPage = 1;
    
        window.openCommentsModal = async (
          songId,
          replyCommentId = null,
          replyUsername = null,
        ) => {
          activeCommentSongId = songId;
          const modal = bootstrap.Modal.getOrCreateInstance(
            document.getElementById("comments-modal"),
          );
          await window.refreshComments(true);
          modal.show();
    
          if (replyCommentId && replyUsername) {
            setTimeout(() => {
              document.getElementById("reply-comment-parent-id").value =
                replyCommentId;
              const preview = document.getElementById("reply-comment-preview");
              if (preview) {
                preview.innerHTML = `<strong class="text-white">Replying to ${escapeHTML(replyUsername)}:</strong>`;
              }
              const input = document.getElementById("reply-comment-input");
              const cleanedUsername = replyUsername.replace(/\s+/g, "");
              input.value = `@${cleanedUsername} `;
    
              bootstrap.Modal.getOrCreateInstance(
                document.getElementById("reply-comment-modal"),
              ).show();
              setTimeout(() => input.focus(), 500);
            }, 500);
          }
        };
    
        window.refreshComments = async (reset = false) => {
          if (!activeCommentSongId) return;
          if (reset === true || typeof reset !== "boolean") currentCommentsPage = 1;
          const sortVal = document.getElementById("comments-sort-select")
            ? document.getElementById("comments-sort-select").value
            : "newest";
    
          const loadMoreBtn = document.getElementById("load-more-comments-btn");
          if (loadMoreBtn && !reset)
            loadMoreBtn.innerHTML =
              '<span class="spinner-border spinner-border-sm"></span>';
    
          const data = await fetchData(
            `?action=get_song_comments&song_id=${activeCommentSongId}&sort=${sortVal}&page=${currentCommentsPage}`,
          );
          const totalCountEl = document.getElementById("total-comments-count");
          if (totalCountEl) totalCountEl.textContent = data.total_comments || 0;
          document.getElementById("song-like-count").textContent =
            data.reactions.like || 0;
          document.getElementById("song-dislike-count").textContent =
            data.reactions.dislike || 0;
    
          const lBtn = document.getElementById("song-like-btn");
          const dBtn = document.getElementById("song-dislike-btn");
          if (lBtn) {
            const lIcon = lBtn.querySelector("i");
            if (lIcon)
              lIcon.className = `bi bi-hand-thumbs-up${data.my_reaction === "like" ? "-fill" : ""} fs-5`;
            lBtn.classList.toggle("active", data.my_reaction === "like");
            lBtn.classList.toggle("text-white", data.my_reaction === "like");
          }
          if (dBtn) {
            const dIcon = dBtn.querySelector("i");
            if (dIcon)
              dIcon.className = `bi bi-hand-thumbs-down${data.my_reaction === "dislike" ? "-fill" : ""} fs-5`;
            dBtn.classList.toggle("active", data.my_reaction === "dislike");
            dBtn.classList.toggle("text-white", data.my_reaction === "dislike");
          }
    
          const buildTree = (comments, parent = null) => {
            const children = comments.filter((c) => c.parent_id == parent);
            if (children.length === 0) return "";
    
            const renderContent = (raw) => {
              let decoded = decodeHTML(raw || "");
              let parsed = parseUserText(decoded);
              if (typeof marked !== "undefined") {
                try {
                  parsed = marked.parse(parsed);
                } catch (e) {}
              }
              return `<div class="rich-comment-box" style="font-size: 0.95rem; line-height: 1.6; word-break: break-word; color: #f1f1f1;">${parsed}</div>`;
            };
    
            const styleInjection =
              parent === null
                ? `
                <style>
                  .rich-comment-box img, .rich-comment-box video, .rich-comment-box iframe { max-width: 100%; max-height: 400px; border-radius: 12px; margin: 10px 0; box-shadow: 0 8px 24px rgba(0,0,0,0.5); border: 1px solid rgba(255,255,255,0.1); object-fit: contain; background: #000; transition: transform 0.3s ease; }
                  .rich-comment-box img:hover { transform: scale(1.02); }
                  .rich-comment-box a { color: #3ea6ff; text-decoration: none; font-weight: 500; padding: 2px 4px; border-radius: 4px; transition: all 0.2s ease; }
                  .rich-comment-box a:hover { color: #fff; background: rgba(62,166,255,0.2); }
                  .rich-comment-box blockquote { border-left: 4px solid #ff0055; padding: 12px 20px; margin: 16px 0; background: linear-gradient(90deg, rgba(255,0,85,0.1) 0%, transparent 100%); border-radius: 0 12px 12px 0; color: #ddd; font-style: italic; font-size: 1.05rem; }
                  .rich-comment-box pre { background: #080808; padding: 16px; border-radius: 12px; border: 1px solid #222; overflow-x: auto; margin: 16px 0; box-shadow: inset 0 4px 10px rgba(0,0,0,0.5); }
                  .rich-comment-box code { font-family: 'Consolas', 'Courier New', monospace; background: rgba(255,255,255,0.08); padding: 3px 6px; border-radius: 6px; font-size: 0.85em; color: #ff8888; }
                  .rich-comment-box ul, .rich-comment-box ol { padding-left: 24px; margin-bottom: 12px; }
                  .rich-comment-box li { margin-bottom: 6px; }
                  .rich-comment-box p { margin-bottom: 12px; }
                  .rich-comment-box p:last-child { margin-bottom: 0; }
                  .rich-comment-box .mention-link { color: #ff4da6; background: rgba(255,77,166,0.15); padding: 2px 8px; border-radius: 12px; transition: 0.2s; border: 1px solid rgba(255,77,166,0.3); display: inline-block; font-weight: bold; }
                  .rich-comment-box .mention-link:hover { background: rgba(255,77,166,0.3); color: #fff; transform: translateY(-2px); box-shadow: 0 4px 12px rgba(255,77,166,0.3); }
                  .phpmusic-comments-action-btn { transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1); border-radius: 50px; padding: 6px 16px; font-weight: 600; display: inline-flex; align-items: center; justify-content: center; gap: 8px; background: rgba(255,255,255,0.05); color: #aaa; border: 1px solid rgba(255,255,255,0.02); cursor: pointer; backdrop-filter: blur(4px); }
                  .phpmusic-comments-action-btn:hover { background: rgba(255,255,255,0.15); color: #fff; transform: scale(1.05); border-color: rgba(255,255,255,0.1); }
                  .phpmusic-comments-action-btn:active { transform: scale(0.95); }
                  .phpmusic-comments-action-btn.active-like { color: #fff; background: rgba(255,255,255,0.15); border-color: rgba(255,255,255,0.3); text-shadow: 0 0 8px rgba(255,255,255,0.3); }
                  .phpmusic-comments-action-btn.active-dislike { color: #fff; background: rgba(255,255,255,0.15); border-color: rgba(255,255,255,0.3); text-shadow: 0 0 8px rgba(255,255,255,0.3); }
                  @keyframes slideFadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
                </style>
              `
            : "";
    
            if (parent === null) {
              return (
                styleInjection +
                children
                  .map(
                    (c) => `
                      <div class="d-flex gap-3 mb-4 position-relative" style="animation: slideFadeIn 0.4s ease forwards;">
                        <div class="d-flex flex-column align-items-center" style="width: 50px; flex-shrink: 0;">
                          <div class="position-relative">
                            <img src="?action=get_profile_picture&id=${c.u_id}"
                                 class="rounded-circle shadow-lg ${c.is_disabled ? "" : "user-profile-link"}"
                                 data-userid="${c.u_id}"
                                 data-artist="${encodeURIComponent(c.artist)}"
                                 style="width:50px; height:50px; object-fit:cover; cursor:${c.is_disabled ? "default" : "pointer"}; border: 2px solid rgba(255,255,255,0.08); transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), border-color 0.3s;"
                                 onmouseover="this.style.transform='scale(1.15) rotate(5deg)'; this.style.borderColor='var(--ytm-accent)';"
                                 onmouseout="this.style.transform='scale(1) rotate(0deg)'; this.style.borderColor='rgba(255,255,255,0.08)';">
                            ${c.u_id == currentUser?.id ? `<span class="position-absolute bottom-0 end-0 bg-success border border-secondary rounded-circle shadow-sm" style="width: 14px; height: 14px; z-index: 2;" title="You"></span>` : ""}
                          </div>
                        </div>
    
                        <div class="flex-grow-1" style="min-width: 0;">
                          <div class="d-flex justify-content-between align-items-start mb-2">
                            <div class="d-flex align-items-center flex-wrap gap-2">
                              <span class="fw-bolder text-white ${c.is_disabled ? "" : "user-profile-link"}"
                                    data-userid="${c.u_id}"
                                    data-artist="${encodeURIComponent(c.artist)}"
                                    style="font-size: 1rem; cursor:${c.is_disabled ? "default" : "pointer"}; letter-spacing: 0.3px; text-shadow: 0 2px 4px rgba(0,0,0,0.8);"
                                    onmouseover="this.style.textDecoration='underline'"
                                    onmouseout="this.style.textDecoration='none'">
                                ${escapeHTML(c.artist)}
                              </span>
                              <span class="text-secondary d-flex align-items-center gap-1 fw-medium" style="font-size: 0.75rem; opacity: 0.8; background: rgba(255,255,255,0.05); padding: 2px 8px; border-radius: 50px;">
                                <i class="bi bi-clock"></i> ${timeAgo(c.created_at)}
                              </span>
                            </div>
                            ${
                              currentUser &&
                              (currentUser.id == c.u_id ||
                                currentUser.status === "super_admin" ||
                                currentUser.is_admin == 1)
                                ? `
                              <div class="position-relative flex-shrink-0 ms-2 custom-opt-dropdown">
                                <button class="btn btn-link text-secondary p-0 border-0 custom-opt-toggle" type="button"><i class="bi bi-three-dots-vertical fs-5"></i></button>
                                <ul class="dropdown-menu dropdown-menu-dark shadow-lg border-secondary custom-opt-menu" style="position: absolute; right: 0; top: 100%; display: none; z-index: 1060; min-width: 150px;">
                                  <li><button class="dropdown-item edit-comment-btn" data-id="${c.id}" data-content="${escapeHTML(c.content)}"><i class="bi bi-pencil"></i> Edit</button></li>
                                  <li><button class="dropdown-item text-danger delete-comment-btn" data-id="${c.id}"><i class="bi bi-trash2"></i> Delete</button></li>
                                </ul>
                              </div>
                            `
                                : ""
                            }
                          </div>
    
                          <div class="p-3 mb-3 rounded-4">
                            ${renderContent(c.content)}
                          </div>
    
                          ${
                            currentUser
                              ? `
                          <div class="d-flex align-items-center flex-wrap gap-2 mt-1">
                            <button class="phpmusic-comments-action-btn comment-react-btn ${c.my_reaction === "like" ? "active-like" : ""}" data-id="${c.id}" data-reaction="like" title="Like">
                              <i class="bi ${c.my_reaction === "like" ? "bi-hand-thumbs-up-fill" : "bi-hand-thumbs-up"} fs-5"></i>
                              <span>${c.like_count || 0}</span>
                            </button>
    
                            <button class="phpmusic-comments-action-btn comment-react-btn ${c.my_reaction === "dislike" ? "active-dislike" : ""}" data-id="${c.id}" data-reaction="dislike" title="Dislike">
                              <i class="bi ${c.my_reaction === "dislike" ? "bi-hand-thumbs-down-fill" : "bi-hand-thumbs-down"} fs-5"></i>
                              <span>${c.dislike_count || 0}</span>
                            </button>
    
                            <button class="phpmusic-comments-action-btn reply-btn" data-id="${c.id}" data-root-id="${c.id}" data-username="${escapeHTML(c.artist)}" data-content="${escapeHTML(c.content)}" title="Reply to ${escapeHTML(c.artist)}">
                              <i class="bi bi-chat-left-text fs-5"></i> Reply ${children.filter((ch) => ch.parent_id == c.id).length > 0 ? `(${children.filter((ch) => ch.parent_id == c.id).length})` : ""}
                            </button>
                          </div>
                          `
                              : `
                          <div class="d-flex align-items-center gap-3 text-secondary fw-bold" style="font-size: 0.9rem;">
                            <span class="d-flex align-items-center gap-2 bg-dark px-3 py-1 rounded-pill border border-secondary shadow-sm"><i class="bi bi-hand-thumbs-up-fill text-white fs-5"></i> ${c.like_count || 0}</span>
                            <span class="d-flex align-items-center gap-2 bg-dark px-3 py-1 rounded-pill border border-secondary shadow-sm"><i class="bi bi-hand-thumbs-down-fill text-white fs-5"></i> ${c.dislike_count || 0}</span>
                          </div>
                          `
                          }
                          <div class="mt-4">${buildTree(comments, c.id)}</div>
                        </div>
                      </div>
                    `,
                  )
                .join("")
              );
            } else {
              const repliesHtml = children
                .map(
                  (c) => `
                    <div class="d-flex gap-3 mb-3 position-relative border-start border-top border-secondary rounded-4 p-2" style="animation: slideFadeIn 0.3s ease forwards;">
                      <div class="d-flex flex-column align-items-center" style="width: 36px; flex-shrink: 0;">
                        <img src="?action=get_profile_picture&id=${c.u_id}"
                             class="rounded-circle shadow-sm ${c.is_disabled ? "" : "user-profile-link"}"
                             data-userid="${c.u_id}"
                             data-artist="${encodeURIComponent(c.artist)}"
                             style="width:36px; height:36px; object-fit:cover; cursor:${c.is_disabled ? "default" : "pointer"}; border: 1px solid rgba(255,255,255,0.15); transition: transform 0.3s;"
                             onmouseover="this.style.transform='scale(1.15)'"
                             onmouseout="this.style.transform='scale(1)'">
                      </div>
  
                      <div class="flex-grow-1" style="min-width: 0;">
                        <div class="d-flex justify-content-between align-items-start mb-1">
                          <div class="d-flex align-items-center flex-wrap gap-2">
                            <span class="fw-bold text-white ${c.is_disabled ? "" : "user-profile-link"}"
                                  data-userid="${c.u_id}"
                                  data-artist="${encodeURIComponent(c.artist)}"
                                  style="font-size: 0.85rem; cursor:${c.is_disabled ? "default" : "pointer"}; text-shadow: 0 1px 2px rgba(0,0,0,0.5);"
                                  onmouseover="this.style.textDecoration='underline'"
                                  onmouseout="this.style.textDecoration='none'">
                              ${escapeHTML(c.artist)}
                            </span>
                            <span class="text-secondary d-flex align-items-center gap-1 fw-medium" style="font-size: 0.7rem; opacity: 0.7;">
                              <i class="bi bi-clock"></i> ${timeAgo(c.created_at)}
                            </span>
                          </div>
                          ${
                            currentUser &&
                            (currentUser.id == c.u_id ||
                              currentUser.status === "super_admin" ||
                              currentUser.is_admin == 1)
                              ? `
                            <div class="position-relative flex-shrink-0 ms-2 custom-opt-dropdown">
                              <button class="btn btn-link text-secondary p-0 border-0 custom-opt-toggle" type="button"><i class="bi bi-three-dots-vertical fs-5"></i></button>
                              <ul class="dropdown-menu dropdown-menu-dark shadow-lg border-secondary custom-opt-menu" style="position: absolute; right: 0; top: 100%; display: none; z-index: 1060; min-width: 150px;">
                                <li><button class="dropdown-item edit-comment-btn" data-id="${c.id}" data-content="${escapeHTML(c.content)}"><i class="bi bi-pencil"></i> Edit</button></li>
                                <li><button class="dropdown-item text-danger delete-comment-btn" data-id="${c.id}"><i class="bi bi-trash2"></i> Delete</button></li>
                              </ul>
                            </div>
                          `
                              : ""
                          }
                        </div>
  
                        <div class="p-2 mb-2">
                          ${renderContent(c.content)}
                        </div>
  
                        ${
                          currentUser
                            ? `
                        <div class="d-flex align-items-center flex-wrap gap-2 mt-1">
                          <button class="phpmusic-comments-action-btn comment-react-btn ${c.my_reaction === "like" ? "active-like" : ""}" data-id="${c.id}" data-reaction="like" style="padding: 4px 10px; font-size: 0.8rem;">
                            <i class="bi ${c.my_reaction === "like" ? "bi-hand-thumbs-up-fill" : "bi-hand-thumbs-up"}"></i>
                            <span>${c.like_count || 0}</span>
                          </button>
  
                          <button class="phpmusic-comments-action-btn comment-react-btn ${c.my_reaction === "dislike" ? "active-dislike" : ""}" data-id="${c.id}" data-reaction="dislike" style="padding: 4px 10px; font-size: 0.8rem;">
                            <i class="bi ${c.my_reaction === "dislike" ? "bi-hand-thumbs-down-fill" : "bi-hand-thumbs-down"}"></i>
                            <span>${c.dislike_count || 0}</span>
                          </button>
  
                          <button class="phpmusic-comments-action-btn reply-btn" data-id="${c.id}" data-root-id="${parent}" data-username="${escapeHTML(c.artist)}" data-content="${escapeHTML(c.content)}" style="padding: 4px 10px; font-size: 0.8rem;">
                            <i class="bi bi-chat-left-text"></i> Reply
                          </button>
                        </div>
                        `
                            : `
                        <div class="d-flex align-items-center gap-3 text-secondary fw-bold" style="font-size: 0.8rem;">
                          <span class="d-flex align-items-center gap-1 bg-dark px-2 py-1 rounded-pill border border-secondary shadow-sm"><i class="bi bi-hand-thumbs-up-fill text-white"></i> ${c.like_count || 0}</span>
                          <span class="d-flex align-items-center gap-1 bg-dark px-2 py-1 rounded-pill border border-secondary shadow-sm"><i class="bi bi-hand-thumbs-down-fill text-white"></i> ${c.dislike_count || 0}</span>
                        </div>
                        `
                        }
                        <div class="mt-2">${buildTree(comments, c.id)}</div>
                      </div>
                    </div>
                  `,
                )
                .join("");
    
              return `
                <div class="ps-3 ms-2 position-relative mt-2" style="border-left: 2px solid rgba(255,255,255,0.1); border-radius: 0 0 0 12px;">
                  <button class="btn btn-link text-info text-decoration-none fw-bold d-inline-flex align-items-center gap-2 toggle-replies-btn mb-3 p-0" data-target="comment-reply-container-${parent}" style="font-size: 0.95rem; transition: 0.2s;" onmouseover="this.style.textShadow='0 0 12px rgba(0, 188, 212, 0.6)'" onmouseout="this.style.textShadow='none'">
                    <div class="d-flex align-items-center justify-content-center bg-info text-dark rounded-circle shadow-sm" style="width: 24px; height: 24px;">
                      <i class="bi bi-chevron-down" style="font-size: 0.85rem;"></i>
                    </div>
                    View ${children.length} ${children.length === 1 ? "reply" : "replies"}
                  </button>
                  <div id="comment-reply-container-${parent}" class="d-none mt-2 pt-2">
                    ${repliesHtml}
                  </div>
                </div>
              `;
            }
          };
    
          const commentsList = document.getElementById("comments-list");
          if (commentsList) {
            const newHtml =
              buildTree(data.comments) ||
              (reset
                ? '<p class="text-secondary text-center mt-3">No comments yet.</p>'
                : "");
            if (reset) {
              preserveReplyState(newHtml, "comments-list");
            } else {
              commentsList.insertAdjacentHTML("beforeend", newHtml);
            }
    
            const btnContainer = document.getElementById(
              "load-more-comments-container",
            );
            if (btnContainer) {
              const rootCount = data.comments.filter(
                (c) => c.parent_id == null,
              ).length;
              if (rootCount >= 25) {
                btnContainer.classList.remove("d-none");
                if (loadMoreBtn) loadMoreBtn.innerHTML = "Load More Comments";
              } else {
                btnContainer.classList.add("d-none");
              }
            }
            window.checkMediaCache();
          }
        };
    
        // Attach global listener for comments modals once
        if (!window.commentsGlobalListenerAttached) {
          window.commentsGlobalListenerAttached = true;
    
          document.addEventListener("click", async (e) => {
            const mentionLink = e.target.closest(".mention-link");
            if (mentionLink) {
              e.stopPropagation();
              bootstrap.Modal.getInstance(
                document.getElementById("comments-modal"),
              ).hide();
              const artistName = mentionLink.dataset.artist;
              loadView({
                type: "artist_songs",
                param: artistName,
                sort: "album_asc",
                filter_user_id: "",
                artist_name: "",
              });
              hideMobileSidebar();
              return;
            }
            const userLink = e.target.closest(".user-profile-link");
            if (userLink) {
              const userId = userLink.dataset.userid;
              const artistName = decodeURIComponent(userLink.dataset.artist);
              const commentsModal = bootstrap.Modal.getInstance(
                document.getElementById("comments-modal"),
              );
              if (commentsModal) commentsModal.hide();
              const connectionsModal = bootstrap.Modal.getInstance(
                document.getElementById("connections-modal"),
              );
              if (connectionsModal) connectionsModal.hide();
              loadView({
                type: "artist_songs",
                param: artistName,
                sort: "album_asc",
                filter_user_id: userId,
                artist_name: "",
              });
              return;
            }
            const replyBtn = e.target.closest(".reply-btn");
            if (replyBtn) {
              const rootId = replyBtn.dataset.rootId || replyBtn.dataset.id;
              const replyToId = replyBtn.dataset.id;
              const username = replyBtn.dataset.username;
              const content = replyBtn.dataset.content || "";
    
              document.getElementById("reply-comment-parent-id").value = rootId;
              document.getElementById("reply-comment-reply-to-id").value = replyToId;
              const preview = document.getElementById("reply-comment-preview");
              if (preview) {
                preview.innerHTML = `<strong class="text-white">Replying to ${escapeHTML(username)}:</strong><br><span class="text-secondary text-truncate d-block">${escapeHTML(content).replace(/<[^>]*>?/gm, "")}</span>`;
              }
    
              const input = document.getElementById("reply-comment-input");
              if (username) {
                const cleanedUsername = username.replace(/\s+/g, "");
                input.value = `@${cleanedUsername} `;
              } else {
                input.value = "";
              }
    
              bootstrap.Modal.getOrCreateInstance(
                document.getElementById("reply-comment-modal"),
              ).show();
              setTimeout(() => input.focus(), 500);
              return;
            }
            const reactBtn = e.target.closest(".comment-react-btn");
            if (reactBtn) {
              e.stopPropagation();
              if (!currentUser) return showToast("Please login", "error");
              const reaction = reactBtn.dataset.reaction;
              const iconEl = reactBtn.querySelector("i");
              const spanEl = reactBtn.querySelector("span");
              let count = parseInt(spanEl.textContent) || 0;
              const isFilled =
                iconEl.classList.contains("bi-hand-thumbs-up-fill") ||
                iconEl.classList.contains("bi-hand-thumbs-down-fill");
    
              if (isFilled) {
                iconEl.className = `bi bi-hand-thumbs-${reaction === "like" ? "up" : "down"} fs-5`;
                spanEl.textContent = Math.max(0, count - 1);
              } else {
                const sibling = reactBtn.parentElement.querySelector(
                  `[data-reaction="${reaction === "like" ? "dislike" : "like"}"]`,
                );
                if (sibling) {
                  const sibIcon = sibling.querySelector("i");
                  if (
                    sibIcon.classList.contains("bi-hand-thumbs-up-fill") ||
                    sibIcon.classList.contains("bi-hand-thumbs-down-fill")
                  ) {
                    sibIcon.className = `bi bi-hand-thumbs-${reaction === "like" ? "down" : "up"} fs-5`;
                    const sibSpan = sibling.querySelector("span");
                    sibSpan.textContent = Math.max(
                      0,
                      (parseInt(sibSpan.textContent) || 0) - 1,
                    );
                  }
                }
                iconEl.className = `bi bi-hand-thumbs-${reaction === "like" ? "up" : "down"}-fill fs-5`;
                spanEl.textContent = count + 1;
              }
    
              fetchData("?action=toggle_comment_reaction", {
                method: "POST",
                body: JSON.stringify({
                  comment_id: reactBtn.dataset.id,
                  reaction: reaction,
                }),
              });
              return;
            }
            const editBtn = e.target.closest(".edit-comment-btn");
            if (editBtn) {
              document.getElementById("edit-comment-id").value = editBtn.dataset.id;
              document.getElementById("edit-comment-input").value = decodeHTML(
                editBtn.dataset.content,
              );
              bootstrap.Modal.getOrCreateInstance(
                document.getElementById("edit-comment-modal"),
              ).show();
              return;
            }
            const deleteBtn = e.target.closest(".delete-comment-btn");
            if (deleteBtn) {
              if (confirm("Delete this comment?")) {
                await fetchData("?action=delete_song_comment", {
                  method: "POST",
                  body: JSON.stringify({
                    comment_id: deleteBtn.dataset.id,
                  }),
                });
                window.refreshComments(true);
              }
              return;
            }
          });
    
          document
            .getElementById("load-more-comments-btn")
            ?.addEventListener("click", () => {
              currentCommentsPage++;
              window.refreshComments(false);
            });
        }
    
        window.handleReaction = async (reaction, btnEl) => {
          if (!currentUser) return showToast("Please login", "error");
    
          const iconEl = btnEl.querySelector("i");
          const countEl = btnEl.querySelector("span");
          let count = parseInt(countEl.textContent) || 0;
          const isLiked =
            iconEl.classList.contains("bi-hand-thumbs-up-fill") ||
            iconEl.classList.contains("bi-hand-thumbs-down-fill");
    
          if (isLiked) {
            iconEl.className = `bi bi-hand-thumbs-${reaction === "like" ? "up" : "down"} fs-5`;
            countEl.textContent = Math.max(0, count - 1);
          } else {
            const siblingId =
              reaction === "like" ? "song-dislike-btn" : "song-like-btn";
            const sibling = document.getElementById(siblingId);
            if (sibling) {
              const sibIcon = sibling.querySelector("i");
              if (
                sibIcon.classList.contains("bi-hand-thumbs-up-fill") ||
                sibIcon.classList.contains("bi-hand-thumbs-down-fill")
              ) {
                sibIcon.className = `bi bi-hand-thumbs-${reaction === "like" ? "down" : "up"} fs-5`;
                const sibCountEl = sibling.querySelector("span");
                sibCountEl.textContent = Math.max(
                  0,
                  (parseInt(sibCountEl.textContent) || 0) - 1,
                );
              }
            }
            iconEl.className = `bi bi-hand-thumbs-${reaction === "like" ? "up" : "down"}-fill fs-5`;
            countEl.textContent = count + 1;
          }
    
          fetchData("?action=toggle_song_reaction", {
            method: "POST",
            body: JSON.stringify({
              song_id: activeCommentSongId,
              reaction: reaction,
            }),
          });
        };
    
        const songLikeBtn = document.getElementById("song-like-btn");
        const songDislikeBtn = document.getElementById("song-dislike-btn");
        const commentForm = document.getElementById("comment-form");
        const editCommentForm = document.getElementById("edit-comment-form");
        const editPostForm = document.getElementById("edit-post-form");
    
        if (songLikeBtn) {
          songLikeBtn.addEventListener("click", () =>
            window.handleReaction("like", songLikeBtn),
          );
        }
        if (songDislikeBtn) {
          songDislikeBtn.addEventListener("click", () =>
            window.handleReaction("dislike", songDislikeBtn),
          );
        }
    
        if (commentForm) {
          commentForm.addEventListener("submit", async (e) => {
            e.preventDefault();
            if (!currentUser) return showToast("Please login", "error");
    
            const submitBtn = commentForm.querySelector('button[type="submit"]');
            if (!window.checkPostCooldown(submitBtn)) return;
    
            const input = document.getElementById("comment-input");
    
            if (submitBtn) {
              submitBtn.dataset.origHtml = submitBtn.innerHTML;
              submitBtn.disabled = true;
              submitBtn.innerHTML =
                '<span class="spinner-border spinner-border-sm"></span>';
            }
    
            await fetchData("?action=add_song_comment", {
              method: "POST",
              body: JSON.stringify({
                song_id: activeCommentSongId,
                parent_id: document.getElementById("comment-parent-id").value || null,
                content: input.value,
              }),
            });
    
            if (submitBtn) {
              submitBtn.disabled = false;
              submitBtn.innerHTML = submitBtn.dataset.origHtml;
            }
    
            window.lastPostTime = Date.now();
            input.value = "";
            document.getElementById("comment-parent-id").value = "";
            input.placeholder = "Add a comment... (use @ to mention)";
            window.refreshComments(true);
          });
        }
    
        const replyCommentForm = document.getElementById("reply-comment-form");
        if (replyCommentForm) {
          replyCommentForm.addEventListener("submit", async (e) => {
            e.preventDefault();
            if (!currentUser) return showToast("Please login", "error");
    
            const submitBtn = replyCommentForm.querySelector('button[type="submit"]');
            if (!window.checkPostCooldown(submitBtn)) return;
    
            const input = document.getElementById("reply-comment-input");
            const parentId = document.getElementById("reply-comment-parent-id").value;
    
            if (!input.value.trim()) return;
    
            if (submitBtn) {
              submitBtn.dataset.origHtml = submitBtn.innerHTML;
              submitBtn.disabled = true;
              submitBtn.innerHTML =
                '<span class="spinner-border spinner-border-sm"></span>';
