            const replyToId = document.getElementById(
              "reply-comment-reply-to-id",
            ).value;
            const res = await fetchData("?action=add_song_comment", {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
              },
              body: JSON.stringify({
                song_id: parseInt(activeCommentSongId),
                parent_id: parentId ? parseInt(parentId) : null,
                reply_to_id: replyToId ? parseInt(replyToId) : null,
                content: input.value,
              }),
            });
    
            if (submitBtn) {
              submitBtn.disabled = false;
              submitBtn.innerHTML = submitBtn.dataset.origHtml;
            }
    
            window.lastPostTime = Date.now();
            input.value = "";
            document.getElementById("reply-comment-parent-id").value = "";
    
            bootstrap.Modal.getInstance(
              document.getElementById("reply-comment-modal"),
            )?.hide();
            window.refreshComments(true);
          });
