        document.addEventListener("change", (e) => {
          if (e.target.id === "blog-comments-sort-select") {
            window.refreshBlogComments(true);
          }
        });
    
        window.openNoteModal = (id = "", title = "", content = "") => {
          document.getElementById("note-id").value = id;
          document.getElementById("note-title").value = title;
          document.getElementById("note-content").value = content;
          bootstrap.Modal.getOrCreateInstance(
            document.getElementById("note-modal"),
          ).show();
        };
    
        window.deleteNote = async (id) => {
          if (!confirm("Delete this note?")) return;
          await fetchData("?action=delete_note", {
            method: "POST",
            body: JSON.stringify({
              id,
            }),
          });
          loadView(currentView);
        };
    
        window.loadManageCategoriesPage = (type) => {
          const list = document.getElementById("cat-manage-list-page");
          const catArray =
            type === "task"
              ? window.taskCategories
              : type === "blog"
                ? window.blogCategories
                : type === "imageditor"
                  ? window.imageditorCategories
                  : window.noteCategories;
          if (list && catArray) {
            list.innerHTML = catArray
              .map(
                (c) => `
                  <div class="cat-manage-item">
                    <span class="text-white fw-medium">${escapeHTML(c.name)}</span>
                    <div class="d-flex gap-2">
                      <button class="note-icon-btn edit-cat-btn" data-id="${c.id}" data-name="${escapeHTML(c.name)}" data-type="${type}"><i class="bi bi-pencil"></i></button>
                      <button class="note-icon-btn text-danger del-cat-btn" data-id="${c.id}" data-type="${type}"><i class="bi bi-trash2"></i></button>
                    </div>
                  </div>
                `,
              )
              .join("");
          }
        };
    
        // Event Delegation for the dynamically rendered Category Page
        document.addEventListener("click", async (e) => {
          const addCatBtnPage = e.target.closest("#addCatBtnPage");
          if (addCatBtnPage) {
            const input = document.getElementById("newCatInputPage");
            const type = input.dataset.type || "note";
            const name = input.value.trim();
            if (!name) return;
            const id = "cat_" + Date.now();
            await fetchData("?action=save_note_category", {
              method: "POST",
              body: JSON.stringify({
                id,
                name,
                type,
              }),
            });
            if (!window.blogCategories) window.blogCategories = [];
            if (!window.imageditorCategories) window.imageditorCategories = [];
            if (type === "task") {
              window.taskCategories.push({ id, name });
            } else if (type === "blog") {
              window.blogCategories.push({ id, name });
            } else if (type === "imageditor") {
              window.imageditorCategories.push({ id, name });
            } else {
              window.noteCategories.push({ id, name });
            }
            input.value = "";
            window.loadManageCategoriesPage(type);
            window.renderNoteCategories();
            return;
          }
    
          const editBtn = e.target.closest(".edit-cat-btn");
          if (editBtn && e.target.closest("#cat-manage-list-page")) {
            const type = editBtn.dataset.type || "note";
            const newName = prompt(
              "Rename category:",
              decodeHTML(editBtn.dataset.name),
            );
            if (newName && newName.trim()) {
              await fetchData("?action=save_note_category", {
                method: "POST",
                body: JSON.stringify({
                  id: editBtn.dataset.id,
                  name: newName.trim(),
                  type,
                }),
              });
              if (!window.blogCategories) window.blogCategories = [];
              const catArray =
                type === "task"
                  ? window.taskCategories
                  : type === "blog"
                    ? window.blogCategories
                    : type === "imageditor"
                      ? window.imageditorCategories
                      : window.noteCategories;
              const cat = catArray.find((c) => c.id === editBtn.dataset.id);
              if (cat) cat.name = newName.trim();
              window.loadManageCategoriesPage(type);
              window.renderNoteCategories();
            }
            return;
          }
    
          const delBtn = e.target.closest(".del-cat-btn");
          if (delBtn && e.target.closest("#cat-manage-list-page")) {
            const type = delBtn.dataset.type || "note";
            if (confirm("Delete category? Items will become Uncategorized.")) {
              await fetchData("?action=delete_note_category", {
                method: "POST",
                body: JSON.stringify({
                  id: delBtn.dataset.id,
                  type,
                }),
              });
              if (!window.blogCategories) window.blogCategories = [];
              if (!window.imageditorCategories) window.imageditorCategories = [];
              if (type === "task") {
                window.taskCategories = window.taskCategories.filter(c => c.id !== delBtn.dataset.id);
              } else if (type === "blog") {
                window.blogCategories = window.blogCategories.filter(c => c.id !== delBtn.dataset.id);
              } else if (type === "imageditor") {
                window.imageditorCategories = window.imageditorCategories.filter(c => c.id !== delBtn.dataset.id);
              } else {
                window.noteCategories = window.noteCategories.filter(c => c.id !== delBtn.dataset.id);
              }
              window.loadManageCategoriesPage(type);
              window.renderNoteCategories();
            }
            return;
          }
