            document.getElementById("fileImportTasks").click();
          });
        document
          .getElementById("export-json-tasks-menu")
          ?.addEventListener("click", async (e) => {
            e.preventDefault();
            const tasks = await fetchData("?action=export_tasks");
            const blob = new Blob([JSON.stringify(tasks, null, 2)], {
              type: "application/json",
            });
            const a = document.createElement("a");
            a.href = URL.createObjectURL(blob);
            a.download = `TasksBackup_${Date.now()}.json`;
            a.click();
          });
    
        document
          .getElementById("fileImportTasks")
          ?.addEventListener("change", async (e) => {
            const file = e.target.files[0];
            if (!file) return;
            const text = await file.text();
            try {
              let importData = JSON.parse(text);
              let proceed = false;
              if (importData.tasks) {
                proceed = true;
              }
              if (proceed) {
                const result = await fetchData("?action=import_tasks", {
                  method: "POST",
                  headers: {
                    "Content-Type": "application/json",
                  },
                  body: JSON.stringify(importData),
                });
                if (result) {
                  showToast(result.message, result.status);
                  requestCache.clear();
                  if (currentView.type === "get_tasks") loadView(currentView);
                }
              } else {
                showToast("Invalid Task JSON format.", "error");
              }
            } catch (err) {
              showToast("Invalid JSON file.", "error");
            }
            e.target.value = "";
          });
    
