        document
          .getElementById("fileImportTxt")
          ?.addEventListener("change", async (e) => {
            const files = e.target.files;
            if (!files.length) return;
            for (let file of files) {
              const text = await file.text();
              await fetchData(
                "?action=save_note",
                {
                  method: "POST",
                  body: JSON.stringify({
                    id: null,
                    title: file.name.replace(/\.txt$/i, ""),
                    content: text,
                    category: "all",
                    starred: 0,
                  }),
                },
                true,
              );
            }
            showToast("Imported TXT files", "success");
            e.target.value = "";
            if (currentView.type === "get_notes") loadView(currentView);
          });
    
        document
          .getElementById("fileImportJson")
          ?.addEventListener("change", async (e) => {
            const file = e.target.files[0];
            if (!file) return;
            const text = await file.text();
            try {
              let data = JSON.parse(text);
              if (data && typeof data === "object" && !Array.isArray(data))
                data = Object.values(data);
              if (Array.isArray(data)) {
                for (let n of data) {
                  if (!n.id) continue;
                  await fetchData(
                    "?action=save_note",
                    {
                      method: "POST",
                      body: JSON.stringify({
                        id: null,
                        title: n.title || "",
                        content: n.content || "",
                        category: "all",
                        starred: n.starred || n.favorite ? 1 : 0,
                      }),
                    },
                    true,
                  );
                }
                showToast("Imported JSON successfully", "success");
                if (currentView.type === "get_notes") loadView(currentView);
              }
            } catch (err) {
              showToast("Invalid JSON file.", "error");
            }
            e.target.value = "";
          });
    
        window.togglePostReaction = async (post_id, reaction) => {
          await fetchData("?action=toggle_post_reaction", {
            method: "POST",
