            }),
          });
          loadView(currentView);
        };
        contentArea.addEventListener("click", async (e) => {
          const target = e.target;
    
          const clearHistoryBtn = target.closest("#clear-history-btn");
          if (clearHistoryBtn) {
            e.stopPropagation();
            if (
              confirm(
                "Are you sure you want to clear your entire listening history? This cannot be undone.",
              )
            ) {
              const result = await fetchData("?action=clear_history");
              if (result && result.status === "success") {
                showToast(result.message, "success");
                loadView({
                  type: "get_history",
                  param: "",
                  sort: "history_desc",
                  filter_user_id: "",
                });
              }
            }
            return;
          }
    
          const mentionLink = target.closest(".mention-link");
          if (mentionLink) {
            e.stopPropagation();
            const artistName = mentionLink.dataset.artist;
            loadView({
              type: "artist_songs",
              param: artistName,
              sort: "album_asc",
              filter_user_id: "",
              artist_name: "",
            });
            hideMobileSidebar();
            return;
          }
    
          if (multiSelectMode) {
            const songItem = target.closest(".song-item");
            if (songItem) {
              e.preventDefault();
              e.stopPropagation();
              toggleSongSelection(songItem);
              return;
            }
          }
    
          const messageBtn = target.closest(".message-btn");
          if (messageBtn) {
            e.stopPropagation();
            await loadView({
              type: "get_inbox",
              param: "",
              sort: "",
              filter_user_id: "",
            });
            window.openChatFull(
              messageBtn.dataset.userId,
              "dm",
              decodeURIComponent(messageBtn.dataset.artist),
            );
            return;
          }
    
          const reportUserBtn = target.closest(".report-user-btn");
          if (reportUserBtn) {
            e.stopPropagation();
            const reportedId = reportUserBtn.dataset.userId;
            const reason = prompt("Enter reason for reporting this profile:");
            if (reason && reason.trim() !== "") {
              const res = await fetchData("?action=report_user", {
                method: "POST",
                headers: {
                  "Content-Type": "application/json",
                },
                body: JSON.stringify({
                  reported_id: parseInt(reportedId),
                  reason: reason.trim(),
                }),
              });
              if (res) {
                showToast(res.message, res.status);
              }
            }
            return;
          }
    
          const blockBtn = target.closest(".block-btn");
          if (blockBtn) {
            e.stopPropagation();
            const userId = blockBtn.dataset.userId;
            if (
              !confirm(
                "Are you sure you want to block/unblock this user? Blocking prevents them from messaging or following you.",
              )
            )
              return;
            fetchData("?action=toggle_block", {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
              },
              body: JSON.stringify({
                blocked_id: userId,
              }),
            }).then((res) => {
              if (res && (res.status === "blocked" || res.status === "unblocked")) {
                showToast(`User ${res.status}.`, "success");
                loadView(currentView); // Refresh profile header to reflect changes
              } else {
                showToast(res?.message || "Error toggling block", "error");
              }
            });
            return;
          }
    
          const followBtn = target.closest(".follow-btn");
          if (followBtn) {
            e.stopPropagation();
            const userId = followBtn.dataset.userId;
            fetchData("?action=toggle_follow", {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
              },
              body: JSON.stringify({
                following_id: userId,
              }),
            }).then(async (res) => {
              if (res && res.status === "followed") {
                window.triggerFollowEffect(followBtn);
                followBtn.textContent = "Unfollow";
                followBtn.classList.remove("btn-danger");
                followBtn.classList.add("btn-outline-light");
    
                const countEls = document.querySelectorAll(
                  `.connection-trigger[data-id="${userId}"][data-type="followers"]`,
                );
                countEls.forEach((countEl) => {
                  let currentCount =
                    parseInt(countEl.textContent.replace(/\D/g, "")) || 0;
                  countEl.textContent =
                    formatSongCount(currentCount + 1) + " followers";
                });
    
                // Fetch Recommended Artists and show the dismissible container
                const recs = await fetchData(
                  `?action=get_recommended_artists&target_id=${userId}`,
                );
                if (recs && recs.length > 0) {
                  const alertContainer = document.getElementById(
                    "recommendation-alert-container",
                  );
                  if (alertContainer) {
                    alertContainer.innerHTML = `
                      <div class="alert bg-dark border-secondary text-white alert-dismissible fade show mt-3 position-relative shadow-lg" role="alert" style="border-radius: 12px;">
                        <h6 class="alert-heading fw-bold mb-3"><i class="bi bi-stars"></i> Because you followed this artist...</h6>
                        <div class="d-flex gap-3 overflow-auto pb-2" style="scrollbar-width: thin; scrollbar-color: rgba(255, 255, 255, 0.2) transparent;">
                          ${recs
                            .map(
                              (a) => `
                            <div class="text-center user-profile-link" data-userid="${a.id}" data-artist="${encodeURIComponent(a.artist)}" style="width: 80px; flex-shrink: 0; cursor: pointer;">
                              <img src="?action=get_profile_picture&id=${a.id}" class="rounded-circle mb-2" style="width: 60px; height: 60px; object-fit: cover;">
                              <div class="small text-truncate w-100 hover-underline">${escapeHTML(a.artist)}</div>
                            </div>
                          `,
                            )
                            .join("")}
                        </div>
                        <button type="button" class="btn-close btn-close-white" data-bs-dismiss="alert"></button>
                      </div>
                    `;
                  }
                }
              } else if (res && res.status === "unfollowed") {
                followBtn.textContent = "Follow";
                followBtn.classList.remove("btn-outline-light");
                followBtn.classList.add("btn-danger");
    
                const countEls = document.querySelectorAll(
                  `.connection-trigger[data-id="${userId}"][data-type="followers"]`,
                );
                countEls.forEach((countEl) => {
                  let currentCount =
                    parseInt(countEl.textContent.replace(/\D/g, "")) || 0;
                  countEl.textContent =
                    formatSongCount(Math.max(0, currentCount - 1)) + " followers";
                });
              } else {
                showToast(res.message || "Error toggling follow", "error");
              }
            });
            return;
          }
    
          const connTrigger = target.closest(".connection-trigger");
          if (connTrigger) {
            e.preventDefault();
            e.stopPropagation();
            const connType = connTrigger.dataset.type;
            const uId = connTrigger.dataset.id;
            const modalEl = document.getElementById("connections-modal");
            if (modalEl) {
              document.getElementById("connections-modal-title").textContent =
                connType.charAt(0).toUpperCase() + connType.slice(1);
              const listEl = document.getElementById("connections-list");
              listEl.innerHTML =
                '<div class="text-center p-4"><div class="spinner-border text-secondary"></div></div>';
              bootstrap.Modal.getOrCreateInstance(modalEl).show();
    
              window.connPage = 1;
              window.connType = connType;
              window.connUserId = uId;
              window.isLoadingConn = false;
    
              window.loadConnections = async (append = false) => {
                if (window.isLoadingConn) return;
                window.isLoadingConn = true;
    
                if (!append) {
                  listEl.innerHTML =
                    '<div class="text-center p-4"><div class="spinner-border text-secondary"></div></div>';
                } else {
                  const btn = document.getElementById("load-more-conn-btn");
                  if (btn)
                    btn.innerHTML =
                      '<span class="spinner-border spinner-border-sm"></span> Loading...';
                }
    
                const data = await fetchData(
                  `?action=get_connections&id=${window.connUserId}&conn_type=${window.connType}&page=${window.connPage}`,
                );
    
                const loadMoreBtnEl = document.getElementById(
                  "load-more-conn-btn-container",
                );
                if (loadMoreBtnEl) loadMoreBtnEl.remove();
    
                if (data && data.length > 0) {
                  const html = data
                    .map(
                      (u) => `
                        <div class="d-flex align-items-center justify-content-between gap-3 p-3 rounded-4" style="background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.05); transition: transform 0.2s, background 0.2s;" onmouseover="this.style.transform='scale(1.02)'; this.style.background='rgba(255,255,255,0.08)';" onmouseout="this.style.transform='scale(1)'; this.style.background='rgba(255,255,255,0.03)';">
                          <div class="d-flex align-items-center gap-3 user-profile-link flex-grow-1" data-userid="${u.id}" data-artist="${encodeURIComponent(u.artist)}" style="cursor: pointer; min-width: 0;" title="View Profile">
                            <div class="position-relative flex-shrink-0">
                              <img src="?action=get_profile_picture&id=${u.id}" class="rounded-circle shadow-sm" style="width: 52px; height: 52px; object-fit: cover; border: 2px solid rgba(255,255,255,0.1);">
                            </div>
                            <div class="d-flex flex-column text-truncate" style="min-width: 0;">
                              <span class="fw-bold text-white fs-6 text-truncate" style="letter-spacing: 0.3px;">${escapeHTML(u.artist)}</span>
                              <span class="text-secondary fw-medium" style="font-size: 0.8rem;">ID: ${u.id}</span>
                            </div>
                          </div>
                          ${
                            currentUser && currentUser.id != u.id
                              ? `<button class="btn btn-sm ${u.is_followed ? "btn-outline-light" : "btn-danger"} rounded-pill fw-bold follow-btn-modal px-4 py-2 flex-shrink-0 shadow-sm" data-user-id="${u.id}" style="font-size: 0.85rem; transition: transform 0.1s;">
                                   ${u.is_followed ? "Unfollow" : "Follow"}
                                 </button>`
                              : ""
                          }
                        </div>
                      `,
                    )
                    .join("");
    
                  if (!append) listEl.innerHTML = html;
                  else listEl.insertAdjacentHTML("beforeend", html);
    
                  if (data.length === 25) {
                    listEl.insertAdjacentHTML(
                      "beforeend",
                      `
                        <div class="text-center p-3" id="load-more-conn-btn-container">
                          <button class="btn btn-sm btn-outline-light rounded-pill px-4" id="load-more-conn-btn">Load More</button>
                        </div>
                      `,
                    );
                  }
                } else {
                  if (!append)
                    listEl.innerHTML = `<div class="p-4 text-center text-secondary">No ${window.connType} found.</div>`;
                }
                window.isLoadingConn = false;
              };
    
              window.loadConnections();
            }
            return;
