              collabDropdown.onclick = (e) => {
                const item = e.target.closest(".song-collab-user-item");
                if (item) {
                  selectedCollabUserId = item.dataset.id;
                  collabInput.value = item.dataset.artist;
                  collabDropdown.classList.add("d-none");
                }
              };
    
              document.addEventListener("click", (e) => {
                if (
                  collabDropdown &&
                  !collabDropdown.contains(e.target) &&
                  e.target !== collabInput
                ) {
                  collabDropdown.classList.add("d-none");
                }
              });
    
              document.getElementById("song-collab-add-btn").onclick = async () => {
                const target = collabInput.value.trim();
                if (!target && !selectedCollabUserId) return;
    
                const reqBody = {
                  song_id: songId,
                  collab_action: "add",
                };
                if (selectedCollabUserId) reqBody.target_id = selectedCollabUserId;
                else reqBody.target = target;
    
                const res = await fetchData("?action=manage_song_collaborators", {
                  method: "POST",
                  headers: {
                    "Content-Type": "application/json",
                  },
                  body: JSON.stringify(reqBody),
                });
                if (res) {
                  showToast(res.message, res.status);
                  if (res.status === "success") {
                    loadCollabs();
                    collabInput.value = "";
                    selectedCollabUserId = null;
                  }
                }
              };
    
              const expireSelect = document.getElementById(
                "song-collab-expire-select",
              );
              const customExpireInput = document.getElementById(
                "song-collab-custom-expire",
              );
              if (expireSelect && customExpireInput) {
                expireSelect.onchange = (e) => {
                  if (e.target.value === "custom")
                    customExpireInput.classList.remove("d-none");
                  else customExpireInput.classList.add("d-none");
                };
              }
    
              const copyLinkBtn = document.getElementById(
                "song-collab-copy-link-btn",
              );
              if (copyLinkBtn) {
                const newCopyBtn = copyLinkBtn.cloneNode(true);
                copyLinkBtn.parentNode.replaceChild(newCopyBtn, copyLinkBtn);
    
                newCopyBtn.addEventListener("click", async () => {
                  let expireVal = expireSelect ? expireSelect.value : "1440";
                  if (expireVal === "custom") {
                    expireVal = customExpireInput.value.trim();
                    if (!expireVal || isNaN(expireVal) || parseInt(expireVal) <= 0) {
                      return showToast(
                        "Please enter a valid number of minutes.",
                        "error",
                      );
                    }
                  } else if (expireVal === "forever") {
                    expireVal = null;
                  }
    
                  newCopyBtn.disabled = true;
                  newCopyBtn.innerHTML =
                    '<span class="spinner-border spinner-border-sm"></span> Generating...';
    
                  const res = await fetchData("?action=manage_song_collaborators", {
                    method: "POST",
                    headers: {
                      "Content-Type": "application/json",
                    },
                    body: JSON.stringify({
                      song_id: songId,
                      collab_action: "generate_link",
                      expire: expireVal,
                    }),
                  });
    
                  if (res && res.status === "success") {
                    const inviteUrl =
                      window.location.origin +
                      window.location.pathname +
                      "?song_invite=" +
                      res.token;
                    const onSuccess = () => {
                      newCopyBtn.innerHTML =
                        '<i class="bi bi-check-lg"></i> Link Copied!';
                      newCopyBtn.classList.replace(
                        "btn-outline-light",
                        "btn-success",
                      );
                      setTimeout(() => {
                        newCopyBtn.innerHTML =
                          '<i class="bi bi-link-45deg"></i> Generate & Copy Link';
                        newCopyBtn.classList.replace(
                          "btn-success",
                          "btn-outline-light",
                        );
                      }, 2000);
                    };
                    const onError = () => showToast("Failed to copy link.", "error");
    
                    if (navigator.clipboard && window.isSecureContext) {
                      navigator.clipboard
                        .writeText(inviteUrl)
                        .then(onSuccess)
                        .catch(onError);
                    } else {
                      const textArea = document.createElement("textarea");
                      textArea.value = inviteUrl;
                      textArea.style.position = "fixed";
                      textArea.style.opacity = "0";
                      document.body.appendChild(textArea);
                      textArea.focus();
                      textArea.select();
                      try {
                        if (document.execCommand("copy")) onSuccess();
                        else onError();
                      } catch (err) {
                        onError();
                      }
                      document.body.removeChild(textArea);
                    }
                  } else {
                    showToast(res?.message || "Error generating link", "error");
                    newCopyBtn.innerHTML =
                      '<i class="bi bi-link-45deg"></i> Generate & Copy Link';
                  }
                  newCopyBtn.disabled = false;
                });
              }
    
