        if (editMetadataForm) {
          editMetadataForm.addEventListener("submit", async (e) => {
            e.preventDefault();
    
            const submitBtn = document.getElementById("edit-metadata-submit-btn");
            const progContainer = document.getElementById(
              "metadata-progress-container",
            );
            const progBar = document.getElementById("metadata-progress");
    
            submitBtn.disabled = true;
            progContainer.classList.remove("d-none");
            progBar.style.width = "0%";
            progBar.textContent = "0%";
    
            const formData = new FormData();
            formData.append("id", document.getElementById("edit-metadata-id").value);
            formData.append(
              "title",
              document.getElementById("edit-metadata-title").value,
            );
            formData.append(
              "artist",
              document.getElementById("edit-metadata-artist").value,
            );
            formData.append(
              "album",
              document.getElementById("edit-metadata-album").value,
            );
            formData.append(
              "genre",
              document.getElementById("edit-metadata-genre").value,
            );
            formData.append(
              "lyrics",
              document.getElementById("edit-metadata-lyrics").value,
            );
            formData.append(
              "is_private",
              document.getElementById("edit-metadata-is-private").checked ? 1 : 0,
            );
            formData.append(
              "is_collaborative",
              document.getElementById("edit-metadata-is-collaborative").checked
                ? 1
                : 0,
            );
    
            const doMetadataUpload = () => {
              const xhr = new XMLHttpRequest();
              xhr.upload.onprogress = (evt) => {
                if (evt.lengthComputable) {
                  const pct = Math.round((evt.loaded / evt.total) * 100);
                  progBar.style.width = pct + "%";
                  progBar.textContent = pct + "%";
                }
              };
              xhr.open("POST", "?action=edit_metadata", true);
              xhr.onload = () => {
                submitBtn.disabled = false;
                progContainer.classList.add("d-none");
                if (xhr.status === 200) {
                  try {
                    const result = JSON.parse(xhr.responseText);
                    if (result && result.status === "success") {
                      showToast(result.message, "success");
                      if (metadataCropper) {
                        metadataCropper.destroy();
                        metadataCropper = null;
                      }
                      if (editMetadataModal) editMetadataModal.hide();
                      loadView(currentView);
                    } else {
                      showToast(result.message || "Upload failed", "error");
                    }
                  } catch (err) {
                    showToast("Invalid server response.", "error");
                  }
                } else {
                  showToast("Upload error", "error");
                }
              };
              xhr.onerror = () => {
                submitBtn.disabled = false;
                progContainer.classList.add("d-none");
                showToast("Network error during upload", "error");
              };
              xhr.send(formData);
            };
    
            if (metadataCropper) {
