                }
              } catch (err) {
                showToast("Upload failed", "error");
              }
              submitBtn.disabled = false;
              submitBtn.textContent = "Save Uploaded Background";
            };
    
            if (profileBgCropper) {
              profileBgCropper
                .getCroppedCanvas({
                  width: 1200,
                  height: 400,
                })
                .toBlob(
                  (blob) => {
                    doBgUpload(blob);
                  },
                  "image/jpeg",
                  0.85,
                );
            } else {
              doBgUpload(profileBgInput.files[0]);
            }
          });
        }
    
        // --- BACKGROUND GENERATOR LOGIC ---
        const bgCanvas = document.getElementById("bg-gen-canvas");
        if (bgCanvas) {
          const bgCtx = bgCanvas.getContext("2d");
          const bgState = {
            pattern: "blobs",
            hue: Math.floor(Math.random() * 360),
            saturation: 70,
            complexity: 5,
            scale: 100,
            angle: 0,
            drawStyle: "fill",
            seed: Math.random(),
          };
          let bgRng = null;
    
          function bgMulberry32(a) {
            return function () {
              var t = (a += 0x6d2b79f5);
              t = Math.imul(t ^ (t >>> 15), t | 1);
              t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
              return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
            };
          }
    
          function bgGetHsl(h, s, l, a = 1) {
            return `hsla(${h}, ${s}%, ${l}%, ${a})`;
          }
    
          function bgGetPalette() {
            const h = bgState.hue;
            const s = bgState.saturation;
            return [
              bgGetHsl(h, s, 40),
              bgGetHsl(h, s * 0.6, 30),
              bgGetHsl((h + 40) % 360, s * 0.8, 40),
              bgGetHsl((h - 40 + 360) % 360, s * 0.8, 40),
