              for (let i = 0; i < 6; i++) {
                const a = (i * Math.PI) / 3;
                bgCtx.arc(
                  Math.cos(a) * s * 0.6,
                  Math.sin(a) * s * 0.6,
                  s * 0.4,
                  0,
                  Math.PI * 2,
                );
              }
              bgCtx.arc(0, 0, s * 0.3, 0, Math.PI * 2);
            },
          };
    
          const bgLayouts = {
            scatter: (b, pal, shapeFn) => {
              const count = bgState.complexity * 12;
              const baseSize = (b.w * (bgState.scale / 100)) / 15;
              for (let i = 0; i < count; i++) {
                bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                bgCtx.save();
                bgCtx.translate(b.x + bgRng() * b.w, b.y + bgRng() * b.h);
                bgCtx.rotate(bgRng() * Math.PI * 2);
                bgCtx.beginPath();
                shapeFn(baseSize * (0.3 + bgRng()));
                bgDrawPath();
                bgCtx.restore();
              }
            },
            grid: (b, pal, shapeFn) => {
              const step = (bgState.scale / 100) * 80 + 20;
              const size = step * (bgState.complexity / 20);
              for (let y = b.y; y < b.y + b.h; y += step) {
                for (let x = b.x; x < b.x + b.w; x += step) {
                  if (bgRng() > 0.9) continue;
                  bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                  bgCtx.save();
                  bgCtx.translate(x, y);
                  bgCtx.beginPath();
                  shapeFn(size);
                  bgDrawPath();
                  bgCtx.restore();
                }
              }
            },
            isometric: (b, pal, shapeFn) => {
              const step = (bgState.scale / 100) * 80 + 20;
              const size = step * (bgState.complexity / 20);
              let row = 0;
              for (let y = b.y; y < b.y + b.h; y += step * 0.866) {
                let off = row % 2 === 0 ? 0 : step / 2;
                for (let x = b.x; x < b.x + b.w; x += step) {
                  if (bgRng() > 0.9) continue;
                  bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                  bgCtx.save();
                  bgCtx.translate(x + off, y);
                  bgCtx.beginPath();
                  shapeFn(size);
                  bgDrawPath();
                  bgCtx.restore();
                }
                row++;
              }
            },
            concentric: (b, pal, shapeFn) => {
              const count = bgState.complexity * 3;
              const maxR = (bgState.scale / 100) * 150;
              for (let i = 0; i < count; i++) {
                const cx = b.x + bgRng() * b.w;
                const cy = b.y + bgRng() * b.h;
                const rings = 3 + Math.floor(bgRng() * 5);
                for (let r = rings; r > 0; r--) {
                  bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                  bgCtx.save();
                  bgCtx.translate(cx, cy);
                  bgCtx.beginPath();
                  shapeFn(maxR * (r / rings));
                  bgDrawPath();
                  bgCtx.restore();
                }
              }
            },
            radial: (b, pal, shapeFn) => {
              const count = bgState.complexity * 12;
              const maxR = b.w;
              const cx = 0,
                cy = 0;
              for (let i = 0; i < count; i++) {
                const a = (i / count) * Math.PI * 2;
                const r = bgRng() * maxR;
                bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                bgCtx.save();
                bgCtx.translate(cx + Math.cos(a) * r, cy + Math.sin(a) * r);
                bgCtx.rotate(a + Math.PI / 2);
                bgCtx.beginPath();
                shapeFn((bgState.scale / 100) * 40 * (0.5 + bgRng()));
                bgDrawPath();
                bgCtx.restore();
              }
            },
            spiral: (b, pal, shapeFn) => {
              const count = bgState.complexity * 15;
              const maxR = b.w;
              const cx = b.x + b.w / 2;
              const cy = b.y + b.h / 2;
              for (let i = 0; i < count; i++) {
                const a = i * 0.5;
                const r = (i / count) * maxR;
                bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                bgCtx.save();
                bgCtx.translate(cx + Math.cos(a) * r, cy + Math.sin(a) * r);
                bgCtx.rotate(a);
                bgCtx.beginPath();
                shapeFn((bgState.scale / 100) * 20 * (1 + bgRng()));
                bgDrawPath();
                bgCtx.restore();
              }
            },
            waveGrid: (b, pal, shapeFn) => {
              const step = (bgState.scale / 100) * 60 + 20;
              const size = step * (bgState.complexity / 20);
              for (let x = b.x; x < b.x + b.w; x += step) {
                let yOffset = Math.sin(x * 0.05) * 100;
                for (let y = b.y; y < b.y + b.h; y += step) {
                  bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                  bgCtx.save();
                  bgCtx.translate(x, y + yOffset);
                  bgCtx.beginPath();
                  shapeFn(size);
                  bgDrawPath();
                  bgCtx.restore();
                }
              }
            },
            zigzag: (b, pal, shapeFn) => {
              const step = (bgState.scale / 100) * 60 + 20;
              const size = step * (bgState.complexity / 20);
              let flip = false;
              for (let y = b.y; y < b.y + b.h; y += step) {
                flip = !flip;
                for (let x = b.x; x < b.x + b.w; x += step) {
                  let px = x + (flip ? step / 2 : 0);
                  bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                  bgCtx.save();
                  bgCtx.translate(px, y);
                  bgCtx.beginPath();
                  shapeFn(size);
                  bgDrawPath();
                  bgCtx.restore();
                }
              }
            },
            orbit: (b, pal, shapeFn) => {
              const cx = b.x + b.w / 2;
              const cy = b.y + b.h / 2;
              const rings = bgState.complexity;
              const maxR = b.w;
              for (let r = 1; r <= rings; r++) {
                const rad = (r / rings) * maxR;
                const items = r * 6;
                for (let i = 0; i < items; i++) {
                  const a = (i / items) * Math.PI * 2 + bgRng() * 0.5;
                  bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                  bgCtx.save();
                  bgCtx.translate(cx + Math.cos(a) * rad, cy + Math.sin(a) * rad);
                  bgCtx.rotate(a);
                  bgCtx.beginPath();
                  shapeFn((bgState.scale / 100) * 30);
                  bgDrawPath();
                  bgCtx.restore();
                }
              }
            },
            pyramid: (b, pal, shapeFn) => {
              const step = (bgState.scale / 100) * 60 + 20;
              const size = step * (bgState.complexity / 20);
              const rows = Math.floor(b.h / step);
              for (let r = 0; r < rows; r++) {
                const cols = r + 1;
                const startX = b.x + b.w / 2 - (cols * step) / 2;
                const y = b.y + r * step;
                for (let c = 0; c < cols; c++) {
                  bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                  bgCtx.save();
                  bgCtx.translate(startX + c * step, y);
                  bgCtx.beginPath();
                  shapeFn(size);
                  bgDrawPath();
                  bgCtx.restore();
                }
              }
            },
            waterfall: (b, pal, shapeFn) => {
              const cols = bgState.complexity * 5;
              const stepX = b.w / cols;
              for (let c = 0; c < cols; c++) {
                const x = b.x + c * stepX;
                const offset = bgRng() * 1000;
                for (let y = b.y; y < b.y + b.h; y += (bgState.scale / 100) * 40) {
                  const px = x + Math.sin((y + offset) * 0.02) * 30;
                  bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                  bgCtx.save();
                  bgCtx.translate(px, y);
                  bgCtx.beginPath();
                  shapeFn((bgState.scale / 100) * 15);
                  bgDrawPath();
                  bgCtx.restore();
                }
              }
            },
            vortex: (b, pal, shapeFn) => {
              const count = bgState.complexity * 12;
              const maxR = b.w;
              const cx = b.x + b.w / 2;
              const cy = b.y + b.h / 2;
              for (let i = count; i > 0; i--) {
                const a = Math.pow(i, 1.1) * 0.2;
                const r = (i / count) * maxR;
                bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                bgCtx.save();
                bgCtx.translate(cx + Math.cos(a) * r, cy + Math.sin(a) * r);
                bgCtx.rotate(a + Math.PI / 4);
                bgCtx.beginPath();
                shapeFn((bgState.scale / 100) * 40 * (i / count));
                bgDrawPath();
                bgCtx.restore();
              }
            },
          };
    
          // Compile all combinatoric variants and merge them into the master drawing function map
          Object.keys(bgLayouts).forEach((layout) => {
            Object.keys(bgShapes).forEach((shape) => {
              bgDrawFns[`${layout}_${shape}`] = (b, pal) =>
                bgLayouts[layout](b, pal, bgShapes[shape]);
            });
          });
    
          const drawWallpaper = () => {
            bgRng = bgMulberry32(Math.floor(bgState.seed * 100000));
            const w = 1200;
            const h = 400;
            bgCanvas.width = w;
            bgCanvas.height = h;
    
            bgCtx.fillStyle = bgGetHsl(bgState.hue, bgState.saturation * 0.3, 10);
            bgCtx.fillRect(0, 0, w, h);
    
            bgCtx.save();
            bgCtx.translate(w / 2, h / 2);
            bgCtx.rotate((bgState.angle * Math.PI) / 180);
    
            const diag = Math.sqrt(w * w + h * h);
            const b = {
              x: -diag / 2,
              y: -diag / 2,
              w: diag,
              h: diag,
            };
    
            if (bgDrawFns[bgState.pattern])
              bgDrawFns[bgState.pattern](b, bgGetPalette());
            bgCtx.restore();
          };
    
          const settingsModalEl = document.getElementById("settings-modal");
          if (settingsModalEl) {
            settingsModalEl.addEventListener("show.bs.modal", () => {
              document.getElementById("bg-gen-hue").value = bgState.hue;
              drawWallpaper();
            });
          }
    
          document
            .getElementById("bg-gen-pattern")
            .addEventListener("change", (e) => {
              bgState.pattern = e.target.value;
              drawWallpaper();
            });
          document.getElementById("bg-gen-style").addEventListener("change", (e) => {
            bgState.drawStyle = e.target.value;
            drawWallpaper();
          });
          document.getElementById("bg-gen-hue").addEventListener("input", (e) => {
            bgState.hue = parseInt(e.target.value);
            drawWallpaper();
          });
    
          document
            .getElementById("bg-gen-random-btn")
            .addEventListener("click", () => {
              bgState.seed = Math.random();
              bgState.hue = Math.floor(Math.random() * 360);
              document.getElementById("bg-gen-hue").value = bgState.hue;
    
              const patterns = Object.keys(bgDrawFns);
              bgState.pattern = patterns[Math.floor(Math.random() * patterns.length)];
              document.getElementById("bg-gen-pattern").value = bgState.pattern;
    
              const styles = ["fill", "stroke", "mixed"];
              bgState.drawStyle = styles[Math.floor(Math.random() * styles.length)];
              document.getElementById("bg-gen-style").value = bgState.drawStyle;
    
              drawWallpaper();
            });
    
          document.getElementById("bg-gen-save-btn").addEventListener("click", () => {
            bgCanvas.toBlob(
              async (blob) => {
                const submitBtn = document.getElementById("bg-gen-save-btn");
                submitBtn.disabled = true;
                submitBtn.innerHTML =
                  '<span class="spinner-border spinner-border-sm"></span> Saving...';
                const formData = new FormData();
                formData.append("profile_background", blob, "generated_bg.jpg");
    
                try {
                  const res = await fetch("?action=upload_profile_background", {
                    method: "POST",
                    body: formData,
                  });
                  const result = await res.json();
                  showToast(result.message, result.status);
                  if (result.status === "success") {
                    await checkSession();
                    if (currentView.type === "user_profile") loadView(currentView);
                  }
                } catch (err) {
                  showToast("Upload failed", "error");
                }
                submitBtn.disabled = false;
                submitBtn.innerHTML = "Set Background";
              },
              "image/jpeg",
              0.9,
            );
          });
        }
    
