        let noteTextHistory = [];
        let noteHistoryIdx = -1;
        let noteSaveTimeout = null;
        let noteHistoryTimeout = null;
        let activeEditorNote = null;
        let isMarkdownPreview = false;
        let presenceEventSource = null;
        let lastSyncContentTime = null;
        window.lastLocalEditTime = 0;
    
        // Initialize Google's Diff-Match-Patch library for Figma-like text merging
        const dmp =
          typeof diff_match_patch !== "undefined" ? new diff_match_patch() : null;
    
        const startPresenceSync = (itemId, itemType) => {
          if (presenceEventSource) presenceEventSource.close();
    
          const avContainer = document.getElementById(
            itemType === "task"
              ? "taskFloatingPresence"
              : itemType === "blog"
                ? "blogFloatingPresence"
                : itemType === "imageditor"
                  ? "imageditorFloatingPresence"
                  : "editorFloatingPresence",
          );
    
          // Use Server-Sent Events (SSE) which acts as a persistent WebSocket replacement without needing CLI
          const sseUrl = `?action=sse_sync&item_id=${itemId}&item_type=${itemType}`;
          presenceEventSource = new EventSource(sseUrl);
    
          presenceEventSource.onmessage = (event) => {
            try {
              const res = JSON.parse(event.data);
    
              if (res.active_users) {
                if (res.active_users.length > 0) {
                  avContainer.innerHTML = res.active_users
                    .map(
                      (u) => `
                          <div class="floating-avatar">
                            <img src="?action=get_profile_picture&id=${u.id}" alt="Avatar">
                            <span>${escapeHTML(u.artist)} is editing...</span>
                          </div>
                        `,
                    )
                    .join("");
                } else {
                  avContainer.innerHTML = "";
                }
              }
    
              if (
                res.latest_update &&
                res.item_data &&
                lastSyncContentTime !== res.latest_update
              ) {
                lastSyncContentTime = res.latest_update;
    
                const smartMergeField = (el, incomingRawText) => {
                  if (!el || typeof incomingRawText !== "string") return;
                  const incomingText = decodeHTML(incomingRawText);
    
                  // Initialize the tracking baseline if it doesn't exist yet
                  if (typeof el.lastServerText === "undefined") {
                    el.lastServerText = el.value;
                  }
    
                  if (el.lastServerText === incomingText) return; // No remote changes detected
    
                  const start = el.selectionStart;
                  const end = el.selectionEnd;
                  const scrollTop = el.scrollTop;
                  const oldLen = el.value.length;
    
                  // FIGMA-LIKE MERGE: Patch the remote changes on top of our local unsaved text (cache)
                  if (dmp && document.activeElement === el) {
                    const diffs = dmp.diff_main(el.lastServerText, incomingText);
                    dmp.diff_cleanupSemantic(diffs);
                    const patches = dmp.patch_make(el.lastServerText, diffs);
                    const [patchedText, results] = dmp.patch_apply(patches, el.value);
    
                    el.value = patchedText;
                    el.lastServerText = incomingText; // Update baseline to the new server state
    
                    try {
                      const diffLen = patchedText.length - oldLen;
                      el.setSelectionRange(
                        Math.max(0, start + diffLen),
                        Math.max(0, end + diffLen),
                      );
                    } catch (e) {}
                  } else {
                    // If we are not actively typing, safely overwrite to keep UI totally synced
                    el.value = incomingText;
                    el.lastServerText = incomingText;
                  }
                  el.scrollTop = scrollTop;
                };
    
                let statusIndicator = null;
    
                if (itemType === "note") {
                  smartMergeField(
                    document.getElementById("editorTitle"),
                    res.item_data.title,
                  );
                  smartMergeField(
                    document.getElementById("editorContent"),
                    res.item_data.content,
                  );
                  statusIndicator = document.getElementById("noteSaveStatus");
                } else if (itemType === "blog") {
                  smartMergeField(
                    document.getElementById("blogEditorTitle"),
                    res.item_data.title,
                  );
                  smartMergeField(
                    document.getElementById("blogEditorContent"),
                    res.item_data.content,
                  );
                  statusIndicator = document.getElementById("blogSaveStatus");
                } else if (itemType === "task") {
                  smartMergeField(
                    document.getElementById("taskEditorTitle"),
                    res.item_data.title,
                  );
    
                  // Wait 1s for array tasks to prevent JSON collision bugs, text is merged live
                  if (
                    !window.isSavingItem &&
                    Date.now() - window.lastLocalEditTime >= 1000 &&
                    res.item_data.content
                  ) {
                    try {
                      window.currentTaskItems = JSON.parse(res.item_data.content);
                      window.renderTaskItems();
                    } catch (e) {}
                  }
                  statusIndicator = document.getElementById("taskSaveStatus");
                } else if (itemType === "imageditor") {
                  const titleInput = document.getElementById("projectTitleInput");
                  if (titleInput && titleInput.value !== res.item_data.title) {
                    titleInput.value = res.item_data.title;
                    if (window.imageditor) window.imageditor.setProjectTitleQuietly(res.item_data.title);
                  }
                  
                  if (!window.isSavingItem && Date.now() - window.lastLocalEditTime >= 1000 && res.item_data.content) {
                    try {
                      if (window.imageditor) window.imageditor.loadStateQuietly(res.item_data.content);
                    } catch(e) {}
                  }
                  statusIndicator = document.getElementById("pe-save-status");
                }
    
                if (statusIndicator) {
                  statusIndicator.innerHTML =
                    '<span class="text-success"><i class="bi bi-arrow-repeat"></i> Live Sync</span>';
                  setTimeout(() => {
                    if (statusIndicator.textContent.includes("Sync"))
                      statusIndicator.textContent = "";
                  }, 1000);
                }
              }
            } catch (e) {
              console.error("SSE Parse Error:", e);
            }
          };
    
          presenceEventSource.onerror = () => {
            presenceEventSource.close();
            setTimeout(() => {
              if (lastSyncContentTime) startPresenceSync(itemId, itemType);
            }, 1000);
          };
        };
    
        const stopPresenceSync = () => {
          if (presenceEventSource) presenceEventSource.close();
          presenceEventSource = null;
