                      <div class="flex-grow-1" style="min-width: 0;">
                        <div class="d-flex justify-content-between align-items-start mb-2">
                          <div class="d-flex align-items-center flex-wrap gap-2">
                            <span class="fw-bolder text-white ${c.is_disabled ? "" : "user-profile-link"}"
                                  data-userid="${c.u_id}"
                                  data-artist="${encodeURIComponent(c.artist)}"
                                  style="font-size: 1rem; cursor:${c.is_disabled ? "default" : "pointer"}; letter-spacing: 0.3px; text-shadow: 0 2px 4px rgba(0,0,0,0.8);"
                                  onmouseover="this.style.textDecoration='underline'"
                                  onmouseout="this.style.textDecoration='none'">
                              ${escapeHTML(c.artist)}
                            </span>
                            <span class="text-secondary d-flex align-items-center gap-1 fw-medium" style="font-size: 0.75rem; opacity: 0.8; background: rgba(255,255,255,0.05); padding: 2px 8px; border-radius: 50px;">
                              <i class="bi bi-clock"></i> ${timeAgo(c.created_at)}
                            </span>
                          </div>
                          ${
                            currentUser &&
                            (currentUser.id == c.u_id ||
                              currentUser.status === "super_admin" ||
                              currentUser.is_admin == 1)
                              ? `
                            <div class="position-relative flex-shrink-0 ms-2 custom-opt-dropdown">
                              <button class="btn btn-link text-secondary p-0 border-0 custom-opt-toggle" type="button"><i class="bi bi-three-dots-vertical fs-5"></i></button>
                              <ul class="dropdown-menu dropdown-menu-dark shadow-lg border-secondary custom-opt-menu" style="position: absolute; right: 0; top: 100%; display: none; z-index: 1060; min-width: 150px;">
                                <li><button class="dropdown-item edit-blog-comment-btn" data-id="${c.id}" data-content="${escapeHTML(c.content)}"><i class="bi bi-pencil"></i> Edit</button></li>
                                <li><button class="dropdown-item text-danger delete-blog-comment-btn" data-id="${c.id}"><i class="bi bi-trash2"></i> Delete</button></li>
                              </ul>
                            </div>
                          `
                              : ""
                          }
                        </div>
  
                        <div class="p-3 mb-3 rounded-4">
                          ${renderContent(c.content)}
                        </div>
  
                        ${
                          currentUser
                            ? `
                        <div class="d-flex align-items-center flex-wrap gap-2 mt-1">
                          <button class="phpmusic-comments-action-btn blog-comment-react-btn ${c.my_reaction === "like" ? "active-like" : ""}" data-id="${c.id}" data-reaction="like" title="Like">
                            <i class="bi ${c.my_reaction === "like" ? "bi-hand-thumbs-up-fill" : "bi-hand-thumbs-up"} fs-5"></i>
                            <span>${c.like_count || 0}</span>
                          </button>
  
                          <button class="phpmusic-comments-action-btn blog-comment-react-btn ${c.my_reaction === "dislike" ? "active-dislike" : ""}" data-id="${c.id}" data-reaction="dislike" title="Dislike">
                            <i class="bi ${c.my_reaction === "dislike" ? "bi-hand-thumbs-down-fill" : "bi-hand-thumbs-down"} fs-5"></i>
                            <span>${c.dislike_count || 0}</span>
                          </button>
  
                          <button class="phpmusic-comments-action-btn blog-reply-btn" data-id="${c.id}" data-root-id="${c.id}" data-username="${escapeHTML(c.artist)}" data-content="${escapeHTML(c.content)}" title="Reply to ${escapeHTML(c.artist)}">
                            <i class="bi bi-chat-left-text fs-5"></i> Reply ${children.filter((ch) => ch.parent_id == c.id).length > 0 ? `(${children.filter((ch) => ch.parent_id == c.id).length})` : ""}
                          </button>
                        </div>
                        `
                            : `
                        <div class="d-flex align-items-center gap-3 text-secondary fw-bold" style="font-size: 0.9rem;">
                          <span class="d-flex align-items-center gap-2 bg-dark px-3 py-1 rounded-pill border border-secondary shadow-sm"><i class="bi bi-hand-thumbs-up-fill text-info fs-5"></i> ${c.like_count || 0}</span>
                          <span class="d-flex align-items-center gap-2 bg-dark px-3 py-1 rounded-pill border border-secondary shadow-sm"><i class="bi bi-hand-thumbs-down-fill text-danger fs-5"></i> ${c.dislike_count || 0}</span>
                        </div>
                        `
                        }
                        <div class="mt-4">${buildTree(comments, c.id)}</div>
                      </div>
                    </div>
                  `,
                )
                .join("")
              );
            } else {
              const repliesHtml = children
                .map((c) => {
                  let replyQuoteHtml = "";
                  if (c.reply_to_id && c.reply_content && c.reply_to_id != parent) {
                    const cleanRep = decodeHTML(c.reply_content).replace(
                      /<[^>]*>?/gm,
                      "",
                    );
                    replyQuoteHtml = `
                      <div class="chat-reply-quote mb-2" onclick="const target=document.querySelector('.reply-anchor-${c.reply_to_id}'); if(target) target.scrollIntoView({behavior:'smooth', block:'center'});" title="Click to jump to post" style="background: rgba(0,0,0,0.2); border-left: 3px solid var(--ytm-accent); padding: 6px 10px; border-radius: 0 6px 6px 0; font-size: 0.85rem; cursor: pointer;">
                        <strong class="text-info">${escapeHTML(c.reply_sender || "Someone")}</strong><br>
                        <span class="text-truncate d-block text-secondary">${escapeHTML(cleanRep)}</span>
                      </div>
                    `;
                  }
                  return `
                    <div class="d-flex gap-3 mb-3 position-relative border-start border-top border-dark border-2 rounded-4 p-2 reply-anchor-${c.id}" style="animation: slideFadeIn 0.3s ease forwards; --bs-border-opacity: .5;">
                      <div class="d-flex flex-column align-items-center" style="width: 36px; flex-shrink: 0;">
                        <img src="?action=get_profile_picture&id=${c.u_id}"
                             class="rounded-circle shadow-sm ${c.is_disabled ? "" : "user-profile-link"}"
                             data-userid="${c.u_id}"
                             data-artist="${encodeURIComponent(c.artist)}"
                             style="width:36px; height:36px; object-fit:cover; cursor:${c.is_disabled ? "default" : "pointer"}; border: 1px solid rgba(255,255,255,0.15); transition: transform 0.3s;"
                             onmouseover="this.style.transform='scale(1.15)'"
                             onmouseout="this.style.transform='scale(1)'">
                        ${children.filter((ch) => ch.parent_id == c.id).length > 0 ? `<div class="mt-2" style="width: 2px; flex-grow: 1; background: linear-gradient(to bottom, rgba(255,255,255,0.1), transparent); border-radius: 2px;"></div>` : ""}
                      </div>
  
                      <div class="flex-grow-1" style="min-width: 0;">
                        <div class="d-flex justify-content-between align-items-start mb-1">
                          <div class="d-flex align-items-center flex-wrap gap-2">
                            <span class="fw-bold text-white ${c.is_disabled ? "" : "user-profile-link"}"
                                  data-userid="${c.u_id}"
                                  data-artist="${encodeURIComponent(c.artist)}"
                                  style="font-size: 0.85rem; cursor:${c.is_disabled ? "default" : "pointer"}; text-shadow: 0 1px 2px rgba(0,0,0,0.5);"
                                  onmouseover="this.style.textDecoration='underline'"
                                  onmouseout="this.style.textDecoration='none'">
                              ${escapeHTML(c.artist)}
                            </span>
                            <span class="text-secondary d-flex align-items-center gap-1 fw-medium" style="font-size: 0.7rem; opacity: 0.7;">
                              <i class="bi bi-clock"></i> ${timeAgo(c.created_at)}
                            </span>
                          </div>
                          ${
                            currentUser &&
                            (currentUser.id == c.u_id ||
                              currentUser.status === "super_admin" ||
                              currentUser.is_admin == 1)
                              ? `
                            <div class="position-relative flex-shrink-0 ms-2 custom-opt-dropdown">
                              <button class="btn btn-link text-secondary p-0 border-0 custom-opt-toggle" type="button"><i class="bi bi-three-dots-vertical fs-5"></i></button>
                              <ul class="dropdown-menu dropdown-menu-dark shadow-lg border-secondary custom-opt-menu" style="position: absolute; right: 0; top: 100%; display: none; z-index: 1060; min-width: 150px;">
                                <li><button class="dropdown-item edit-blog-comment-btn" data-id="${c.id}" data-content="${escapeHTML(c.content)}"><i class="bi bi-pencil"></i> Edit</button></li>
                                <li><button class="dropdown-item text-danger delete-blog-comment-btn" data-id="${c.id}"><i class="bi bi-trash2"></i> Delete</button></li>
                              </ul>
                            </div>
                          `
                              : ""
                          }
                        </div>
  
                        <div class="p-2 mb-2">
                          ${replyQuoteHtml}
                          ${renderContent(c.content)}
                        </div>
  
                        ${
                          currentUser
                            ? `
                        <div class="d-flex align-items-center flex-wrap gap-2 mt-1">
                          <button class="phpmusic-comments-action-btn blog-comment-react-btn ${c.my_reaction === "like" ? "active-like" : ""}" data-id="${c.id}" data-reaction="like" style="padding: 4px 12px; font-size: 0.85rem;">
                            <i class="bi ${c.my_reaction === "like" ? "bi-hand-thumbs-up-fill" : "bi-hand-thumbs-up"}"></i>
                            <span>${c.like_count || 0}</span>
                          </button>
  
                          <button class="phpmusic-comments-action-btn blog-comment-react-btn ${c.my_reaction === "dislike" ? "active-dislike" : ""}" data-id="${c.id}" data-reaction="dislike" style="padding: 4px 12px; font-size: 0.85rem;">
                            <i class="bi ${c.my_reaction === "dislike" ? "bi-hand-thumbs-down-fill" : "bi-hand-thumbs-down"}"></i>
                            <span>${c.dislike_count || 0}</span>
                          </button>
  
                          <button class="phpmusic-comments-action-btn blog-reply-btn" data-id="${c.id}" data-root-id="${parent}" data-username="${escapeHTML(c.artist)}" data-content="${escapeHTML(c.content)}" style="padding: 4px 12px; font-size: 0.85rem;">
                            <i class="bi bi-chat-left-text"></i> Reply ${children.filter((ch) => ch.parent_id == c.id).length > 0 ? `(${children.filter((ch) => ch.parent_id == c.id).length})` : ""}
                          </button>
                        </div>
                        `
                            : `
                        <div class="d-flex align-items-center gap-3 text-secondary fw-bold" style="font-size: 0.8rem;">
                          <span class="d-flex align-items-center gap-1 bg-dark px-2 py-1 rounded-pill border border-secondary shadow-sm"><i class="bi bi-hand-thumbs-up-fill text-info"></i> ${c.like_count || 0}</span>
                          <span class="d-flex align-items-center gap-1 bg-dark px-2 py-1 rounded-pill border border-secondary shadow-sm"><i class="bi bi-hand-thumbs-down-fill text-danger"></i> ${c.dislike_count || 0}</span>
                        </div>
                        `
                        }
                        <div class="mt-2">${buildTree(comments, c.id)}</div>
                      </div>
                    </div>
                  `;
              })
              .join("");
    
              return `
                <div class="ps-3 ms-2 position-relative mt-2" style="border-left: 2px solid rgba(255,255,255,0.1); border-radius: 0 0 0 12px;">
                  <button class="btn btn-link text-info text-decoration-none fw-bold d-inline-flex align-items-center gap-2 toggle-replies-btn mb-3 p-0" data-target="blog-comment-reply-container-${parent}" style="font-size: 0.95rem; transition: 0.2s;" onmouseover="this.style.textShadow='0 0 12px rgba(0, 188, 212, 0.6)'" onmouseout="this.style.textShadow='none'">
                    <div class="d-flex align-items-center justify-content-center bg-info text-dark rounded-circle shadow-sm" style="width: 24px; height: 24px;">
                      <i class="bi bi-chevron-down" style="font-size: 0.85rem;"></i>
                    </div>
                    View ${children.length} ${children.length === 1 ? "reply" : "replies"}
                  </button>
                  <div id="blog-comment-reply-container-${parent}" class="d-none mt-2 pt-2">
                    ${repliesHtml}
                  </div>
                </div>
              `;
            }
          };
    
          const commentsList = document.getElementById("blog-comments-list");
          if (commentsList) {
            const newHtml =
              buildTree(data.comments) ||
              (reset
                ? '<p class="text-secondary text-center mt-3">No comments yet. Be the first to comment!</p>'
                : "");
            if (reset) preserveReplyState(newHtml, "blog-comments-list");
            else commentsList.insertAdjacentHTML("beforeend", newHtml);
    
            const btnContainer = document.getElementById(
              "load-more-blog-comments-container",
            );
            if (btnContainer) {
              const rootCount = data.comments.filter(
                (c) => c.parent_id == null,
              ).length;
              if (rootCount >= 25) btnContainer.classList.remove("d-none");
              else btnContainer.classList.add("d-none");
            }
            window.checkMediaCache();
          }
        };
    
        // Attach listeners for blog view comments & reactions
        document.addEventListener("click", async (e) => {
          const blogLikeBtn = e.target.closest("#blog-like-btn");
          if (blogLikeBtn) {
            if (!currentUser) return showToast("Please login", "error");
            const iconEl = blogLikeBtn.querySelector("i");
            const countEl = blogLikeBtn.querySelector("span");
            let count = parseInt(countEl.textContent) || 0;
            if (iconEl.classList.contains("bi-hand-thumbs-up-fill")) {
              iconEl.className = "bi bi-hand-thumbs-up fs-5";
              countEl.textContent = Math.max(0, count - 1);
            } else {
              const sib = document.getElementById("blog-dislike-btn");
              if (
                sib &&
                sib.querySelector("i").classList.contains("bi-hand-thumbs-down-fill")
              ) {
                sib.querySelector("i").className = "bi bi-hand-thumbs-down fs-5";
                sib.querySelector("span").textContent = Math.max(
                  0,
                  (parseInt(sib.querySelector("span").textContent) || 0) - 1,
                );
              }
              iconEl.className = "bi bi-hand-thumbs-up-fill fs-5";
              countEl.textContent = count + 1;
            }
            fetchData("?action=toggle_blog_reaction", {
              method: "POST",
              body: JSON.stringify({
                blog_id: window.activeBlogPublicId,
                reaction: "like",
              }),
            });
            return;
          }
          const blogDislikeBtn = e.target.closest("#blog-dislike-btn");
          if (blogDislikeBtn) {
            if (!currentUser) return showToast("Please login", "error");
            const iconEl = blogDislikeBtn.querySelector("i");
            const countEl = blogDislikeBtn.querySelector("span");
            let count = parseInt(countEl.textContent) || 0;
            if (iconEl.classList.contains("bi-hand-thumbs-down-fill")) {
              iconEl.className = "bi bi-hand-thumbs-down fs-5";
              countEl.textContent = Math.max(0, count - 1);
            } else {
              const sib = document.getElementById("blog-like-btn");
              if (
                sib &&
                sib.querySelector("i").classList.contains("bi-hand-thumbs-up-fill")
              ) {
                sib.querySelector("i").className = "bi bi-hand-thumbs-up fs-5";
                sib.querySelector("span").textContent = Math.max(
                  0,
                  (parseInt(sib.querySelector("span").textContent) || 0) - 1,
                );
              }
              iconEl.className = "bi bi-hand-thumbs-down-fill fs-5";
              countEl.textContent = count + 1;
            }
            fetchData("?action=toggle_blog_reaction", {
              method: "POST",
              body: JSON.stringify({
                blog_id: window.activeBlogPublicId,
                reaction: "dislike",
              }),
            });
            return;
          }
          const blogReplyBtn = e.target.closest(".blog-reply-btn");
          if (blogReplyBtn) {
            document.getElementById("reply-blog-comment-parent-id").value =
              blogReplyBtn.dataset.rootId || blogReplyBtn.dataset.id;
            document.getElementById("reply-blog-comment-reply-to-id").value =
              blogReplyBtn.dataset.id;
            const input = document.getElementById("reply-blog-comment-input");
            const preview = document.getElementById("reply-blog-comment-preview");
            const username = blogReplyBtn.dataset.username;
            const content = blogReplyBtn.dataset.content || "";
            if (preview) {
              preview.innerHTML = `<strong class="text-white">Replying to ${escapeHTML(username)}:</strong><br><span class="text-secondary text-truncate d-block">${escapeHTML(content).replace(/<[^>]*>?/gm, "")}</span>`;
            }
            if (username) {
              input.value = `@${username.replace(/\s+/g, "")} `;
            } else {
              input.value = "";
            }
            bootstrap.Modal.getOrCreateInstance(
              document.getElementById("reply-blog-comment-modal"),
            ).show();
            setTimeout(() => input.focus(), 500);
            return;
          }
          const communityReplyBtn = e.target.closest(".community-reply-btn");
          if (communityReplyBtn) {
            e.stopPropagation();
            document.getElementById("reply-community-post-parent-id").value =
              communityReplyBtn.dataset.rootId || communityReplyBtn.dataset.id;
            document.getElementById("reply-community-post-reply-to-id").value =
              communityReplyBtn.dataset.id;
            const input = document.getElementById("reply-community-post-input");
            const preview = document.getElementById("reply-community-post-preview");
            const username = communityReplyBtn.dataset.username;
            const content = communityReplyBtn.dataset.content || "";
            if (preview) {
              preview.innerHTML = `<strong class="text-white">Replying to ${escapeHTML(username)}:</strong><br><span class="text-secondary text-truncate d-block">${escapeHTML(content).replace(/<[^>]*>?/gm, "")}</span>`;
            }
            if (username) {
              input.value = `@${username.replace(/\s+/g, "")} `;
            } else {
              input.value = "";
            }
            bootstrap.Modal.getOrCreateInstance(
              document.getElementById("reply-community-post-modal"),
            ).show();
            setTimeout(() => input.focus(), 500);
            return;
          }
          const blogCommentReactBtn = e.target.closest(".blog-comment-react-btn");
          if (blogCommentReactBtn) {
            e.stopPropagation();
            if (!currentUser) return showToast("Please login", "error");
            const reaction = blogCommentReactBtn.dataset.reaction;
            const iconEl = blogCommentReactBtn.querySelector("i");
            const spanEl = blogCommentReactBtn.querySelector("span");
            let count = parseInt(spanEl.textContent) || 0;
            const isFilled =
              iconEl.classList.contains("bi-hand-thumbs-up-fill") ||
              iconEl.classList.contains("bi-hand-thumbs-down-fill");
    
            if (isFilled) {
              iconEl.className = `bi bi-hand-thumbs-${reaction === "like" ? "up" : "down"} fs-5`;
              spanEl.textContent = Math.max(0, count - 1);
            } else {
              const sibling = blogCommentReactBtn.parentElement.querySelector(
                `[data-reaction="${reaction === "like" ? "dislike" : "like"}"]`,
              );
              if (sibling) {
                const sibIcon = sibling.querySelector("i");
                if (
                  sibIcon.classList.contains("bi-hand-thumbs-up-fill") ||
                  sibIcon.classList.contains("bi-hand-thumbs-down-fill")
                ) {
                  sibIcon.className = `bi bi-hand-thumbs-${reaction === "like" ? "down" : "up"} fs-5`;
                  const sibSpan = sibling.querySelector("span");
                  sibSpan.textContent = Math.max(
                    0,
                    (parseInt(sibSpan.textContent) || 0) - 1,
                  );
                }
              }
              iconEl.className = `bi bi-hand-thumbs-${reaction === "like" ? "up" : "down"}-fill fs-5`;
              spanEl.textContent = count + 1;
            }
    
            fetchData("?action=toggle_blog_comment_reaction", {
              method: "POST",
              body: JSON.stringify({
                comment_id: blogCommentReactBtn.dataset.id,
                reaction: reaction,
              }),
            });
            return;
          }
          const editBlogCommentBtn = e.target.closest(".edit-blog-comment-btn");
          if (editBlogCommentBtn) {
            document.getElementById("edit-blog-comment-id").value =
              editBlogCommentBtn.dataset.id;
            document.getElementById("edit-blog-comment-input").value = decodeHTML(
              editBlogCommentBtn.dataset.content,
            );
            bootstrap.Modal.getOrCreateInstance(
              document.getElementById("edit-blog-comment-modal"),
            ).show();
            return;
          }
          const deleteBlogCommentBtn = e.target.closest(".delete-blog-comment-btn");
          if (deleteBlogCommentBtn) {
            if (confirm("Delete this comment?")) {
              await fetchData("?action=delete_blog_comment", {
                method: "POST",
                body: JSON.stringify({
                  comment_id: deleteBlogCommentBtn.dataset.id,
                }),
              });
              window.refreshBlogComments(true);
            }
            return;
          }

          const editArtCommentBtn = e.target.closest(".edit-art-comment-btn");
          if (editArtCommentBtn) {
            e.stopPropagation();
            document.getElementById("edit-art-comment-id").value = editArtCommentBtn.dataset.id;
            document.getElementById("edit-art-comment-input").value = decodeHTML(editArtCommentBtn.dataset.content);
            bootstrap.Modal.getOrCreateInstance(document.getElementById("edit-art-comment-modal")).show();
            return;
          }

          const deleteArtCommentBtn = e.target.closest(".delete-art-comment-btn");
          if (deleteArtCommentBtn) {
            e.stopPropagation();
            if (confirm("Delete this comment?")) {
              fetchData("?action=delete_art_comment", {
                method: "POST",
                body: JSON.stringify({ comment_id: deleteArtCommentBtn.dataset.id }),
              }).then(() => window.refreshArtComments());
            }
            return;
          }

          /* --- NEW PHPSHARES CLICK LISTENERS --- */
          const artCommentReactBtn = e.target.closest(".art-comment-react-btn");
          if (artCommentReactBtn) {
            e.stopPropagation();
            if (!currentUser) return showToast("Please login", "error");
            fetchData("?action=toggle_art_comment_reaction", {
              method: "POST",
              body: JSON.stringify({
                comment_id: artCommentReactBtn.dataset.id,
                reaction: artCommentReactBtn.dataset.reaction,
              }),
            }).then(() => window.refreshArtComments());
            return;
          }
          
          const artReplyBtn = e.target.closest(".art-reply-btn");
          if (artReplyBtn) {
            document.getElementById("reply-art-comment-parent-id")?.remove();
            document.getElementById("reply-art-comment-reply-to-id")?.remove();
            
            const form = document.getElementById("reply-art-comment-form");
            form.insertAdjacentHTML('beforeend', `<input type="hidden" id="reply-art-comment-parent-id" value="${artReplyBtn.dataset.rootId || artReplyBtn.dataset.id}">`);
            form.insertAdjacentHTML('beforeend', `<input type="hidden" id="reply-art-comment-reply-to-id" value="${artReplyBtn.dataset.id}">`);
            
            const input = document.getElementById("reply-art-comment-input-real");
            const preview = document.getElementById("reply-art-comment-preview");
            const username = artReplyBtn.dataset.username;
            const content = artReplyBtn.dataset.content || "";
            if (preview) {
              preview.innerHTML = `<strong class="text-white">Replying to ${escapeHTML(username)}:</strong><br><span class="text-secondary text-truncate d-block">${escapeHTML(content).replace(/<[^>]*>?/gm, "")}</span>`;
            }
            if (username) {
              input.value = `@${username.replace(/\s+/g, "")} `;
            } else {
              input.value = "";
            }
            bootstrap.Modal.getOrCreateInstance(document.getElementById("reply-art-comment-modal")).show();
            setTimeout(() => input.focus(), 500);
            return;
          }

          const artsMetaLink = e.target.closest(".arts-meta-link");
          if (artsMetaLink) {
            e.preventDefault();
            e.stopPropagation();
            const meta = artsMetaLink.dataset.meta;
            loadView({ type: "arts_meta", param: meta, sort: "", filter: "" });
            hideMobileSidebar();
            return;
          }

          const artContextBtn = e.target.closest(".art-more-btn");
          if (artContextBtn) {
            e.preventDefault();
            e.stopPropagation();
            const pId = artContextBtn.dataset.id;
            const contextMenu = document.getElementById("context-menu");
            if (contextMenu.style.display === "block" && window.contextMenuItemEl === artContextBtn) {
              contextMenu.style.display = "none";
              return;
            }
            window.contextMenuItemEl = artContextBtn;
            let menuItems = `
              <li class="context-menu-item" data-action="edit_art" data-public-id="${pId}"><i class="bi bi-pencil-fill text-warning"></i> Edit Artwork</li>
              <li class="context-menu-item text-danger fw-bold" data-action="delete_art" data-public-id="${pId}"><i class="bi bi-trash2-fill"></i> Delete Artwork</li>
              <hr class="dropdown-divider bg-secondary mx-2 my-1">
              <li class="context-menu-item" data-action="close_menu"><i class="bi bi-x-lg"></i> Close Menu</li>
            `;
            contextMenu.innerHTML = menuItems;
            contextMenu.style.display = "block";
            
            positionContextMenu(artContextBtn);
            return;
          }
        });

        document.addEventListener("submit", async (e) => {
          if (e.target.id === "page-upload-art-form") {
            e.preventDefault();
            if (window.artFilesToUpload.length === 0) return showToast("Select at least one image.", "error");
            
            const btn = document.getElementById("art-submit-btn");
            const originalText = btn.innerHTML;
            btn.disabled = true;
            btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span> Uploading...';
            
            const progContainer = document.getElementById("art-upload-progress-container");
            const progBar = document.getElementById("art-upload-progress");
            progContainer.classList.remove("d-none");
            progBar.style.width = "0%";
            progBar.textContent = "0%";
            
            const fd = new FormData();
            fd.append("title", document.getElementById("art-title").value);
            fd.append("type", document.getElementById("art-type").value);
            fd.append("tags", document.getElementById("art-tags").value);
            fd.append("description", document.getElementById("art-desc").value);
            fd.append("characters", document.getElementById("art-characters").value);
            fd.append("parodies", document.getElementById("art-parodies").value);
            fd.append("groups", document.getElementById("art-groups").value);
            fd.append("series", document.getElementById("art-series").value);
            fd.append("nsfw", document.getElementById("art-nsfw").checked ? "1" : "0");
            
            window.artFilesToUpload.forEach(f => fd.append("files[]", f));
            
            const xhr = new XMLHttpRequest();
            xhr.upload.onprogress = (evt) => {
              if (evt.lengthComputable) {
                const pct = Math.round((evt.loaded / evt.total) * 100);
                progBar.style.width = pct + "%";
                progBar.textContent = pct + "%";
              }
            };
            xhr.open("POST", "?action=upload_art", true);
            xhr.onload = () => {
              btn.disabled = false;
              progContainer.classList.add("d-none");
              if (xhr.status === 200) {
                try {
                  const result = JSON.parse(xhr.responseText);
                  if (result && result.status === "success") {
                    showToast("Artwork published!", "success");
                    window.artFilesToUpload = [];
                    loadView({type: 'view_art', param: result.public_id, sort: '', filter: ''});
                  } else {
                    showToast(result.message || "Upload failed.", "error");
                    btn.innerHTML = originalText;
                  }
                } catch(e) {
                  showToast("Server error.", "error");
                  btn.innerHTML = originalText;
                }
              }
            };
            xhr.send(fd);
          } else if (e.target.id === "page-edit-art-form") {
            e.preventDefault();
            const btn = e.target.querySelector('button[type="submit"]');
            const origHtml = btn.innerHTML;
            btn.disabled = true;
            btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span> Saving...';
            
            const fd = new FormData();
            fd.append("public_id", document.getElementById("edit-art-public-id").value);
            fd.append("title", document.getElementById("edit-art-title").value);
            fd.append("tags", document.getElementById("edit-art-tags").value);
            fd.append("description", document.getElementById("edit-art-desc").value);
            fd.append("characters", document.getElementById("edit-art-characters").value);
            fd.append("parodies", document.getElementById("edit-art-parodies").value);
            fd.append("groups", document.getElementById("edit-art-groups").value);
            fd.append("series", document.getElementById("edit-art-series").value);
            fd.append("nsfw", document.getElementById("edit-art-nsfw").checked ? "1" : "0");

            const res = await fetch("?action=edit_art", { method: "POST", body: fd });
            const result = await res.json();
            
            btn.disabled = false;
            btn.innerHTML = origHtml;
            
            if (result && result.status === "success") {
              showToast("Artwork updated!", "success");
              loadView({type: 'view_art', param: document.getElementById("edit-art-public-id").value, sort: '', filter: ''});
            } else {
              showToast(result.message || "Failed to update", "error");
            }
          } else if (e.target.id === "edit-art-comment-form") {
            e.preventDefault();
            const id = document.getElementById("edit-art-comment-id").value;
            const content = document.getElementById("edit-art-comment-input").value;
            await fetchData("?action=edit_art_comment", {
              method: "POST",
              body: JSON.stringify({ comment_id: id, content: content }),
            });
            bootstrap.Modal.getInstance(document.getElementById("edit-art-comment-modal")).hide();
            window.refreshArtComments();
          } else if (e.target.id === "reply-art-comment-form") {
            e.preventDefault();
            if (!currentUser) return showToast("Please login", "error");
            const input = document.getElementById("reply-art-comment-input-real");
            const parentId = document.getElementById("reply-art-comment-parent-id").value;
            const replyToId = document.getElementById("reply-art-comment-reply-to-id").value;
            await fetchData("?action=add_art_comment", {
              method: "POST",
              body: JSON.stringify({
                public_id: window.activeArtPublicId,
                parent_id: parentId || null,
                reply_to_id: replyToId || null,
                content: input.value,
              }),
            });
            input.value = "";
            bootstrap.Modal.getInstance(document.getElementById("reply-art-comment-modal"))?.hide();
            window.refreshArtComments();
          } else if (e.target.id === "blog-comment-form") {
            e.preventDefault();
            if (!currentUser) return showToast("Please login", "error");
            const input = document.getElementById("blog-comment-input");
            const parentId = document.getElementById("blog-comment-parent-id").value;
            await fetchData("?action=add_blog_comment", {
              method: "POST",
              body: JSON.stringify({
                blog_id: window.activeBlogPublicId,
                parent_id: parentId || null,
                content: input.value,
              }),
            });
            input.value = "";
            document.getElementById("blog-comment-parent-id").value = "";
            input.placeholder = "Add a comment... (use @ to mention)";
            window.refreshBlogComments(true);
          }
        });
    
        let findBlogMatches = [];
        let currentBlogMatchIdx = -1;
    
        const executeBlogFind = (fromInput = true) => {
          const text = document.getElementById("blogEditorContent").value;
          const query = document.getElementById("blogFindInput").value;
          findBlogMatches = [];
          if (!query) {
            updateBlogFindUI(-1, false);
            return;
          }
    
          const regex = new RegExp(
            query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"),
            "gi",
          );
          let match;
          while ((match = regex.exec(text)) !== null) {
            findBlogMatches.push({
              index: match.index,
              length: match[0].length,
            });
          }
    
          if (findBlogMatches.length > 0) {
            if (fromInput) {
              if (
                currentBlogMatchIdx < 0 ||
                currentBlogMatchIdx >= findBlogMatches.length
              )
                currentBlogMatchIdx = 0;
              updateBlogFindUI(currentBlogMatchIdx, false);
            } else {
              currentBlogMatchIdx = 0;
              updateBlogFindUI(currentBlogMatchIdx, true);
            }
          } else {
            updateBlogFindUI(-1, false);
          }
        };
    
        const updateBlogFindUI = (idx, doFocusJump = true) => {
          currentBlogMatchIdx = idx;
          const counter = document.getElementById("blogFindCounter");
          if (findBlogMatches.length === 0 || idx < 0) {
            counter.innerText = "0/0";
            return;
          }
          counter.innerText = `${idx + 1}/${findBlogMatches.length}`;
    
          if (doFocusJump) {
            const ta = document.getElementById("blogEditorContent");
            const match = findBlogMatches[idx];
            ta.focus({
              preventScroll: true,
            });
            ta.setSelectionRange(match.index, match.index + match.length);
          }
        };
    
        document
          .getElementById("blogEditorFindBtn")
          ?.addEventListener("click", () => {
            if (isBlogMarkdownPreview) return;
            const p = document.getElementById("blogFindReplacePanel");
            p.classList.toggle("active");
            if (p.classList.contains("active")) {
              document.getElementById("blogFindInput").focus();
              executeBlogFind();
            } else {
              document.getElementById("blogEditorContent").focus();
            }
          });
    
        document
          .getElementById("closeBlogFindBtn")
          ?.addEventListener("click", () =>
            document
              .getElementById("blogFindReplacePanel")
              .classList.remove("active"),
          );
        document
          .getElementById("blogFindInput")
          ?.addEventListener("input", executeBlogFind);
    
        document.getElementById("blogFindNextBtn")?.addEventListener("click", () => {
          if (findBlogMatches.length === 0) return;
          let next = currentBlogMatchIdx + 1;
          if (next >= findBlogMatches.length) next = 0;
          updateBlogFindUI(next, true);
        });
    
        document.getElementById("blogFindPrevBtn")?.addEventListener("click", () => {
          if (findBlogMatches.length === 0) return;
          let next = currentBlogMatchIdx - 1;
          if (next < 0) next = findBlogMatches.length - 1;
          updateBlogFindUI(next, true);
        });
    
        document.getElementById("blogReplaceBtn")?.addEventListener("click", () => {
          if (currentBlogMatchIdx < 0 || findBlogMatches.length === 0) return;
          const rep = document.getElementById("blogReplaceInput").value;
          const ta = document.getElementById("blogEditorContent");
          const match = findBlogMatches[currentBlogMatchIdx];
          ta.value =
            ta.value.substring(0, match.index) +
            rep +
            ta.value.substring(match.index + match.length);
          ta.dispatchEvent(new Event("input"));
          executeBlogFind(false);
        });
    
        document
          .getElementById("blogReplaceAllBtn")
          ?.addEventListener("click", () => {
            const query = document.getElementById("blogFindInput").value;
            if (!query) return;
            const rep = document.getElementById("blogReplaceInput").value;
            const ta = document.getElementById("blogEditorContent");
            const regex = new RegExp(
              query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"),
              "gi",
            );
            ta.value = ta.value.replace(regex, rep);
            ta.dispatchEvent(new Event("input"));
            executeBlogFind(false);
          });
    
        window.openEditorNote = (note) => {
          activeEditorNote = note;
          if (note.id) fetchData("?action=log_item_view", { method: "POST", body: JSON.stringify({ item_id: note.id, item_type: "note" }) }, true);
          const isOwner =
            !note.id || note.user_id == (currentUser ? currentUser.id : null);
    
          const catSelect = document.getElementById("editorCategorySelect");
          if (catSelect) {
            catSelect.disabled = !isOwner;
            catSelect.style.opacity = isOwner ? "1" : "0.6";
            catSelect.style.cursor = isOwner ? "pointer" : "default";
            if (note.category) catSelect.value = note.category;
          }
    
          const moveBtn = document.getElementById("editorMoveProjectBtn");
          if (moveBtn) moveBtn.style.display = isOwner ? "flex" : "none";
    
          const delBtn = document.getElementById("editorDeleteBtn");
          if (delBtn) delBtn.style.display = isOwner ? "flex" : "none";
    
          const noteIdEl = document.getElementById("editorNoteId");
          if (noteIdEl) noteIdEl.value = note.id || "";
    
          const noteTypeEl = document.getElementById("editorNoteType");
          if (noteTypeEl) noteTypeEl.value = note.note_type || "note";
    
          const titleEl = document.getElementById("editorTitle");
          if (titleEl) {
            titleEl.value = note.title ? decodeHTML(note.title) : "";
            titleEl.lastServerText = titleEl.value;
          }
    
          const contentEl = document.getElementById("editorContent");
          if (contentEl) {
            contentEl.value = note.content ? decodeHTML(note.content) : "";
            contentEl.lastServerText = contentEl.value;
          }
    
          const dateEl = document.getElementById("editorDate");
          if (dateEl)
            dateEl.innerText = note.updated_at
              ? new Date(note.updated_at.replace(" ", "T") + "Z").toLocaleDateString()
              : new Date().toLocaleDateString();
    
          // History state implementation for back/forth
          if (!history.state || history.state.overlay !== "note_" + note.id) {
            history.pushState(
              {
                viewConfig: currentView,
                overlay: "note_" + note.id,
              },
              "",
              window.location.pathname,
            );
          }
    
          const savedNoteMode = localStorage.getItem('note_view_mode') || 'edit';
          setNoteViewMode(savedNoteMode);
    
          if (contentEl) noteTextHistory = [contentEl.value];
          noteHistoryIdx = 0;
    
          const starIcon = document.getElementById("editorStarIcon");
          if (starIcon) {
            starIcon.className =
              note.starred == 1 ? "bi bi-star-fill text-warning" : "bi bi-star";
          }
    
          updateEditorWordCount();
          const findPanel = document.getElementById("findReplacePanel");
          if (findPanel) findPanel.classList.remove("active");
    
          const moreMenu = document.getElementById("editorMoreMenu");
          if (moreMenu) moreMenu.classList.remove("active");
    
          const overlay = document.getElementById("editorOverlay");
          if (overlay) overlay.classList.add("active");
          if (typeof currentSong !== 'undefined' && currentSong) toggleMainMiniPlayer(true);
    
          const isCollab = currentView.filter && currentView.filter.startsWith("proj_");
          if (note.id && isCollab) {
            lastSyncContentTime = note.updated_at;
            startPresenceSync(note.id, "note");
          }
        };
    
        const saveCurrentEditorNote = async (force = false) => {
          window.isSavingItem = true;
          const statusIndicator = document.getElementById("noteSaveStatus");
          if (statusIndicator) statusIndicator.textContent = "Saving...";
          const idInput = document.getElementById("editorNoteId");
          const id = idInput.value;
          const title = document.getElementById("editorTitle").value.trim();
          const content = document.getElementById("editorContent").value;
          const category = document.getElementById("editorCategorySelect").value;
          const noteType = document.getElementById("editorNoteType").value || "note";
          const isStarred = document
            .getElementById("editorStarIcon")
            .classList.contains("bi-star-fill")
            ? 1
            : 0;
    
          if (!title && !content) return;
    
          let projId = null;
          if (currentView.filter && currentView.filter.startsWith("proj_")) {
            projId = currentView.filter.replace("proj_", "");
          }
          const res = await fetchData(
            "?action=save_note",
            {
              method: "POST",
              body: JSON.stringify({
                id: id || null,
                title,
                content,
                category,
                starred: isStarred,
                note_type: noteType,
                project_id: projId,
              }),
            },
            true,
          );
    
          if (res && res.status === "success" && res.id && !id) {
            idInput.value = res.id;
            startPresenceSync(res.id, "note");
          }
          if (statusIndicator && res && res.status === "success") {
            statusIndicator.textContent = "Saved";
    
            // Update baseline cache to prevent text duplication on echo
            const titleEl = document.getElementById("editorTitle");
            if (titleEl) titleEl.lastServerText = titleEl.value;
            const contentEl = document.getElementById("editorContent");
            if (contentEl) contentEl.lastServerText = contentEl.value;
    
            setTimeout(() => {
              if (statusIndicator.textContent === "Saved")
                statusIndicator.textContent = "";
            }, 2000);
          }
          window.isSavingItem = false;
          window.lastLocalEditTime = Date.now();
        };
    
        document.getElementById("editorPresentBtn")?.addEventListener("click", () => {
          const text = document.getElementById("editorContent").value;
          window.openPresentation(text);
        });

        let isNoteSplitView = false;

        const generateTOC = (previewElement, tocContainerId) => {
          const tocList = document.getElementById(tocContainerId);
          if (!tocList) return;
          const headings = previewElement.querySelectorAll('h1, h2, h3, h4, h5, h6');
          tocList.innerHTML = '';
          if (headings.length === 0) {
            tocList.innerHTML = '<div class="text-muted p-2 small">No headings found in the document.</div>';
            return;
          }
          headings.forEach((h, index) => {
            if (!h.id) h.id = 'heading-' + index;
            const link = document.createElement('a');
            link.href = '#' + h.id;
            link.textContent = h.textContent;
            const level = parseInt(h.tagName[1]);
            link.className = `toc-link text-truncate py-1 px-2 mb-1`;
            link.style.paddingLeft = `${(level - 1) * 15 + 10}px`;
            if (level === 1) link.classList.add('fw-bold', 'text-white');
            else link.classList.add('text-secondary');

            link.addEventListener('click', (e) => {
              e.preventDefault();
              h.scrollIntoView({ behavior: 'smooth', block: 'start' });
            });
            tocList.appendChild(link);
          });
        };

        const renderNoteMarkdown = async () => {
          const contentArea = document.getElementById("editorContent");
          const previewArea = document.getElementById("editorMarkdownPreview");
          if (typeof marked !== "undefined") {
            const rawHTML = marked.parse(contentArea.value);
            
            // SECURITY FIX: Sanitize HTML output to prevent "Re-scan Covers" Modal header injections!
            let cleanHTML = rawHTML;
            if (typeof DOMPurify !== 'undefined') {
               cleanHTML = DOMPurify.sanitize(rawHTML, { ADD_TAGS: ['iframe', 'video', 'source'], ADD_ATTR: ['allow', 'allowfullscreen', 'frameborder', 'src', 'controls', 'type', 'width', 'height'] });
            } else {
               cleanHTML = cleanHTML.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '').replace(/class="[^"]*fixed[^"]*"/gi, '');
            }

            previewArea.innerHTML = cleanHTML;
            await parseMermaidBlocks(previewArea);
            generateTOC(previewArea, "toc-list-note");

            previewArea.querySelectorAll('input[type="checkbox"]').forEach((cb) => {
              cb.addEventListener("change", (e) => {
                const isChecked = e.target.checked;
                const regex = new RegExp(`\\[[ xX]\\]`, "g");
                let matchCount = 0;
                let cbIndex = Array.from(previewArea.querySelectorAll('input[type="checkbox"]')).indexOf(e.target);

                contentArea.value = contentArea.value.replace(regex, (match) => {
                  if (matchCount === cbIndex) {
                    matchCount++;
                    return isChecked ? `[x]` : `[ ]`;
                  }
                  matchCount++;
                  return match;
                });
                if (isNoteSplitView) renderNoteMarkdown();
                saveCurrentEditorNote(false);
              });
            });
          } else {
            previewArea.innerHTML = '<p class="text-secondary text-center p-5">Markdown renderer is loading or unavailable.</p>';
          }
        };

        let isSyncingLeftNote = false;
        let isSyncingRightNote = false;

        document.getElementById("editorContent")?.addEventListener("scroll", (e) => {
          if (!isNoteSplitView) return;
          if (isSyncingRightNote) { isSyncingRightNote = false; return; }
          isSyncingLeftNote = true;
          const previewArea = document.getElementById("editorMarkdownPreview");
          if (!previewArea) return;
          const percentage = e.target.scrollTop / (e.target.scrollHeight - e.target.clientHeight || 1);
          previewArea.scrollTop = percentage * (previewArea.scrollHeight - previewArea.clientHeight);
        });

        document.getElementById("editorMarkdownPreview")?.addEventListener("scroll", (e) => {
          if (!isNoteSplitView) return;
          if (isSyncingLeftNote) { isSyncingLeftNote = false; return; }
          isSyncingRightNote = true;
          const contentArea = document.getElementById("editorContent");
          if (!contentArea) return;
          const percentage = e.target.scrollTop / (e.target.scrollHeight - e.target.clientHeight || 1);
          contentArea.scrollTop = percentage * (contentArea.scrollHeight - contentArea.clientHeight);
        });

        document.getElementById("editorSplitBtn")?.addEventListener("click", () => {
          isNoteSplitView = !isNoteSplitView;
          localStorage.setItem('note_split_view', isNoteSplitView);
          const container = document.getElementById("noteSplitContainer");
          const contentArea = document.getElementById("editorContent");
          const previewArea = document.getElementById("editorMarkdownPreview");
          const splitIcon = document.getElementById("editorSplitBtn").querySelector("i");
          
          isMarkdownPreview = false;
          const mdIcon = document.getElementById("editorMarkdownBtn").querySelector("i");
          if (mdIcon) mdIcon.className = "bi bi-markdown";
          const findBtn = document.getElementById("editorFindBtn");
          if (findBtn) {
            findBtn.disabled = false;
            findBtn.style.opacity = "1";
          }

          if (isNoteSplitView) {
            splitIcon.className = "bi bi-layout-split text-info";
            container.classList.add("split-active");
            contentArea.classList.remove("d-none");
            previewArea.classList.remove("d-none");
            renderNoteMarkdown();
          } else {
            splitIcon.className = "bi bi-layout-split";
            container.classList.remove("split-active");
            previewArea.classList.add("d-none");
            contentArea.classList.remove("d-none");
          }
        });

        let wordCountTimeout = null;
        const updateEditorWordCount = () => {
          const text = document.getElementById("editorContent").value;
          document.getElementById("editorCharCount").innerText =
            `${new Intl.NumberFormat().format(text.length)} chars`;

          clearTimeout(wordCountTimeout);
          wordCountTimeout = setTimeout(() => {
            let words = 0;
            if (text.length > 100000) {
              const approxWords = (text.match(/ /g) || []).length + 1;
              document.getElementById("editorWordCount").innerText = `~${new Intl.NumberFormat().format(approxWords)} words`;
              const readTime = Math.max(1, Math.ceil(approxWords / 200));
              const readTimeEl = document.getElementById("editorReadTime");
              if (readTimeEl) readTimeEl.innerHTML = `<i class="bi bi-book"></i> ~${readTime} min read`;
            } else if (text.trim()) {
              const matches = text.match(/\S+/g);
              words = matches ? matches.length : 0;
              document.getElementById("editorWordCount").innerText = `${new Intl.NumberFormat().format(words)} words`;
              const readTime = Math.max(1, Math.ceil(words / 200));
              const readTimeEl = document.getElementById("editorReadTime");
              if (readTimeEl) readTimeEl.innerHTML = `<i class="bi bi-book"></i> ${readTime} min read`;
            } else {
              document.getElementById("editorWordCount").innerText = `0 words`;
              const readTimeEl = document.getElementById("editorReadTime");
              if (readTimeEl) readTimeEl.innerHTML = `<i class="bi bi-book"></i> 0 min read`;
            }
          }, 400);
        };
    
        document.getElementById("editorCopyBtn")?.addEventListener("click", () => {
          document.getElementById("editorMoreMenu").classList.remove("active");
          const text = document.getElementById("editorContent").value;
          if (navigator.clipboard && window.isSecureContext) {
            navigator.clipboard
              .writeText(text)
              .then(() => showToast("Copied to clipboard!", "success"));
          }
        });
    
        document.addEventListener("click", (e) => {
          const btn = e.target.closest("button[data-md]");
          if (!btn) return;
          e.preventDefault();
          const md = btn.dataset.md;
          let ta;
          const container = btn.closest(".rich-input-container");
    
          if (container) {
            ta = document.getElementById(container.dataset.targetId);
          } else if (btn.closest("#blogEditorToolbar")) {
            ta = document.getElementById("blogEditorContent");
          } else if (btn.closest(".editor-toolbar")) {
            ta = document.getElementById("editorContent");
          }
          if (!ta) return;
    
          const start = ta.selectionStart;
          const end = ta.selectionEnd;
          const selectedText = ta.value.substring(start, end);
          let pre = "",
            suf = "",
            def = "";
    
          switch (md) {
            case "bold":
              pre = "**";
              suf = "**";
              def = "bold text";
              break;
            case "italic":
              pre = "*";
              suf = "*";
              def = "italic text";
              break;
            case "heading":
              pre = "### ";
              def = "Heading";
              break;
            case "strikethrough":
              pre = "~~";
              suf = "~~";
              def = "strikethrough";
              break;
            case "spoiler":
              pre = "[spoiler]";
              suf = "[/spoiler]";
              def = "spoiler text";
              break;
            case "ul":
              pre = "- ";
              def = "List item";
              break;
            case "ol":
              pre = "1. ";
              def = "List item";
              break;
            case "task":
              pre = "- [ ] ";
              def = "Task";
              break;
            case "quote":
              pre = "> ";
              def = "Quote";
              break;
            case "code":
              pre = "```\n";
              suf = "\n```";
              def = "code block";
              break;
            case "table":
              pre = "| Header | Header |\n| --- | --- |\n| Cell | Cell |";
              break;
            case "mermaid":
              pre = "```mermaid\ngraph TD;\n    A-->B;\n    A-->C;\n    B-->D;\n    C-->D;\n```\n";
              def = "";
              break;
            case "align-left":
              pre = '<div style="text-align: left;">\n';
              suf = "\n</div>";
              def = "Left aligned text";
              break;
            case "align-center":
              pre = '<div style="text-align: center;">\n';
              suf = "\n</div>";
              def = "Center aligned text";
              break;
            case "align-right":
              pre = '<div style="text-align: right;">\n';
              suf = "\n</div>";
              def = "Right aligned text";
              break;
            case "link":
              pre = "[";
              suf = "](url)";
              def = "link text";
              break;
            case "image":
              const imgUrl = prompt(
                "Enter image URL:",
                "https://example.com/image.jpg",
              );
              if (imgUrl) {
                const imgWidth = prompt(
                  "Enter width (e.g. 100%, 300px, auto):",
                  "100%",
                );
                const imgHeight = prompt("Enter height (e.g. auto, 300px):", "auto");
                pre = `<img src="${imgUrl}" width="${imgWidth || "100%"}" height="${imgHeight || "auto"}" alt="`;
                suf = '">';
                def = "image description";
              } else {
                return; // Cancelled
              }
              break;
            case "video":
              const vidUrl = prompt(
                "Enter Video or YouTube URL:",
                "https://www.youtube.com/watch?v=...",
              );
              if (vidUrl) {
                const ytMatch = vidUrl.match(
                  /(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]{11})/i,
                );
                if (ytMatch && ytMatch[1]) {
                  pre = `\n<iframe src="https://www.youtube.com/embed/${ytMatch[1]}" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe>\n`;
                } else {
                  pre = `\n<video src="${vidUrl}" controls style="background: #000;"></video>\n`;
                }
                suf = "";
                def = "";
              } else {
                return; // Cancelled
              }
              break;
          }
    
          const insertText = selectedText || def;
          const finalInsert = md === "table" ? pre : pre + insertText + suf;
    
          ta.value =
            ta.value.substring(0, start) + finalInsert + ta.value.substring(end);
          ta.focus();
    
          if (md === "table") {
            ta.setSelectionRange(start + 2, start + 8);
          } else if (selectedText) {
            ta.setSelectionRange(start, start + finalInsert.length);
          } else {
            ta.setSelectionRange(start + pre.length, start + pre.length + def.length);
          }
    
          ta.dispatchEvent(new Event("input"));
          ta.style.height = "";
          ta.style.height = ta.scrollHeight + "px";
        });
    
        let taskSaveTimeout = null;
        let isTaskSplitView = false;
        let isTaskMarkdownPreview = false;
        window.taskSortable = null;

        const updateTaskEditorWordCount = () => {
          const total = window.currentTaskItems ? window.currentTaskItems.length : 0;
          const completed = window.currentTaskItems ? window.currentTaskItems.filter(i => i.completed).length : 0;
          const pct = total > 0 ? Math.round((completed / total) * 100) : 0;

          const totalEl = document.getElementById("taskEditorTotalCount");
          const compEl = document.getElementById("taskEditorCompletedCount");
          const badgeEl = document.getElementById("taskEditorProgressBadge");

          if (totalEl) totalEl.innerText = `${total} ${total === 1 ? 'item' : 'items'}`;
          if (compEl) compEl.innerText = `${completed} completed`;
          if (badgeEl) badgeEl.innerHTML = `<i class="bi bi-check2-circle"></i> ${pct}% Done`;
        };

        const setTaskViewMode = (mode) => {
          const container = document.getElementById("taskSplitContainer");
          if (!container) return;
          
          if (mode === 'split' && window.innerWidth < 768) {
            mode = 'edit';
          }

          localStorage.setItem('task_view_mode', mode);

          const idInput = document.getElementById("taskEditorId")?.value;
          if (idInput) window.noteViewerStates[idInput] = (mode === 'preview') ? "markdown" : "editor";

          container.classList.remove('view-mode-edit', 'view-mode-split', 'view-mode-preview');
          container.classList.add(`view-mode-${mode}`);
          
          ['taskEditorModeEditBtn', 'taskEditorSplitBtn', 'taskEditorMarkdownBtn'].forEach(id => {
            const btn = document.getElementById(id);
            if (btn) btn.classList.remove('active');
          });
          
          let activeBtnId = 'taskEditorModeEditBtn';
          if (mode === 'split') activeBtnId = 'taskEditorSplitBtn';
          if (mode === 'preview') activeBtnId = 'taskEditorMarkdownBtn';
          
          const activeBtn = document.getElementById(activeBtnId);
          if (activeBtn) activeBtn.classList.add('active');
          
          const findBtn = document.getElementById("taskEditorFindBtn");
          const addToolbarBtn = document.getElementById("addTaskItemBtnToolbar");

          const contentArea = document.getElementById("taskEditorContentArea");
          const previewArea = document.getElementById("taskMarkdownPreview");
          const resizer = document.getElementById("taskResizer");

          if (mode === 'edit') {
            isTaskSplitView = false;
            isTaskMarkdownPreview = false;
            if (contentArea) {
              contentArea.style.width = "100%";
              contentArea.style.flex = "1 1 100%";
            }
            if (resizer) resizer.style.display = "none";
            if (previewArea) previewArea.style.display = "none";
            if (findBtn) { findBtn.disabled = false; findBtn.style.opacity = "1"; }
            if (addToolbarBtn) { addToolbarBtn.style.display = "inline-flex"; }
            if (window.taskSortable) window.taskSortable.option("disabled", false);
          } else if (mode === 'split') {
            isTaskSplitView = true;
            isTaskMarkdownPreview = false;
            if (contentArea) {
              contentArea.style.width = "50%";
              contentArea.style.flex = "none";
            }
            if (resizer) resizer.style.display = "block";
            if (previewArea) {
              previewArea.style.display = "block";
              previewArea.style.width = "";
              previewArea.style.flex = "1 1 0%";
            }
            window.renderTaskMarkdown(false);
            if (findBtn) { findBtn.disabled = false; findBtn.style.opacity = "1"; }
            if (addToolbarBtn) { addToolbarBtn.style.display = "inline-flex"; }
            if (window.taskSortable) window.taskSortable.option("disabled", false);
          } else if (mode === 'preview') {
            isTaskSplitView = false;
            isTaskMarkdownPreview = true;
            document.getElementById("taskFindReplacePanel")?.classList.remove("active");
            if (contentArea) contentArea.style.display = "none";
            if (resizer) resizer.style.display = "none";
            if (previewArea) {
              previewArea.style.display = "block";
              previewArea.style.width = "100%";
              previewArea.style.flex = "1 1 100%";
            }
            if (findBtn) { findBtn.disabled = true; findBtn.style.opacity = "0.5"; }
            if (addToolbarBtn) { addToolbarBtn.style.display = "none"; }
            if (window.taskSortable) window.taskSortable.option("disabled", true);
            window.renderTaskMarkdown(true); // Pure read-only non-interactive view
          }
        };

        document.getElementById("taskEditorModeEditBtn")?.addEventListener("click", () => setTaskViewMode('edit'));
        document.getElementById("taskEditorSplitBtn")?.addEventListener("click", () => setTaskViewMode('split'));
        document.getElementById("taskEditorMarkdownBtn")?.addEventListener("click", () => setTaskViewMode('preview'));

        window.openTaskEditor = (task) => {
          if (task.id) fetchData("?action=log_item_view", { method: "POST", body: JSON.stringify({ item_id: task.id, item_type: "task" }) }, true);
          const isOwner =
            !task.id || task.user_id == (currentUser ? currentUser.id : null);
    
          const catSelect = document.getElementById("taskEditorCategorySelect");
          if (catSelect) {
            catSelect.disabled = !isOwner;
            catSelect.style.opacity = isOwner ? "1" : "0.6";
            catSelect.style.cursor = isOwner ? "pointer" : "default";
            if (task.category) catSelect.value = task.category;
          }
    
          const moveBtn = document.getElementById("taskMoveProjectBtn");
          if (moveBtn) moveBtn.style.display = isOwner ? "flex" : "none";
    
          const delBtn = document.getElementById("taskEditorDeleteBtn");
          if (delBtn) delBtn.style.display = isOwner ? "flex" : "none";
    
          if (!history.state || history.state.overlay !== "task_" + task.id) {
            history.pushState(
              {
                viewConfig: currentView,
                overlay: "task_" + task.id,
              },
              "",
              window.location.pathname,
            );
          }
    
          const idEl = document.getElementById("taskEditorId");
          if (idEl) idEl.value = task.id || "";
    
          const titleEl = document.getElementById("taskEditorTitle");
          if (titleEl) {
            titleEl.value = task.title ? decodeHTML(task.title) : "";
            titleEl.lastServerText = titleEl.value;
          }
    
          const dateEl = document.getElementById("taskEditorDate");
          if (dateEl)
            dateEl.innerText = task.updated_at
              ? new Date(task.updated_at.replace(" ", "T") + "Z").toLocaleDateString()
              : new Date().toLocaleDateString();
    
          const starIcon = document.getElementById("taskEditorStarIcon");
          if (starIcon)
            starIcon.className =
              task.starred == 1 ? "bi bi-star-fill text-warning" : "bi bi-star";
    
          let items = [];
          try {
            items = task.items ? JSON.parse(task.items) : [];
          } catch (e) {}
          window.currentTaskItems = items;
    
          window.renderTaskItems();

          const savedTaskMode = localStorage.getItem('task_view_mode') || 'edit';
          setTaskViewMode(savedTaskMode);
    
          const findPanel = document.getElementById("taskFindReplacePanel");
          if (findPanel) findPanel.classList.remove("active");
    
          const moreMenu = document.getElementById("taskEditorMoreMenu");
          if (moreMenu) moreMenu.classList.remove("active");
    
          const overlay = document.getElementById("taskEditorOverlay");
          if (overlay) overlay.classList.add("active");
          if (typeof currentSong !== 'undefined' && currentSong) toggleMainMiniPlayer(true);
    
          // Re-calculate accurate heights once overlay is rendered and visible in DOM
          requestAnimationFrame(() => {
            document.querySelectorAll("#taskItemsContainer .task-item-input").forEach((input) => {
              input.style.height = "0px";
              input.style.height = Math.max(24, input.scrollHeight) + "px";
            });
          });

          const isCollab = currentView.filter && currentView.filter.startsWith("proj_");
          if (task.id && isCollab) {
            lastSyncContentTime = task.updated_at;
            startPresenceSync(task.id, "task");
          }
        };
    
        window.renderTaskMarkdown = async (readOnly = false) => {
          const previewArea = document.getElementById("taskMarkdownPreview");
          if (!previewArea) return;
          const itemsList = window.currentTaskItems || [];
          let markdownText = itemsList.map(t => (t.completed ? "- [x] " : "- [ ] ") + t.text).join('\n');
          
          if (typeof marked !== "undefined") {
            marked.use({ gfm: true });
            const rawHTML = marked.parse(markdownText || "*(No tasks added yet)*");

            let cleanHTML = rawHTML;
            if (typeof DOMPurify !== 'undefined') {
              cleanHTML = DOMPurify.sanitize(rawHTML, { ADD_TAGS: ['iframe', 'video', 'source'], ADD_ATTR: ['allow', 'allowfullscreen', 'frameborder', 'src', 'controls', 'type', 'width', 'height'] });
            } else {
              cleanHTML = cleanHTML.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '').replace(/class="[^"]*fixed[^"]*"/gi, '');
            }

            previewArea.innerHTML = cleanHTML;
            await parseMermaidBlocks(previewArea);
            generateTOC(previewArea, "toc-list-task");

            previewArea.querySelectorAll('input[type="checkbox"]').forEach((cb) => {
              if (readOnly) {
                cb.setAttribute("disabled", "true");
                cb.style.pointerEvents = "none";
                cb.style.cursor = "default";
              } else {
                cb.removeAttribute("disabled");
                cb.style.pointerEvents = "auto";
                cb.style.cursor = "pointer";
                cb.addEventListener("change", (e) => {
                  const isChecked = e.target.checked;
                  let cbIndex = Array.from(previewArea.querySelectorAll('input[type="checkbox"]')).indexOf(e.target);
                  if (window.currentTaskItems[cbIndex]) {
                    window.currentTaskItems[cbIndex].completed = isChecked;
                    window.renderTaskItems();
                    window.saveCurrentTask(false);
                  }
                });
              }
            });
          } else {
            previewArea.innerHTML = '<p class="text-secondary text-center p-5">Markdown renderer is loading or unavailable.</p>';
          }
        };

        let isSyncingLeftTask = false;
        let isSyncingRightTask = false;

        document.getElementById("taskItemsContainer")?.addEventListener("scroll", (e) => {
          if (!isTaskSplitView) return;
          if (isSyncingRightTask) { isSyncingRightTask = false; return; }
          isSyncingLeftTask = true;
          const previewArea = document.getElementById("taskMarkdownPreview");
          if (!previewArea) return;
          const percentage = e.target.scrollTop / (e.target.scrollHeight - e.target.clientHeight || 1);
          previewArea.scrollTop = percentage * (previewArea.scrollHeight - previewArea.clientHeight);
        });

        document.getElementById("taskMarkdownPreview")?.addEventListener("scroll", (e) => {
          if (!isTaskSplitView) return;
          if (isSyncingLeftTask) { isSyncingLeftTask = false; return; }
          isSyncingRightTask = true;
          const contentArea = document.getElementById("taskItemsContainer");
          if (!contentArea) return;
          const percentage = e.target.scrollTop / (e.target.scrollHeight - e.target.clientHeight || 1);
          contentArea.scrollTop = percentage * (contentArea.scrollHeight - contentArea.clientHeight);
        });

        window.renderTaskItems = () => {
          const container = document.getElementById("taskItemsContainer");
          if (!container) return;
          const autoResizeTaskInput = (el) => {
            if (!el) return;
            el.style.height = "0px";
            el.style.height = Math.max(24, el.scrollHeight) + "px";
          };
    
          container.innerHTML = (window.currentTaskItems || [])
            .map(
              (item, idx) => `
                <div class="task-item-row" data-idx="${idx}">
                  <i class="bi bi-grip-vertical text-secondary task-item-drag-handle" title="Drag to reorder" style="cursor: grab; font-size: 1.1rem; user-select: none;"></i>
                  <input type="checkbox" class="task-item-checkbox" data-idx="${idx}" ${item.completed ? "checked" : ""}>
                  <textarea class="task-item-input ${item.completed ? "completed" : ""}" data-idx="${idx}" placeholder="Task description..." rows="1" style="resize: none; overflow: hidden; height: 24px; padding: 2px 0; line-height: 1.4;">${escapeHTML(item.text)}</textarea>
                  <button class="task-item-del" data-idx="${idx}"><i class="bi bi-x-lg"></i></button>
                </div>
              `,
            )
            .join("");

          updateTaskEditorWordCount();

          // Initialize / reattach SortableJS for drag-and-drop task sorting
          if (typeof Sortable !== "undefined") {
            if (window.taskSortable) {
              window.taskSortable.destroy();
              window.taskSortable = null;
            }
            window.taskSortable = Sortable.create(container, {
              animation: 150,
              handle: ".task-item-drag-handle",
              ghostClass: "ghost",
              onEnd: () => {
                window.lastLocalEditTime = Date.now();
                const reorderedItems = [];
                container.querySelectorAll(".task-item-row").forEach((row) => {
                  const idx = parseInt(row.dataset.idx);
                  if (window.currentTaskItems[idx]) {
                    reorderedItems.push(window.currentTaskItems[idx]);
                  }
                });
                window.currentTaskItems = reorderedItems;
                window.renderTaskItems();
                if (isTaskSplitView) {
                  window.renderTaskMarkdown(false);
                }
                window.saveCurrentTask(false);
              },
            });
          }
    
          container.querySelectorAll(".task-item-input").forEach((input) => {
            autoResizeTaskInput(input);
            input.addEventListener("input", (e) => {
              window.lastLocalEditTime = Date.now();
              autoResizeTaskInput(e.target);
              window.currentTaskItems[e.target.dataset.idx].text = e.target.value;
              updateTaskEditorWordCount();
              if (isTaskSplitView) {
                window.renderTaskMarkdown(false);
              }
              if (
                document
                  .getElementById("taskFindReplacePanel")
                  .classList.contains("active")
              )
                executeTaskFind();
              clearTimeout(taskSaveTimeout);
              taskSaveTimeout = setTimeout(() => window.saveCurrentTask(false), 300);
            });
            input.addEventListener("keydown", (e) => {
              window.lastLocalEditTime = Date.now();
              if (e.key === "Enter") {
                e.preventDefault();
                const idx = parseInt(e.target.dataset.idx);
                window.currentTaskItems.splice(idx + 1, 0, {
                  text: "",
                  completed: false,
                });
                window.renderTaskItems();
                const inputs = document.querySelectorAll(".task-item-input");
                if (inputs.length > idx + 1) inputs[idx + 1].focus();
                window.saveCurrentTask(false);
              } else if (e.key === "Backspace" && e.target.value === "") {
                e.preventDefault();
                const idx = parseInt(e.target.dataset.idx);
                if (idx > 0) {
                  window.currentTaskItems.splice(idx, 1);
                  window.renderTaskItems();
                  const inputs = document.querySelectorAll(".task-item-input");
                  if (inputs.length > idx - 1) {
                    inputs[idx - 1].focus();
                    const val = inputs[idx - 1].value;
                    inputs[idx - 1].value = "";
                    inputs[idx - 1].value = val;
                  }
                  window.saveCurrentTask(false);
                }
              }
            });
          });
    
          container.querySelectorAll(".task-item-checkbox").forEach((chk) => {
            chk.addEventListener("change", (e) => {
              window.lastLocalEditTime = Date.now();
              const idx = e.target.dataset.idx;
              const isChecked = e.target.checked;
              window.currentTaskItems[idx].completed = isChecked;
    
              const row = e.target.closest(".task-item-row");
              if (row) {
                const inputField = row.querySelector(".task-item-input");
                if (inputField) {
                  if (isChecked) inputField.classList.add("completed");
                  else inputField.classList.remove("completed");
                }
              }
              updateTaskEditorWordCount();
              if (isTaskSplitView) {
                window.renderTaskMarkdown(false);
              }
              window.saveCurrentTask(false);
            });
          });
    
          container.querySelectorAll(".task-item-del").forEach((btn) => {
            btn.addEventListener("click", (e) => {
              window.lastLocalEditTime = Date.now();
              window.currentTaskItems.splice(e.currentTarget.dataset.idx, 1);
              window.renderTaskItems();
              if (isTaskSplitView) window.renderTaskMarkdown(false);
              window.saveCurrentTask(false);
            });
          });
        };
    
        window.saveCurrentTask = async (force = false) => {
          window.isSavingItem = true;
          const statusIndicator = document.getElementById("taskSaveStatus");
          if (statusIndicator) statusIndicator.textContent = "Saving...";
          const idInput = document.getElementById("taskEditorId");
          const id = idInput.value;
          const title = document.getElementById("taskEditorTitle").value.trim();
          const category = document.getElementById("taskEditorCategorySelect").value;
          const isStarred = document
            .getElementById("taskEditorStarIcon")
            .classList.contains("bi-star-fill")
            ? 1
            : 0;
          const items = JSON.stringify(window.currentTaskItems);
    
          if (!title && window.currentTaskItems.length === 0) return;
    
          let projId = null;
          if (currentView.filter && currentView.filter.startsWith("proj_")) {
            projId = currentView.filter.replace("proj_", "");
          }
          const res = await fetchData(
            "?action=save_task",
            {
              method: "POST",
              body: JSON.stringify({
                id: id || null,
                title,
                items,
                category,
                starred: isStarred,
                project_id: projId,
              }),
            },
            true,
          );
    
          if (res && res.status === "success" && res.id && !id) {
            idInput.value = res.id;
            startPresenceSync(res.id, "task");
          }
          if (statusIndicator && res && res.status === "success") {
            statusIndicator.textContent = "Saved";
    
            const titleEl = document.getElementById("taskEditorTitle");
            if (titleEl) titleEl.lastServerText = titleEl.value;
    
            setTimeout(() => {
              if (statusIndicator.textContent === "Saved")
                statusIndicator.textContent = "";
            }, 2000);
          }
          window.isSavingItem = false;
          window.lastLocalEditTime = Date.now();
        };
    
        const handleAddTaskItem = () => {
          window.lastLocalEditTime = Date.now();
          if (isTaskMarkdownPreview) {
            setTaskViewMode('edit');
          }
          window.currentTaskItems.push({
            text: "",
            completed: false,
          });
          window.renderTaskItems();
          if (isTaskSplitView) window.renderTaskMarkdown(false);
          const inputs = document.querySelectorAll(".task-item-input");
          if (inputs.length > 0) inputs[inputs.length - 1].focus();
        };

        document.getElementById("addTaskItemBtn")?.addEventListener("click", handleAddTaskItem);
        document.getElementById("addTaskItemBtnToolbar")?.addEventListener("click", handleAddTaskItem);
    
        document.getElementById("taskEditorTitle")?.addEventListener("input", () => {
          window.lastLocalEditTime = Date.now();
          clearTimeout(taskSaveTimeout);
          taskSaveTimeout = setTimeout(() => window.saveCurrentTask(false), 300);
        });
    
        document
          .getElementById("taskEditorCategorySelect")
          ?.addEventListener("change", () => window.saveCurrentTask(false));
    
        document
          .getElementById("closeTaskEditorBtn")
          ?.addEventListener("click", async () => {
            if (taskPipWin) {
              taskPipWin.close();
              taskPipWin = null;
            }
            await window.saveCurrentTask(true);
            stopPresenceSync();
            document
              .getElementById("taskFindReplacePanel")
              ?.classList.remove("active");
            document.getElementById("taskEditorOverlay").classList.remove("active");
            toggleMainMiniPlayer(false);
            if (currentView.type === "get_tasks") loadView(currentView);
          });
    
        document
          .getElementById("taskEditorStarBtn")
          ?.addEventListener("click", () => {
            const starIcon = document.getElementById("taskEditorStarIcon");
            starIcon.className = starIcon.classList.contains("bi-star-fill")
              ? "bi bi-star"
              : "bi bi-star-fill text-warning";
            window.saveCurrentTask(true);
          });
    
        document
          .getElementById("taskEditorMoreBtn")
          ?.addEventListener("click", (e) => {
            e.stopPropagation();
            document.getElementById("taskEditorMoreMenu").classList.toggle("active");
          });
    
        document
          .getElementById("taskEditorForceSaveBtn")
          ?.addEventListener("click", async () => {
            await window.saveCurrentTask(true);
            showToast("Tasks saved!", "success");
            document.getElementById("taskEditorMoreMenu").classList.remove("active");
          });
    
        document
          .getElementById("taskEditorCopyBtn")
          ?.addEventListener("click", () => {
            document.getElementById("taskEditorMoreMenu").classList.remove("active");
            const text = window.currentTaskItems
              .map((t) => (t.completed ? "[x] " : "[ ] ") + t.text)
              .join("\n");
            if (navigator.clipboard && window.isSecureContext) {
              navigator.clipboard
                .writeText(text)
                .then(() => showToast("Copied to clipboard!", "success"));
            }
          });
    
        document
          .getElementById("taskEditorDeleteBtn")
          ?.addEventListener("click", async () => {
            if (taskPipWin) {
              taskPipWin.close();
              taskPipWin = null;
            }
            document.getElementById("taskEditorMoreMenu").classList.remove("active");
            const id = document.getElementById("taskEditorId").value;
            if (!id) {
              document.getElementById("taskEditorOverlay").classList.remove("active");
              showToast("Discarded unsaved task list.", "info");
              return;
            }
            if (confirm("Delete this task list?")) {
              await fetchData("?action=delete_task", {
                method: "POST",
                body: JSON.stringify({
                  id,
                }),
              });
              document.getElementById("taskEditorOverlay").classList.remove("active");
              if (currentView.type === "get_tasks") loadView(currentView);
            }
          });
    
        let noteMarkdownTimer = null;
        document.getElementById("editorContent").addEventListener("input", (e) => {
          window.lastLocalEditTime = Date.now();
          clearTimeout(noteSaveTimeout);
          clearTimeout(noteMarkdownTimer);
          if (isNoteSplitView) noteMarkdownTimer = setTimeout(renderNoteMarkdown, 300);
          clearTimeout(noteHistoryTimeout);
          updateEditorWordCount();
          if (
            document.getElementById("findReplacePanel").classList.contains("active")
          )
            executeNoteFind();
          noteSaveTimeout = setTimeout(() => saveCurrentEditorNote(false), 300);
          noteHistoryTimeout = setTimeout(() => {
            if (noteTextHistory[noteHistoryIdx] === e.target.value) return;
            noteTextHistory = noteTextHistory.slice(0, noteHistoryIdx + 1);
            noteTextHistory.push(e.target.value);
    
            // ADVANCED MEMORY MGMT: Cap history dynamically to prevent RAM crashes on massive documents
            const maxHistory = e.target.value.length > 200000 ? 5 : 50;
            if (noteTextHistory.length > maxHistory) noteTextHistory.shift();
            else noteHistoryIdx++;
          }, 600);
        });
    
        document.getElementById("editorTitle").addEventListener("input", () => {
          window.lastLocalEditTime = Date.now();
          clearTimeout(noteSaveTimeout);
          noteSaveTimeout = setTimeout(() => saveCurrentEditorNote(false), 300);
        });
    
        document
          .getElementById("editorCategorySelect")
          .addEventListener("change", () => saveCurrentEditorNote(false));
    
        document
          .getElementById("closeEditorBtn")
          .addEventListener("click", async () => {
            if (notePipWin) {
              notePipWin.close();
              notePipWin = null;
            }
            await saveCurrentEditorNote(true);
            stopPresenceSync();
            document.getElementById("editorOverlay").classList.remove("active");
            toggleMainMiniPlayer(false);
            activeEditorNote = null;
            if (currentView.type === "get_notes") loadView(currentView);
          });
    
        let blogSaveTimeout = null;
        let blogHistoryTimeout = null;
        let blogTextHistory = [];
        let blogHistoryIdx = -1;
        let isBlogMarkdownPreview = false;
    
        window.openBlogEditor = (blog) => {
          if (blog.public_id) fetchData("?action=log_item_view", { method: "POST", body: JSON.stringify({ item_id: blog.public_id, item_type: "blog" }) }, true);
          const isOwner =
            !blog.id || blog.user_id == (currentUser ? currentUser.id : null);
    
          const catSelect = document.getElementById("blogEditorCategorySelect");
          if (catSelect) {
            catSelect.disabled = !isOwner;
            catSelect.style.opacity = isOwner ? "1" : "0.6";
            catSelect.style.cursor = isOwner ? "pointer" : "default";
            if (blog.category) catSelect.value = blog.category;
          }
    
          const moveBtn = document.getElementById("blogEditorMoveProjectBtn");
          if (moveBtn) moveBtn.style.display = isOwner ? "flex" : "none";
    
          const delBtn = document.getElementById("blogEditorDeleteBtn");
          if (delBtn) delBtn.style.display = isOwner ? "flex" : "none";
    
          const titleEl = document.getElementById("blogEditorTitle");
          const contentEl = document.getElementById("blogEditorContent");
          const idEl = document.getElementById("blogEditorId");
          const pubIdEl = document.getElementById("blogEditorPublicId");
          const statusSelect = document.getElementById("blogEditorStatusSelect");
          const dateEl = document.getElementById("blogEditorDate");
    
          idEl.value = blog.id || "";
          if (pubIdEl) pubIdEl.value = blog.public_id || "";
          titleEl.value = blog.title ? decodeHTML(blog.title) : "";
          titleEl.lastServerText = titleEl.value;
          contentEl.value = blog.content ? decodeHTML(blog.content) : "";
          contentEl.lastServerText = contentEl.value;
          statusSelect.value = blog.status || "private";
          dateEl.innerText = blog.updated_at
            ? new Date(blog.updated_at.replace(" ", "T") + "Z").toLocaleDateString()
            : new Date().toLocaleDateString();
    
          const savedBlogMode = localStorage.getItem('blog_view_mode') || 'edit';
          setBlogViewMode(savedBlogMode);
    
          if (contentEl) blogTextHistory = [contentEl.value];
          blogHistoryIdx = 0;
          updateBlogEditorWordCount();
    
          document.getElementById("blogEditorOverlay").classList.add("active");
          if (typeof currentSong !== 'undefined' && currentSong) toggleMainMiniPlayer(true);
    
          const isCollab = currentView.filter && currentView.filter.startsWith("proj_");
          if (blog.id && isCollab) {
            lastSyncContentTime = blog.updated_at;
            startPresenceSync(blog.id, "blog");
          }
        };
    
        const saveCurrentBlog = async (force = false) => {
          window.isSavingItem = true;
          const statusIndicator = document.getElementById("blogSaveStatus");
          if (statusIndicator) statusIndicator.textContent = "Saving...";
          const idInput = document.getElementById("blogEditorId");
          const id = idInput.value;
          const title = document.getElementById("blogEditorTitle").value.trim();
          const content = document.getElementById("blogEditorContent").value;
          const status = document.getElementById("blogEditorStatusSelect").value;
          const category = document.getElementById("blogEditorCategorySelect").value;
    
          if (!title && !content) return;
    
          let projId = null;
          if (currentView.filter && currentView.filter.startsWith("proj_")) {
            projId = currentView.filter.replace("proj_", "");
          }
    
          const res = await fetchData(
            "?action=save_blog",
            {
              method: "POST",
              body: JSON.stringify({
                id: id || null,
                title,
                content,
                status,
                category,
                project_id: projId,
              }),
            },
            true,
          );
    
          if (res && res.status === "success" && res.id && !id) {
            idInput.value = res.id;
            startPresenceSync(res.id, "blog");
          }
          if (res && res.status === "success" && res.public_id) {
            const pubIdEl = document.getElementById("blogEditorPublicId");
            if (pubIdEl) pubIdEl.value = res.public_id;
          }
          if (statusIndicator && res && res.status === "success") {
            statusIndicator.textContent = "Saved";
    
            const titleEl = document.getElementById("blogEditorTitle");
            if (titleEl) titleEl.lastServerText = titleEl.value;
            const contentEl = document.getElementById("blogEditorContent");
            if (contentEl) contentEl.lastServerText = contentEl.value;
    
            setTimeout(() => {
              if (statusIndicator.textContent === "Saved")
                statusIndicator.textContent = "";
            }, 2000);
          }
          window.isSavingItem = false;
          window.lastLocalEditTime = Date.now();
        };
    
        document
          .getElementById("blogEditorViewBtn")
