        document
          .getElementById("editorMarkdownHelpBtn")
          ?.addEventListener("click", () => {
            document.getElementById("editorMoreMenu").classList.remove("active");
          });
    
        const setDownloadProgress = (pct, text) => {
          const container = document.getElementById("download-progress-container");
          const bar = document.getElementById("download-progress-bar");
          if (container) container.classList.remove("d-none");
          if (bar) {
            bar.style.width = `${pct}%`;
            bar.textContent = text || `${pct}%`;
          }
        };
    
        const resetDownloadProgress = () => {
          const container = document.getElementById("download-progress-container");
          const bar = document.getElementById("download-progress-bar");
          if (container) container.classList.add("d-none");
          if (bar) {
            bar.style.width = "0%";
            bar.textContent = "0%";
          }
        };
    
        const downloadFile = async (type) => {
          const confirmBtn = document.getElementById("confirm-download-note-btn");
          if (confirmBtn) confirmBtn.disabled = true;
    
          try {
            setDownloadProgress(10, "10% - Reading Document...");
            await new Promise((r) => setTimeout(r, 80));
    
            document.getElementById("editorMoreMenu")?.classList.remove("active");
            document.getElementById("taskEditorMoreMenu")?.classList.remove("active");
            document.getElementById("blogEditorMoreMenu")?.classList.remove("active");
    
            const isTask = document
              .getElementById("taskEditorOverlay")
              ?.classList.contains("active");
            const isBlog = document
              .getElementById("blogEditorOverlay")
              ?.classList.contains("active");
    
            let title = "Document";
            let rawContent = "";
            let htmlContent = "";
    
            if (isTask) {
              title =
                document.getElementById("taskEditorTitle")?.value || "Task List";
              const items = window.currentTaskItems || [];
              rawContent = items
                .map(
                  (t) => (t.completed ? "[x] " : "[ ] ") + decodeHTML(t.text || ""),
                )
                .join("\n");
              htmlContent =
                '<ul style="list-style-type: none; padding: 0; font-family: sans-serif; font-size: 15px;">' +
                items
                  .map(
                    (t) =>
                      `<li style="padding: 6px 0; border-bottom: 1px solid #eee;">${t.completed ? '<strong style="color:#27c93f;">[âœ“]</strong>' : '<span style="color:#888;">[ ]</span>'} ${escapeHTML(decodeHTML(t.text || ""))}</li>`,
                  )
                  .join("") +
                "</ul>";
            } else if (isBlog) {
              title =
                document.getElementById("blogEditorTitle")?.value || "Blog Post";
              rawContent = decodeHTML(
                document.getElementById("blogEditorContent")?.value || "",
              );
              if (typeof marked !== "undefined" && rawContent) {
                try {
                  marked.use({
                    gfm: true,
                  });
                  htmlContent = marked.parse(rawContent);
                } catch (e) {
                  htmlContent = `<div style="white-space: pre-wrap; font-family: sans-serif;">${escapeHTML(rawContent)}</div>`;
                }
              } else {
                htmlContent = `<div style="white-space: pre-wrap; font-family: sans-serif;">${escapeHTML(rawContent)}</div>`;
              }
            } else {
              title = document.getElementById("editorTitle")?.value || "Note";
              rawContent = decodeHTML(
                document.getElementById("editorContent")?.value || "",
              );
              if (typeof marked !== "undefined" && rawContent) {
                try {
                  marked.use({
                    gfm: true,
                  });
                  htmlContent = marked.parse(rawContent);
                } catch (e) {
                  htmlContent = `<div style="white-space: pre-wrap; font-family: sans-serif;">${escapeHTML(rawContent)}</div>`;
                }
              } else {
                htmlContent = `<div style="white-space: pre-wrap; font-family: sans-serif;">${escapeHTML(rawContent)}</div>`;
              }
            }
    
            if (!rawContent.trim() && !htmlContent.trim()) {
              showToast(
                "Cannot download empty content. Please write something first.",
                "warning",
              );
              resetDownloadProgress();
              return;
            }
    
            setDownloadProgress(35, "35% - Formatting Content...");
            await new Promise((r) => setTimeout(r, 80));
    
            const safeTitle = (decodeHTML(title) || "document")
              .replace(/[^\w\s-]/gi, "_")
              .trim();
    
            if (type === "txt" || type === "md") {
              setDownloadProgress(75, "75% - Building File...");
              await new Promise((r) => setTimeout(r, 80));
    
              const blob = new Blob([rawContent], {
                type: "text/plain;charset=utf-8",
              });
              const url = URL.createObjectURL(blob);
              const a = document.createElement("a");
              a.href = url;
              a.download = `${safeTitle}.${type}`;
              document.body.appendChild(a);
              a.click();
              document.body.removeChild(a);
              URL.revokeObjectURL(url);
    
              setDownloadProgress(100, "100% - Complete!");
              await new Promise((r) => setTimeout(r, 400));
            } else if (type === "html") {
              setDownloadProgress(75, "75% - Generating HTML...");
              await new Promise((r) => setTimeout(r, 80));
    
              const fullHtml = `<!DOCTYPE html>\n<html>\n<head>\n<meta charset="utf-8">\n<title>${escapeHTML(title)}</title>\n<style>body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;padding:30px;max-width:800px;margin:0 auto;line-height:1.6;color:#111;}h1{border-bottom:2px solid #eee;padding-bottom:10px;}</style>\n</head>\n<body>\n<h1>${escapeHTML(title)}</h1>\n${htmlContent}\n</body>\n</html>`;
              const blob = new Blob([fullHtml], {
                type: "text/html;charset=utf-8",
              });
              const url = URL.createObjectURL(blob);
              const a = document.createElement("a");
              a.href = url;
              a.download = `${safeTitle}.html`;
              document.body.appendChild(a);
              a.click();
              document.body.removeChild(a);
              URL.revokeObjectURL(url);
    
              setDownloadProgress(100, "100% - Complete!");
              await new Promise((r) => setTimeout(r, 400));
            } else if (type === "pdf") {
              setDownloadProgress(60, "60% - Preparing Render Box...");
              await new Promise((r) => setTimeout(r, 100));
    
              setDownloadProgress(80, "80% - Converting to PDF...");
    
              if (typeof html2pdf !== "undefined") {
                const opt = {
                  margin: [10, 10, 10, 10],
                  filename: `${safeTitle}.pdf`,
                  image: {
                    type: "jpeg",
                    quality: 0.98,
                  },
                  html2canvas: {
                    scale: 2,
                    useCORS: true,
                    logging: false,
                  },
                  jsPDF: {
                    unit: "mm",
                    format: "a4",
                    orientation: "portrait",
                  },
                };
    
                // FIX BLANK PDF: Pass a clean HTML string directly to html2pdf.
                // This forces it to create its own isolated rendering container, avoiding document scroll & CSS clipping bugs entirely.
                const pdfHtmlContent = `
                  <div style="background-color: #ffffff; color: #000000; padding: 20px; font-family: Arial, sans-serif; line-height: 1.6; word-wrap: break-word;">
                    <style>
                      h1, h2, h3 { color: #000000 !important; margin-top: 16px; margin-bottom: 8px; font-weight: bold; }
                      code, pre { background-color: #f4f4f4 !important; border: 1px solid #ddd; padding: 6px 10px; border-radius: 4px; font-family: monospace; color: #000000 !important; }
                      blockquote { border-left: 4px solid #cc0000 !important; padding-left: 12px; color: #444444 !important; margin: 15px 0; }
                      table { width: 100%; border-collapse: collapse; margin: 15px 0; color: #000000 !important; }
                      th, td { border: 1px solid #ccc; padding: 8px; text-align: left; }
                      th { background-color: #eeeeee !important; }
                      p, li, span, div { color: #000000 !important; }
                    </style>
                    <h1 style="font-size: 24px; border-bottom: 2px solid #333; padding-bottom: 8px;">${escapeHTML(title)}</h1>
                    <div style="font-size: 14px;">${htmlContent}</div>
                  </div>
                `;
    
                await html2pdf().set(opt).from(pdfHtmlContent).save();
    
                setDownloadProgress(100, "100% - Complete!");
                await new Promise((r) => setTimeout(r, 400));
              } else {
                showToast("PDF library error. Try HTML format.", "error");
              }
            }
          } catch (err) {
            console.error("Download File Error:", err);
            showToast("Error generating file download.", "error");
          } finally {
            resetDownloadProgress();
            if (confirmBtn) confirmBtn.disabled = false;
          }
        };
    
