          async openArtistDetail(artistName) {
            this.activeArtistDetailName = artistName;
    
            // Cache current state to survive page reloads
            localStorage.setItem("rg_active_artist", artistName);
            localStorage.setItem("rg_active_tab", "artistDetail");
    
            // 2. Determine if the artist is a registered user to fetch overall stats
            let sampleSong = {
              id: 0,
            };
    
            const uStmt = await fetchData(
              `?action=get_view_data&type=artist&name=${encodeURIComponent(artistName)}`,
              {},
              true,
            );
            let artistUserId = null;
            let isUser = false;
    
            if (uStmt && uStmt.details) {
              if (uStmt.details.is_user) {
                artistUserId = uStmt.details.user_id;
                isUser = true;
              }
              if (uStmt.songs && uStmt.songs.length > 0) {
                sampleSong = uStmt.songs[0];
              }
            }
    
            let totalScore = 0;
            let artistScores = [];
            let displayRank = "F";
            let rankColor = "#555";
    
            const activePlayerId =
              typeof currentUser !== "undefined" && currentUser
                ? currentUser.id
                : null;
    
            if (isUser && artistUserId) {
              // Fetch the artist's personal overall play history of ALL songs they played
              artistScores =
                (await fetchData(
                  `?action=get_user_rhythm_scores&target_user_id=${artistUserId}&page=1`,
                  {},
                  true,
                )) || [];
    
              let totalPerfect = 0,
                totalGreat = 0,
                totalGood = 0,
                totalBad = 0,
                totalMiss = 0;
              artistScores.forEach((s) => {
                totalScore += parseInt(s.score || 0);
                totalPerfect += parseInt(s.perfect || 0);
                totalGreat += parseInt(s.great || 0);
                totalGood += parseInt(s.good || 0);
                totalBad += parseInt(s.bad || 0);
                totalMiss += parseInt(s.miss || 0);
              });
    
              const rankInfo = this.getRankFromStats(
                totalPerfect,
                totalGreat,
                totalGood,
                totalBad,
                totalMiss,
              );
              displayRank = artistScores.length > 0 ? rankInfo.rank : "F";
              rankColor = artistScores.length > 0 ? rankInfo.color : "#555";
            }
    
            // Render Header with statistical metrics & dynamic Share Button
            const headerContainer = document.getElementById(
              "rg-artist-detail-header",
            );
            if (isUser && artistUserId) {
              headerContainer.innerHTML = `
                <img src="?action=get_image&id=${sampleSong.id}&size=small" onerror="this.onerror=null; this.src='?action=get_app_icon';" class="rounded-circle shadow-lg border border-secondary" style="width: 72px; height: 72px; object-fit: cover; flex-shrink: 0;">
                <div class="d-flex flex-column justify-content-center flex-grow-1" style="min-width: 0; text-align: left;">
                  <h4 class="text-white fw-bold mb-1 text-truncate" style="font-size: 1.4rem; max-width: 100%;">${escapeHTML(artistName)}</h4>
                  <div class="d-flex flex-column align-items-start text-secondary small gap-1" style="font-weight: 500;">
                    <div class="d-flex align-items-center gap-3 flex-wrap">
                      <span>Played: <b class="text-white">${artistScores.length}</b> times</span>
                      <span>Score: <b class="text-white">${totalScore.toLocaleString()}</b></span>
                    </div>
                    <button class="btn btn-outline-light btn-sm rounded-pill px-3 fw-bold border-secondary text-secondary mt-1" id="rg-btn-share-artist" style="font-size: 0.7rem; height: 24px; padding: 0 10px; display: inline-flex; align-items: center; gap: 4px; transition: 0.2s;"><i class="bi bi-share-fill"></i> Share</button>
                  </div>
                </div>
                <div class="d-flex flex-column align-items-end flex-shrink-0">
                  <span class="badge d-flex align-items-center justify-content-center" style="font-family: 'Arial Black', sans-serif; font-size: 1.1rem; font-weight: 900; background-color: ${rankColor}; color: #000; height: 42px; min-width: 48px; border-radius: 8px; box-shadow: 0 4px 12px ${rankColor}40;" title="AVERAGE RANK">${displayRank}</span>
                </div>
              `;
    
              document.getElementById("rg-btn-share-artist").onclick = (e) => {
                e.stopPropagation();
                showShareModal("game", "", artistName, artistUserId, artistName);
              };
            } else {
              headerContainer.innerHTML = `
                <img src="?action=get_image&id=${sampleSong.id}&size=small" onerror="this.onerror=null; this.src='?action=get_app_icon';" class="rounded-circle shadow-lg border border-secondary" style="width: 72px; height: 72px; object-fit: cover; flex-shrink: 0;">
                <div class="d-flex flex-column justify-content-center flex-grow-1" style="min-width: 0; text-align: left;">
                  <h4 class="text-white fw-bold mb-1 text-truncate" style="font-size: 1.4rem; max-width: 100%;">${escapeHTML(artistName)}</h4>
                  <div class="d-flex flex-column align-items-start text-secondary small gap-1" style="font-weight: 500;">
                    <span class="badge bg-dark border border-secondary text-secondary">Guest Artist</span>
                    <button class="btn btn-outline-light btn-sm rounded-pill px-3 fw-bold border-secondary text-secondary mt-1" id="rg-btn-share-artist" style="font-size: 0.7rem; height: 24px; padding: 0 10px; display: inline-flex; align-items: center; gap: 4px; transition: 0.2s;"><i class="bi bi-share-fill"></i> Share</button>
                  </div>
                </div>
              `;
    
              document.getElementById("rg-btn-share-artist").onclick = (e) => {
                e.stopPropagation();
                showShareModal("game", "", artistName, "", artistName); // No User ID for guest artists
              };
            }
    
            // Render History list for this artist's personal plays
            const histContainer = document.getElementById("rg-list-artist-history");
            if (!isUser) {
              histContainer.innerHTML = `<div class="text-center p-5 text-secondary"><i class="bi bi-person-fill-x d-block fs-1 mb-2"></i>Only registered artist user accounts have an active play history.</div>`;
            } else if (artistScores.length === 0) {
              histContainer.innerHTML = `<div class="text-center p-5 text-secondary"><i class="bi bi-controller d-block fs-1 mb-2"></i>This user hasn't played any tracks yet.</div>`;
            } else {
              const diffColors = {
                easy: "#22d3ee",
                medium: "#34d399",
                hard: "#fb923c",
                expert: "#f43f5e",
                master: "#a78bfa",
                demon: "#7f1d1d",
              };
              const diffLabels = {
                easy: "EZ",
                medium: "ND",
                hard: "HD",
                expert: "EX",
                master: "MS",
                demon: "DM",
              };
    
              histContainer.innerHTML = artistScores
                .map((s) => {
                  const jud = this.getRankFromStats(
                    s.perfect,
                    s.great,
                    s.good,
                    s.bad,
                    s.miss,
                  );
                  const diffColor = diffColors[s.difficulty] || "#aaa";
                  const diffLabel = diffLabels[s.difficulty] || "UN";
                  const lvlText = s.level ? `Lv.${s.level}` : "Lv.--";
                  const coverSvg = getSvgPlaceholder(s.title);
                  const playedAt = s.played_at
                    ? new Date(
                        s.played_at.replace(" ", "T") + "Z",
                      ).toLocaleDateString()
                    : "Unknown";
                  const totalHits =
                    parseInt(s.perfect || 0) +
                    parseInt(s.great || 0) +
                    parseInt(s.good || 0) +
                    parseInt(s.bad || 0) +
                    parseInt(s.miss || 0);
                  const suspicious =
                    (jud.acc === "100.00" && totalHits > 50) ||
                    (s.max_combo > 500 && s.miss == 0)
                      ? '<span class="badge bg-danger ms-2" style="font-size: 0.6rem;" title="Perfect Play / Bot Suspected"><i class="bi bi-exclamation-triangle-fill"></i> SUS</span>'
                      : "";
    
                  return `
                    <div class="rg-list-item" style="background: linear-gradient(135deg, rgba(255,255,255,0.02) 0%, rgba(255,255,255,0.01) 100%); border: 1px solid rgba(255,255,255,0.05); border-left: 4px solid ${diffColor}; border-radius: 12px; padding: 12px 16px; display: flex; flex-direction: column; gap: 8px; cursor: default;">
                      <div class="d-flex align-items-center justify-content-between gap-3" style="min-width: 0; width: 100%;">
                        <div class="d-flex align-items-center gap-3" style="min-width: 0; flex: 1;">
                          <img src="?action=get_image&id=${s.song_id}&v=${s.last_modified}" onerror="this.onerror=null; this.src='${coverSvg}'" style="width: 44px; height: 44px; border-radius: 8px; object-fit: cover; box-shadow: 0 4px 8px rgba(0,0,0,0.4); flex-shrink: 0;">
                          <div class="text-truncate text-start" style="min-width: 0; flex: 1;">
                            <div class="text-white fw-bold text-truncate" style="font-size: 0.95rem;">${escapeHTML(s.title)}</div>
                            <div class="text-secondary small mt-1" style="font-size: 0.75rem;">by ${escapeHTML(s.artist)}</div>
                          </div>
                        </div>
                        <div class="d-flex align-items-center gap-1" style="flex-shrink: 0;">
                          ${suspicious}
                          <span class="badge d-flex align-items-center justify-content-center" style="font-family: monospace; font-size: 0.65rem; font-weight: 800; background-color: ${diffColor}; color: ${s.difficulty === "demon" ? "#fff" : "#000"}; padding: 2px 6px; border-radius: 4px;">${diffLabel} ${lvlText}</span>
                          <span class="badge d-flex align-items-center justify-content-center" style="font-family: monospace; font-size: 0.65rem; font-weight: 800; background-color: ${jud.color}; color: #000;">${jud.rank}</span>
                        </div>
                      </div>

                      <div style="display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; width: 100%; border-top: 1px solid rgba(255,255,255,0.03); padding-top: 8px; margin-top: 4px; text-align: center;">
                        <div style="grid-column: span 2; display: flex; justify-content: space-between; align-items: center; background-color: rgba(255,255,255,0.01); border: 1px solid rgba(255,255,255,0.02); padding: 4px 10px; border-radius: 6px; text-align: left;">
                          <span style="font-size: 0.65rem; font-weight: 700; color: #888; text-transform: uppercase;">Score</span>
                          <span style="font-size: 0.9rem; font-weight: 900; font-family: monospace; color: var(--rg-primary);">${parseInt(s.score).toLocaleString()}</span>
                        </div>
                        <div style="grid-column: span 2; display: flex; justify-content: space-between; align-items: center; background-color: rgba(255,255,255,0.01); border: 1px solid rgba(255,255,255,0.02); padding: 4px 10px; border-radius: 6px; text-align: left;">
                          <span style="font-size: 0.65rem; font-weight: 700; color: #888; text-transform: uppercase;">Combo</span>
                          <span style="font-size: 0.9rem; font-weight: 900; font-family: monospace; color: #fff;">${s.max_combo}x</span>
                        </div>
                      </div>
                    </div>
                  `;
                })
                .join("");
            }
    
            this.activeArtistDetailId = artistUserId;
    
            // Render Playlists list for this artist
            const playContainer = document.getElementById("rg-list-artist-playlists");
            if (playContainer) {
              if (
                uStmt &&
                uStmt.details &&
                uStmt.details.playlists &&
                uStmt.details.playlists.length > 0
              ) {
                playContainer.innerHTML = uStmt.details.playlists
                  .slice(0, 25)
                  .map(
                    (p) => `
                        <div class="rg-list-item rg-artist-playlist-item" data-id="${p.public_id}" data-name="${escapeHTML(p.name).replace(/"/g, "&quot;")}" style="background: linear-gradient(135deg, rgba(255,255,255,0.02) 0%, rgba(255,255,255,0.01) 100%); border: 1px solid rgba(255,255,255,0.05); border-left: 4px solid var(--rg-primary); border-radius: 12px; padding: 12px 16px; display: flex; align-items: center; gap: 12px; cursor: pointer; transition: transform 0.2s;" onmouseover="this.style.transform='scale(1.02)'" onmouseout="this.style.transform='scale(1)'">
                          <img src="?action=get_image&id=${p.image_id || 0}&v=${p.image_v || 0}&size=small" style="width: 50px; height: 50px; border-radius: 8px; object-fit: cover; box-shadow: 0 4px 8px rgba(0,0,0,0.4); flex-shrink: 0;">
                          <div class="text-truncate flex-grow-1" style="min-width: 0;">
                            <div class="text-white fw-bold text-truncate" style="font-size: 1rem;">${p.is_private == 1 ? '<i class="bi bi-lock-fill text-warning me-1"></i>' : ""}${escapeHTML(p.name)}</div>
                            <div class="text-secondary small mt-1" style="font-size: 0.75rem;"><i class="bi bi-music-note-list text-danger"></i> ${p.song_count} Tracks</div>
                          </div>
                          <i class="bi bi-chevron-right text-secondary fs-5" style="flex-shrink: 0;"></i>
                        </div>
                      `,
                  )
                  .join("");
    
                // Securely bind click events natively
                playContainer
                  .querySelectorAll(".rg-artist-playlist-item")
                  .forEach((item) => {
                    item.addEventListener("click", () => {
                      this.loadRgPlaylistSongs(item.dataset.id, item.dataset.name);
                    });
                  });
              } else {
                playContainer.innerHTML = `<div class="text-center p-5 text-secondary"><i class="bi bi-music-note-list d-block fs-1 mb-2"></i>No playlists found.</div>`;
              }
            }
    
            // Render Favorites list for this artist
            if (isUser && artistUserId) {
              const favsSearchInput = document.getElementById(
                "rg-search-artist-favs",
              );
              if (favsSearchInput) favsSearchInput.value = "";
              this.loadArtistFavorites(artistUserId);
              this.loadArtistFollowing(artistUserId);
            } else {
              const favsContainer = document.getElementById("rg-list-artist-favs");
              if (favsContainer) {
                favsContainer.innerHTML = `<div class="text-center p-5 text-secondary"><i class="bi bi-heart-break-fill d-block fs-1 mb-2"></i>Only registered users can have favorites.</div>`;
              }
              const folContainer = document.getElementById(
                "rg-list-artist-following",
              );
              if (folContainer) {
                folContainer.innerHTML = `<div class="text-center p-5 text-secondary"><i class="bi bi-person-fill-x d-block fs-1 mb-2"></i>Only registered users can follow others.</div>`;
              }
            }
    
            document.getElementById("rg-search-artist-songs").value = "";
    
            // Hide ALL active tabs first to prevent vertical overlapping conflicts
            Object.values(this.tabs).forEach((t) => {
              if (t) t.classList.add("rg-hidden");
            });
    
            // Show only the artist detail view
            if (this.tabs.artistDetail) {
              this.tabs.artistDetail.classList.remove("rg-hidden");
            }
    
            // Sync bottom navigation highlight conditionally (Profile vs Artists)
            const isMyOwnProfile =
              typeof currentUser !== "undefined" &&
              currentUser &&
              artistName.toLowerCase() === currentUser.artist.toLowerCase();
            document.querySelectorAll(".rg-nav-item").forEach((n) => {
              if (isMyOwnProfile) {
                n.classList.toggle("active", n.id === "rg-nav-my-profile");
              } else {
                n.classList.toggle(
                  "active",
                  n.getAttribute("data-target") === "artists",
                );
              }
            });
    
            // Default to correct sub-tab based on device size
            if (window.innerWidth >= 992) {
              const artTabHistory = document.getElementById("rg-art-tab-history");
              if (artTabHistory) artTabHistory.click();
            } else {
              const artTabTracks = document.getElementById("rg-art-tab-tracks");
              if (artTabTracks) artTabTracks.click();
            }
    
            this.loadArtistSongs(artistName);
          }
    
          openArtistChoiceDialog(artistsList) {
            const body = document.getElementById("artists-modal-body");
            if (!body) return;
    
            const modalEl = document.getElementById("artists-modal");
            const modal = bootstrap.Modal.getOrCreateInstance(modalEl);
    
            const modalTitle = modalEl.querySelector(".modal-title");
            if (modalTitle) modalTitle.textContent = "Artists";
    
            body.innerHTML = `
              <div class="list-group list-group-flush rounded">
                ${artistsList
                  .map(
                    (a) => `
                  <button type="button" class="list-group-item list-group-item-action bg-transparent text-white border-secondary rhythm-artist-modal-item py-3 text-start px-4" style="border-left: none; border-right: none;" data-artist="${encodeURIComponent(a)}">
                    ${a}
                  </button>
                `,
                  )
                  .join("")}
              </div>
            `;
    
            // Re-bind clicks directly to open the selected artist profile
            body.querySelectorAll(".rhythm-artist-modal-item").forEach((btn) => {
              btn.addEventListener("click", () => {
                modal.hide();
                this.openArtistDetail(decodeURIComponent(btn.dataset.artist));
              });
            });
    
            modal.show();
          }
    
          async endGame(failed = false) {
            this.isPlaying = false;
            if (this.audioPlayback) this.audioPlayback.pause();
    
            if (this.autoplayWakeLocked) {
              if (typeof noSleep !== "undefined") noSleep.disable();
              this.autoplayWakeLocked = false;
            }
    
            this.switchScreen("result");
    
            // Inject dynamic blurred cover background to results screen
            const resultScreen = document.getElementById("rg-screen-result");
            if (resultScreen) {
              resultScreen.style.backgroundColor = "transparent";
              let resultBg = document.getElementById("rg-result-bg");
              if (!resultBg) {
                resultBg = document.createElement("div");
                resultBg.id = "rg-result-bg";
                resultBg.style.cssText =
                  "position:absolute; top:-40px; left:-40px; right:-40px; bottom:-40px; background-size:cover; background-position:center; filter:blur(40px) brightness(0.35); z-index:0; pointer-events:none; transition: background-image 0.5s ease;";
                resultScreen.insertBefore(resultBg, resultScreen.firstChild);
              }
              if (this.selectedSong) {
                resultBg.style.backgroundImage = `url('?action=get_image&id=${this.selectedSong.id}&v=${this.selectedSong.last_modified || 0}')`;
              }
            }
    
            const resultWarningId = "rg-offline-result-warning";
            let resultWarningEl = document.getElementById(resultWarningId);
            if (resultWarningEl) resultWarningEl.remove();
    
            if (!navigator.onLine && !failed && !this.isAutoplay) {
              const resultButtonContainer = document.getElementById(
                "rg-btn-result-share",
              ).parentNode;
              resultButtonContainer.insertAdjacentHTML(
                "beforebegin",
                `
                  <div id="${resultWarningId}" class="alert border-danger text-danger small mb-3 text-center rounded-3 w-100" style="background: rgba(255,59,48,0.1); line-height: 1.4; font-weight: bold; border-style: dashed;">
                    <i class="bi bi-shield-slash-fill me-2"></i>Score Not Saved: Played while offline. This score will NOT be synced to the database.
                  </div>
                `,
              );
            }
    
            const titleEl = document.querySelector("#rg-screen-result h2");
            if (titleEl) {
              titleEl.textContent = failed ? "STAGE FAILED" : "STAGE CLEARED";
              titleEl.style.color = failed ? "#ff5f56" : "var(--rg-primary)";
            }
            const shareBtn = document.getElementById("rg-btn-result-share");
            if (shareBtn) {
              shareBtn.style.display = failed ? "none" : "block";
            }
    
            let rank = "F";
            let rankColor = "#7f1d1d";
            const accVal = parseFloat(this.accuracy);
    
            if (accVal >= 98.0) {
              rank = "SS";
              rankColor = "#ff0055";
            } else if (accVal >= 95.0) {
              rank = "S";
              rankColor = "#ffbd2e";
            } else if (accVal >= 90.0) {
              rank = "A";
              rankColor = "#a78bfa";
            } else if (accVal >= 80.0) {
              rank = "B";
              rankColor = "#60a5fa";
            } else if (accVal >= 70.0) {
              rank = "C";
              rankColor = "#34d399";
            } else if (accVal >= 60.0) {
              rank = "D";
              rankColor = "#fb923c";
            } else if (accVal >= 50.0) {
              rank = "E";
              rankColor = "#9ca3af";
            }
    
            if (failed) {
              rank = "F";
              rankColor = "#ff5f56";
            }
    
            const rankEl = document.getElementById("rg-res-rank");
            if (rankEl) {
              rankEl.textContent = rank;
              rankEl.style.color = rankColor;
            }
    
            const accEl = document.getElementById("rg-res-acc");
            if (accEl) {
              accEl.textContent = this.accuracy + "%";
            }
    
            let maxScore = 0;
            this.chartNotes.forEach((n) => {
              if (n.isLong) {
                maxScore += n.hitEndSwipe ? 350 : 110;
              } else {
                maxScore += n.isSwipe ? 150 : 100;
              }
            });
            if (maxScore === 0) maxScore = 1;
            const pct = Math.min(100, Math.max(0, (this.curScore / maxScore) * 100));
            const scoreBar = document.getElementById("rg-res-score-bar");
            if (scoreBar) {
              scoreBar.style.width = "0%";
              setTimeout(() => {
                scoreBar.style.width = pct + "%";
              }, 100);
            }
    
            document.getElementById("rg-res-score").textContent = String(
              this.curScore,
            ).padStart(9, "0");
            document.getElementById("rg-res-max-combo").textContent = this.maxCombo;
            document.getElementById("rg-res-perfect").textContent =
              this.stats.perfect;
            document.getElementById("rg-res-great").textContent = this.stats.great;
            document.getElementById("rg-res-good").textContent = this.stats.good;
            document.getElementById("rg-res-bad").textContent = this.stats.bad;
            document.getElementById("rg-res-miss").textContent = this.stats.miss;
    
            const resTitle = document.querySelector("#rg-screen-result h2");
            if (this.isAutoplay && resTitle) {
              resTitle.textContent = "AUTOPLAY (UNRANKED)";
              resTitle.style.color = "#00bcd4";
            }
    
            if (
              !failed &&
              this.curScore > 0 &&
              this.selectedSong &&
              !this.isAutoplay
            ) {
              await fetchData("?action=save_rhythm_score", {
                method: "POST",
                headers: {
                  "Content-Type": "application/json",
                },
                body: JSON.stringify({
                  song_id: this.selectedSong.id,
                  score: this.curScore,
                  max_combo: this.maxCombo,
                  perfect: this.stats.perfect,
                  great: this.stats.great,
                  good: this.stats.good,
                  bad: this.stats.bad,
                  miss: this.stats.miss,
                  difficulty: this.selectedDiff,
                  hit_deltas: this.hitDeltas,
                }),
              });
              this.loadLeaderboard();
            }
          }
        }
    
        // --- ImagEditor Fabric.js Engine ---
        window.imageditor = (function() {
          let canvas;
          let history = [];
          let historyIndex = -1;
          let isProcessingHistory = false;
          let currentWidth = 1080;
          let currentHeight = 1080;
          let zoomLevel = 1;
          let apiDebounceTimer = null;
          let currentProjectId = null;
          let currentProjectTitle = "Untitled Project";
          let projectsIndex = [];
          let cropperInstance = null;
          let cropTargetObj = null;
          let currentProjectSort = 'modified';
          let currentBrushType = 'dip';
          let symmetryMode = 'none';
          let verticalGuide = null;
          let horizontalGuide = null;
          const toastEl = document.getElementById('pe-toast');
          const propertiesPanel = document.getElementById('propertiesPanel');
          const quickToolbar = document.getElementById('quickToolbar');

          async function init() {
            if (!document.getElementById('mainCanvas')) return;
            
            if (canvas) {
              try { canvas.dispose(); } catch (e) {}
              canvas = null;
            }

            // Move rotate control to the bottom to avoid Quick Toolbar overlap
            if (fabric.Object.prototype.controls && fabric.Object.prototype.controls.mtr) {
              fabric.Object.prototype.controls.mtr.y = 0.5;
              fabric.Object.prototype.controls.mtr.offsetY = 35;
            }
            
            canvas = new fabric.Canvas('mainCanvas', {
              preserveObjectStacking: true,
              selection: true,
              backgroundColor: null
            });
            setCanvasDimensions(currentWidth, currentHeight);
            setupEvents();
            await initDB();
            window.removeEventListener('resize', resizeViewport);
            window.addEventListener('resize', resizeViewport);
            resizeViewport();
            showToast("ImagEditor Ready");
          }
  
          function setCanvasDimensions(width, height) {
            currentWidth = width;
            currentHeight = height;
            const btn = document.getElementById('canvasSizeBtn');
            if (btn) btn.title = `Canvas Size: ${width} x ${height} px`;
            resizeViewport();
          }

          function applyZoom() {
            const container = document.getElementById('canvasContainer');
            if (container) {
              container.style.width = `${currentWidth * zoomLevel}px`;
              container.style.height = `${currentHeight * zoomLevel}px`;
              container.style.transform = `none`;
            }
            if (canvas) {
              canvas.setDimensions({ width: currentWidth * zoomLevel, height: currentHeight * zoomLevel });
              canvas.setZoom(zoomLevel);
            }
            const zoomLabel = document.getElementById('zoomLevelLabel');
            if (zoomLabel) zoomLabel.innerText = `${Math.round(zoomLevel * 100)}%`;
          }

          function resizeViewport() {
            const workspace = document.getElementById('workspace');
            if (!workspace || !canvas) return;
            const padding = 60;
            const availableW = workspace.clientWidth - padding;
            const availableH = workspace.clientHeight - padding;
            const scaleX = availableW / currentWidth;
            const scaleY = availableH / currentHeight;
            zoomLevel = Math.min(scaleX, scaleY, 1);
            applyZoom();
          }
  
          async function initDB() {
            if (!window.imageditorCategories || window.imageditorCategories.length === 0) {
              window.imageditorCategories = await fetchData("?action=get_note_categories&type=imageditor") || [];
            }
            const catSelect = document.getElementById("peCategorySelect");
            if (catSelect) {
              catSelect.innerHTML = '<option value="all">Uncategorized</option>';
              window.imageditorCategories.forEach(c => {
                catSelect.insertAdjacentHTML('beforeend', `<option value="${c.id}">${escapeHTML(c.name)}</option>`);
              });
            }
            await loadProjectsIndex();
          }

          async function loadProjectsIndex() {
            if (!currentUser) return;
            try {
              let filterStr = "";
              if (typeof currentView !== 'undefined' && currentView && currentView.type === 'photo_editor' && currentView.filter) {
                filterStr = `&filter=${currentView.filter}`;
              }
              const res = await fetchData(`?action=get_imageditor_projects${filterStr}`);
              const paramId = (typeof currentView !== 'undefined' && currentView && currentView.type === 'photo_editor' && currentView.param) ? currentView.param : null;
              
              if (res && res.length > 0) {
                projectsIndex = res;
                const lastActiveId = paramId || localStorage.getItem('imageditor_last_project');
                const foundProject = projectsIndex.find(p => p.public_id === lastActiveId);
                
                if (foundProject) {
                  currentProjectId = foundProject.public_id;
                  currentProjectTitle = foundProject.title;
                } else if (paramId) {
                  currentProjectId = paramId;
                  currentProjectTitle = "Loading...";
                } else {
                  currentProjectId = projectsIndex[0].public_id;
                  currentProjectTitle = projectsIndex[0].title;
                }
              } else {
                projectsIndex = [];
                if (paramId) {
                  currentProjectId = paramId;
                  currentProjectTitle = "Loading...";
                } else {
                  await createNewProject("Untitled Project");
                  return;
                }
              }
            } catch (err) {
              projectsIndex = [];
            }
            const projInput = document.getElementById('projectTitleInput');
            if (projInput) projInput.value = currentProjectTitle;
            if (currentProjectId) await loadProject(currentProjectId);
          }

          function updateSaveStatus(status) {
            const statusEl = document.getElementById('pe-save-status');
            if (!statusEl) return;
            if (status === 'saving') {
              statusEl.innerHTML = '<span class="spinner-border spinner-border-sm" style="width: 10px; height: 10px; border-width: 0.1em; margin-right: 4px;"></span> Saving...';
              statusEl.style.color = 'var(--primary)';
            } else if (status === 'saved') {
              statusEl.innerHTML = '<i class="bi bi-cloud-check"></i> Saved';
              statusEl.style.color = 'var(--green)';
              setTimeout(() => {
                if (statusEl.innerHTML.includes('Saved')) {
                  statusEl.style.color = 'var(--on-surface-variant)';
                }
              }, 2000);
            } else if (status === 'error') {
              statusEl.innerHTML = '<i class="bi bi-exclamation-triangle"></i> Error';
              statusEl.style.color = '#f87171';
            }
          }

          async function saveAutosaveToDB() {
            if (!currentUser || !currentProjectId) return;
            window.isSavingItem = true;
            updateSaveStatus('saving');
            try {
              const catSelect = document.getElementById("peCategorySelect");
              const isStarred = document.getElementById("peStarIcon") && document.getElementById("peStarIcon").classList.contains("bi-star-fill") ? 1 : 0;
              let projId = null;
              if (currentView && currentView.filter && currentView.filter.startsWith("proj_")) {
                projId = currentView.filter.replace("proj_", "");
              }

              const projectData = {
                public_id: currentProjectId,
                title: currentProjectTitle,
                width: currentWidth,
                height: currentHeight,
                state: JSON.stringify(canvas.toJSON()),
                category: catSelect ? catSelect.value : 'all',
                starred: isStarred,
                project_id: projId
              };
              const res = await fetchData("?action=save_imageditor_project", {
                method: "POST",
                body: JSON.stringify(projectData)
              });
              
              if (res && res.status === 'success') {
                const p = projectsIndex.find(item => item.public_id === currentProjectId);
                if (p) {
                  p.title = currentProjectTitle;
                  p.updated_at = new Date().toISOString();
                }
                updateSaveStatus('saved');
              } else {
                updateSaveStatus('error');
              }
            } catch (err) {
              console.error(err);
              updateSaveStatus('error');
            }
            window.isSavingItem = false;
            window.lastLocalEditTime = Date.now();
          }

          function setProjectTitleQuietly(title) {
            currentProjectTitle = title || "Untitled Project";
            const p = projectsIndex.find(item => item.public_id === currentProjectId);
            if (p) {
              p.title = currentProjectTitle;
            }
          }

          function loadStateQuietly(stateJson) {
            if (!canvas) return;
            const currentJson = JSON.stringify(canvas.toJSON());
            if (currentJson === stateJson) return; 
            
            let stateObj = {};
            try { stateObj = JSON.parse(stateJson); } catch(e) { return; }
            
            isProcessingHistory = true;
            canvas.loadFromJSON(stateObj, function() {
              try { canvas.renderAll(); } catch(e) {}
              isProcessingHistory = false;
              updateLayersList();
            });
          }

          function manualSave() {
            clearTimeout(apiDebounceTimer);
            saveAutosaveToDB();
          }

          async function loadProject(projId) {
            if (!currentUser) return;
            try {
              fetchData("?action=log_item_view", { method: "POST", body: JSON.stringify({ item_id: projId, item_type: "imageditor" }) }, true);
              const res = await fetchData(`?action=get_imageditor_project&public_id=${projId}`);
              if (res && res.status === 'success' && res.project) {
                const data = res.project;
                const starIcon = document.getElementById("peStarIcon");
                if (starIcon) {
                  starIcon.className = data.starred == 1 ? "bi bi-star-fill text-warning" : "bi bi-star";
                }
                const catSelect = document.getElementById("peCategorySelect");
                if (catSelect) {
                  catSelect.value = data.category || "all";
                  const isOwner = !data.user_id || data.user_id == (currentUser ? currentUser.id : null);
                  catSelect.disabled = !isOwner;
                }
                currentProjectId = data.public_id;
                currentProjectTitle = data.title || "Untitled Project";
                localStorage.setItem('imageditor_last_project', currentProjectId);
                const projInput = document.getElementById('projectTitleInput');
                if (projInput) projInput.value = currentProjectTitle;
                if (data.width && data.height) {
                  setCanvasDimensions(data.width, data.height);
                }
                isProcessingHistory = true;
                let stateObj = {};
                try {
                  stateObj = typeof data.state === 'string' ? JSON.parse(data.state || '{}') : (data.state || {});
                } catch(e) {
                  stateObj = {};
                }
                try {
                  canvas.loadFromJSON(stateObj, function() {
                    try { canvas.renderAll(); } catch(e) {}
                    isProcessingHistory = false;
                    history = [JSON.stringify(canvas.toJSON())];
                    historyIndex = 0;
                    updateLayersList();
                    showToast(`Loaded "${currentProjectTitle}"`);
                  });
                } catch(e) {
                  isProcessingHistory = false;
                  try { canvas.renderAll(); } catch(err) {}
                  saveHistory();
                }

                const isCollab = (typeof currentView !== 'undefined' && currentView && currentView.filter && currentView.filter.startsWith("proj_")) || (data.project_id && data.project_id != 0);
                if (data.id && isCollab) {
                  lastSyncContentTime = data.updated_at;
                  startPresenceSync(data.id, "imageditor");
                }
              }
            } catch (err) {
              isProcessingHistory = false;
              saveHistory();
            }
          }

          async function createNewProject(title = "Untitled Project") {
            if (!currentUser) {
              showToast("Login required to save projects", "error");
              return;
            }
            try {
              let projId = null;
              if (typeof currentView !== 'undefined' && currentView && currentView.filter && currentView.filter.startsWith("proj_")) {
                projId = currentView.filter.replace("proj_", "");
              }
              const projectData = {
                public_id: '',
                title: title,
                width: currentWidth || 1080,
                height: currentHeight || 1080,
                state: '{}',
                project_id: projId
              };
              const res = await fetchData("?action=save_imageditor_project", {
                method: "POST",
                body: JSON.stringify(projectData)
              });
              if (res && res.status === 'success') {
                currentProjectId = res.public_id;
                currentProjectTitle = title;
                localStorage.setItem('imageditor_last_project', currentProjectId);
                const projInput = document.getElementById('projectTitleInput');
                if (projInput) projInput.value = currentProjectTitle;
                
                let filterStr = "";
                if (typeof currentView !== 'undefined' && currentView && currentView.type === 'photo_editor' && currentView.filter) {
                  filterStr = `&filter=${currentView.filter}`;
                }
                const idxRes = await fetchData(`?action=get_imageditor_projects${filterStr}`);
                if (idxRes) projectsIndex = idxRes;
                
                canvas.clear();
                saveHistory();
                closeModal('projectsModal');
                showToast("New project created");
              }
            } catch (e) {
              showToast("Failed to create project", "error");
            }
          }

          async function deleteProject(projId, event) {
            if (event) event.stopPropagation();
            if (projectsIndex.length <= 1) {
              showToast("Cannot delete the only project");
              return;
            }
            if (!confirm("Delete this project?")) return;
            
            try {
              const res = await fetchData("?action=delete_imageditor_project", {
                method: "POST",
                body: JSON.stringify({ public_id: projId })
              });
              if (res && res.status === 'success') {
                projectsIndex = projectsIndex.filter(p => p.public_id !== projId);
                if (currentProjectId === projId) {
                  await loadProject(projectsIndex[0].public_id);
                } else {
                  renderProjectsList();
                }
                showToast("Project deleted");
              }
            } catch(e) {
              showToast("Delete failed", "error");
            }
          }

          async function duplicateProject(projId, event) {
            if (event) event.stopPropagation();
            try {
              const res = await fetchData("?action=duplicate_imageditor_project", {
                method: "POST",
                body: JSON.stringify({ public_id: projId })
              });
              if (res && res.status === 'success') {
                let filterStr = "";
                if (typeof currentView !== 'undefined' && currentView && currentView.type === 'photo_editor' && currentView.filter) {
                  filterStr = `&filter=${currentView.filter}`;
                }
                const idxRes = await fetchData(`?action=get_imageditor_projects${filterStr}`);
                if (idxRes) projectsIndex = idxRes;
                renderProjectsList();
                showToast("Project duplicated");
              }
            } catch(e) {
              showToast("Duplication failed", "error");
            }
          }
  
          function updateProjectTitle(newTitle) {
            window.lastLocalEditTime = Date.now();
            currentProjectTitle = newTitle.trim() || "Untitled Project";
            const p = projectsIndex.find(item => item.public_id === currentProjectId);
            if (p) {
              p.title = currentProjectTitle;
            }
            saveAutosaveToDB();
          }
  
          function setProjectSort(sortType) {
            currentProjectSort = sortType;
            renderProjectsList();
          }
  
          function renderProjectsList() {
            const container = document.getElementById('projectsListContainer');
            if (!container) return;
            container.innerHTML = '';
            
            let sortedProjects = [...projectsIndex];
            
            if (currentProjectSort === 'recent') {
              sortedProjects.sort((a, b) => {
                if ((b.view_count || 0) !== (a.view_count || 0)) return (b.view_count || 0) - (a.view_count || 0);
                return new Date(b.last_viewed || 0) - new Date(a.last_viewed || 0);
              });
            } else if (currentProjectSort === 'modified') {
              sortedProjects.sort((a, b) => new Date(b.updated_at || 0) - new Date(a.updated_at || 0));
            } else {
              sortedProjects.sort((a, b) => {
                const timeA = new Date(a.updated_at || 0).getTime();
                const timeB = new Date(b.updated_at || 0).getTime();
                return currentProjectSort === 'newest' ? timeB - timeA : timeA - timeB;
              });
            }
  
            sortedProjects.forEach(proj => {
              const isActive = proj.public_id === currentProjectId;
              const dateStr = new Date(proj.updated_at).toLocaleDateString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
              const item = document.createElement('div');
              const activeStyles = isActive ? 'background: rgba(94, 21, 31, 0.4); border-color: var(--primary);' : 'background: var(--surface-dim); border-color: var(--outline-variant);';
              item.style.cssText = `display: flex; align-items: center; justify-content: space-between; padding: 12px; border-radius: 12px; border: 1px solid; transition: all 0.2s; cursor: pointer; margin-bottom: 8px; ${activeStyles}`;
              
              item.onmouseover = () => { if (!isActive) item.style.background = 'var(--surface-container)'; };
              item.onmouseout = () => { if (!isActive) item.style.background = 'var(--surface-dim)'; };
              item.onclick = () => {
                if (!isActive) {
                  loadProject(proj.public_id);
                  closeModal('projectsModal');
                }
              };
              item.innerHTML = `
                <div style="display: flex; align-items: center; gap: 12px;">
                  <div style="width: 32px; height: 32px; border-radius: 8px; background: var(--surface-container-high); display: flex; align-items: center; justify-content: center; font-weight: bold; font-size: 0.75rem; color: ${isActive ? 'var(--primary)' : 'var(--on-surface-variant)'};">📄</div>
                  <div>
                    <h5 style="margin: 0; font-size: 0.8rem; font-weight: 700; color: #fff;">${escapeHTML(proj.title)}</h5>
                    <p style="margin: 0; font-size: 0.65rem; color: var(--on-surface-variant);">Modified: ${dateStr}</p>
                  </div>
                </div>
                <div style="display: flex; align-items: center; gap: 4px;">
                  <button class="action-btn" style="padding: 6px;" onclick="window.imageditor.duplicateProject('${proj.public_id}', event)" title="Duplicate Project">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width: 14px; height: 14px;"><rect x="9" y="9" width="13" height="13" rx="2"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>
                  </button>
                  <button class="action-btn" style="padding: 6px; color: var(--primary);" onclick="window.imageditor.deleteProject('${proj.public_id}', event)" title="Delete Project">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width: 14px; height: 14px;"><path d="M3 6h18"></path><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path></svg>
                  </button>
                </div>
              `;
              container.appendChild(item);
            });
          }
  
          function openProjectsModal() {
            renderProjectsList();
            showModal('projectsModal');
          }
  
          async function exportAllProjects() {
            if (!currentUser) return showToast("Login required", "error");
            try {
              const backupData = {
                version: 1,
                timestamp: Date.now(),
                projects: []
              };
              for (const proj of projectsIndex) {
                try {
                  const res = await fetchData(`?action=get_imageditor_project&public_id=${proj.public_id}`);
                  if (res && res.status === 'success' && res.project) {
                    backupData.projects.push(res.project);
                  }
                } catch (e) {}
              }
              const blob = new Blob([JSON.stringify(backupData)], { type: 'application/json' });
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `imageditor_backup_${new Date().toISOString().slice(0,10)}.json`;
              a.click();
              URL.revokeObjectURL(url);
              showToast("Backup exported");
            } catch (err) {
              console.error(err);
              showToast("Export failed", "error");
            }
          }
  
          async function importAllProjects(e) {
            const file = e.target.files[0];
            if (!file || !currentUser) return;
            const reader = new FileReader();
            reader.onload = async function(evt) {
              try {
                const backupData = JSON.parse(evt.target.result);
                if (!backupData.projects || !Array.isArray(backupData.projects)) {
                  return showToast("Invalid backup file", "error");
                }
                
                showToast("Importing...", "info");
                let count = 0;
                for (const projData of backupData.projects) {
                  try {
                    await fetchData("?action=save_imageditor_project", {
                      method: "POST",
                      body: JSON.stringify({
                        public_id: '',
                        title: projData.title || "Imported Project",
                        width: projData.width || 1080,
                        height: projData.height || 1080,
                        state: projData.state || '{}'
                      })
                    });
                    count++;
                  } catch(e) {}
                }
                
                const idxRes = await fetchData("?action=get_imageditor_projects");
                if (idxRes) projectsIndex = idxRes;
                
                renderProjectsList();
                showToast(`${count} projects imported`, "success");
              } catch (err) {
                console.error(err);
                showToast("Import failed", "error");
              }
              e.target.value = '';
            };
            reader.readAsText(file);
          }

          function cropActiveImage() {
            const active = canvas.getActiveObject();
            if (!active || active.type !== 'image') return showToast("Select an image to crop", "error");
            
            cropTargetObj = active;
            const cropImgEl = document.getElementById('cropTargetImage');
            
            cropImgEl.src = active.getSrc();
            
            showModal('cropModal');
            
            if (cropperInstance) cropperInstance.destroy();
            setTimeout(() => {
              cropperInstance = new Cropper(cropImgEl, {
                viewMode: 1,
                dragMode: 'crop',
                background: false,
                autoCropArea: 1,
                responsive: true
              });
            }, 150);
          }

          function applyCrop() {
            if (!cropperInstance || !cropTargetObj) return;
            const croppedCanvas = cropperInstance.getCroppedCanvas();
            const dataUrl = croppedCanvas.toDataURL('image/png', 1.0);
            
            const left = cropTargetObj.left;
            const top = cropTargetObj.top;
            const scaleX = cropTargetObj.scaleX;
            const scaleY = cropTargetObj.scaleY;
            const angle = cropTargetObj.angle;
            
            cropTargetObj.setSrc(dataUrl, function(img) {
              img.set({
                left: left,
                top: top,
                scaleX: scaleX,
                scaleY: scaleY,
                angle: angle
              });
              canvas.renderAll();
              saveHistory();
              closeModal('cropModal');
              showToast('Image cropped');
              
              if (cropperInstance) {
                cropperInstance.destroy();
                cropperInstance = null;
              }
            });
          }
  
          function setupEvents() {
            const ws = document.getElementById('workspace');
            if (ws) {
              ws.addEventListener('dragover', e => e.preventDefault());
              ws.addEventListener('drop', e => {
                e.preventDefault();
                if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
                  uploadImageToOPFS({ target: { files: e.dataTransfer.files } });
                }
              });
            }
            canvas.on('selection:created', handleSelection);
            canvas.on('selection:updated', handleSelection);
            canvas.on('selection:cleared', () => {
              const propsPanel = document.getElementById('propertiesPanel');
              const qToolbar = document.getElementById('quickToolbar');
              if (propsPanel) propsPanel.classList.remove('visible');
              if (qToolbar) qToolbar.classList.remove('visible');
            });
            canvas.on('object:modified', () => {
              if (!isProcessingHistory) window.lastLocalEditTime = Date.now();
              saveHistory();
              updateQuickToolbarPosition();
            });
            canvas.on('object:added', () => { if (!isProcessingHistory) window.lastLocalEditTime = Date.now(); });
            canvas.on('object:removed', () => { if (!isProcessingHistory) window.lastLocalEditTime = Date.now(); });
            canvas.on('object:moving', (e) => {
              updateQuickToolbarPosition();
              handleSnapping(e);
            });
            canvas.on('object:scaling', updateQuickToolbarPosition);
            canvas.on('object:rotating', updateQuickToolbarPosition);
            canvas.on('mouse:up', clearGuides);
            canvas.on('path:created', function(e) {
              if (!isProcessingHistory) window.lastLocalEditTime = Date.now();
              if (!e.path) return;
              if (currentBrushType === 'eraser') {
                e.path.globalCompositeOperation = 'destination-out';
                canvas.renderAll();
              }
              if (symmetryMode === 'none') {
                saveHistory();
                return;
              }
              applySymmetryMirrors(e.path);
            });
            setupDraggablePanel();
          }
  
          function handleSelection(e) {
            const active = e.selected ? e.selected[0] : canvas.getActiveObject();
            if (!active) return;
            updateQuickToolbarPosition();
            const ctrlText = document.getElementById('ctrl-text');
            const ctrlColor = document.getElementById('ctrl-color');
            if (ctrlText) ctrlText.classList.add('d-none');
            if (ctrlColor) ctrlColor.classList.remove('d-none');
            const panelTitle = document.getElementById('panelTitle');
            if (panelTitle) panelTitle.innerText = active.type.toUpperCase() + ' PROPERTIES';
            if (active.fill && typeof active.fill === 'string') {
              const propFill = document.getElementById('prop-fill');
              if (propFill) propFill.value = active.fill.startsWith('#') ? active.fill : '#f2354a';
            }
            const propStroke = document.getElementById('prop-stroke');
            if (propStroke) propStroke.value = active.stroke || '#000000';
            const propStrokeW = document.getElementById('prop-stroke-width');
            if (propStrokeW) propStrokeW.value = active.strokeWidth || 0;
            const valStrokeW = document.getElementById('val-stroke-width');
            if (valStrokeW) valStrokeW.innerText = active.strokeWidth || 0;
            
            const ctrlBorderRadius = document.getElementById('ctrl-border-radius');
            if (active.type === 'rect') {
              if (ctrlBorderRadius) ctrlBorderRadius.classList.remove('d-none');
              const propRadius = document.getElementById('prop-border-radius');
              if (propRadius) propRadius.value = active.rx || 0;
              const valRadius = document.getElementById('val-border-radius');
              if (valRadius) valRadius.innerText = active.rx || 0;
            } else {
              if (ctrlBorderRadius) ctrlBorderRadius.classList.add('d-none');
            }
            
            const opacity = active.opacity !== undefined ? active.opacity : 1;
            const propOp = document.getElementById('prop-opacity');
            if (propOp) propOp.value = opacity;
            const valOp = document.getElementById('val-opacity');
            if (valOp) valOp.innerText = Math.round(opacity * 100) + '%';
            if (active.type === 'i-text' || active.type === 'text') {
              if (ctrlText) ctrlText.classList.remove('d-none');
              const propText = document.getElementById('prop-text-value');
              if (propText) propText.value = active.text;
              const propFont = document.getElementById('prop-font-family');
              if (propFont) propFont.value = active.fontFamily || 'Roboto';
            }
            updateLayersList();
          }
  
          function updateQuickToolbarPosition() {
            const active = canvas.getActiveObject();
            const qToolbar = document.getElementById('quickToolbar');
            const propsPanel = document.getElementById('propertiesPanel');
            const cropBtn = document.getElementById('pe-crop-btn');

            if (!active || (propsPanel && propsPanel.classList.contains('visible'))) {
              if (qToolbar) qToolbar.classList.remove('visible');
              return;
            }

            if (cropBtn) {
              if (active.type === 'image') cropBtn.style.display = 'flex';
              else cropBtn.style.display = 'none';
            }

            const workspace = document.getElementById('workspace');
            const canvasEl = canvas.getElement();

            if (!workspace || !canvasEl || !qToolbar) return;

            qToolbar.classList.add('visible');
            active.setCoords();

            const cRect = canvasEl.getBoundingClientRect();
            const wRect = workspace.getBoundingClientRect();

            // Since we use canvas.setZoom(), getBoundingRect() returns pre-scaled coordinates relative to the canvas!
            const bound = active.getBoundingRect();

            // Strict viewport offsets relative to workspace
            const offsetX = cRect.left - wRect.left;
            const offsetY = cRect.top - wRect.top;

            const objCenterX = offsetX + bound.left + (bound.width / 2);
            const objTopY = offsetY + bound.top;

            const toolbarWidth = qToolbar.offsetWidth || 240;
            const toolbarHeight = qToolbar.offsetHeight || 44;

            let toolbarLeft = objCenterX - (toolbarWidth / 2);
            let toolbarTop = objTopY - toolbarHeight - 12;

            if (isNaN(toolbarLeft)) toolbarLeft = (wRect.width / 2) - (toolbarWidth / 2);
            if (isNaN(toolbarTop)) toolbarTop = 20;

            // Strict viewport horizontal bounds
            toolbarLeft = Math.max(12, Math.min(wRect.width - toolbarWidth - 12, toolbarLeft));

            // Strict viewport vertical bounds (flip below object if hitting ceiling)
            if (toolbarTop < 12) {
              toolbarTop = offsetY + bound.top + bound.height + 16;
              // If it also overflows the bottom of the workspace, center it vertically as a last resort fallback
              if (toolbarTop + toolbarHeight > wRect.height) {
                 toolbarTop = (wRect.height / 2) - (toolbarHeight / 2);
              }
            }

            qToolbar.style.left = `${toolbarLeft}px`;
            qToolbar.style.top = `${toolbarTop}px`;
          }

          function handleSnapping(e) {
            const obj = e.target;
            const canvasCenterX = currentWidth / 2;
            const canvasCenterY = currentHeight / 2;
            const snapZone = 15 / zoomLevel;

            const center = obj.getCenterPoint();
            let snappedX = false;
            let snappedY = false;

            if (Math.abs(center.x - canvasCenterX) < snapZone) {
              obj.setPositionByOrigin(new fabric.Point(canvasCenterX, center.y), 'center', 'center');
              snappedX = true;
            }
            
            const updatedCenter = obj.getCenterPoint();

            if (Math.abs(updatedCenter.y - canvasCenterY) < snapZone) {
              obj.setPositionByOrigin(new fabric.Point(updatedCenter.x, canvasCenterY), 'center', 'center');
              snappedY = true;
            }

            if (snappedX && !verticalGuide) {
              verticalGuide = new fabric.Line([canvasCenterX, -currentHeight * 2, canvasCenterX, currentHeight * 3], {
                stroke: '#06b6d4', strokeWidth: 2 / zoomLevel, selectable: false, evented: false, strokeDashArray: [5, 5], opacity: 0.8, excludeFromExport: true
              });
              canvas.add(verticalGuide);
            } else if (!snappedX && verticalGuide) {
              canvas.remove(verticalGuide);
              verticalGuide = null;
            }

            if (snappedY && !horizontalGuide) {
              horizontalGuide = new fabric.Line([-currentWidth * 2, canvasCenterY, currentWidth * 3, canvasCenterY], {
                stroke: '#06b6d4', strokeWidth: 2 / zoomLevel, selectable: false, evented: false, strokeDashArray: [5, 5], opacity: 0.8, excludeFromExport: true
              });
              canvas.add(horizontalGuide);
            } else if (!snappedY && horizontalGuide) {
              canvas.remove(horizontalGuide);
              horizontalGuide = null;
            }
          }

          function clearGuides() {
            if (verticalGuide) {
              canvas.remove(verticalGuide);
              verticalGuide = null;
            }
            if (horizontalGuide) {
              canvas.remove(horizontalGuide);
              horizontalGuide = null;
            }
            canvas.renderAll();
          }
  
          function addShape(type) {
            let shape;
            const common = {
              left: currentWidth / 2,
              top: currentHeight / 2,
              originX: 'center',
              originY: 'center',
              fill: '#f2354a',
              stroke: '#000000',
              strokeWidth: 0,
              cornerColor: '#f2354a',
              cornerStrokeColor: '#ffffff',
              transparentCorners: false,
              cornerSize: 10
            };
            switch(type) {
              case 'rect': shape = new fabric.Rect({ ...common, width: 200, height: 200 }); break;
              case 'circle': shape = new fabric.Circle({ ...common, radius: 100 }); break;
              case 'triangle': shape = new fabric.Triangle({ ...common, width: 200, height: 200 }); break;
              case 'star': shape = new fabric.Polygon([
                {x: 0, y: -50}, {x: 14, y: -20}, {x: 47, y: -15}, {x: 23, y: 7},
                {x: 29, y: 40}, {x: 0, y: 25}, {x: -29, y: 40}, {x: -23, y: 7},
                {x: -47, y: -15}, {x: -14, y: -20}
              ], { ...common, scaleX: 2, scaleY: 2 }); break;
              case 'heart': shape = new fabric.Path('M 272.70141,238.71731 C 206.46141,238.71731 152.70141,292.47731 152.70141,358.71731 C 152.70141,498.71731 352.70141,618.71731 352.70141,618.71731 C 352.70141,618.71731 552.70141,498.71731 552.70141,358.71731 C 552.70141,292.47731 498.94141,238.71731 432.70141,238.71731 C 385.62141,238.71731 345.17141,265.80731 325.70141,305.10731 C 306.23141,265.80731 265.78141,238.71731 272.70141,238.71731 z', { ...common, scaleX: 0.4, scaleY: 0.4 }); break;
              case 'line': shape = new fabric.Line([50, 100, 250, 100], { ...common, stroke: '#f2354a', strokeWidth: 4 }); break;
            }
            if (shape) {
              canvas.add(shape);
              canvas.setActiveObject(shape);
              closeDrawers();
              saveHistory();
              showToast(`Added ${type}`);
            }
          }
  
          function addText(preset = 'heading') {
            let options = {
              left: currentWidth / 2,
              top: currentHeight / 2,
              originX: 'center',
              originY: 'center',
              fontFamily: 'Roboto',
              fill: '#ffffff',
              cornerColor: '#f2354a',
              transparentCorners: false,
              lockUniScaling: true
            };
            let textStr = 'Edit Text';
            if (preset === 'heading') { textStr = 'HEADING TITLE'; options.fontSize = 72; options.fontWeight = 'bold'; }
            else if (preset === 'subheading') { textStr = 'Subheading Text'; options.fontSize = 40; options.fontWeight = '600'; }
            else if (preset === 'body') { textStr = 'Body paragraph copy goes here...'; options.fontSize = 24; }
            else if (preset === 'neon') {
              textStr = 'GLOW NEON'; options.fontSize = 60; options.fill = '#f2354a';
              options.shadow = new fabric.Shadow({ color: '#f2354a', blur: 20 });
            }
            const textObj = new fabric.IText(textStr, options);
            textObj.setControlsVisibility({
              mt: false,
              mb: false,
              ml: false,
              mr: false
            });
            canvas.add(textObj);
            canvas.setActiveObject(textObj);
            closeDrawers();
            saveHistory();
          }
  
          function addBadge(type) {
            if (type === 'sale') {
              const rect = new fabric.Rect({ width: 220, height: 70, fill: '#f2354a', rx: 12, ry: 12 });
              const text = new fabric.Text('SALE 50%', { fontSize: 28, fill: '#ffffff', fontWeight: 'bold', originX: 'center', originY: 'center', left: 110, top: 35 });
              const group = new fabric.Group([rect, text], { left: currentWidth/2, top: currentHeight/2, originX: 'center', originY: 'center' });
              canvas.add(group);
            } else if (type === 'new') {
              const circle = new fabric.Circle({ radius: 50, fill: '#e5b35a' });
              const text = new fabric.Text('NEW!', { fontSize: 24, fill: '#000000', fontWeight: 'bold', originX: 'center', originY: 'center', left: 50, top: 50 });
              const group = new fabric.Group([circle, text], { left: currentWidth/2, top: currentHeight/2, originX: 'center', originY: 'center' });
              canvas.add(group);
